/* Vragenbank PA-toets per module. Vorm: [vraag, [[antwoord, uitleg] x4]]; het EERSTE antwoord is steeds het juiste (de toets husselt zelf).
   Na het herzien van een module: pas de datum "bijgewerkt" aan in assets/js/modules.js. */
window.PA_VRAGEN={
"basis":[
["Welk toezichtmodel hanteert Nederland voor de financiële sector?", [["Twin peaks: de AFM houdt gedragstoezicht en DNB prudentieel toezicht", "Het toezicht is ingedeeld naar doel: de AFM let op het gedrag richting klanten en markten, DNB op de soliditeit van instellingen."], ["Een sectoraal model met één toezichthouder per branche", "Dat model is juist verlaten; het toezicht is ingedeeld naar doel en niet naar sector zoals banken of verzekeraars."], ["Eén centrale toezichthouder voor de hele sector, namelijk DNB", "Nederland kent twee toezichthouders met elk een eigen taak; DNB houdt geen gedragstoezicht op adviseurs."], ["Toezicht door het ministerie van Financiën, met de AFM en DNB als adviseurs", "Het ministerie maakt beleid en wetgeving; het toezicht zelf is belegd bij AFM en DNB."]]],
["In welk deel van de Wft staan de regels voor het gedragstoezicht op financiële ondernemingen, zoals de zorgplicht en informatieregels?", [["Deel 4", "Deel 4 Wft bevat het gedragstoezicht op financiële ondernemingen, waaronder informatieverstrekking, zorgplicht en klachtbehandeling."], ["Deel 2", "Deel 2 Wft gaat over markttoegang: de vergunningplicht en de vrijstellingen daarvan."], ["Deel 3", "Deel 3 Wft regelt het prudentiële toezicht, zoals solvabiliteit en een beheerste bedrijfsvoering."], ["Deel 5", "Deel 5 Wft betreft het gedragstoezicht op financiële markten, zoals prospectussen en marktmisbruik."]]],
["Wat is volgens de Wft het doel van het gedragstoezicht door de AFM?", [["Ordelijke en transparante marktprocessen, zuivere verhoudingen tussen marktpartijen en zorgvuldige behandeling van cliënten", "Dit is de wettelijke omschrijving van het gedragstoezicht; de nadruk ligt op het gedrag van partijen, ook richting klanten."], ["De financiële soliditeit van banken, verzekeraars en pensioenfondsen waarborgen, zodat zij hun verplichtingen kunnen nakomen", "Dat is het doel van prudentieel toezicht, de taak van DNB en niet van de AFM."], ["De stabiliteit van het financiële stelsel als geheel bewaken en crises voorkomen", "Financiële stabiliteit hoort bij de taken van DNB; de AFM richt zich op gedrag en transparantie."], ["Individuele geschillen tussen consumenten en financiële dienstverleners bindend beslechten en daarbij schadevergoedingen toekennen", "Geschillen worden beslecht door Kifid of de rechter; de AFM is geen geschilleninstantie."]]],
["Een klant belt de AFM met een klacht over zijn adviseur en verwacht dat de AFM hem een schadevergoeding toekent. Wat is juist?", [["De AFM behandelt geen individuele klachten maar gebruikt de melding als signaal; de klant gaat naar de adviseur en daarna naar Kifid", "De AFM kan wel optreden tegen de onderneming, maar beslecht geen individuele geschillen en kent geen schadevergoeding toe."], ["De AFM onderzoekt de klacht, hoort beide partijen en kent bij een gegronde klacht een schadevergoeding toe tot een wettelijk maximum", "Een schadevergoeding kan alleen via Kifid of de rechter worden verkregen, niet via de toezichthouder."], ["De AFM stuurt de klacht door naar DNB, omdat DNB over klachten van consumenten gaat", "DNB houdt prudentieel toezicht en behandelt evenmin individuele klachten van consumenten."], ["De AFM verplicht de adviseur om binnen een vaste termijn een schikking met de klant te treffen", "De AFM kan geen schikking in een individueel geschil afdwingen; dat hoort bij Kifid of de rechter."]]],
["Welke maatregel kan de AFM zelf opleggen aan een financiële onderneming die de Wft overtreedt?", [["Een bestuurlijke boete of een last onder dwangsom", "Dit zijn bestuursrechtelijke handhavingsinstrumenten die de Wft aan de AFM toekent; daarnaast kan zij onder meer een aanwijzing geven of de vergunning intrekken."], ["Een gevangenisstraf voor de verantwoordelijke bestuurders", "Vrijheidsstraffen kan alleen de strafrechter opleggen, niet een toezichthouder."], ["Een schadevergoeding aan de gedupeerde klanten van de onderneming", "Het toekennen van schadevergoeding is voorbehouden aan de rechter of een geschilleninstantie zoals Kifid."], ["Het faillissement van de onderneming, uitgesproken door de AFM zelf", "Een faillissement wordt door de rechtbank uitgesproken; de AFM kan dat niet zelf doen."]]],
["Hoe kan een consument het beste nagaan of een financieel adviseur over een Wft-vergunning beschikt?", [["Door het openbare register van de AFM te raadplegen", "De AFM verleent de vergunningen voor adviseren en bemiddelen en houdt daarvan een openbaar register bij."], ["Door het handelsregister van de Kamer van Koophandel te raadplegen", "Een KvK-inschrijving zegt niets over het hebben van een Wft-vergunning; elk bedrijf moet zich daar inschrijven."], ["Door bij het BKR een vergunningcheck aan te vragen", "Het BKR registreert kredieten van consumenten en houdt geen register van vergunningen bij."], ["Door bij DNB te controleren of het kantoor solvabel is", "DNB verleent geen vergunningen aan adviseurs en bemiddelaars; dat doet de AFM."]]],
["Aan wie verleent de AFM een vergunning voor het adviseren over of bemiddelen in financiële producten?", [["Aan de financiële onderneming", "De vergunning geldt voor de onderneming; individuele medewerkers moeten daarnaast zelf vakbekwaam zijn."], ["Aan iedere individuele adviseur persoonlijk", "Medewerkers hebben geen eigen vergunning nodig; voor hen gelden de vakbekwaamheidseisen."], ["Aan de branchevereniging namens haar leden", "Een branchevereniging kan geen vergunning namens leden houden; elke onderneming vraagt die zelf aan."], ["Aan de aanbieder, die daarmee al zijn tussenpersonen dekt", "De vergunning van een bank of verzekeraar dekt in beginsel niet de activiteiten van zelfstandige tussenpersonen."]]],
["Voor welke activiteit is in beginsel een Wft-vergunning van de AFM nodig?", [["Adviseren over een overlijdensrisicoverzekering", "Een overlijdensrisicoverzekering is een financieel product in de zin van de Wft; adviseren erover is vergunningplichtig."], ["Bemiddelen bij de aankoop van een woning als makelaar", "Makelaardij in onroerend goed is geen dienstverlening over een financieel product in de zin van de Wft."], ["Het opstellen van een testament voor een klant", "Een testament is een notariële akte en geen financieel product; daarvoor geldt geen Wft-vergunning."], ["Het verzorgen van de jaarlijkse belastingaangifte", "Belastingadvies en aangiftewerk vallen niet onder de Wft-vergunningplicht."]]],
["Wat verstaat de Wft in de kern onder bemiddelen?", [["Werkzaamheden gericht op het sluiten van een overeenkomst over een financieel product tussen klant en aanbieder", "Bemiddelen draait om het tot stand brengen van de overeenkomst; bij verzekeringen hoort ook het assisteren bij beheer en uitvoering ervan."], ["Het doen van een persoonlijke aanbeveling aan een klant over een of meer specifieke financiële producten van een aanbieder", "Dat is de omschrijving van adviseren; adviseren en bemiddelen zijn afzonderlijke activiteiten."], ["Het zelf als wederpartij aangaan van de overeenkomst met de klant", "Wie zelf de wederpartij is, biedt het product aan; dat is aanbieden en geen bemiddelen."], ["Het namens de klant beheren van diens vermogen naar eigen inzicht", "Dat is vermogensbeheer, een beleggingsdienst met een eigen regime."]]],
["Een website legt in algemene termen uit wat het verschil is tussen een annuïteiten- en een lineaire hypotheek, zonder gegevens van de bezoeker te vragen. Is dit adviseren in de zin van de Wft?", [["Nee, algemene informatie zonder op de persoon toegesneden aanbeveling is geen advies", "Zonder persoonlijke aanbeveling over een specifiek product is er sprake van informatieverstrekking, die wel correct en niet misleidend moet zijn."], ["Ja, alle informatie over financiële producten geldt als advies", "Niet alle informatie is advies; het gaat om een persoonlijke aanbeveling over een specifiek product."], ["Ja, want informatie over hypotheken is altijd vergunningplichtig advies, ook zonder klantgegevens", "Ook over hypotheken mag algemene voorlichting worden gegeven zonder dat sprake is van advies."], ["Nee, want informatie op een website valt nooit onder de Wft", "Ook online kan advies worden gegeven, en ook voor websites gelden de informatieregels van de Wft."]]],
["Een fietsenwinkel biedt bij de verkoop van een nieuwe fiets ook een fietsverzekering aan. Wat is juist?", [["Dit kan onder de vrijstelling voor aanvullende verzekeringen bij levering van een goed vallen, mits aan de voorwaarden is voldaan", "Voor verzekeringen die aanvullend zijn op een geleverd goed of dienst geldt onder voorwaarden een lichter regime in plaats van de volledige vergunningplicht."], ["De winkel heeft altijd een volledige vergunning voor bemiddelen in schadeverzekeringen nodig, net als een zelfstandig advieskantoor", "Voor aanvullende verzekeringen bij de levering van een goed bestaat juist een vrijstelling onder voorwaarden."], ["De Wft is niet van toepassing omdat de winkel vooral fietsen verkoopt", "Ook een winkel die bemiddelt in een verzekering valt onder de Wft; de vrijstelling geldt alleen onder voorwaarden."], ["Een vergunning is alleen nodig als de klant uitdrukkelijk om advies vraagt", "Ook bemiddelen zonder advies kan vergunningplichtig zijn; het gaat hier om de vrijstellingsvoorwaarden."]]],
["Een kantoor bemiddelt uitsluitend in particuliere schadeverzekeringen en geeft daarbij nooit advies. Heeft het kantoor een Wft-vergunning nodig?", [["Ja, ook voor bemiddelen zonder advies is in beginsel een vergunning nodig", "De Wft kent een afzonderlijke vergunningplicht voor bemiddelen, los van die voor adviseren."], ["Nee, alleen adviseren is vergunningplichtig", "Bemiddelen is een zelfstandige vergunningplichtige activiteit naast adviseren."], ["Nee, schadeverzekeringen vallen buiten de Wft", "Schadeverzekeringen zijn financiële producten in de zin van de Wft."], ["Alleen als de premie per polis boven een wettelijk grensbedrag van € 1.000,00 per jaar uitkomt", "De vergunningplicht hangt niet af van de hoogte van de premie per polis."]]],
["Welke eis hoort bij het verkrijgen en behouden van een AFM-vergunning als adviseur of bemiddelaar?", [["De dagelijks beleidsbepalers moeten betrouwbaar en geschikt zijn", "De AFM toetst de betrouwbaarheid en geschiktheid van beleidsbepalers bij de vergunningaanvraag en bij wijzigingen."], ["Het kantoor moet lid zijn van een erkende branchevereniging", "Lidmaatschap van een branchevereniging is vrijwillig en geen vergunningseis."], ["Elk advies moet vooraf door de AFM worden goedgekeurd", "De AFM houdt achteraf toezicht en keurt geen individuele adviezen goed."], ["Het kantoor moet met een minimum aantal van vijf aanbieders per productsoort samenwerken", "De Wft schrijft geen minimum aantal aanbieders voor als vergunningseis."]]],
["Wat is het gevolg als een onderneming zonder de vereiste vergunning adviseert over hypotheken?", [["De onderneming overtreedt de Wft; de AFM kan handhavend optreden, bijvoorbeeld met een boete of last onder dwangsom", "Werken zonder vergunning is een overtreding van een kernverbod in de Wft, waartegen de AFM kan optreden."], ["De gegeven adviezen zijn automatisch nietig, zodat de klant geen advieskosten hoeft te betalen en de afgesloten producten vervallen", "De Wft regelt niet dat adviezen automatisch nietig zijn; de civielrechtelijke gevolgen hangen af van de situatie."], ["Kifid legt een boete op en schrapt de onderneming uit het register", "Kifid is geen toezichthouder en legt geen boetes op; dat is de bevoegdheid van de AFM."], ["Er is geen gevolg zolang de klanten tevreden zijn over het advies", "Klanttevredenheid neemt de overtreding van de vergunningplicht niet weg."]]],
["Wat is de rol van het CDFD?", [["Het CDFD ontwikkelt de Wft-examens en houdt het register bij van behaalde diploma's en PE-examens", "Het College Deskundigheid Financiële Dienstverlening beheert het examenstelsel; de examens worden afgenomen bij erkende exameninstituten."], ["Het CDFD verleent namens de AFM vergunningen aan adviseurs en bemiddelaars en houdt daarvan een register bij", "Vergunningen worden verleend door de AFM zelf, die ook het vergunningenregister bijhoudt; het CDFD heeft daarin geen rol."], ["Het CDFD behandelt klachten van consumenten over adviezen", "Klachten worden eerst intern behandeld en daarna door Kifid."], ["Het CDFD houdt prudentieel toezicht op kleine advieskantoren", "Prudentieel toezicht is een taak van DNB; het CDFD is geen toezichthouder."]]],
["Hoe is de vakbekwaamheid van een medewerker die adviseert over financiële producten opgebouwd?", [["Een Wft-diploma (Basis en de relevante productmodule), actueel gehouden via permanente educatie", "Het diploma toont de vakbekwaamheid aan en via PE blijft die kennis actueel."], ["Een afgeronde hbo-opleiding in een economische richting", "Een algemene opleiding is niet hetzelfde als een Wft-diploma, tenzij die formeel is gelijkgesteld."], ["Een minimum aantal jaren aantoonbare werkervaring in de financiële sector, vastgelegd in een ervaringsverklaring", "Werkervaring alleen is geen vervanging voor het vereiste Wft-diploma."], ["Een eenmalig behaald certificaat dat levenslang geldig blijft", "De kennis moet actueel worden gehouden; zonder PE blijft het diploma niet geldig."]]],
["Een adviseur haalt zijn PE-examen niet vóór het einde van de geldende termijn. Wat is het gevolg?", [["Hij voldoet niet meer aan de vakbekwaamheidseisen en mag die werkzaamheden niet verrichten totdat hij weer voldoet", "Zonder actuele PE is de vakbekwaamheid niet meer aangetoond, zodat de medewerker die werkzaamheden niet mag uitvoeren."], ["Hij krijgt automatisch een jaar uitstel zonder verdere gevolgen", "Er bestaat geen automatisch uitstel; het niet tijdig voldoen heeft direct gevolgen voor de vakbekwaamheid."], ["Alleen zijn werkgever krijgt een waarschuwing van de AFM; de adviseur mag gewoon doorwerken tot de volgende PE-periode", "De medewerker zelf mag niet meer adviseren; de werkgever moet daar ook op toezien."], ["Hij hoeft niets te doen zolang hij al meer dan tien jaar adviseert", "Ervaring vervangt de PE-verplichting niet; die geldt voor iedereen."]]],
["Wie is er volgens de Wft verantwoordelijk voor dat medewerkers met klantcontact vakbekwaam zijn?", [["De financiële onderneming, die ervoor zorgt en kan aantonen dat haar medewerkers vakbekwaam zijn", "De onderneming moet zorgen dat de medewerkers die de werkzaamheden verrichten vakbekwaam zijn en moet dat aantoonbaar maken."], ["Uitsluitend de medewerker zelf, die zijn diploma en PE-bewijzen persoonlijk bij de AFM moet registreren", "De medewerker moet zijn diploma en PE halen, maar de onderneming is wettelijk verantwoordelijk voor de vakbekwaamheid."], ["De AFM, die elke medewerker jaarlijks persoonlijk toetst", "De AFM toetst niet elke medewerker; zij houdt toezicht op de onderneming."], ["De aanbieder van de producten waarover wordt geadviseerd", "Een aanbieder is niet verantwoordelijk voor de vakbekwaamheid van medewerkers van een zelfstandig advieskantoor."]]],
["Welke minimale omvang van bij- en nascholing schrijft de Europese richtlijn verzekeringsdistributie (IDD) voor?", [["Ten minste 15 uur per jaar", "De IDD vraagt minimaal 15 uur professionele training of ontwikkeling per jaar; Nederland geeft hier invulling aan via het PE-stelsel."], ["Ten minste 5 uur per jaar", "Dit is lager dan het minimum dat de IDD voorschrijft."], ["Ten minste 30 uur per jaar", "De IDD noemt een lager minimum; lidstaten mogen wel strengere eisen stellen."], ["Geen minimum; een eenmalig diploma is voldoende", "De IDD vereist juist doorlopende bij- en nascholing naast de initiële vakbekwaamheid."]]],
["Wat toetst de module Wft Basis?", [["Algemene kennis die voor alle productgebieden geldt, zoals wet- en regelgeving, klantbelang en financiële basisbegrippen", "Wft Basis is de gemeenschappelijke kennisbasis; productspecifieke kennis wordt getoetst in aparte modules."], ["De specialistische kennis van hypotheekberekeningen, de leennormen en de fiscale behandeling van de eigen woning in box 1", "Dat is de inhoud van de productmodule Hypothecair krediet."], ["De kennis die nodig is om zelfstandig vermogensbeheer uit te voeren", "Vermogensbeheer en beleggingsdienstverlening hebben een eigen vakbekwaamheidskader."], ["Uitsluitend de fiscale regels rond de eigen woning en pensioen", "Fiscaliteit komt in Basis alleen op hoofdlijnen aan bod; verdieping zit in de productmodules."]]],
["Wat is de kern van de algemene zorgplicht voor financiële dienstverleners in de Wft?", [["Zorgvuldig rekening houden met de rechtmatige belangen van de klant", "De algemene zorgplicht vraagt dat de dienstverlener bij zijn dienstverlening zorgvuldig rekening houdt met de rechtmatige belangen van de klant."], ["Zoveel mogelijk producten verkopen binnen de wettelijke grenzen en de eigen acceptatieregels", "Omzet staat niet centraal; de zorgplicht draait om het belang van de klant."], ["De klant alleen informeren als hij daar zelf om vraagt", "De dienstverlener moet ook uit zichzelf relevante informatie geven en zorgvuldig handelen."], ["Altijd het goedkoopste product op de markt garanderen", "De zorgplicht vraagt een passende oplossing, niet per se het goedkoopste product."]]],
["Een klant wil snel een overlijdensrisicoverzekering afsluiten via advies, maar weigert informatie te geven over zijn inkomen en lasten. Wat moet de adviseur doen?", [["Uitleggen dat hij zonder die informatie geen passend advies kan geven en zich dan van advies onthouden", "Zonder voldoende klantinformatie kan de adviseur niet beoordelen wat passend is en mag hij niet adviseren."], ["Toch adviseren op basis van gemiddelde aannames, zonder dit vast te leggen", "Adviseren op aannames zonder klantinformatie levert geen passend advies op."], ["Uit voorzorg de hoogst mogelijke dekking adviseren", "Een hoge dekking is niet automatisch passend en kan onnodig duur zijn."], ["De klant een afstandsverklaring laten tekenen en daarna gewoon adviseren op basis van de wel bekende gegevens", "Een afstandsverklaring ontslaat de adviseur niet van de plicht om passend te adviseren."]]],
["Waarom is het belangrijk dat een adviseur het klantprofiel en de onderbouwing van zijn advies in het dossier vastlegt?", [["Zodat achteraf aantoonbaar is op welke informatie het advies berust en waarom het passend was", "Een goed dossier maakt het advies controleerbaar voor de klant, de onderneming en de toezichthouder."], ["Omdat de klant anders geen premie hoeft te betalen", "Het vastleggen van het dossier heeft geen invloed op de betalingsverplichting van de klant."], ["Omdat het dossier vooraf door de AFM moet worden goedgekeurd voordat het advies aan de klant mag worden uitgebracht", "De AFM keurt dossiers niet vooraf goed, maar kan ze wel opvragen bij onderzoek."], ["Omdat de aanbieder anders de polis niet mag afgeven", "De aanbieder heeft eigen acceptatieregels; het adviesdossier is een plicht van de adviseur zelf."]]],
["Met welke vier kenmerken heeft de AFM omschreven wanneer een product of dienst het klantbelang centraal stelt?", [["Kostenefficiënt, nuttig, veilig en begrijpelijk", "Met deze vier kenmerken heeft de AFM uitgewerkt wat klantbelang centraal in de praktijk betekent."], ["Goedkoop, snel, digitaal en flexibel", "Dit zijn wenselijke eigenschappen, maar niet de kenmerken die de AFM hanteert."], ["Rendabel, innovatief, schaalbaar en uniek", "Dit zijn kenmerken vanuit het perspectief van de aanbieder, niet vanuit het klantbelang."], ["Onafhankelijk, provisievrij, garantievrij en eenvoudig", "Deze combinatie is niet de omschrijving die de AFM gebruikt."]]],
["Wat vraagt het productontwikkelingsproces (productgoedkeurings- en reviewproces) van aanbieders van financiële producten?", [["Dat zij producten vooraf toetsen op het klantbelang, een doelgroep bepalen en het product periodiek evalueren", "Aanbieders moeten producten evenwichtig ontwerpen voor een bepaalde doelgroep en die ook na introductie blijven beoordelen."], ["Dat elk nieuw product vooraf door de AFM wordt goedgekeurd", "De AFM keurt producten niet vooraf goed; de aanbieder moet zelf een zorgvuldig proces hebben."], ["Dat zij alleen de winstgevendheid van het product toetsen", "Het proces is juist gericht op het klantbelang en niet alleen op winstgevendheid."], ["Dat producten pas worden aangepast nadat Kifid klachten over het product gegrond heeft verklaard of de AFM daarom vraagt", "Het proces vraagt een proactieve toetsing vooraf en periodiek, niet pas na klachten."]]],
["Wat is de zogenoemde bijzondere zorgplicht die in de civiele rechtspraak voor financiële instellingen is ontwikkeld?", [["Een plicht om vanwege hun deskundigheid en maatschappelijke functie de klant te beschermen, bijvoorbeeld door te waarschuwen voor risico's", "De Hoge Raad heeft deze zorgplicht ontwikkeld; zij geldt naast de publiekrechtelijke Wft-regels."], ["Een Wft-regel die uitsluitend geldt voor de grootste systeembanken en die door de AFM wordt gehandhaafd met bestuurlijke boetes", "De bijzondere zorgplicht komt uit het civiele recht en is niet beperkt tot grote banken."], ["De plicht van de klant om alle risico's van een financieel product zelf te onderzoeken voordat hij een overeenkomst sluit, ook na advies", "Het gaat juist om een plicht van de financiële instelling jegens de klant."], ["De plicht van de AFM om consumenten persoonlijk te waarschuwen", "De bijzondere zorgplicht rust op de instelling, niet op de toezichthouder."]]],
["Een klant kiest, na advies, voor een product dat de adviseur uitdrukkelijk niet passend vindt. Wat is de juiste handelwijze?", [["De adviseur legt zijn advies en de risico's helder uit en legt vast dat de klant daarvan afwijkt", "De klant beslist zelf, maar de adviseur moet zijn advies duidelijk geven en het afwijken goed vastleggen."], ["De adviseur past zijn advies aan zodat het overeenkomt met de wens van de klant, en legt alleen dat aangepaste advies vast", "Het advies moet de eigen professionele beoordeling blijven; het aanpassen aan de wens is niet zorgvuldig."], ["De adviseur meldt de klant bij de AFM", "Een afwijkende keuze van de klant is geen reden voor een melding aan de AFM."], ["De adviseur sluit het product af zonder verder iets vast te leggen", "Zonder vastlegging kan de adviseur later niet aantonen dat hij zorgvuldig heeft gewaarschuwd."]]],
["Wat kenmerkt execution only dienstverlening?", [["De klant kiest zelf zonder advies; de dienstverlener doet geen persoonlijke aanbeveling maar moet wel zorgvuldig handelen", "Bij execution only wordt niet geadviseerd, maar de algemene zorgplicht en informatieregels blijven gelden."], ["Er gelden geen Wft-regels, omdat er geen advies wordt gegeven", "Ook zonder advies gelden onder meer de zorgplicht en de informatieverplichtingen."], ["De dienstverlener blijft aansprakelijk voor de passendheid van het gekozen product, net als bij een volledig adviestraject", "Zonder advies is er geen adviesaansprakelijkheid voor passendheid, al blijft zorgvuldigheid nodig."], ["Het is alleen toegestaan bij het openen van een spaarrekening", "Execution only komt bij meer producten voor; voor sommige gelden aanvullende eisen."]]],
["Wat is het doel van het dienstverleningsdocument?", [["De klant vooraf informeren over de aard en kosten van de dienstverlening en de relatie met aanbieders", "Met deze informatie kan de klant bewust kiezen of en bij wie hij advies of bemiddeling afneemt."], ["De klant informeren over de polisvoorwaarden van het geadviseerde product", "Productvoorwaarden komen van de aanbieder; het dienstverleningsdocument gaat over de dienstverlening van het kantoor."], ["Het persoonlijke advies en de onderbouwing daarvan, inclusief het klantprofiel, schriftelijk aan de klant vastleggen", "Dat gebeurt in het adviesrapport, dat pas na de inventarisatie wordt opgesteld."], ["De klant jaarlijks informeren over de waarde van zijn verzekeringen", "Een waarde-overzicht is periodieke productinformatie, geen informatie over de dienstverlening."]]],
["Wanneer moet de klant de informatie over de dienstverlening en de kosten daarvan in beginsel ontvangen?", [["Voordat de dienstverlening begint", "De klant moet vooraf weten wat hij kan verwachten en wat het kost, zodat hij daar een bewuste keuze over kan maken."], ["Bij het ondertekenen van de offerte van de aanbieder", "Dan is de dienstverlening al grotendeels verricht en kan de klant niet meer vooraf kiezen."], ["Na afloop van de dienstverlening, samen met de factuur", "Achteraf informeren over kosten maakt een bewuste keuze vooraf onmogelijk."], ["Alleen wanneer de klant er uitdrukkelijk om vraagt", "Het gaat om een verplichting van de dienstverlener, niet om informatie op verzoek."]]],
["Onder welke voorwaarden mag een adviseur zich onafhankelijk noemen?", [["Als hij adviseert op basis van een analyse van voldoende producten op de markt en geen provisie van aanbieders ontvangt", "De term onafhankelijk is beschermd; zowel een voldoende brede marktanalyse als het ontbreken van provisie van aanbieders is vereist."], ["Als hij niet in loondienst is van een bank of verzekeraar", "Zelfstandig zijn is niet genoeg; de wettelijke voorwaarden gaan over marktanalyse en provisie."], ["Als hij lid is van een beroepsvereniging met een eigen gedragscode en is ingeschreven in het register van die vereniging", "Een lidmaatschap is geen wettelijke voorwaarde voor het gebruik van de term onafhankelijk."], ["Als hij met ten minste twee aanbieders samenwerkt", "Twee aanbieders is niet zonder meer een voldoende aantal, en ook de provisievoorwaarde geldt."]]],
["Welk gestandaardiseerd document moet onder de IDD bij een schadeverzekering worden verstrekt?", [["Het informatiedocument over het verzekeringsproduct (IPID)", "Het IPID geeft in een vast format de kern van een schadeverzekering weer, zoals de dekking en uitsluitingen."], ["Het Europees gestandaardiseerd informatieblad (ESIS)", "Het ESIS hoort bij hypothecair krediet, niet bij schadeverzekeringen."], ["Het essentiële-informatiedocument op grond van de PRIIPs-verordening", "Dit document geldt voor verpakte beleggingsproducten en beleggingsverzekeringen, niet voor schadeverzekeringen."], ["Het standaardformulier Europese informatie inzake consumentenkrediet", "Dit formulier hoort bij consumptief krediet."]]],
["Wat is het ESIS?", [["Een Europees gestandaardiseerd informatieblad met de belangrijkste kenmerken en kosten van een hypotheek", "Door de vaste opbouw kan de consument aanbiedingen van verschillende kredietgevers vergelijken."], ["Een Europese toets op de kredietwaardigheid van de consument, die de geldverstrekker vóór het aanbod moet uitvoeren", "De kredietwaardigheidstoets is een aparte verplichting; het ESIS is een informatiedocument."], ["Een registratie van alle hypotheken in de Europese Unie", "Er bestaat geen Europees hypotheekregister onder deze naam; het ESIS is klantinformatie."], ["Een Europees keurmerk voor duurzame hypotheken", "Het ESIS is geen keurmerk, maar een verplicht informatieblad."]]],
["Wat geeft het jaarlijks kostenpercentage (JKP) bij een krediet weer?", [["De totale kosten van het krediet voor de consument, als jaarlijks percentage van het kredietbedrag", "Het JKP omvat naast de rente ook andere verplichte kosten, zodat kredieten beter vergelijkbaar zijn."], ["Alleen de nominale rente die de kredietgever per jaar in rekening brengt, zonder afsluit- en bemiddelingskosten", "Het JKP is breder dan de nominale rente, omdat ook andere kosten worden meegerekend."], ["Het deel van het krediet dat per jaar moet worden afgelost", "Aflossing is terugbetaling van de hoofdsom en geen kostenpercentage."], ["De verwachte inflatie gedurende de looptijd van het krediet", "Inflatie maakt geen deel uit van het JKP."]]],
["Welke waarschuwingszin moet in reclame voor consumptief krediet worden opgenomen?", [["Let op! Geld lenen kost geld.", "Deze standaardwaarschuwing maakt consumenten erop attent dat lenen niet gratis is."], ["Let op! Lenen is altijd verantwoord.", "Dit is geen wettelijke tekst en zou juist misleidend zijn."], ["Let op! U loopt risico op het verlies van uw inleg.", "Een dergelijke waarschuwing past bij beleggen, niet bij kredietreclame."], ["Let op! Raadpleeg eerst de AFM.", "Dit is geen voorgeschreven tekst; de AFM geeft geen individueel kredietadvies."]]],
["Wat houdt het provisieverbod in?", [["Adviseurs en bemiddelaars mogen voor bepaalde producten geen provisie van de aanbieder ontvangen; de klant betaalt zelf", "Voor onder meer hypotheken en complexe producten is de beloning via de aanbieder vervangen door directe klantbeloning."], ["Adviseurs mogen voor geen enkel product nog beloning ontvangen; het advies moet voortaan door de aanbieder gratis worden gegeven", "Adviseurs mogen wel beloond worden, maar dan door de klant zelf."], ["Aanbieders mogen geen kosten meer in hun producten verwerken", "Het verbod ziet op provisie aan tussenpersonen, niet op alle productkosten."], ["Klanten mogen hun adviseur niet meer per uur betalen", "Uurtarief is juist een gangbare vorm van directe beloning door de klant."]]],
["Sinds wanneer geldt het provisieverbod voor onder meer hypothecair krediet en complexe financiële producten?", [["1 januari 2013", "Op deze datum werd het provisieverbod ingevoerd voor onder meer hypotheken, complexe producten en arbeidsongeschiktheidsverzekeringen."], ["1 januari 2007", "Dit is de datum waarop de Wft in werking trad; het provisieverbod kwam later."], ["1 oktober 2018", "Dit is de datum waarop de IDD van toepassing werd, niet die van het provisieverbod."], ["10 maart 2021", "Op deze datum werd de SFDR van toepassing; het provisieverbod bestond toen al."]]],
["Bij welk van de volgende producten mag een bemiddelaar in beginsel wel provisie van de aanbieder ontvangen?", [["Een inboedelverzekering", "Voor particuliere schadeverzekeringen zoals een inboedelverzekering geldt het provisieverbod niet, al moet de beloning wel transparant en evenwichtig zijn."], ["Een hypothecair krediet", "Voor hypothecair krediet geldt het provisieverbod."], ["Een arbeidsongeschiktheidsverzekering voor een particulier", "Arbeidsongeschiktheidsverzekeringen vallen onder het provisieverbod."], ["Een beleggingsverzekering", "Een beleggingsverzekering is een complex product en valt onder het provisieverbod."]]],
["Wat was een belangrijke reden voor de invoering van het provisieverbod?", [["Het wegnemen van de prikkel om te adviseren wat de meeste provisie oplevert in plaats van wat het best bij de klant past", "Provisie van de aanbieder kon het advies sturen; directe beloning maakt de kosten zichtbaar en het advies zuiverder."], ["Het verlagen van de rente op hypotheken voor alle consumenten", "Het verbod was niet bedoeld om rentes te verlagen, maar om belangenconflicten te beperken."], ["Het beperken van het aantal adviseurs in Nederland", "Doel was een betere kwaliteit van advies, niet minder adviseurs."], ["Het mogelijk maken dat aanbieders zelf meer adviseurs in dienst nemen en hun producten rechtstreeks aan consumenten verkopen", "Het provisieverbod geldt ook voor advies door aanbieders; het ging om het zuiveren van advies."]]],
["Een geldverstrekker biedt een advieskantoor een gratis studiereis aan als het kantoor een bepaald aantal hypotheken bij hem onderbrengt. Wat is juist?", [["Dit is niet toegestaan, omdat ook een vergoeding in natura van een aanbieder onder het provisieverbod valt", "Een reis die afhangt van de productie is een beloning van de aanbieder die het advies kan beïnvloeden."], ["Dit is toegestaan, omdat het geen geldbedrag is", "Het provisieverbod geldt niet alleen voor geld maar ook voor andere voordelen."], ["Dit is toegestaan, zolang de klant er niet voor hoeft te betalen", "Ook als de klant niet meebetaalt, tast de prikkel het klantbelang aan."], ["Dit is toegestaan als het kantoor de reis in zijn jaarverslag vermeldt en de klant er in het dienstverleningsdocument op wijst", "Openbaarmaking maakt een verboden vergoeding niet toelaatbaar."]]],
["Wat geldt voor de beloning van medewerkers met klantcontact bij een financiële onderneming?", [["De beloning mag geen prikkel geven om in strijd met het belang van de klant te handelen", "Beloningsbeleid moet zo zijn ingericht dat medewerkers niet worden aangezet tot het verkopen van producten die niet in het belang van de klant zijn."], ["De beloning moet volledig afhangen van het aantal afgesloten producten, zodat de productie van het kantoor stijgt", "Een volledig productiegebonden beloning geeft juist een prikkel tegen het klantbelang."], ["Er gelden geen regels, zolang het vaste salaris marktconform is", "Ook voor variabele beloning en het beloningsbeleid gelden wettelijke regels."], ["Alleen bestuurders vallen onder beloningsregels, medewerkers niet", "Beloningsregels gelden ook voor medewerkers, in het bijzonder voor wie met klanten werkt."]]],
["Wat is de juiste aanpak van belangenconflicten volgens de regelgeving?", [["Belangenconflicten identificeren, voorkomen of beheersen, en de klant informeren als dat onvoldoende lukt", "Melden aan de klant is het sluitstuk; eerst moet de onderneming het conflict zelf voorkomen of beheersen."], ["Belangenconflicten alleen in de algemene voorwaarden vermelden, zodat de klant er bij het tekenen mee instemt", "Een algemene vermelding is geen beheersing van het concrete conflict."], ["Belangenconflicten alleen melden als de klant ernaar vraagt", "De onderneming moet zelf actief belangenconflicten signaleren en aanpakken."], ["Belangenconflicten zijn toegestaan zolang de AFM er niet naar vraagt", "Er geldt een eigen verplichting om belangenconflicten te beheersen, los van vragen van de AFM."]]],
["Een adviseur heeft een financieel belang in een geldverstrekker waarvan hij hypotheken adviseert. Wat is juist?", [["Dit is een belangenconflict dat moet worden beheerst en waarover hij de klant duidelijk informeert", "Een eigen financieel belang kan het advies beïnvloeden; het advies moet in het belang van de klant blijven."], ["Dit is geen probleem, omdat het belang buiten de onderneming ligt", "Een privébelang van de adviseur kan het advies net zo goed beïnvloeden."], ["De adviseur mag die geldverstrekker nooit meer adviseren", "Een algemeen verbod geldt niet; het conflict moet worden beheerst en gemeld."], ["Het is alleen relevant als de klant zelf aandelen heeft in de geldverstrekker of daar een spaarrekening aanhoudt", "Het gaat om het belang van de adviseur, niet om dat van de klant."]]],
["Een adviseur wordt gevraagd zowel de koper als de verkoper van dezelfde woning te adviseren over de financiële afwikkeling. Wat is juist?", [["Er is sprake van een belangenconflict, omdat de belangen van koper en verkoper tegengesteld kunnen zijn", "Bij tegengestelde belangen kan de adviseur niet zonder meer voor beide partijen optimaal handelen; dit vraagt beheersing en transparantie, of afzien."], ["Er is geen belangenconflict, omdat het om één woning gaat", "Juist omdat het om dezelfde transactie gaat, kunnen de belangen botsen."], ["Er is geen belangenconflict zolang beide partijen tevreden zijn", "Tevredenheid achteraf neemt het conflict vooraf niet weg."], ["Er is alleen een belangenconflict als de adviseur ook als makelaar bij de verkoop van de woning betrokken is", "Ook zonder makelaarsrol kunnen de belangen van beide klanten tegengesteld zijn."]]],
["Wat moet een financiële onderneming vastleggen met betrekking tot belangenconflicten?", [["Een beleid voor belangenconflicten en een registratie van situaties waarin die zijn ontstaan of kunnen ontstaan", "Vastlegging maakt het beheersen van belangenconflicten controleerbaar voor de onderneming en de toezichthouder."], ["Alleen de belangenconflicten die tot een klacht hebben geleid", "Ook conflicten zonder klacht moeten worden gesignaleerd en beheerst."], ["Niets, omdat belangenconflicten uitsluitend mondeling met de betrokken klant en de compliance officer worden besproken", "Mondeling bespreken is onvoldoende; het beleid en de registratie moeten aantoonbaar zijn."], ["Alleen belangenconflicten van bestuurders, niet van medewerkers", "Ook medewerkers kunnen belangenconflicten hebben die beheerst moeten worden."]]],
["Wat moet een consument doen voordat hij met een klacht bij Kifid terechtkan?", [["Eerst de klacht voorleggen aan de financiële dienstverlener zelf", "Kifid behandelt een klacht pas als de interne klachtenprocedure van de dienstverlener niet tot een oplossing heeft geleid."], ["Eerst een procedure bij de kantonrechter beginnen", "Kifid is juist een alternatief voor de rechter; een rechtszaak vooraf is niet nodig."], ["Eerst toestemming vragen aan de AFM", "De AFM speelt geen rol in de toegang tot Kifid."], ["Eerst een advocaat inschakelen die de klacht namens hem schriftelijk indient", "Een consument kan zelf een klacht indienen; een advocaat is niet verplicht."]]],
["Wat voor organisatie is Kifid?", [["Een onafhankelijke, erkende geschilleninstantie die buiten de rechter om financiële geschillen beslecht", "Kifid biedt laagdrempelige geschilbeslechting voor consumenten als alternatief voor de rechter."], ["Een rechtbank voor financiële zaken", "Kifid is geen overheidsrechter, maar een buitengerechtelijke geschilleninstantie."], ["Een toezichthouder naast de AFM en DNB", "Kifid houdt geen toezicht en legt geen boetes op."], ["Een belangenvereniging van financiële dienstverleners die klachten van consumenten namens haar leden afhandelt", "Kifid is onafhankelijk en behartigt niet de belangen van één partij."]]],
["Een consument heeft een niet-bindende uitspraak van Kifid gekregen en is het daar niet mee eens. Wat kan hij doen?", [["Hij kan de zaak alsnog aan de rechter voorleggen", "Een niet-bindende uitspraak is een advies; partijen kunnen daarna naar de rechter."], ["Niets, iedere uitspraak van Kifid is definitief", "Alleen een bindende uitspraak bindt partijen; een niet-bindende uitspraak niet."], ["Hij moet de AFM vragen de uitspraak te herzien", "De AFM heeft geen bevoegdheid om uitspraken van Kifid te herzien."], ["Hij kan alleen een nieuwe klacht bij dezelfde commissie indienen", "Dezelfde klacht opnieuw indienen is geen gangbare route; de rechter staat open."]]],
["Wat hoort bij een zorgvuldige interne klachtafhandeling door een advieskantoor?", [["Klachten registreren, tijdig en inhoudelijk reageren en ze analyseren om herhaling te voorkomen", "Een goede procedure lost de klacht op en gebruikt de les om de dienstverlening te verbeteren."], ["Klachten alleen behandelen als ze per aangetekende brief en binnen zes weken na het advies worden ingediend", "Een dergelijke drempel past niet bij een toegankelijke klachtenprocedure."], ["Klachten direct doorsturen naar Kifid zonder eigen reactie", "Het kantoor moet eerst zelf de klacht behandelen."], ["Klachten pas registreren als de klant een schadevergoeding eist", "Ook klachten zonder schadeclaim horen geregistreerd en behandeld te worden."]]],
["Een klant laat telefonisch boos weten dat hij al weken wacht op zijn offerte. Hij dient geen schriftelijke klacht in. Wat is juist?", [["Dit is een klacht die volgens de klachtenprocedure behandeld en geregistreerd moet worden", "Ook een mondelinge klacht verdient serieuze behandeling en registratie."], ["Dit is geen klacht, omdat alleen schriftelijke klachten meetellen", "Een klacht hoeft niet schriftelijk te zijn om als klacht te gelden."], ["Dit is een zaak voor Kifid, dus het kantoor hoeft niets te doen", "Het kantoor moet eerst zelf de klacht behandelen."], ["Dit is pas een klacht als de klant financiële schade heeft geleden en die schriftelijk heeft onderbouwd", "Een klacht gaat over ontevredenheid over de dienstverlening, ook zonder schade."]]],
["Waaruit bestaat het cliëntenonderzoek onder de Wwft?", [["Identificatie en verificatie van cliënt en UBO, vaststellen van doel en aard van de relatie en doorlopende controle", "Het cliëntenonderzoek is meer dan een identiteitscheck: ook het doel van de relatie en voortdurende monitoring horen erbij."], ["Alleen het kopiëren van het identiteitsbewijs van de cliënt", "Identificatie is maar één onderdeel; ook verificatie, UBO, doel en monitoring zijn nodig."], ["Een kredietcheck bij het BKR en een inkomenstoets", "Dit zijn kredietwaardigheidscontroles, geen onderdelen van het Wwft-cliëntenonderzoek."], ["Het opvragen van een verklaring omtrent het gedrag van de cliënt en een recent uittreksel uit de Basisregistratie Personen", "Een VOG en een BRP-uittreksel zijn geen onderdelen van het cliëntenonderzoek onder de Wwft."]]],
["Bij welke instantie meldt een Wwft-plichtige onderneming een ongebruikelijke transactie?", [["FIU-Nederland", "De Financial Intelligence Unit ontvangt en analyseert meldingen van ongebruikelijke transacties."], ["De politie", "De melding gaat naar FIU-Nederland, dat zo nodig gegevens doorgeeft aan opsporingsinstanties."], ["De AFM", "De AFM houdt toezicht op naleving, maar is niet het meldpunt voor ongebruikelijke transacties."], ["De Belastingdienst", "De Belastingdienst is niet het meldpunt onder de Wwft."]]],
["Een adviseur heeft een ongebruikelijke transactie gemeld. De klant vraagt later of er ergens een probleem is met zijn dossier. Wat mag de adviseur zeggen?", [["Hij mag niet vertellen dat er een melding is gedaan", "De Wwft kent een geheimhoudingsplicht: de cliënt mag niet worden geïnformeerd over de melding."], ["Hij moet de klant volledig informeren over de melding", "Het informeren van de klant is juist verboden, omdat het een onderzoek kan schaden."], ["Hij mag het vertellen als de klant schriftelijk om inzage vraagt", "Ook een inzageverzoek doorbreekt de geheimhoudingsplicht van de Wwft niet."], ["Hij mag het vertellen als de melding ouder is dan een jaar", "De geheimhoudingsplicht kent zo'n termijn niet."]]],
["Uit het cliëntenonderzoek blijkt dat een nieuwe klant een politiek prominent persoon (PEP) is. Wat is juist?", [["Verscherpt cliëntenonderzoek doen, onder meer naar de herkomst van het vermogen, met goedkeuring op hoger leidinggevend niveau", "Bij een PEP is het risico hoger, daarom gelden extra maatregelen."], ["De onderneming mag geen zakelijke relatie aangaan met een PEP of met diens directe familieleden en naaste geassocieerden", "Een relatie met een PEP is toegestaan, maar vraagt verscherpte maatregelen."], ["Er gelden dezelfde maatregelen als bij iedere andere klant", "Voor PEP's geldt juist een verscherpt cliëntenonderzoek."], ["De onderneming moet de klant direct melden bij FIU-Nederland en mag pas na toestemming van FIU een relatie aangaan", "De PEP-status alleen is geen ongebruikelijke transactie en geen reden voor een melding."]]],
["Hoe lang moeten gegevens uit het cliëntenonderzoek onder de Wwft ten minste worden bewaard?", [["Vijf jaar na het einde van de zakelijke relatie of na uitvoering van de transactie", "De Wwft schrijft deze termijn voor, zodat gegevens beschikbaar zijn voor onderzoek."], ["Zeven jaar na het aangaan van de zakelijke relatie, gelijk aan de fiscale bewaarplicht voor de administratie", "Zeven jaar is de fiscale bewaarplicht; de Wwft hanteert een andere termijn en een ander startpunt."], ["Eén jaar na de laatste transactie", "Die termijn is te kort voor de Wwft."], ["Zolang de klant daarmee instemt", "De bewaarplicht is wettelijk en hangt niet af van de instemming van de klant."]]],
["Wat beschermt een melder die te goeder trouw een ongebruikelijke transactie meldt?", [["Hij is gevrijwaard van strafrechtelijke en civielrechtelijke aansprakelijkheid voor de melding", "De Wwft beschermt de melder te goeder trouw, zodat de meldplicht niet tot aansprakelijkheid leidt."], ["Hij krijgt een financiële beloning van FIU-Nederland", "Er is geen beloning voor een melding."], ["Hij krijgt automatisch een nieuwe identiteit", "Dat is geen onderdeel van de Wwft-regeling."], ["Hij is niet beschermd en draagt zelf het risico van een schadeclaim van de klant over wie hij heeft gemeld", "De Wwft biedt juist bescherming aan melders te goeder trouw."]]],
["Een nieuwe zakelijke klant weigert informatie te geven over wie de uiteindelijke belanghebbende (UBO) is. Wat moet de onderneming doen?", [["Geen zakelijke relatie aangaan, omdat het cliëntenonderzoek niet kan worden voltooid, en een melding overwegen", "Zonder voltooid cliëntenonderzoek mag de relatie niet worden aangegaan; de weigering kan reden zijn voor een melding."], ["De relatie gewoon aangaan en het UBO-onderzoek later afronden", "Het cliëntenonderzoek moet in beginsel vooraf zijn afgerond."], ["De relatie aangaan als de klant een hogere vergoeding betaalt", "Een hogere vergoeding verandert niets aan de wettelijke plicht."], ["De relatie gewoon aangaan, omdat de plicht om de UBO vast te stellen alleen voor banken en trustkantoren geldt", "Ook andere Wwft-plichtige instellingen, zoals advieskantoren, moeten de UBO vaststellen."]]],
["Op welke grondslag verwerkt een adviseur doorgaans de inkomensgegevens van een klant om een hypotheekadvies te geven?", [["De verwerking is noodzakelijk voor de uitvoering van de overeenkomst met de klant", "Zonder inkomensgegevens kan het gevraagde advies niet worden gegeven; dat is een eigen grondslag naast toestemming."], ["Toestemming van de klant is altijd vereist en is de enige mogelijke grondslag voor financiële gegevens", "De AVG kent zes grondslagen; toestemming is er één van en is niet altijd de meest passende."], ["Het vitale belang van de klant", "Deze grondslag is bedoeld voor levensbedreigende situaties, niet voor advies."], ["Het algemeen belang van een goed werkende hypotheekmarkt", "Deze grondslag geldt voor taken van algemeen belang, niet voor een advies aan een klant."]]],
["Een medewerker verliest een laptop met onversleutelde klantdossiers. Wat moet het kantoor doen?", [["Het datalek in beginsel binnen 72 uur melden bij de Autoriteit Persoonsgegevens en zo nodig de betrokken klanten informeren", "Melden is nodig tenzij het lek waarschijnlijk geen risico voor de betrokkenen oplevert; bij een hoog risico worden ook de klanten zelf geïnformeerd."], ["Het lek alleen intern registreren, omdat het om een ongeluk gaat", "Ook een onopzettelijk lek kan meldplichtig zijn; de oorzaak is niet bepalend."], ["Het lek binnen 72 uur melden bij de AFM, omdat het om financiële gegevens gaat, en de geldverstrekkers van de klanten inlichten", "De meldplicht voor datalekken geldt jegens de Autoriteit Persoonsgegevens."], ["Wachten tot een klant een klacht indient", "De meldtermijn begint bij de ontdekking, niet bij een klacht."]]],
["Welke van de volgende gegevens is een bijzonder persoonsgegeven onder de AVG?", [["Informatie over de gezondheid van de klant", "Gezondheidsgegevens zijn bijzondere persoonsgegevens; verwerking is in beginsel verboden behalve onder specifieke uitzonderingen."], ["Het bruto jaarinkomen en de vermogenspositie van de klant", "Inkomen en vermogen zijn gevoelig, maar geen bijzondere persoonsgegevens in de zin van de AVG."], ["Het woonadres van de klant", "Een adres is een gewoon persoonsgegeven."], ["Het e-mailadres van de klant", "Een e-mailadres is een gewoon persoonsgegeven."]]],
["Een klant vraagt het kantoor welke persoonsgegevens het van hem heeft. Wat geldt?", [["De klant heeft recht op inzage en het kantoor moet in beginsel binnen een maand reageren", "De AVG geeft een inzagerecht; de termijn kan bij complexe verzoeken worden verlengd."], ["Het kantoor hoeft alleen te reageren als de klant een advocaat inschakelt", "Het inzagerecht kan de klant zelf uitoefenen."], ["Het kantoor mag een inzageverzoek altijd weigeren vanwege bedrijfsgeheimen of de interne adviesnotities", "Weigeren kan alleen in uitzonderlijke gevallen; het recht op inzage is het uitgangspunt."], ["Het kantoor moet de gegevens eerst aan de AFM voorleggen", "De AFM speelt geen rol bij inzageverzoeken onder de AVG."]]],
["Mag een adviseur gegevens die hij voor een hypotheekadvies heeft verkregen zonder meer gebruiken voor een marketingactie van een partnerbedrijf?", [["Nee, gegevens mogen alleen voor verenigbare doelen worden gebruikt; voor een ander doel is een eigen grondslag nodig", "Het beginsel van doelbinding voorkomt dat gegevens ongemerkt voor nieuwe doelen worden gebruikt."], ["Ja, zodra gegevens zijn verkregen mogen ze vrij worden gebruikt", "De AVG kent doelbinding; vrij gebruik is niet toegestaan."], ["Ja, als het partnerbedrijf ook een financiële onderneming is met een eigen AFM-vergunning en een gepubliceerde privacyverklaring", "Het type ontvanger verandert niets aan de eis van een passende grondslag."], ["Ja, als de klant niet binnen een week bezwaar maakt", "Stilzwijgen geldt niet als toestemming onder de AVG."]]],
["Een kantoor laat zijn klantdossiers opslaan door een externe softwareleverancier. Wat is juist?", [["Het kantoor moet een verwerkersovereenkomst sluiten en blijft verwerkingsverantwoordelijke", "De leverancier verwerkt gegevens in opdracht en is verwerker; het kantoor blijft verantwoordelijk."], ["De leverancier wordt automatisch de enige verwerkingsverantwoordelijke", "Het kantoor bepaalt het doel en de middelen en blijft verantwoordelijk."], ["Er zijn geen afspraken nodig, omdat de leverancier zelf de AVG moet naleven en daarvoor zelf aansprakelijk is", "De AVG eist juist schriftelijke afspraken met een verwerker."], ["Alleen toestemming van iedere klant is vereist", "Het gaat hier om een verwerkersrelatie, die een overeenkomst vereist en geen toestemming."]]],
["Wie moeten de eed of belofte financiële sector afleggen?", [["Niet alleen bestuurders, maar ook medewerkers van een financiële onderneming in Nederland, bijvoorbeeld met klantcontact", "De eed of belofte geldt voor bestuurders en commissarissen en ook voor veel medewerkers, zoals degenen die rechtstreeks met klanten werken."], ["Uitsluitend bestuurders en commissarissen van banken en verzekeraars die onder prudentieel toezicht van DNB staan", "De verplichting is breder en geldt ook voor medewerkers, en niet alleen bij banken."], ["Alleen adviseurs die zelfstandig ondernemer zijn", "De eed is niet beperkt tot zelfstandigen; juist medewerkers in dienst vallen er ook onder."], ["Alleen medewerkers die een strafblad hebben gehad", "De eed is een algemene integriteitsverklaring en hangt niet af van het verleden van de medewerker."]]],
["Wat is de strekking van de eed of belofte financiële sector?", [["Integer en zorgvuldig handelen, het klantbelang centraal stellen en het vertrouwen in de financiële sector bevorderen", "De eed onderstreept de persoonlijke verantwoordelijkheid van medewerkers voor een integere sector."], ["De belofte om de winst van de werkgever zo groot mogelijk te maken en de aandeelhouders daarover jaarlijks te informeren", "De eed draait niet om winst, maar om integriteit en klantbelang."], ["De belofte om nooit een fout te maken in een advies", "Fouten zijn menselijk; de eed gaat over integer en zorgvuldig handelen."], ["De belofte om alleen producten van de eigen werkgever aan te bieden", "De eed bevat geen productvoorkeur; het belang van de klant staat centraal."]]],
["Binnen welke termijn na aanvang van de werkzaamheden moet een medewerker de eed of belofte financiële sector in beginsel afleggen?", [["Binnen drie maanden", "De regeling gaat uit van het afleggen van de eed of belofte binnen drie maanden nadat iemand de werkzaamheden is gaan verrichten."], ["Binnen één week", "Een termijn van één week schrijft de regeling niet voor."], ["Binnen twee jaar", "Twee jaar is veel langer dan de termijn die de regeling hanteert."], ["Pas bij het behalen van het eerste PE-examen", "De eed staat los van de PE-systematiek."]]],
["Wat wordt verstaan onder een integriteitsrisico voor een financiële onderneming?", [["Het risico op aantasting van reputatie of vermogen door niet-integer gedrag, zoals fraude of witwassen", "Een integere bedrijfsvoering vraagt dat de onderneming deze risico's analyseert en beheerst."], ["Het risico dat de rente op de kapitaalmarkt stijgt", "Dat is een marktrisico, geen integriteitsrisico."], ["Het risico dat een klant zijn premie niet op tijd betaalt", "Dat is een kredietrisico, geen integriteitsrisico."], ["Het risico dat de software van het kantoor verouderd raakt en klantgegevens daardoor onbereikbaar worden", "Dat is een operationeel of IT-risico, geen integriteitsrisico in de eigenlijke zin."]]],
["Een collega stelt voor om het inkomen op een werkgeversverklaring wat hoger in te vullen, zodat de gewenste hypotheek toch past. Wat is de juiste reactie?", [["Niet meewerken en het voorval intern melden, bijvoorbeeld bij compliance of de leidinggevende", "Het aanpassen van inkomensgegevens is hypotheekfraude en raakt de integriteit van de onderneming."], ["Meewerken, omdat het in het belang van de klant is", "Een te hoge lening is niet in het belang van de klant en het aanpassen is fraude."], ["Meewerken, zolang het om een klein bedrag gaat", "Ook een kleine aanpassing van gegevens is fraude."], ["Niets doen en het aan de geldverstrekker overlaten om de werkgeversverklaring bij de acceptatie te controleren", "Wegkijken past niet bij integer handelen; de onderneming moet zelf ingrijpen."]]],
["Wat kenmerkt een annuïteitenlening bij een gelijkblijvende rente?", [["De bruto maandlast blijft gelijk; het rentedeel daalt en het aflossingsdeel stijgt", "Bij annuïteiten verschuift de samenstelling van de vaste termijn geleidelijk van rente naar aflossing."], ["Er wordt elke maand hetzelfde bedrag afgelost, zodat de bruto maandlast in de loop van de tijd daalt", "Dit is het kenmerk van een lineaire lening."], ["Er wordt pas aan het einde van de looptijd in één keer afgelost", "Dit kenmerkt een aflossingsvrije lening."], ["Het rentedeel blijft gelijk en het aflossingsdeel daalt", "Het rentedeel daalt juist, omdat de schuld steeds kleiner wordt."]]],
["Twee leningen hebben dezelfde hoofdsom, rente en looptijd. De ene wordt lineair afgelost, de andere annuïtair. Welke uitspraak is juist?", [["Bij de lineaire lening wordt in totaal minder rente betaald", "Bij lineair aflossen daalt de schuld in het begin sneller, waardoor de totale rente lager is."], ["Bij de annuïtaire lening wordt in totaal minder rente betaald", "Bij annuïteiten wordt in het begin juist minder afgelost, zodat over meer schuld rente wordt betaald."], ["Beide leningen leiden tot precies dezelfde totale rente", "Door het verschillende aflossingsverloop verschilt de totale rente."], ["De totale rente hangt alleen af van de inflatie", "De totale rente hangt af van rente, looptijd en aflossingsverloop, niet van inflatie."]]],
["Iemand zet € 1.000,00 op een spaarrekening tegen 10% rente per jaar. De rente wordt jaarlijks bijgeschreven en gaat meerenten. Hoeveel staat er na twee jaar op de rekening?", [["€ 1.210,00", "Na een jaar is het € 1.100,00; daarover 10% rente geeft na twee jaar € 1.210,00 (rente-op-rente)."], ["€ 1.200,00", "Dit is de uitkomst bij enkelvoudige rente, waarbij de rente niet meerent."], ["€ 1.100,00", "Dit is het saldo na één jaar, niet na twee jaar."], ["€ 1.020,00", "Dit zou passen bij 1% rente per jaar, niet bij 10%."]]],
["De spaarrente bedraagt 2% en de inflatie 3%. Wat gebeurt er met de koopkracht van het spaargeld, belastingen buiten beschouwing gelaten?", [["De koopkracht daalt, omdat de prijzen sneller stijgen dan het spaartegoed groeit", "Het reële rendement is negatief; met het tegoed kan na een jaar minder worden gekocht."], ["De koopkracht stijgt, omdat er rente wordt bijgeschreven", "De nominale groei is lager dan de prijsstijging, dus de koopkracht stijgt niet."], ["De koopkracht blijft gelijk, omdat rente en inflatie elkaar over een heel jaar gemeten opheffen", "Rente en inflatie zijn hier niet gelijk; de inflatie is hoger."], ["De koopkracht hangt alleen af van de hoogte van het saldo", "Koopkracht wordt bepaald door de verhouding tussen tegoed en prijsniveau."]]],
["Tot welk bedrag beschermt het depositogarantiestelsel het spaargeld van een rekeninghouder als zijn bank failliet gaat?", [["€ 100.000,00 per rekeninghouder per bank", "Deze Europees geharmoniseerde dekking geldt voor tegoeden op betaal- en spaarrekeningen bij een bank."], ["€ 20.000,00 per rekeninghouder per bank", "Dit was een veel lagere dekking uit het verleden; het huidige bedrag is hoger."], ["€ 50.000,00 per rekening, ongeacht het aantal rekeningen", "De dekking geldt per rekeninghouder per bank, niet per rekening."], ["Onbeperkt, zolang de bank onder toezicht van DNB staat", "De garantie is begrensd; boven het maximum is spaargeld niet gedekt."]]],
["Wat houdt het indemniteitsbeginsel bij schadeverzekeringen in?", [["De uitkering is niet hoger dan de werkelijk geleden schade; de verzekerde mag er niet beter van worden", "Een schadeverzekering vergoedt het verlies en is niet bedoeld om winst te maken."], ["De verzekeraar keert altijd het verzekerde bedrag uit, ongeacht de schade", "Dat kenmerkt een sommenverzekering, niet een schadeverzekering."], ["De verzekerde mag dezelfde schade bij meerdere verzekeraars volledig claimen, mits hij elke polis zelf betaalt", "Dubbel vergoeden zou de verzekerde verrijken, wat het beginsel juist uitsluit."], ["De premie wordt achteraf vastgesteld op basis van de schade", "Het beginsel gaat over de uitkering, niet over de premievaststelling."]]],
["Een inboedel is verzekerd voor € 30.000,00, maar de werkelijke waarde is € 60.000,00. Er ontstaat € 10.000,00 schade. Er is geen garantie tegen onderverzekering. Wat keert de verzekeraar volgens de evenredigheidsregel uit?", [["€ 5.000,00", "Er is voor de helft van de waarde verzekerd, dus de schade wordt voor de helft vergoed."], ["€ 10.000,00", "Zonder garantie tegen onderverzekering wordt de schade niet volledig vergoed."], ["€ 30.000,00", "Het verzekerde bedrag is een maximum, geen uitkering bij elke schade."], ["€ 3.333,33", "Deze berekening past de verhouding niet juist toe; de verhouding verzekerd/waarde is 1/2."]]],
["In welke box van de inkomstenbelasting valt spaargeld van een particulier?", [["Box 3", "Box 3 belast inkomen uit sparen en beleggen."], ["Box 1", "Box 1 betreft inkomen uit werk en woning, zoals loon en de eigen woning."], ["Box 2", "Box 2 betreft inkomen uit een aanmerkelijk belang in een vennootschap."], ["Spaargeld valt buiten de inkomstenbelasting", "Spaargeld kan in box 3 worden belast, afhankelijk van het vermogen en het heffingvrij vermogen."]]],
["Aan welke aflossingseis moet een nieuwe hypotheeklening voor de eigen woning sinds 2013 in beginsel voldoen om de rente aftrekbaar te laten zijn?", [["De lening moet in maximaal 30 jaar ten minste annuïtair worden afgelost", "Voor nieuwe eigenwoningschulden sinds 1 januari 2013 is renteaftrek gekoppeld aan deze aflossingseis."], ["De lening mag aflossingsvrij zijn als de klant een spaarrekening aanhoudt", "Een nieuwe aflossingsvrije lening voldoet niet aan de aflossingseis voor renteaftrek."], ["De lening moet binnen tien jaar volledig zijn afgelost", "De wet vraagt geen aflossing binnen tien jaar, maar ten minste annuïtair in maximaal 30 jaar."], ["Er geldt geen aflossingseis, zolang de woning de hoofdverblijfplaats is", "Hoofdverblijf is een voorwaarde voor de eigen woning, maar daarnaast geldt de aflossingseis."]]],
["Wat is het verschil tussen een persoonlijke lening en een doorlopend krediet?", [["Persoonlijke lening: vast bedrag en vaste looptijd; doorlopend krediet: binnen een limiet opnemen en terugbetalen", "Dit zijn de kernkenmerken van beide vormen van consumptief krediet."], ["Een persoonlijke lening heeft altijd een variabele rente; een doorlopend krediet heeft juist altijd een vaste rente", "Het is doorgaans andersom: een doorlopend krediet kent meestal een variabele rente."], ["Bij een doorlopend krediet hoeft nooit te worden afgelost", "Ook bij een doorlopend krediet wordt maandelijks een termijn betaald."], ["Een persoonlijke lening wordt niet geregistreerd, een doorlopend krediet wel", "Beide kredietvormen worden in beginsel geregistreerd bij het BKR."]]],
["Wat registreert het Centraal Krediet Informatiesysteem (CKI) van het BKR?", [["Kredieten van consumenten en eventuele betalingsachterstanden daarop", "Kredietverstrekkers raadplegen deze registratie om overkreditering te voorkomen."], ["Het vermogen dat consumenten op hun spaar- en beleggingsrekeningen bij banken hebben", "Spaartegoeden worden niet bij het BKR geregistreerd."], ["Alle verzekeringspolissen van consumenten", "Verzekeringen worden niet in het CKI geregistreerd."], ["Het inkomen van consumenten volgens de Belastingdienst", "Inkomensgegevens maken geen deel uit van het CKI."]]],
["Wat is het verschil tussen een heffingskorting en een aftrekpost in de inkomstenbelasting?", [["Een heffingskorting verlaagt de verschuldigde belasting zelf; een aftrekpost verlaagt het belastbare inkomen", "Een aftrekpost levert voordeel op tegen het tarief, terwijl een heffingskorting direct op de belasting in mindering komt."], ["Een heffingskorting verlaagt het belastbare inkomen; een aftrekpost verlaagt rechtstreeks de verschuldigde belasting zelf", "Dit is precies omgekeerd."], ["Er is geen verschil; beide termen betekenen hetzelfde", "Beide werken op een ander niveau in de belastingberekening."], ["Een heffingskorting geldt alleen voor ondernemers", "Heffingskortingen, zoals de algemene heffingskorting, gelden ook voor particulieren."]]],
["Welke verbintenis heeft een adviseur in de regel op grond van de overeenkomst van opdracht?", [["Een inspanningsverbintenis: hij moet de zorg van een goed opdrachtnemer in acht nemen", "De adviseur belooft zorgvuldig te werken, niet een bepaald resultaat zoals een gegarandeerd rendement."], ["Een resultaatsverbintenis: hij garandeert dat het geadviseerde product het beoogde resultaat oplevert", "Een adviseur garandeert in de regel geen uitkomst; hij moet zorgvuldig handelen."], ["Een verbintenis om alleen te doen wat de klant letterlijk vraagt", "Een goed opdrachtnemer denkt mee en waarschuwt waar nodig."], ["Geen verbintenis, omdat advies vrijblijvend is", "Een adviesopdracht is een overeenkomst waaruit verplichtingen voortvloeien."]]],
["Wat moet een schuldeiser in de regel doen voordat de schuldenaar in verzuim is bij het niet nakomen van een overeenkomst?", [["De schuldenaar in gebreke stellen met een redelijke termijn om alsnog na te komen", "Pas na het verstrijken van die termijn treedt verzuim in, tenzij een uitzondering geldt zoals een fatale termijn."], ["Direct de rechter vragen de overeenkomst te ontbinden", "Ontbinding vraagt in de regel eerst verzuim, en kan ook buitengerechtelijk."], ["De schuldenaar melden bij de AFM", "De AFM speelt geen rol bij de civielrechtelijke nakoming."], ["Niets, verzuim ontstaat altijd automatisch op de dag waarop de afgesproken prestatie had moeten plaatsvinden", "Automatisch verzuim geldt alleen in uitzonderingsgevallen, zoals bij een fatale termijn."]]],
["Wanneer verjaart in de regel een vordering tot schadevergoeding van een klant tegen zijn adviseur?", [["Vijf jaar na bekendheid met schade en aansprakelijke persoon, uiterlijk twintig jaar na de schadeveroorzakende gebeurtenis", "Dit is de hoofdregel in het Burgerlijk Wetboek voor de verjaring van schadevorderingen."], ["Eén jaar na het geven van het advies, ongeacht het moment waarop de klant de schade of de fout ontdekt", "Een termijn van één jaar is niet de hoofdregel voor schadevorderingen."], ["Nooit, een vordering op een adviseur verjaart niet", "Ook vorderingen op adviseurs verjaren."], ["Drie maanden na de eerste klacht bij de adviseur, tenzij de klant binnen die termijn een procedure bij Kifid start", "Deze termijn heeft niets te maken met de civielrechtelijke verjaring."]]],
["Wat moet een verzekeringnemer vóór het sluiten van een verzekering aan de verzekeraar meedelen?", [["De feiten die hij kent of behoort te kennen en waarvan hij weet of moet begrijpen dat ze voor de verzekeraar van belang zijn", "Bij een vragenlijst kan de verzekeraar zich in beginsel niet beroepen op feiten waarnaar niet is gevraagd, behalve bij opzet tot misleiding."], ["Alleen de feiten die de verzekeraar na het sluiten van de verzekering opvraagt, bijvoorbeeld bij de eerste schademelding", "De mededelingsplicht geldt juist vóór het sluiten van de verzekering."], ["Niets, de verzekeraar moet zelf alle risico's onderzoeken, bijvoorbeeld via een medische keuring of een taxatierapport", "De verzekeringnemer heeft een wettelijke mededelingsplicht."], ["Alleen feiten die in zijn voordeel zijn", "De mededelingsplicht omvat juist de feiten die voor de verzekeraar relevant zijn, ook als ze nadelig zijn."]]],
["Een consument sluit online, op afstand, een schadeverzekering af. Welk herroepingsrecht heeft hij in beginsel?", [["Hij kan de overeenkomst binnen 14 dagen zonder opgave van redenen ontbinden", "Voor financiële diensten op afstand geldt in beginsel een bedenktijd van 14 dagen, met uitzonderingen zoals kortlopende reisverzekeringen."], ["Hij heeft geen herroepingsrecht, omdat het om een financiële dienst gaat en de dekking direct ingaat", "Ook financiële diensten op afstand kennen in beginsel een herroepingsrecht."], ["Hij kan binnen 1 dag herroepen, daarna niet meer", "Een termijn van 1 dag geldt niet; de termijn is aanzienlijk langer."], ["Hij kan op elk moment kosteloos herroepen zonder termijn", "Het herroepingsrecht is aan een termijn gebonden; daarna gelden de normale opzegregels."]]],
["Wat geldt voor een beding in algemene voorwaarden dat op de zwarte lijst staat bij een consumentenovereenkomst?", [["Het beding wordt altijd als onredelijk bezwarend aangemerkt en is vernietigbaar", "Bij de zwarte lijst is geen nadere afweging nodig; bij de grijze lijst wordt onredelijkheid slechts vermoed."], ["Het beding wordt vermoed onredelijk bezwarend te zijn, maar tegenbewijs is mogelijk", "Dit is het kenmerk van de grijze lijst."], ["Het beding is altijd geldig, omdat de consument heeft getekend", "Ondertekening maakt een beding op de zwarte lijst niet geldig."], ["Het beding geldt alleen tussen bedrijven, niet tegenover consumenten", "De zwarte lijst is juist bedoeld om consumenten te beschermen."]]],
["Een medewerker van een advieskantoor maakt bij het advies een fout, waardoor de klant schade lijdt. Bij wie kan de klant de schade in de regel verhalen?", [["Bij het advieskantoor, dat contractspartij is en als werkgever aansprakelijk is voor zijn medewerkers", "De klant heeft de overeenkomst met het kantoor gesloten; ook geldt de werkgeversaansprakelijkheid voor fouten van werknemers."], ["Alleen bij de medewerker persoonlijk", "De klant kan in de regel het kantoor aanspreken; persoonlijke aansprakelijkheid van de werknemer is beperkt."], ["Bij de AFM, omdat die toezicht houdt op het kantoor", "De toezichthouder is niet aansprakelijk voor adviesfouten van een kantoor."], ["Bij de aanbieder van het geadviseerde product, omdat die de polis heeft afgegeven en de premie ontvangt", "De aanbieder is niet verantwoordelijk voor fouten van een zelfstandig advieskantoor."]]],
["Welke van de volgende regelingen is een werknemersverzekering?", [["De WIA", "De WIA is een werknemersverzekering bij langdurige arbeidsongeschiktheid, gefinancierd met premies via de werkgever."], ["De AOW", "De AOW is een volksverzekering voor iedereen die in Nederland woont of werkt."], ["De Anw", "De Anw is een volksverzekering voor nabestaanden."], ["De Wet langdurige zorg", "De Wlz is een volksverzekering voor langdurige zorg."]]],
["Een werknemer wordt langdurig ziek. Wanneer kan een WIA-uitkering in de regel op zijn vroegst ingaan?", [["Na 104 weken ziekte", "De werkgever betaalt in de regel twee jaar het loon door; daarna kan een WIA-uitkering ingaan."], ["Na 13 weken ziekte", "Na 13 weken is er nog sprake van loondoorbetaling door de werkgever."], ["Direct op de eerste ziektedag", "De WIA gaat pas in na de wachttijd van twee jaar."], ["Pas na vijf jaar ziekte", "De wachttijd voor de WIA is korter."]]],
["Wanneer heeft iemand recht op een IVA-uitkering binnen de WIA?", [["Als hij volledig en duurzaam arbeidsongeschikt is", "De IVA is bedoeld voor wie geen of nauwelijks kans op herstel heeft en volledig arbeidsongeschikt is."], ["Als hij gedeeltelijk arbeidsongeschikt is en kans op herstel heeft", "In die situatie is de WGA van toepassing, niet de IVA."], ["Als hij minder dan 35% arbeidsongeschikt is", "Bij minder dan 35% arbeidsongeschiktheid is er in beginsel geen recht op een WIA-uitkering."], ["Als hij werkloos is geworden na een reorganisatie", "Werkloosheid valt onder de WW, niet onder de IVA."]]],
["Een werknemer is na twee jaar ziekte voor minder dan 35% arbeidsongeschikt verklaard. Wat geldt in beginsel?", [["Hij heeft in beginsel geen recht op een WIA-uitkering", "Onder de 35% ontstaat geen WIA-recht; werkgever en werknemer zoeken naar passend werk."], ["Hij krijgt een IVA-uitkering voor de duur van zijn arbeidsongeschiktheid", "De IVA geldt alleen bij volledige en duurzame arbeidsongeschiktheid."], ["Hij krijgt een AOW-uitkering tot aan zijn pensioen", "De AOW is een ouderdomsvoorziening en hangt niet af van arbeidsongeschiktheid."], ["Hij krijgt automatisch een Anw-uitkering", "De Anw is bedoeld voor nabestaanden, niet voor arbeidsongeschikten."]]],
["Een zzp'er vraagt welke wettelijke voorziening hem beschermt als hij langdurig arbeidsongeschikt raakt. Wat is juist?", [["Hij valt als zelfstandige in beginsel niet onder de WIA en moet dit risico zelf afdekken", "De WIA is een werknemersverzekering; zelfstandigen moeten zelf voor dekking zorgen."], ["Hij valt automatisch onder de WIA, net als werknemers, zodra hij bij de KvK staat ingeschreven", "De WIA geldt voor werknemers, niet voor zelfstandigen zonder werknemersstatus."], ["Hij krijgt een AOW-uitkering zodra hij arbeidsongeschikt is", "De AOW hangt af van leeftijd, niet van arbeidsongeschiktheid."], ["Hij heeft recht op een WW-uitkering", "De WW geldt voor werknemers die werkloos worden, niet voor arbeidsongeschikte zelfstandigen."]]],
["Waarom is de Anw-uitkering voor veel nabestaanden geen toereikende voorziening?", [["Omdat er alleen onder strikte voorwaarden recht op is, zoals de zorg voor een kind onder 18 jaar, en er een inkomenstoets geldt", "Veel nabestaanden voldoen niet aan de voorwaarden of krijgen door hun inkomen een lagere uitkering; een overlijdensrisicoverzekering kan dit gat dichten."], ["Omdat de Anw alleen geldt voor gehuwden die langer dan twintig jaar getrouwd zijn en geen eigen pensioen hebben opgebouwd", "Een dergelijke huwelijksduur is geen voorwaarde voor de Anw."], ["Omdat de Anw uitsluitend wordt uitgekeerd aan kinderen", "De Anw kent een uitkering voor de nabestaande partner en een wezenuitkering."], ["Omdat de Anw pas ingaat bij het bereiken van de AOW-leeftijd", "De Anw is juist bedoeld voor nabestaanden vóór de AOW-leeftijd."]]],
["Hoe bouwt iemand recht op AOW op?", [["Met 2% per jaar dat hij in Nederland woont of werkt in de 50 jaar vóór de AOW-leeftijd", "Wie die volledige periode verzekerd is geweest, heeft recht op een volledige AOW; elk ontbrekend jaar kost 2%."], ["Door per jaar premie te betalen in een individuele pensioenpot die bij de SVB wordt belegd", "De AOW is een omslagstelsel; er wordt geen individuele pot opgebouwd."], ["Alleen via de werkgever bij een pensioenfonds", "Pensioen via de werkgever is de tweede pijler; de AOW is de eerste pijler."], ["Met 1% per jaar dat iemand in loondienst heeft gewerkt", "De opbouw hangt af van wonen of werken in Nederland, niet alleen van loondienst, en bedraagt 2% per jaar."]]],
["Wat is volgens de SFDR het verschil tussen een artikel 8- en een artikel 9-product?", [["Een artikel 8-product promoot ecologische of sociale kenmerken; een artikel 9-product heeft duurzame beleggingen als doelstelling", "Artikel 9-producten hebben duurzaamheid als expliciet doel en worden vaak als donkergroen aangeduid."], ["Een artikel 8-product heeft duurzame beleggingen als doelstelling; een artikel 9-product promoot alleen ecologische of sociale kenmerken", "Dit is precies omgekeerd."], ["Een artikel 8-product is altijd een spaarproduct; een artikel 9-product altijd een aandelenfonds", "De artikelen gaan over duurzaamheidsambitie, niet over het soort product."], ["Er is geen verschil; beide artikelen gelden voor alle beleggingsfondsen", "De artikelen onderscheiden juist producten met een verschillend duurzaamheidsprofiel."]]],
["Wat is een duurzaamheidsrisico in de zin van de SFDR?", [["Een ecologische, sociale of governancegebeurtenis of -omstandigheid die de waarde van een belegging wezenlijk negatief kan beïnvloeden", "Het gaat om het risico dat duurzaamheidsfactoren de waarde van de belegging raken."], ["Het risico dat een duurzame belegging over een periode van vijf jaar minder rendement oplevert dan de gemiddelde markt", "Een lager rendement op zich is geen duurzaamheidsrisico in de zin van de SFDR."], ["Het risico dat een klant geen duurzaamheidsvoorkeuren heeft", "Klantvoorkeuren zijn een ander begrip dan het duurzaamheidsrisico van een belegging."], ["Het risico dat de AFM een product als niet duurzaam beoordeelt", "De SFDR omschrijft het risico vanuit de belegging, niet vanuit de toezichthouder."]]],
["Bij welke dienstverlening moet een adviseur in beginsel vragen naar de duurzaamheidsvoorkeuren van de klant?", [["Bij advies over verzekeringsgebaseerde beleggingsproducten en bij beleggingsadvies", "Sinds 2 augustus 2022 maken duurzaamheidsvoorkeuren deel uit van de geschiktheidsbeoordeling bij deze vormen van advies."], ["Bij iedere schadeverzekering, zoals een autoverzekering", "Voor gewone schadeverzekeringen geldt deze uitvraag niet."], ["Alleen bij zakelijke klanten met meer dan vijftig werknemers die onder de rapportageplicht van de CSRD vallen", "De uitvraag geldt juist bij advies aan klanten, ongeacht een werknemersaantal."], ["Nooit; het vragen naar duurzaamheid is volledig vrijwillig", "Bij de genoemde vormen van advies is het een verplicht onderdeel."]]],
["Welke indeling van duurzaamheidsvoorkeuren hanteert de Europese regelgeving bij advies?", [["Minimumaandeel taxonomieconforme beleggingen, minimumaandeel duurzame beleggingen (SFDR) en aandacht voor de belangrijkste ongunstige effecten", "Een klant kan een of meer van deze voorkeuren aangeven, die de adviseur meeneemt in zijn advies."], ["Een voorkeur voor een laag, middel of hoog rendement", "Rendementswens hoort bij de doelstellingen van de klant, niet bij de duurzaamheidsvoorkeuren."], ["Een voorkeur voor Nederlandse, Europese of wereldwijde beleggingen", "Een regionale voorkeur is geen wettelijke categorie van duurzaamheidsvoorkeuren."], ["Een voorkeur voor groen, oranje of rood volgens het AFM-duurzaamheidslabel, aangevuld met een minimale ESG-score per fonds", "Er bestaat geen wettelijk AFM-kleurenlabel voor duurzaamheidsvoorkeuren."]]],
["Een adviseur presenteert een beleggingsverzekering als 'volledig groen', terwijl de aanbieder het product niet als duurzaam classificeert en er geen onderbouwing is. Wat is juist?", [["Dit is greenwashing: misleidende informatie, in strijd met de eis dat informatie correct, duidelijk en niet misleidend is", "Duurzaamheidsclaims moeten kloppen en onderbouwd zijn, net als andere productinformatie."], ["Dit is toegestaan, omdat duurzaamheid een subjectief begrip is", "Ook duurzaamheidsclaims moeten feitelijk juist en onderbouwd zijn."], ["Dit is toegestaan als de klant geen duurzaamheidsvoorkeuren heeft, omdat duurzaamheid dan geen rol speelt in het advies", "Ook tegenover een klant zonder voorkeuren mag informatie niet misleidend zijn."], ["Dit is alleen een probleem als de AFM het product vooraf heeft gekeurd", "De AFM keurt producten niet vooraf; de informatieplicht geldt altijd."]]],
["Een klant geeft bij een beleggingsadvies aan geen duurzaamheidsvoorkeuren te hebben. Wat is juist?", [["De adviseur legt dit vast; hij mag dan zowel producten met als zonder duurzame kenmerken adviseren", "Een klant zonder voorkeuren wordt als duurzaamheidsneutraal behandeld; het advies moet verder gewoon passend zijn."], ["De adviseur mag dan alleen producten zonder enig duurzaam kenmerk adviseren, zoals een artikel 6-product", "Ook producten met duurzame kenmerken mogen worden geadviseerd aan een klant zonder voorkeuren."], ["De adviseur mag de klant dan geen advies meer geven", "Het ontbreken van voorkeuren staat advies niet in de weg."], ["De adviseur moet de klant verplichten toch een voorkeur te kiezen", "Het aangeven van voorkeuren is een keuze van de klant, geen verplichting."]]]
],
"consumptief-krediet":[
["Wat kenmerkt een doorlopend krediet?", [["Een kredietlimiet waarbinnen de consument opnieuw kan opnemen wat is afgelost", "Bij een doorlopend krediet ontstaat door aflossing weer opnameruimte tot de afgesproken limiet."], ["Een vast leenbedrag dat in een vast aantal termijnen wordt afgelost", "Dat beschrijft een persoonlijke lening; afgeloste bedragen kunnen daar niet opnieuw worden opgenomen."], ["Een lening waarbij de zaak pas na de laatste termijn eigendom wordt", "Dat is huurkoop; bij doorlopend krediet wordt geld geleend, geen zaak in termijnen gekocht."], ["Een krediet dat uitsluitend via een daaraan gekoppelde creditcard kan worden opgenomen", "Een creditcard kan aan een doorlopend krediet gekoppeld zijn, maar dat is geen kenmerk van elk doorlopend krediet."]]],
["Wat is kenmerkend voor een persoonlijke lening?", [["Een vast bedrag, een vaste looptijd en doorgaans een vaste rente", "Bij een persoonlijke lening ligt vooraf vast hoeveel er wordt geleend en in hoeveel termijnen het wordt afgelost."], ["Een variabele limiet die de consument zelf kan verhogen", "Een limiet waarbinnen opnieuw kan worden opgenomen hoort bij doorlopend krediet, niet bij de persoonlijke lening."], ["Een lening zonder rente die binnen drie maanden wordt terugbetaald", "Dat lijkt op uitgesteld betalen (BNPL); een persoonlijke lening heeft een langere looptijd en rente."], ["Een lening met een woning als onderpand en renteaftrek", "Een lening met hypotheekrecht op de woning is hypothecair krediet, geen persoonlijke lening."]]],
["Mevrouw Bakker heeft vijf jaar geleden een persoonlijke lening van € 15.000,00 afgesloten en wil nu een deel aflossen en het bedrag later weer opnemen. Wat is juist?", [["Afgeloste bedragen bij een persoonlijke lening kunnen niet opnieuw worden opgenomen", "Een persoonlijke lening is een aflopend krediet; voor opnieuw lenen is een nieuwe kredietaanvraag nodig."], ["Zij kan het afgeloste bedrag opnemen zolang de looptijd niet is verstreken", "Opnemen binnen een limiet kan alleen bij doorlopend krediet, niet bij een aflopende lening."], ["Zij mag niet extra aflossen omdat de looptijd vastligt", "De consument heeft altijd het recht om geheel of gedeeltelijk vervroegd af te lossen."], ["De kredietgever moet het afgeloste deel automatisch als nieuwe limiet beschikbaar stellen", "Er bestaat geen verplichting om een aflopende lening om te zetten in een opneembare limiet."]]],
["Wat is het verschil tussen huurkoop en koop op afbetaling?", [["Bij huurkoop gaat het eigendom pas over na betaling van de laatste termijn", "Bij huurkoop blijft de verkoper eigenaar tot alles is betaald; bij koop op afbetaling gaat het eigendom direct over."], ["Bij huurkoop gaat het eigendom direct over bij de aflevering", "Dit is juist het kenmerk van koop op afbetaling, niet van huurkoop."], ["Huurkoop is alleen mogelijk voor onroerende zaken zoals woningen en bedrijfspanden", "Huurkoop komt in de consumentenmarkt juist voor bij roerende zaken zoals auto's en apparaten."], ["Bij huurkoop betaalt de consument nooit rente of kosten", "Ook bij huurkoop kan een kredietvergoeding in de termijnen zijn verwerkt."]]],
["Wat is in de regel kenmerkend voor private lease van een auto?", [["De consument betaalt een vast maandbedrag voor het gebruik en wordt geen eigenaar", "Bij private lease huurt de consument de auto voor een vaste periode; de leasemaatschappij blijft eigenaar."], ["De consument wordt na de laatste termijn automatisch eigenaar van de auto", "Automatische eigendomsoverdracht past bij huurkoop of financiële lease, niet bij gewone private lease."], ["De consument draagt zelf alle onderhouds- en verzekeringskosten apart", "Bij private lease zitten onderhoud en verzekering doorgaans juist in het maandbedrag."], ["Private lease is een vorm van hypothecair krediet waarbij de auto als onderpand dient", "Een auto kan geen onderpand voor hypothecair krediet zijn; private lease is een huurconstructie."]]],
["Waarom is een private-leasecontract relevant bij een latere hypotheekaanvraag van de consument?", [["De leaseverplichting telt mee als vaste last en beperkt de leencapaciteit", "Een private-leasecontract wordt bij BKR geregistreerd en geldt bij de hypotheektoets als financiële verplichting."], ["Private lease wordt niet geregistreerd en speelt daarom geen rol", "Private-leasecontracten worden sinds enkele jaren bij BKR geregistreerd en zijn dus zichtbaar voor kredietgevers."], ["De leaseauto mag als extra onderpand voor de hypotheek dienen", "De auto is eigendom van de leasemaatschappij en kan geen onderpand voor de hypotheek zijn."], ["Het leasebedrag is fiscaal aftrekbaar in box 1 en verhoogt daardoor het toetsinkomen", "Private-leasetermijnen zijn voor een particulier niet aftrekbaar en verhogen het inkomen niet."]]],
["Wat is buy now pay later (BNPL)?", [["Achteraf of in termijnen betalen, vaak zonder rente bij tijdige betaling", "BNPL laat de consument later of gespreid betalen; kosten ontstaan meestal pas bij te laat betalen."], ["Een spaarvorm waarbij de consument eerst spaart en daarna koopt", "Bij BNPL koopt de consument eerst en betaalt later, wat juist een vorm van krediet is."], ["Een doorlopend krediet met een limiet die vast aan een creditcard van de winkel hangt", "BNPL is meestal gekoppeld aan een specifieke aankoop, niet aan een opneembare limiet."], ["Een betaalwijze waarbij de verkoper vooraf het volledige bedrag int", "Bij vooruitbetaling is er geen uitstel van betaling en dus geen krediet."]]],
["Wat is een geoorloofde debetstand (rood staan)?", [["Een vooraf afgesproken mogelijkheid om tot een limiet negatief te staan op de betaalrekening", "Bij een geoorloofde debetstand heeft de bank met de klant een kredietlimiet op de betaalrekening afgesproken."], ["Een negatief saldo dat de bank stilzwijgend toestaat zonder enige voorafgaande afspraak met de klant", "Een stilzwijgend aanvaarde debetstand zonder of boven de afspraak heet een overschrijding."], ["Een lening met een vaste looptijd die op de betaalrekening wordt uitbetaald", "Dat is een persoonlijke lening; de uitbetaling op de betaalrekening maakt het geen debetstand."], ["Een betalingsachterstand op de termijnen van een persoonlijke lening", "Een achterstand op een lening is geen debetstand op een betaalrekening."]]],
["Meneer De Vries staat zonder afspraak met de bank € 400,00 rood op zijn betaalrekening; de bank laat dit toe. Hoe heet dit?", [["Een overschrijding", "Een stilzwijgend aanvaarde negatieve stand zonder afgesproken limiet of boven de limiet heet een overschrijding."], ["Een geoorloofde debetstand", "Daarvoor is een vooraf afgesproken limiet nodig, die hier ontbreekt."], ["Een persoonlijke lening", "Er is geen leenbedrag met vaste looptijd afgesproken."], ["Huurkoop", "Huurkoop betreft de koop van een zaak in termijnen, niet een negatief saldo."]]],
["Wanneer is sprake van consumptief krediet in de zin van de Wft?", [["Bij krediet aan een natuurlijk persoon die buiten zijn beroep of bedrijf handelt", "De Wft beschermt de consument; krediet voor privédoeleinden aan een natuurlijk persoon valt eronder."], ["Bij elk krediet aan een natuurlijk persoon, ook als het voor zijn eenmanszaak bestemd is", "Krediet dat een ondernemer voor zijn bedrijf aangaat, is zakelijk krediet en geen consumptief krediet."], ["Alleen bij krediet dat door een bank met bankvergunning wordt verstrekt", "Ook andere kredietaanbieders met een Wft-vergunning verstrekken consumptief krediet."], ["Alleen bij krediet met een looptijd van langer dan vijf jaar", "De looptijd bepaalt niet of iets consumptief krediet is."]]],
["Wat is een gelieerde kredietovereenkomst?", [["Een krediet dat alleen dient voor een bepaalde aankoop en daarmee een eenheid vormt", "Bijvoorbeeld een lening via de autodealer voor die auto: koop en krediet hangen samen, met gevolgen voor herroeping en verweer."], ["Een krediet dat aan een spaarrekening van de consument is gekoppeld", "Een koppeling met een spaarrekening maakt een krediet niet gelieerd in deze zin."], ["Een krediet dat twee partners samen aangaan, waarbij ieder hoofdelijk aansprakelijk is", "Gezamenlijk lenen gaat over aansprakelijkheid, niet over de band tussen koop en krediet."], ["Een krediet dat is overgesloten van een andere kredietgever", "Oversluiten maakt een krediet niet gelieerd aan een koopovereenkomst."]]],
["Een consument koopt online een televisie en financiert die met een lening die de webwinkel speciaal voor deze aankoop regelt. Hij herroept de koop tijdig. Wat is in beginsel het gevolg voor het krediet?", [["Het gelieerde krediet eindigt eveneens zonder boete", "Bij een gelieerde kredietovereenkomst werkt de herroeping van de koop door: de consument is ook niet langer aan het krediet gebonden."], ["Het krediet blijft volledig doorlopen tot het einde van de looptijd", "Omdat koop en krediet een commerciële eenheid vormen, blijft het krediet niet zonder meer bestaan."], ["De consument moet een boete van de volledige resterende rente betalen", "Een dergelijke boete past niet bij het einde van een gelieerd krediet na het vervallen van de koop."], ["Het krediet wordt automatisch omgezet in een doorlopend krediet", "Er bestaat geen regel die het krediet omzet in een ander kredietproduct."]]],
["Wie moet vóór het sluiten van een consumptief krediet de kredietwaardigheid van de consument beoordelen?", [["De kredietaanbieder", "De wettelijke plicht om overkreditering te voorkomen ligt bij de aanbieder, ook als een bemiddelaar betrokken is."], ["Uitsluitend de bemiddelaar", "Een bemiddelaar verzamelt gegevens en adviseert, maar de toetsplicht van de aanbieder blijft bestaan."], ["Stichting BKR", "BKR registreert kredieten maar beoordeelt geen aanvragen."], ["De AFM als toezichthouder", "De AFM houdt toezicht op de naleving, maar toetst geen individuele kredietaanvragen."]]],
["Wat is het doel van de kredietwaardigheidstoets bij consumptief krediet?", [["Voorkomen dat de consument een krediet aangaat dat hij niet verantwoord kan dragen", "De toets beschermt de consument tegen overkreditering en betalingsproblemen."], ["Vaststellen welke rente de aanbieder de consument maximaal kan vragen", "De rente wordt begrensd door de maximale kredietvergoeding, niet door de kredietwaardigheidstoets."], ["Bepalen of de consument recht heeft op aftrek van de betaalde rente", "Rente op consumptief krediet is niet aftrekbaar; de toets heeft daar niets mee te maken."], ["Controleren of de consument zich met een geldig en niet verlopen identiteitsbewijs meldt", "Identificatie hoort bij het cliëntenonderzoek; de kredietwaardigheidstoets gaat over draagkracht."]]],
["Welke gegevensbron moet een kredietaanbieder in Nederland bij een aanvraag voor consumptief krediet raadplegen?", [["Het kredietregistratiesysteem (CKI) van BKR", "Aanbieders moeten een stelsel van kredietregistratie raadplegen; in Nederland is dat het CKI van Stichting BKR."], ["Het Kadaster en de openbare registers", "Het Kadaster registreert onroerend goed en hypotheekrechten, niet consumptieve kredieten."], ["Het polisregister van het UWV", "Het polisregister bevat inkomensgegevens, maar is niet het verplichte kredietregistratiestelsel."], ["Uitsluitend het Centraal Insolventieregister", "Het insolventieregister kan aanvullend nuttig zijn, maar vervangt de BKR-toetsing niet."]]],
["Waarop zijn de leennormen in de Gedragscode van de VFN op hoofdlijnen gebaseerd?", [["Netto inkomen minus woonlast en een Nibud-normbedrag voor levensonderhoud", "De VFN-normen bepalen de afloscapaciteit uit inkomen, woonlast en Nibud-gebaseerde normbedragen."], ["Uitsluitend het bruto jaarinkomen vermenigvuldigd met een vaste factor", "Een vaste inkomensfactor houdt geen rekening met woonlasten en huishoudsituatie."], ["De marktwaarde van de woning van de consument en zijn partner", "Bij consumptief krediet staat de draagkracht centraal, niet de woningwaarde."], ["De hoogte van het spaarsaldo en de beleggingen van de consument", "Vermogen kan meewegen, maar is niet de basis van de VFN-leennormen."]]],
["Wat is de VFN in de context van consumptief krediet?", [["De brancheorganisatie van aanbieders van consumptief krediet", "De Vereniging van Financieringsondernemingen in Nederland stelt onder meer een gedragscode met leennormen op."], ["De toezichthouder op consumptief krediet", "Het gedragstoezicht ligt bij de AFM; de VFN is een brancheorganisatie."], ["Het centrale register waarin alle consumptieve kredieten worden vastgelegd", "Kredietregistratie gebeurt bij BKR, niet bij de VFN."], ["De geschilleninstantie voor klachten over krediet", "Geschillen over financiële diensten gaan naar Kifid."]]],
["Welke gegevens houdt BKR bij in het Centraal Krediet Informatiesysteem?", [["Lopende en afgeloste kredieten en eventuele betalingsachterstanden", "Het CKI bevat zowel positieve registraties (kredieten) als negatieve (achterstanden)."], ["Alleen kredieten waarop een achterstand is ontstaan", "BKR registreert ook kredieten zonder achterstand; dat zijn positieve registraties."], ["Het inkomen en vermogen van de consument", "BKR registreert kredieten, geen inkomens- of vermogensgegevens."], ["Alle betalingen die de consument met zijn betaalpas of creditcard doet", "Betaalgegevens worden niet aan BKR doorgegeven."]]],
["Wat betekent een achterstandscode A in het BKR?", [["Er is een betalingsachterstand gemeld", "Code A registreert dat de consument niet volgens afspraak heeft betaald."], ["Het krediet is volledig afgelost en beëindigd", "Volledige aflossing wordt als einddatum geregistreerd, niet als code A."], ["De consument heeft een kredietaanvraag ingediend", "Een aanvraag is geen achterstandscode."], ["De kredietlimiet van het krediet is verhoogd", "Een limietwijziging is een wijziging van het contract, geen achterstand."]]],
["Wat betekent een code H in het BKR?", [["De gemelde achterstand is ingelopen (herstel)", "Code H laat zien dat de consument de eerder gemelde achterstand heeft ingehaald."], ["Er is een hypothecaire lening geregistreerd", "Hypotheken staan niet als code H in het CKI; H is een herstelcode."], ["Het krediet is door de kredietgever opgeëist", "Opeising is een andere bijzonderheid dan herstel."], ["De consument heeft het krediet tijdig herroepen", "Herroeping is geen BKR-code; H staat voor herstel."]]],
["Een klant heeft een doorlopend krediet met een limiet van € 10.000,00, waarvan niets is opgenomen. Hoe gaat dit krediet in de regel mee in de toets bij een nieuwe kredietaanvraag?", [["Als last op basis van een fictieve maandtermijn over de volledige limiet", "Omdat de klant de limiet op elk moment kan opnemen, wordt gerekend met de limiet en niet met het opgenomen saldo."], ["Het telt niet mee, omdat er van de limiet niets is opgenomen", "De opnameruimte kan elk moment worden gebruikt; het niet-opgenomen deel wordt daarom niet genegeerd."], ["Alleen de rente die feitelijk over het krediet wordt betaald telt mee", "Zonder opname is er geen rente, maar het risico van de limiet blijft bestaan."], ["Het krediet verhoogt juist de leencapaciteit van de klant omdat het als buffer geldt", "Een openstaande limiet vermindert de ruimte voor nieuw krediet."]]],
["Een aanvrager vraagt een persoonlijke lening aan; de kredietaanbieder wijst af op basis van de BKR-raadpleging. Wat moet de aanbieder doen?", [["De consument direct en kosteloos informeren over de raadpleging en het resultaat", "Bij afwijzing op basis van een databankraadpleging moet de consument daarover worden geïnformeerd, zodat hij de gegevens kan controleren."], ["Niets melden, omdat de reden van afwijzing bedrijfsvertrouwelijk is", "Juist bij een afwijzing op basis van een registratie heeft de consument recht op die informatie."], ["De consument zonder overleg aanmelden bij de gemeentelijke schuldhulp", "Een afwijzing is geen reden om iemand zonder toestemming bij schuldhulp aan te melden."], ["De BKR-registratie laten verwijderen en de aanvraag daarna opnieuw volledig toetsen", "De aanbieder mag een juiste registratie niet laten verwijderen om een afwijzing te herstellen."]]],
["Een consument meent dat een BKR-registratie onjuist is. Welke stap ligt het meest voor de hand?", [["Inzage vragen en de registrerende kredietgever om correctie verzoeken", "De registrerende kredietgever is verantwoordelijk voor de juistheid; de consument heeft recht op inzage en correctie."], ["De AFM vragen de registratie direct uit het systeem te schrappen", "De AFM beslist niet over individuele BKR-registraties."], ["Een nieuwe lening afsluiten zodat de oude registratie wordt overschreven", "Een nieuwe lening verwijdert geen bestaande registratie en verzwaart de schuldenlast."], ["De Belastingdienst om een verklaring over zijn inkomen vragen", "De Belastingdienst is niet betrokken bij kredietregistraties."]]],
["Een klant met een doorlopend krediet van € 5.000,00 vraagt de limiet te verhogen naar € 15.000,00. Moet de kredietaanbieder de kredietwaardigheid opnieuw beoordelen?", [["Ja, bij een aanzienlijke verhoging is een nieuwe beoordeling vereist", "Een verhoging is materieel een nieuw kredietrisico; de draagkracht moet opnieuw worden getoetst."], ["Nee, de eerdere toets bij het afsluiten van het krediet blijft geldig", "De financiële situatie kan sinds het afsluiten zijn veranderd; een oude toets volstaat niet."], ["Alleen als de consument zelf uitdrukkelijk om een nieuwe toets vraagt", "De toetsplicht is een verplichting van de aanbieder, geen keuze van de consument."], ["Alleen als er op het bestaande krediet een BKR-achterstand bestaat", "Ook zonder achterstand moet bij een aanzienlijke verhoging opnieuw worden getoetst."]]],
["Een zzp'er vraagt een persoonlijke lening aan voor een verbouwing van zijn eigen woning. Welk inkomen is relevant voor de toets?", [["Een duurzaam inkomen, onderbouwd met cijfers over meerdere jaren", "Bij ondernemers kijkt de aanbieder naar het inkomen over meerdere jaren om een betrouwbaar beeld te krijgen."], ["Alleen de omzet van het laatste kwartaal volgens de administratie", "Omzet is geen inkomen en één kwartaal geeft geen duurzaam beeld."], ["Het inkomen dat de klant na afronding van de verbouwing verwacht", "Een verwachting zonder onderbouwing is geen solide basis voor de toets."], ["Geen, omdat zzp'ers zijn uitgesloten van consumptief krediet", "Zelfstandigen kunnen voor privédoelen gewoon consumptief krediet aanvragen."]]],
["Waarom vraagt een kredietaanbieder bij een aanvraag naar de woonlasten van de consument?", [["Woonlasten zijn een vaste last die de afloscapaciteit direct beperkt", "In de leennormen wordt de woonlast van het inkomen afgetrokken voordat de ruimte voor krediet wordt berekend."], ["Om de woning als onderpand te kunnen gebruiken", "Bij consumptief krediet wordt de woning doorgaans niet als onderpand genomen."], ["Om te bepalen of de consument huurtoeslag krijgt", "Toeslagen kunnen relevant zijn voor het inkomen, maar daarvoor wordt niet naar woonlasten gevraagd."], ["Omdat de hoogte van de woonlast de maximale kredietvergoeding van de lening bepaalt", "De maximale kredietvergoeding staat los van de woonlast van de consument."]]],
["Welk document moet de consument vóór het sluiten van een consumptief krediet ontvangen om aanbiedingen te kunnen vergelijken?", [["De Standaard Europese consumentenkredietinformatie", "De SECCI is het gestandaardiseerde informatieformulier voor consumentenkrediet en maakt vergelijking mogelijk."], ["Het Europees gestandaardiseerd informatieblad (ESIS)", "Het ESIS is het Europese informatieformulier voor hypothecair krediet."], ["Het essentiële-informatiedocument (EID) onder PRIIPs", "Het EID hoort bij verpakte beleggings- en verzekeringsproducten onder PRIIPs."], ["Het Uniform Pensioenoverzicht van de pensioenuitvoerder", "Het UPO is een pensioenoverzicht en heeft niets met krediet te maken."]]],
["Wat drukt het jaarlijkse kostenpercentage (JKP) uit?", [["De totale kosten van het krediet als jaarlijks percentage van het kredietbedrag", "Het JKP omvat rente en alle andere verplichte kosten en maakt kredieten onderling vergelijkbaar."], ["Alleen de nominale debetrente die over het uitstaande krediet op jaarbasis wordt berekend", "De debetrente is slechts één onderdeel; het JKP omvat ook andere verplichte kosten."], ["Het percentage van het netto inkomen dat maandelijks aan de lening opgaat", "Dat is een woonquote- of lastenbegrip, niet het JKP."], ["De maximale rente die de AFM ieder jaar voor consumptief krediet vaststelt", "Het JKP is een eigenschap van een concreet krediet, geen door de AFM vastgesteld maximum."]]],
["Welke kosten worden in de totale kosten van het krediet voor de berekening van het JKP niet meegenomen?", [["Kosten bij niet-nakoming, zoals boetes bij een betalingsachterstand", "Het JKP gaat uit van normale nakoming; kosten bij wanbetaling vallen erbuiten."], ["De rente die de consument over het opgenomen krediet verschuldigd is", "De rente is het belangrijkste onderdeel van de kosten van het krediet."], ["Verplichte afsluitkosten die de kredietgever bij aanvang in rekening brengt", "Kosten die de consument verplicht moet betalen om het krediet te krijgen tellen mee."], ["Premie van een verzekering die verplicht is om het krediet te krijgen", "Een verplichte nevendienst als voorwaarde voor het krediet hoort bij de kosten."]]],
["Welke waarschuwing is in Nederland verplicht in reclame voor consumptief krediet?", [["Let op! Geld lenen kost geld", "Deze vaste zin moet duidelijk zichtbaar of hoorbaar in kredietreclame staan."], ["Lenen is een risico, informeer bij de AFM", "Dit is geen wettelijk voorgeschreven tekst."], ["In het verleden behaalde resultaten bieden geen garantie", "Deze tekst hoort bij beleggingsreclame, niet bij krediet."], ["Let op! Rente kan stijgen", "Dit is geen voorgeschreven waarschuwingszin voor kredietreclame."]]],
["Een kredietaanbieder adverteert met een rentepercentage voor een persoonlijke lening. Wat moet de reclame in dat geval ook bevatten?", [["Standaardinformatie met een representatief voorbeeld, waaronder het JKP", "Wie in reclame een rente of ander kostencijfer noemt, moet de standaardinformatie geven met een representatief voorbeeld."], ["Een overzicht van alle klachten die het afgelopen jaar zijn ontvangen", "Klachtgegevens horen niet in kredietreclame."], ["De naam en het registratienummer van de behandelend adviseur", "Reclame hoeft geen persoonlijke adviseur te noemen."], ["Een verklaring dat de AFM het product vooraf heeft goedgekeurd", "De AFM keurt producten of reclame niet vooraf goed."]]],
["Mag een consument vóór het sluiten van een consumptief krediet om een ontwerp van de kredietovereenkomst vragen?", [["Ja, hij kan kosteloos een exemplaar van de ontwerpovereenkomst krijgen", "Tenzij de aanbieder niet bereid is het krediet te verstrekken, heeft de consument recht op een kosteloos ontwerp."], ["Nee, de ontwerpovereenkomst wordt pas bij de ondertekening aan hem verstrekt", "De wet geeft de consument juist het recht vooraf een ontwerp te ontvangen."], ["Ja, maar alleen tegen betaling van administratiekosten", "Het ontwerp moet kosteloos worden verstrekt."], ["Alleen als het kredietbedrag hoger is dan de leennorm", "Het recht op een ontwerp hangt niet af van de hoogte van het krediet."]]],
["Wat houdt de toelichtingsplicht van de kredietaanbieder of -bemiddelaar in?", [["De consument zo toelichten dat hij kan beoordelen of het krediet bij hem past", "Naast de SECCI moet de consument uitleg krijgen over kenmerken, gevolgen en risico's, waaronder die van niet-betalen."], ["Uitsluitend het SECCI-formulier toesturen, zonder daarbij verdere uitleg te geven", "Het formulier alleen is onvoldoende; ook een toelichting is vereist."], ["De consument voor uitleg doorverwijzen naar de website van de AFM", "Doorverwijzen vervangt de eigen toelichting niet."], ["De consument laten tekenen dat hij uitdrukkelijk geen uitleg wenst", "De toelichtingsplicht kan niet zomaar worden weggetekend."]]],
["Welke informatie over betalingsachterstand moet in de precontractuele informatie over consumptief krediet staan?", [["De gevolgen van het niet nakomen van betalingen, zoals extra kosten en registratie", "De consument moet vooraf weten wat er gebeurt als hij niet betaalt, zodat hij het risico kan inschatten."], ["De naam en het adres van het incassobureau dat de kredietgever bij achterstanden inschakelt", "Dat is geen verplicht onderdeel van de precontractuele informatie."], ["Het aantal klanten met een betalingsachterstand bij de aanbieder", "Statistieken van de aanbieder horen niet in de precontractuele informatie."], ["Geen; achterstanden worden pas besproken als ze daadwerkelijk ontstaan", "De gevolgen van achterstanden moeten juist vooraf worden vermeld."]]],
["Een consument met een doorlopend krediet staat al geruime tijd aanzienlijk boven zijn limiet. Wat moet de kredietgever in dat geval doen?", [["De consument informeren over de overschrijding, de rente en de kosten", "Bij een aanzienlijke overschrijding die langer duurt dan een maand moet de consument zonder vertraging worden geïnformeerd."], ["De overschrijding stilzwijgend laten voortduren zonder de consument iets te melden", "De consument moet juist worden geïnformeerd om verdere schuldopbouw te voorkomen."], ["De limiet automatisch verhogen tot het bedrag dat is opgenomen", "Een limietverhoging vraagt een nieuwe kredietwaardigheidstoets en kan niet automatisch."], ["Het krediet en de overschrijding direct bij de AFM melden", "Individuele overschrijdingen worden niet bij de AFM gemeld."]]],
["Een klant ontvangt twee offertes: lening A met lagere rente maar afsluitkosten, lening B zonder afsluitkosten. Welke vergelijking is voor deze klant het meest zuiver?", [["Vergelijk het JKP en het totaal te betalen bedrag van beide leningen", "Het JKP en het totaalbedrag nemen rente én kosten mee en laten zien wat de lening de klant werkelijk kost."], ["Kies altijd de lening met de laagste debetrente op jaarbasis", "De laagste rente kan door afsluitkosten toch duurder uitpakken."], ["Kies altijd de lening met de laagste maandtermijn voor de klant", "Een lage maandtermijn kan het gevolg zijn van een langere looptijd en dus hogere totale kosten."], ["Vergelijk alleen de looptijd en de einddatum van beide leningen met elkaar", "De looptijd zegt op zichzelf niets over de kosten."]]],
["Hoe lang is de herroepingstermijn bij een consumptief krediet?", [["Veertien kalenderdagen", "De consument kan de kredietovereenkomst binnen veertien kalenderdagen zonder opgave van redenen herroepen."], ["Drie werkdagen", "Drie dagen is de bedenktijd bij de koop van een woning, niet bij krediet."], ["Eenentwintig kalenderdagen", "De herroepingstermijn bij consumptief krediet is veertien kalenderdagen, niet eenentwintig."], ["Zeven werkdagen", "Een termijn van zeven werkdagen geldt niet voor consumptief krediet."]]],
["Wanneer begint de herroepingstermijn bij een consumptief krediet te lopen?", [["Bij het sluiten, of later als de consument de informatie pas daarna krijgt", "De termijn start pas als de consument zowel de overeenkomst heeft als de verplichte informatie."], ["Op de dag waarop de eerste maandtermijn wordt afgeschreven", "De eerste betaling is niet bepalend voor de start van de termijn."], ["Op de dag waarop de BKR-registratie van het nieuwe krediet voor het eerst zichtbaar wordt", "BKR-registratie staat los van de herroepingstermijn."], ["Op de dag waarop de consument de kredietaanvraag indient", "Bij de aanvraag is er nog geen overeenkomst die herroepen kan worden."]]],
["Mevrouw Jansen herroept tijdig haar persoonlijke lening, die al op haar rekening is gestort. Wat moet zij doen?", [["Het geleende bedrag en de verlopen rente binnen dertig dagen terugbetalen", "Na herroeping betaalt de consument de hoofdsom en de verlopen rente terug, zonder boete."], ["Niets terugbetalen tot het einde van de oorspronkelijke looptijd van de lening", "Herroeping beëindigt het krediet; het geld moet worden terugbetaald."], ["Een boete van een vast percentage van het kredietbedrag aan de kredietgever betalen", "Bij herroeping is geen boete verschuldigd."], ["Alleen de afsluitkosten betalen en het geleende geld verder houden", "Het geleende geld moet worden terugbetaald; herroepen is niet hetzelfde als lenen zonder kosten."]]],
["Heeft een consument het recht om een persoonlijke lening vervroegd af te lossen?", [["Ja, geheel of gedeeltelijk, hooguit tegen een begrensde vergoeding", "Vervroegd aflossen is een recht; de kredietgever mag hooguit een beperkte, wettelijk gemaximeerde vergoeding vragen."], ["Nee, alleen als de kredietgever daarvoor vooraf toestemming geeft", "De consument heeft dit recht ongeacht de toestemming van de kredietgever."], ["Alleen nadat de helft van de looptijd van de lening is verstreken", "Er geldt geen wachttijd voor vervroegd aflossen."], ["Ja, maar alleen volledig en in één keer, niet gedeeltelijk", "Ook gedeeltelijk vervroegd aflossen is toegestaan."]]],
["Wanneer mag een kredietgever bij vervroegde aflossing van een consumptief krediet geen vergoeding vragen?", [["Als de aflossing valt in een periode waarin de rente variabel is", "De vergoeding dekt alleen nadeel bij een vaste rente; bij variabele rente is geen vergoeding toegestaan."], ["Als de rente vast staat voor de gehele looptijd van het krediet", "Juist bij een vaste rente kan een begrensde vergoeding worden gevraagd."], ["Als de consument met zijn eigen spaargeld vervroegd aflost", "De herkomst van het geld bepaalt niet of een vergoeding mag."], ["Als de resterende looptijd van het krediet langer is dan een jaar", "Bij een resterende looptijd van meer dan een jaar mag juist een (iets hogere) vergoeding worden gevraagd."]]],
["Hoe kan een consument een doorlopend krediet (krediet voor onbepaalde tijd) opzeggen?", [["Kosteloos en op elk moment, met hooguit een maand opzegtermijn", "De consument mag een doorlopend krediet altijd kosteloos opzeggen; een opzegtermijn mag niet langer zijn dan een maand."], ["Alleen na afloop van een minimale looptijd van vijf jaar", "Een dergelijke minimumtermijn is niet toegestaan."], ["Alleen tegen betaling van een opzegvergoeding aan de kredietgever", "Opzeggen van een doorlopend krediet is kosteloos."], ["Alleen met voorafgaande toestemming van de kredietgever", "Toestemming van de kredietgever is niet nodig."]]],
["Mag een kredietgever het recht van de consument om op een doorlopend krediet op te nemen opschorten?", [["Ja, als dat is afgesproken en er objectief gerechtvaardigde gronden zijn", "Bijvoorbeeld bij vermoeden van fraude of een aanzienlijk verhoogd risico dat de consument niet kan terugbetalen."], ["Nee, de afgesproken limiet moet altijd volledig beschikbaar blijven", "Opschorting is mogelijk bij objectief gerechtvaardigde redenen."], ["Ja, op elk gewenst moment en zonder opgave van een reden", "Er is een objectief gerechtvaardigde grond nodig en de consument moet worden geïnformeerd."], ["Alleen nadat de AFM daarvoor in dat specifieke geval vooraf toestemming heeft gegeven", "Voor opschorting in een individueel geval is geen AFM-toestemming nodig."]]],
["Waar is de maximale kredietvergoeding voor consumptief krediet geregeld?", [["In het Besluit kredietvergoeding", "Dit besluit bepaalt het maximum dat aan kosten en rente in rekening mag worden gebracht."], ["In de Tijdelijke regeling hypothecair krediet", "De TRHK bevat leennormen voor hypotheken, geen maximale kredietvergoeding."], ["In de VFN-Gedragscode", "De gedragscode bevat leennormen; het maximum is wettelijk vastgelegd."], ["In de algemene voorwaarden van BKR", "BKR stelt geen tarieven of maxima voor kredieten vast."]]],
["Waaraan is de maximale kredietvergoeding bij consumptief krediet gekoppeld?", [["Aan de wettelijke rente, vermeerderd met een vast aantal procentpunten", "Het maximum beweegt mee met de wettelijke rente, zodat het niet bij elke renteverandering opnieuw hoeft te worden vastgesteld."], ["Aan de depositorente die DNB aan banken vergoedt, plus een opslag", "Het maximum is niet gekoppeld aan een rente van DNB."], ["Aan de gemiddelde hypotheekrente van de drie grootste Nederlandse banken", "Hypotheekrentes zijn niet de grondslag van het maximum."], ["Aan het inkomen van de consument en de hoogte van het krediet", "Het maximum is gelijk voor alle consumenten en hangt niet van het inkomen af."]]],
["Wat valt onder de kredietvergoeding waarop het wettelijk maximum ziet?", [["De rente en alle andere kosten die de consument voor het krediet betaalt", "Het maximum geldt voor de totale vergoeding, zodat het niet kan worden omzeild met losse kosten."], ["Alleen de nominale rente, zonder afsluit- of beheerkosten", "Als alleen de rente telde, kon het maximum worden ontweken met afsluit- of beheerkosten."], ["Alleen de afsluitkosten die bij aanvang van het krediet ineens in rekening worden gebracht", "Ook de rente valt onder de kredietvergoeding."], ["Alleen de kosten die na de eerste maand van het krediet ontstaan", "Het maximum geldt voor alle kosten van het krediet, vanaf de start."]]],
["Een bank rekent over een overschrijding op de betaalrekening van een klant een hoge debetrente. Geldt de maximale kredietvergoeding hier ook?", [["Ja, het maximum geldt ook voor debetstanden en overschrijdingen", "Ook bij rood staan mag de bank niet meer rekenen dan de maximale kredietvergoeding."], ["Nee, alleen voor persoonlijke leningen", "Het maximum is niet beperkt tot persoonlijke leningen."], ["Nee, betaalrekeningen vallen onder vrije tarieven", "Ook krediet op een betaalrekening valt onder het maximum."], ["Alleen als de debetstand op de betaalrekening langer dan een jaar duurt", "De duur van de debetstand bepaalt niet of het maximum geldt."]]],
["Welke wet regelt consumptief krediet voor zover dat niet onder de Wft valt?", [["De Wet op het consumentenkrediet (Wck)", "De Wck is na de invoering van de Wft blijven bestaan voor kredieten die buiten het Wft-regime vallen."], ["De Wet gemeentelijke schuldhulpverlening", "Die wet gaat over de taak van gemeenten bij schuldhulp."], ["De Wet ter voorkoming van witwassen en financieren van terrorisme", "De Wwft gaat over witwassen, niet over kredietovereenkomsten."], ["De Tijdelijke regeling hypothecair krediet", "De TRHK bevat leennormen voor hypothecair krediet."]]],
["Wie houdt gedragstoezicht op aanbieders van en bemiddelaars in consumptief krediet?", [["De AFM", "De AFM ziet toe op het gedrag van financiële ondernemingen tegenover consumenten, ook bij krediet."], ["BKR", "BKR beheert de kredietregistratie, maar is geen toezichthouder."], ["De VFN", "De VFN is een brancheorganisatie met een gedragscode, geen wettelijke toezichthouder."], ["Het Nibud", "Het Nibud levert budgetcijfers, maar houdt geen toezicht."]]],
["Heeft een onderneming die bemiddelt in consumptief krediet in beginsel een AFM-vergunning nodig?", [["Ja, bemiddelen in krediet is een vergunningplichtige financiële dienst", "Bemiddelen in financiële producten, waaronder krediet, mag in beginsel alleen met een vergunning of een geldige uitzondering."], ["Nee, alleen de aanbieder heeft een vergunning nodig", "Ook voor bemiddelen geldt in beginsel een vergunningplicht."], ["Alleen als het krediet hoger is dan de hypotheekgrens", "Er is geen koppeling aan een hypotheekgrens."], ["Nee, een inschrijving bij de Kamer van Koophandel als bemiddelaar volstaat", "Een KvK-inschrijving is geen Wft-vergunning."]]],
["Bij welke instantie kan een consument terecht met een klacht over een kredietaanbieder als de interne klachtenprocedure geen oplossing biedt?", [["Kifid", "Wft-ondernemingen die diensten aan consumenten verlenen, moeten zijn aangesloten bij Kifid."], ["BKR", "BKR behandelt vragen over registraties, maar is geen geschilleninstantie voor kredietklachten."], ["Het Nibud", "Het Nibud geeft voorlichting over geldzaken, maar behandelt geen klachten."], ["De Belastingdienst", "De Belastingdienst behandelt geen geschillen tussen consumenten en kredietaanbieders."]]],
["Welk Wft-examen is in de regel vereist voor een adviseur die consumenten adviseert over consumptief krediet?", [["Wft Consumptief Krediet, naast Wft Basis", "Voor adviseren over consumptief krediet is de module Consumptief Krediet de vakbekwaamheidseis, met Wft Basis als fundament."], ["Uitsluitend de module Wft Hypothecair Krediet", "Hypothecair krediet is een andere module die consumptief krediet niet vervangt."], ["De module Wft Schade Particulier", "Die module gaat over schadeverzekeringen."], ["De module Wft Pensioen, naast Wft Basis", "Die module gaat over pensioenadvies."]]],
["Welke Europese richtlijn ligt tot 20 november 2026 ten grondslag aan de Nederlandse regels voor consumentenkrediet?", [["Richtlijn 2008/48/EG (CCD I)", "De eerste richtlijn consumentenkrediet is in de Wft en het BW geïmplementeerd en wordt per 20 november 2026 vervangen door CCD II."], ["Richtlijn 2014/17/EU (MCD)", "De MCD gaat over hypothecair krediet."], ["Richtlijn (EU) 2016/97 (IDD)", "De IDD gaat over verzekeringsdistributie."], ["Richtlijn 2014/65/EU (MiFID II)", "MiFID II gaat over beleggingsdiensten."]]],
["Waar staan de civielrechtelijke regels over de kredietovereenkomst met een consument, zoals herroeping en vervroegd aflossen, grotendeels?", [["In Boek 7 van het Burgerlijk Wetboek", "De privaatrechtelijke regels uit de richtlijn consumentenkrediet zijn in een aparte titel van Boek 7 BW opgenomen."], ["In de Wet gemeentelijke schuldhulpverlening", "Die wet regelt de schuldhulptaak van gemeenten, niet de kredietovereenkomst."], ["In de Algemene wet bestuursrecht", "De Awb gaat over de verhouding tussen burger en overheid."], ["In de Faillissementswet", "De Faillissementswet gaat over insolventie, niet over het sluiten van kredietovereenkomsten."]]],
["Een winkelier biedt klanten aan een aankoop gespreid te betalen in drie termijnen binnen drie maanden, zonder rente en kosten. Waarom valt dit onder de huidige regels meestal buiten het vergunningplichtige kredietregime?", [["Renteloos kortlopend krediet met geringe kosten is uitgezonderd", "Deze uitzondering verklaart waarom BNPL tot nu toe grotendeels buiten het kredietregime viel; CCD II beperkt haar."], ["Omdat de winkelier geen bank is en dus geen krediet kan verlenen", "Ook niet-banken kunnen vergunningplichtig krediet aanbieden; het type krediet is bepalend."], ["Omdat het aankoopbedrag lager is dan de NHG-kostengrens", "Een hypotheekgrens speelt bij consumptief krediet geen rol."], ["Omdat de consument zelf om het uitstel van betaling heeft gevraagd", "Wie om het krediet vraagt, bepaalt niet of het regime van toepassing is."]]],
["Vanaf wanneer is de herziene richtlijn consumentenkrediet (EU) 2023/2225 van toepassing?", [["20 november 2026", "Lidstaten moeten de nieuwe regels vanaf 20 november 2026 toepassen."], ["1 januari 2026", "Op die datum golden de regels van CCD II nog niet."], ["20 november 2025", "Dat was de uiterste datum voor omzetting in nationale wetgeving, niet de datum van toepassing."], ["1 juli 2027", "Op die datum begint de toepassing niet; die is eerder."]]],
["Wat is de status van de Nederlandse implementatie van CCD II op de peildatum 15 oktober 2026?", [["De implementatiewet is in voorbereiding", "De richtlijn is nog niet volledig in Nederlandse wetgeving omgezet; marktpartijen moeten zich wel voorbereiden."], ["De implementatiewet geldt al sinds 2024", "Op de peildatum was de implementatie nog niet afgerond."], ["Nederland heeft besloten CCD II niet te implementeren", "Lidstaten zijn verplicht een richtlijn om te zetten."], ["CCD II werkt rechtstreeks als verordening en hoeft niet te worden omgezet", "CCD II is een richtlijn en moet in nationale wetgeving worden omgezet."]]],
["Welke ontwikkeling hoort bij CCD II?", [["Buy now pay later en lease met koopoptie komen onder het kredietregime", "CCD II verruimt het toepassingsgebied naar vormen die eerder buiten de regels vielen."], ["Hypothecair krediet gaat onder CCD II vallen", "Hypotheken blijven onder de hypothekenrichtlijn vallen."], ["De kredietwaardigheidstoets wordt afgeschaft voor kredieten onder € 1.000,00", "CCD II versterkt de toets juist, ook voor kleinere bedragen; er komt geen vrijstelling onder € 1.000,00."], ["Het herroepingsrecht vervalt bij online krediet", "Het herroepingsrecht blijft bestaan, ook online."]]],
["Wat verandert CCD II aan de ondergrens van het toepassingsgebied ten opzichte van CCD I?", [["Ook kredieten onder € 200,00 vallen in beginsel onder de richtlijn", "CCD I gold niet voor kredieten onder € 200,00; CCD II schrapt die ondergrens, wat vooral kleine BNPL-kredieten raakt."], ["De ondergrens wordt verhoogd naar een bedrag van € 1.000,00", "CCD II verlaagt de drempel juist; kleine kredieten komen eronder."], ["Er gaat een nieuwe ondergrens van € 500,00 per krediet gelden", "CCD II introduceert geen nieuwe ondergrens van € 500,00."], ["De ondergrens van CCD I blijft onder CCD II ongewijzigd", "Het vervallen van de ondergrens is juist een van de wijzigingen."]]],
["Wat bepaalt CCD II over het gebruik van gegevens bij de kredietwaardigheidstoets?", [["Bijzondere persoonsgegevens en gegevens van sociale media zijn uitgesloten", "De toets moet steunen op relevante, juiste informatie over inkomen en uitgaven, niet op gevoelige of sociale-mediagegevens."], ["Alle beschikbare gegevens, inclusief sociale media, moeten worden gebruikt", "CCD II sluit sociale-mediagegevens juist uit."], ["Alleen de eigen verklaring van de consument mag worden gebruikt", "De aanbieder moet de informatie waar nodig verifiëren en kan ook databanken raadplegen."], ["Gezondheidsgegevens zijn verplicht bij kredieten met een looptijd van meer dan tien jaar", "Gezondheidsgegevens zijn bijzondere persoonsgegevens en mogen niet worden gebruikt."]]],
["Welk recht krijgt de consument onder CCD II als de kredietwaardigheidstoets geautomatiseerd plaatsvindt?", [["Recht op menselijke tussenkomst, uitleg en het geven van een eigen standpunt", "De consument kan een herbeoordeling door een mens vragen en uitleg krijgen over de beoordeling."], ["Het recht om de kredietwaardigheidstoets zelf uit te voeren en aan te leveren", "De toets blijft een verplichting van de aanbieder."], ["Het recht om zelf de rente en de looptijd van het krediet te bepalen", "De consument krijgt geen recht om de rente vast te stellen."], ["Het recht om juiste BKR-registraties direct te laten verwijderen", "CCD II geeft geen recht op verwijdering van juiste registraties."]]],
["Wat bepaalt CCD II over het verstrekken van krediet als de kredietwaardigheidstoets negatief uitvalt?", [["In beginsel mag het krediet dan niet ter beschikking worden gesteld", "Krediet mag alleen worden verstrekt als uit de beoordeling blijkt dat de consument waarschijnlijk aan zijn verplichtingen kan voldoen."], ["Het krediet mag altijd worden verstrekt als de consument tekent voor het risico", "Een handtekening van de consument maakt een negatieve toets niet positief."], ["Het krediet mag worden verstrekt tegen een hogere rente", "Een hogere rente verhoogt het risico van overkreditering juist."], ["Het krediet moet dan via een bemiddelaar lopen", "Inschakeling van een bemiddelaar verandert niets aan de uitkomst van de toets."]]],
["Wat zegt CCD II over ongevraagd krediet?", [["Krediet mag niet worden verstrekt zonder verzoek en instemming van de consument", "Ongevraagd krediet en ongevraagde limietverhogingen zijn verboden om overkreditering te voorkomen."], ["Ongevraagd krediet is toegestaan zolang de rente lager is dan het wettelijke maximum", "Een lage rente maakt ongevraagd krediet niet toegestaan."], ["Ongevraagd krediet mag wel worden verstrekt aan bestaande klanten", "Ook bij bestaande klanten is ongevraagd krediet niet toegestaan."], ["CCD II laat de regels over ongevraagd krediet volledig aan de markt", "CCD II bevat hierover juist een uitdrukkelijk verbod."]]],
["Welke verplichting legt CCD II op aan kredietgevers voordat zij invorderingsmaatregelen nemen bij betalingsproblemen?", [["Waar passend redelijke coulance betrachten, zoals aangepaste voorwaarden", "CCD II vraagt om tegemoetkomende maatregelen vóór invordering, rekening houdend met de situatie van de consument."], ["Direct de volledige vordering opeisen en uit handen geven aan incasso", "Direct opeisen zonder coulance is in strijd met de gedachte van CCD II."], ["Het openstaande krediet in alle gevallen volledig kwijtschelden", "Kwijtschelding is geen verplichting; wel moet coulance worden overwogen."], ["De consument verplicht doorverwijzen naar de rechter voor een regeling", "Een gang naar de rechter is geen verplichte eerste stap."]]],
["Wat verplicht CCD II de lidstaten op het gebied van schuldhulp?", [["Zorgen dat consumenten toegang hebben tot onafhankelijke schuldhulp", "Kredietgevers moeten consumenten met (dreigende) problemen naar deze diensten verwijzen."], ["Een centraal Europees register van alle consumentenschulden invoeren", "CCD II verplicht niet tot een Europees schuldenregister."], ["Schuldhulp volledig laten uitvoeren door de kredietgevers zelf", "Schuldhulp moet juist onafhankelijk zijn van de kredietgever."], ["Alle consumentenschulden onder een bepaald bedrag laten kwijtschelden", "CCD II bevat geen kwijtscheldingsregeling."]]],
["Wat bepaalt CCD II over de kosten van krediet in het algemeen?", [["Maatregelen nemen tegen buitensporige rente en kosten, zoals maxima", "Nederland kent met het Besluit kredietvergoeding al een maximum; CCD II verplicht alle lidstaten tot dergelijke maatregelen."], ["Lidstaten mogen voor consumptief krediet geen maximumrente meer hanteren", "CCD II staat maxima juist toe en verlangt maatregelen tegen buitensporige kosten."], ["De rente op consumentenkrediet wordt voortaan door de ECB vastgesteld", "De ECB stelt geen consumentenkredietrente vast."], ["De kosten van krediet worden volledig vrijgelaten om concurrentie te bevorderen", "CCD II vergroot juist de bescherming tegen buitensporige kosten."]]],
["Een webwinkel werkt samen met een BNPL-aanbieder die nu nog onder een uitzondering valt. Wat is voor deze aanbieder de belangrijkste vraag in aanloop naar CCD II?", [["Of zijn dienst onder het kredietregime valt, met vergunning en kredietwaardigheidstoets", "CCD II brengt BNPL onder de regels; de Nederlandse implementatie bepaalt de precieze verplichtingen."], ["Of de webwinkel voor het aanbieden van deze betaalwijze een hypotheekvergunning moet aanvragen", "BNPL heeft niets met hypothecair krediet te maken."], ["Of de consument nog een herroepingsrecht heeft op de gekochte producten", "Het herroepingsrecht op de koop bestaat los van CCD II; het gaat hier om het kredietregime."], ["Of de BNPL-aanbieder de aandelen van de webwinkel moet overnemen", "CCD II stelt geen eisen aan eigendomsverhoudingen tussen winkel en aanbieder."]]],
["Welke overheid is in Nederland verantwoordelijk voor de schuldhulpverlening aan inwoners?", [["De gemeente", "Op grond van de Wet gemeentelijke schuldhulpverlening moeten gemeenten schuldhulp aan inwoners bieden."], ["De provincie", "Provincies hebben geen wettelijke taak bij schuldhulp."], ["Het Rijk via de Belastingdienst", "De Belastingdienst is schuldeiser, geen schuldhulpverlener."], ["De AFM", "De AFM is toezichthouder en verleent geen schuldhulp."]]],
["Wat is vroegsignalering in het kader van schuldhulp?", [["Achterstanden op vaste lasten vroeg aan de gemeente melden om hulp te bieden", "Bepaalde schuldeisers zoals energie- en drinkwaterbedrijven, zorgverzekeraars en verhuurders geven achterstanden door aan de gemeente."], ["Elke aankoop van een consument automatisch registreren bij BKR", "Vroegsignalering gaat over achterstanden, niet over aankopen."], ["Kredietaanvragen van consumenten vooraf laten blokkeren door de AFM", "De AFM blokkeert geen individuele aanvragen."], ["Werkgevers vroeg waarschuwen over de schulden van hun werknemers", "Vroegsignalering loopt via de gemeente, niet via de werkgever."]]],
["Wat is het verschil tussen het minnelijk traject en de Wsnp?", [["Minnelijk is een vrijwillige regeling; de Wsnp is een wettelijke sanering via de rechter", "Pas als een minnelijke regeling niet lukt, kan de rechter iemand toelaten tot de Wsnp."], ["Het minnelijk traject loopt via de rechter, de Wsnp loopt via de gemeentelijke schuldhulpverlening", "Het is precies andersom: de Wsnp loopt via de rechtbank."], ["Er is geen verschil; het zijn twee namen voor hetzelfde schuldhulptraject", "Het zijn twee verschillende trajecten met een andere juridische basis."], ["De Wsnp is alleen bedoeld voor ondernemers met zakelijke schulden", "Ook particulieren kunnen tot de Wsnp worden toegelaten."]]],
["Een klant met een doorlopend krediet belt dat hij zijn baan verliest en de termijn volgende maand waarschijnlijk niet kan betalen. Wat is de beste eerste reactie van de kredietgever?", [["In gesprek gaan over een passende betalingsregeling en wijzen op schuldhulpmogelijkheden", "Vroeg ingrijpen voorkomt oplopende schulden; de zorgplicht vraagt om meedenken met de klant."], ["De limiet tijdelijk verhogen zodat de klant de komende termijnen uit het krediet zelf kan betalen", "Nieuw krediet om bestaand krediet te betalen vergroot de schuldenlast."], ["Het krediet direct opeisen voordat er daadwerkelijk een achterstand ontstaat", "Direct opeisen zonder overleg is onnodig hard en niet in het belang van de klant."], ["Niets doen tot de vordering na enkele maanden aan een incassobureau gaat", "Afwachten laat de schuld en kosten oplopen."]]],
["Wat is de beslagvrije voet?", [["Het deel van het inkomen dat bij beslag beschermd blijft voor levensonderhoud", "Schuldeisers mogen het inkomen onder deze grens niet aantasten."], ["Het maximale bedrag dat iemand volgens de leennormen mag lenen", "Dat is een leennorm, geen beslagvrije voet."], ["De periode direct na het sluiten van een lening waarin geen beslag mag worden gelegd", "De beslagvrije voet is een bedrag, geen tijdsperiode."], ["Het bedrag waarboven een krediet verplicht bij BKR moet worden gemeld", "Dat heeft niets met beslag te maken."]]],
["Een consument wordt toegelaten tot de Wsnp. Wat is in het algemeen het gevolg als hij zich gedurende de looptijd aan alle verplichtingen houdt?", [["Hij kan aan het einde een schone lei krijgen voor de resterende schulden", "Met de schone lei zijn de resterende schulden niet meer afdwingbaar."], ["Al zijn schulden worden direct bij de start van de regeling kwijtgescholden", "Kwijting volgt pas na afloop als de verplichtingen zijn nagekomen."], ["Hij krijgt na afloop automatisch een nieuw krediet van de gemeente", "De Wsnp leidt niet tot nieuw krediet."], ["Zijn kredietgever moet hem na afloop een hogere kredietlimiet geven", "Van een verplichting tot meer krediet is geen sprake."]]],
["Een adviseur merkt in een kennismakingsgesprek dat een klant meerdere betalingsachterstanden en incassobrieven heeft. Wat is passend?", [["Geen krediet adviseren dat de problemen vergroot en wijzen op schuldhulp", "De zorgplicht vraagt om het belang van de klant voorop te zetten, ook als dat betekent dat er geen krediet komt."], ["Snel een doorlopend krediet regelen zodat de lopende incasso's stoppen", "Extra krediet bij bestaande achterstanden kan de klant verder in de problemen brengen."], ["De achterstanden buiten het dossier houden zodat de toets wel slaagt", "Informatie verzwijgen of niet vastleggen is in strijd met de zorgplicht en kan fraude zijn."], ["De klant adviseren eerst bij een andere aanbieder een tweede lening te vragen", "Ook een lening elders vergroot de schuldenlast en lost het probleem niet op."]]],
["Waarom valt een kredietaanbieder onder de Wwft?", [["Omdat kredietverlening een financiële dienst is die vatbaar is voor witwassen", "Kredietaanbieders zijn Wwft-instelling en moeten cliëntenonderzoek doen en ongebruikelijke transacties melden."], ["Omdat elke ondernemer die rente in rekening brengt onder de Wwft valt", "Het rekenen van rente maakt een onderneming niet zonder meer Wwft-plichtig."], ["Omdat BKR dat als voorwaarde stelt in zijn algemene voorwaarden", "De Wwft-plicht volgt uit de wet, niet uit voorwaarden van BKR."], ["Omdat consumptief krediet onder het provisieverbod van de Wft valt", "Het provisieverbod heeft niets met de Wwft te maken."]]],
["Een klant lost een persoonlijke lening van € 20.000,00 kort na het afsluiten ineens af met contant geld waarvan de herkomst onduidelijk is. Wat moet de kredietaanbieder doen?", [["Onderzoeken of dit een ongebruikelijke transactie is en zo nodig melden bij de FIU", "Een snelle aflossing met contant geld van onduidelijke herkomst is een signaal dat onderzoek en mogelijk melding vraagt."], ["De klant vooraf waarschuwen dat er mogelijk een melding over hem wordt gedaan", "Er geldt een geheimhoudingsplicht; de klant mag niet over een melding worden ingelicht."], ["De aflossing weigeren en het contante geld direct aan de politie overdragen", "De Wwft vraagt om onderzoek en melding, niet om afgifte aan de politie."], ["Niets doen, omdat vervroegd aflossen een wettelijk recht van de klant is", "Het recht op vervroegd aflossen ontslaat niet van de Wwft-verplichtingen."]]],
["Welk onderdeel hoort bij het cliëntenonderzoek onder de Wwft bij het aangaan van een kredietrelatie?", [["Het vaststellen en verifiëren van de identiteit", "De aanbieder moet weten met wie hij zaken doet, bijvoorbeeld via een geldig identiteitsbewijs."], ["Het berekenen van het JKP van het krediet", "Het JKP is precontractuele informatie, geen cliëntenonderzoek."], ["Het toetsen aan de VFN-leennormen", "Dat hoort bij de kredietwaardigheidstoets, niet bij het Wwft-onderzoek."], ["Het opstellen en verstrekken van een SECCI", "De SECCI is een informatieformulier, geen onderdeel van het cliëntenonderzoek."]]],
["Welk AVG-beginsel betekent dat een kredietaanbieder niet meer persoonsgegevens verwerkt dan nodig is voor de kredietbeoordeling?", [["Dataminimalisatie", "Er mogen alleen gegevens worden verwerkt die toereikend, ter zake dienend en beperkt zijn tot wat nodig is."], ["Dataportabiliteit", "Dat is het recht van de betrokkene om gegevens mee te nemen naar een andere partij."], ["Integriteit en vertrouwelijkheid", "Dit beginsel gaat over beveiliging, niet over de hoeveelheid gegevens."], ["Juistheid", "Dit beginsel gaat over correcte gegevens, niet over beperking van de hoeveelheid."]]],
["Een bemiddelaar vraagt een klant om volledige bankafschriften van een jaar, inclusief alle uitgaven, terwijl een recente loonstrook en een overzicht van vaste lasten volstaan. Welk aandachtspunt speelt hier vooral?", [["Of de gevraagde gegevens nodig zijn voor het doel (dataminimalisatie)", "De AVG vraagt om alleen gegevens te verwerken die voor de kredietbeoordeling nodig zijn."], ["Of de klant de afschriften in kleur en op papier aanlevert", "De vorm van aanlevering is geen AVG-kernvraag."], ["Of de bemiddelaar de afschriften aan BKR moet doorsturen", "BKR ontvangt geen bankafschriften van klanten."], ["Of de klant daardoor zijn herroepingsrecht op de lening verliest", "Het opvragen van stukken heeft geen invloed op het herroepingsrecht."]]],
["Hoe lang mag een kredietaanbieder persoonsgegevens uit een kredietdossier bewaren volgens de AVG?", [["Niet langer dan nodig, met inachtneming van wettelijke bewaarplichten", "De AVG schrijft geen vaste termijn voor; het doel en wettelijke plichten zoals uit de Wwft bepalen de termijn."], ["Altijd voor onbepaalde tijd, zodat het dossier compleet blijft", "Onbeperkt bewaren is in strijd met het beginsel van opslagbeperking."], ["Precies één maand na de afwijzing of het afsluiten van het krediet", "De AVG kent geen vaste termijn van één maand."], ["Zo lang als de klant geen bezwaar maakt tegen de bewaring", "De bewaartermijn hangt af van het doel en wettelijke plichten, niet van het uitblijven van bezwaar."]]],
["Welke toezichthouder houdt toezicht op de naleving van de AVG door een kredietaanbieder?", [["De Autoriteit Persoonsgegevens", "De AP is de toezichthouder op de verwerking van persoonsgegevens."], ["De Autoriteit Financiële Markten", "De AFM houdt gedragstoezicht op financiële dienstverlening, niet op de AVG."], ["Stichting BKR in Tiel", "BKR is zelf verwerkingsverantwoordelijke en geen toezichthouder."], ["FIU-Nederland", "De FIU ontvangt meldingen van ongebruikelijke transacties."]]],
["Welke informatie moet een adviseur inwinnen voordat hij een consumptief krediet adviseert?", [["Financiële positie, kennis en ervaring, doelen en risicobereidheid", "Alleen met een volledig klantprofiel kan het advies passend zijn."], ["Alleen de maandtermijn die de klant zelf wenst te betalen", "Een gewenste termijn is één wens, geen volledig klantbeeld."], ["Alleen de gegevens die bij BKR over de klant bekend zijn", "BKR-gegevens vullen het beeld aan, maar vervangen het klantonderzoek niet."], ["Alleen het doel waarvoor de klant de lening wil gebruiken", "Het doel is belangrijk, maar ook draagkracht en situatie moeten bekend zijn."]]],
["Een klant wil een auto met een verwachte gebruiksduur van vijf jaar financieren met een persoonlijke lening van tien jaar om de maandlast laag te houden. Wat is passend advies?", [["De looptijd afstemmen op de gebruiksduur van de auto, ook als de maandlast dan hoger is", "Een looptijd die langer is dan de gebruiksduur betekent dat de klant nog betaalt voor iets wat hij niet meer heeft."], ["De langste looptijd kiezen, omdat een lage maandlast altijd beter is", "Een lange looptijd verhoogt de totale kosten en het risico van een restschuld."], ["Een doorlopend krediet adviseren zonder vaste aflossingsverplichting", "Zonder aflossingsdiscipline blijft de schuld langer bestaan."], ["De klant adviseren de auto te leasen en daarnaast ook te lenen", "Dubbele financiering van één bestedingsdoel is niet in het belang van de klant."]]],
["Een klant sluit zonder advies, op execution-only-basis, online een persoonlijke lening af. Wat is juist?", [["Dat mag, maar de aanbieder moet nog steeds de kredietwaardigheid toetsen", "Bij execution only adviseert niemand, maar de wettelijke toetsplicht van de aanbieder blijft gelden."], ["Dat mag niet, omdat consumptief krediet altijd advies vereist", "Consumptief krediet mag ook zonder advies worden afgesloten."], ["Dat mag, en de kredietwaardigheidstoets vervalt dan voor de aanbieder", "De toetsplicht vervalt niet bij execution only."], ["Dat mag alleen bij een lening met een looptijd van meer dan tien jaar", "De looptijd bepaalt niet of execution only mogelijk is."]]],
["Wat betekent de algemene zorgplicht van een financiële dienstverlener bij consumptief krediet?", [["Zorgvuldig rekening houden met de rechtmatige belangen van de klant", "De zorgplicht is een open norm die verder kan gaan dan de concrete regels, bijvoorbeeld bij signalen van financiële problemen."], ["Altijd het krediet met de hoogste limiet adviseren", "Een zo hoog mogelijke limiet is vaak juist niet in het belang van de klant."], ["Uitsluitend de wettelijke informatieformulieren verstrekken", "Formulieren verstrekken is niet genoeg om aan de zorgplicht te voldoen."], ["Alleen de belangen van de kredietgever behartigen", "De zorgplicht ziet juist op de belangen van de klant."]]],
["Een klant vraagt advies over een lening om een vakantie te betalen terwijl hij nauwelijks een buffer heeft. Welke aanpak past bij goed advies?", [["Bespreken of lenen voor dit doel verstandig is en wat het voor zijn buffer betekent", "Een goede adviseur toetst niet alleen of het kan, maar ook of het in het belang van de klant is."], ["Direct de hoogst mogelijke lening aanvragen zodat er ruimte overblijft", "Maximaal lenen past niet bij een klant zonder buffer."], ["Het bestedingsdoel niet bespreken omdat dat een privézaak van de klant is", "Het bestedingsdoel is relevant voor passend advies."], ["Adviseren de vakantie te betalen via een overschrijding op de betaalrekening", "Een overschrijding is duur en ongepland; dat is geen passend alternatief."]]],
["Wat moet een adviseur vastleggen in het klantdossier bij een advies over consumptief krediet?", [["De klantgegevens, de afwegingen en de onderbouwing van het advies", "Een goed dossier laat zien dat het advies passend is en maakt het controleerbaar voor klant en toezichthouder."], ["Alleen de handtekening van de klant op de offerte van de aanbieder", "Een handtekening laat niet zien waarom het advies passend was."], ["Alleen de rente en de looptijd van het gekozen kredietproduct", "De rente is één gegeven; de onderbouwing van het advies ontbreekt dan."], ["Niets, omdat mondeling gegeven advies niet hoeft te worden vastgelegd", "Ook mondeling advies moet worden vastgelegd om de passendheid te kunnen aantonen."]]],
["Een klant met een stabiel inkomen wil een tuinverbouwing van € 12.000,00 financieren en twijfelt tussen een doorlopend krediet en een persoonlijke lening. Wat is in de regel het belangrijkste argument voor de persoonlijke lening?", [["Door de vaste aflossing is de schuld na de afgesproken looptijd weg", "Bij een eenmalige, bekende besteding past een aflopend krediet met vaste aflossing beter dan een opneembare limiet."], ["Een persoonlijke lening heeft altijd een variabele, dalende rente", "Een persoonlijke lening heeft juist meestal een vaste rente."], ["Bij een persoonlijke lening kan de klant later opnieuw opnemen", "Opnieuw opnemen is een kenmerk van doorlopend krediet."], ["Een persoonlijke lening wordt niet bij BKR geregistreerd", "Ook een persoonlijke lening wordt bij BKR geregistreerd."]]],
["Geldt het provisieverbod uit de Wft voor bemiddeling in consumptief krediet?", [["Nee, bij consumptief krediet is provisie onder voorwaarden toegestaan", "Het provisieverbod geldt onder meer voor hypotheken en complexe producten; bij consumptief krediet mag provisie, maar de zorgplicht blijft gelden."], ["Ja, het provisieverbod geldt voor alle vormen van krediet", "Het verbod is beperkt tot bepaalde producten en omvat consumptief krediet niet."], ["Ja, maar het provisieverbod geldt alleen voor doorlopend krediet", "Ook voor doorlopend krediet geldt het provisieverbod niet."], ["Nee, en bij consumptief krediet gelden ook verder geen beloningsregels", "Er gelden wel regels, zoals de eis dat de beloning het klantbelang niet mag schaden."]]],
["Welke eis geldt in het algemeen voor provisie die een bemiddelaar van een kredietaanbieder ontvangt?", [["De beloning mag de zorgvuldige dienstverlening aan de klant niet schaden", "Provisie mag geen prikkel zijn om een product te adviseren dat niet in het belang van de klant is."], ["De provisie moet zo hoog mogelijk zijn zodat de klant beter wordt geholpen", "Hoogte van de provisie is geen klantvoordeel."], ["De provisie moet per afgesloten krediet aan BKR worden gemeld", "BKR registreert geen provisies."], ["De provisie moet vooraf door de AFM worden goedgekeurd", "De AFM keurt provisieafspraken niet vooraf goed; wel moet de beloning het klantbelang dienen."]]],
["Een bemiddelaar krijgt van aanbieder A meer provisie dan van aanbieder B, terwijl de lening van B voor de klant goedkoper is. Wat is passend?", [["De lening adviseren die het best past bij de klant, ook als de provisie lager is", "Het klantbelang gaat voor het eigen belang; een beloningsprikkel mag het advies niet sturen."], ["Aanbieder A adviseren, omdat de bemiddelaar daar meer aan verdient", "Advies op basis van eigen beloning is in strijd met de zorgplicht."], ["De klant zelf laten kiezen zonder de verschillen tussen beide te noemen", "De klant moet de informatie krijgen om een goede keuze te maken."], ["Beide leningen tegelijk afsluiten zodat de klant kan kiezen welke hij houdt", "Twee leningen voor één doel zijn niet in het belang van de klant."]]],
["Waarmee moet een adviseur rekening houden bij het oversluiten van een bestaand consumptief krediet?", [["De totale kosten van oud en nieuw, inclusief looptijd en aflossingsvergoeding", "Een lagere rente kan door een langere looptijd of kosten toch duurder uitpakken."], ["Alleen de hoogte van de nieuwe maandtermijn ten opzichte van de oude", "Een lagere termijn kan het gevolg zijn van een langere looptijd en hogere totale kosten."], ["Alleen de rente van de nieuwe lening ten opzichte van de huidige rente", "De rente is één factor; looptijd en kosten tellen ook."], ["Alleen of de klant een BKR-registratie met een achterstandscode heeft", "BKR is relevant voor de toets, maar zegt niet of oversluiten voordelig is."]]],
["Een klant heeft drie doorlopende kredieten bij verschillende aanbieders en wil die oversluiten naar één persoonlijke lening. Wat is een belangrijk aandachtspunt?", [["Dat de oude kredieten echt worden afgelost en de limieten worden opgezegd", "Als de oude limieten blijven bestaan, kan de klant opnieuw opnemen en neemt de schuld toe."], ["Dat de oude kredieten blijven bestaan als reserve voor onverwachte uitgaven", "Open limieten zijn een risico op extra schuld en tellen mee bij toekomstige toetsen."], ["Dat de nieuwe lening een zo lang mogelijke looptijd krijgt voor een lage last", "Een lange looptijd verhoogt de totale kosten."], ["Dat de klant bij oversluiten niet opnieuw getoetst hoeft te worden", "Ook bij oversluiten moet de kredietwaardigheid worden getoetst."]]],
["Een klant wil een consumptief krediet meefinancieren in zijn hypotheek. Wat is fiscaal juist?", [["Het deel dat niet aan de eigen woning wordt besteed, geeft geen renteaftrek", "Alleen schuld voor aankoop, verbouwing of onderhoud van de eigen woning kan eigenwoningschuld zijn."], ["De rente over het hele bedrag is aftrekbaar omdat het een hypotheek is", "De besteding bepaalt de aftrek, niet de vorm van de lening."], ["Het consumptieve deel valt in box 1 en telt mee als eigenwoningschuld", "Een consumptieve besteding valt niet onder de eigenwoningschuld."], ["Met NHG wordt ook het consumptieve deel van de lening eigenwoningschuld", "NHG is een borgstelling en verandert niets aan het fiscale karakter van een consumptieve besteding."]]],
["Waarom kan oversluiten van een doorlopend krediet naar een persoonlijke lening in het belang van de klant zijn?", [["Er geldt vaste aflossing binnen een vaste looptijd, zodat de schuld afneemt", "Een doorlopend krediet kan lang open blijven; een persoonlijke lening heeft een einddatum."], ["De rente van een persoonlijke lening is altijd hoger dan bij doorlopend krediet", "Een hogere rente is geen voordeel voor de klant."], ["Een persoonlijke lening wordt in tegenstelling tot doorlopend krediet niet geregistreerd", "Ook persoonlijke leningen worden geregistreerd."], ["De klant kan na het oversluiten afgeloste bedragen opnieuw opnemen", "Opnemen is juist niet mogelijk bij een persoonlijke lening."]]],
["Een kredietgever draagt een vordering uit een consumptief krediet over aan een andere partij. Welke positie heeft de consument?", [["Hij kan zijn verweermiddelen ook tegenover de nieuwe schuldeiser inroepen", "De overdracht mag de positie van de consument niet verslechteren."], ["Hij verliest alle verweermiddelen tegenover de nieuwe schuldeiser", "De consument behoudt zijn verweren."], ["Hij moet het krediet direct volledig aflossen", "Overdracht van de vordering maakt het krediet niet opeisbaar."], ["Hij moet een nieuwe kredietwaardigheidstoets ondergaan", "Bij overdracht van een bestaande vordering is geen nieuwe toets nodig."]]],
["Een kredietaanbieder gebruikt een kredietscoringsmodel met kunstmatige intelligentie om consumenten te beoordelen. Hoe kwalificeert de AI-verordening deze toepassing?", [["Als hoogrisico-AI-systeem", "Kredietwaardigheidsbeoordeling van natuurlijke personen staat in de AI-verordening als toepassing met hoog risico."], ["Als verboden AI-praktijk", "Kredietscoring is niet verboden, maar valt onder strenge eisen."], ["Als toepassing met minimaal risico", "Gezien de impact op toegang tot krediet geldt een hoger risicoprofiel."], ["Als toepassing die buiten de verordening valt", "Kredietscoring is in de verordening uitdrukkelijk genoemd."]]],
["Kan een consument zich bij een gelieerd krediet tot de kredietgever wenden als de verkoper de gekochte zaak niet levert?", [["Ja, onder voorwaarden, nadat hij eerst de verkoper heeft aangesproken", "Bij een gelieerde kredietovereenkomst kan de consument in bepaalde gevallen verhaal halen bij de kredietgever."], ["Nee, kredietgever en verkoper staan in alle gevallen volledig los van elkaar", "Bij een gelieerd krediet vormen koop en krediet juist een commerciële eenheid."], ["Ja, en de kredietgever moet dan altijd de dubbele koopprijs vergoeden", "Een dubbele vergoeding bestaat niet."], ["Alleen als de AFM daarvoor in het individuele geval toestemming geeft", "Voor het verhaal op de kredietgever is geen AFM-toestemming nodig."]]],
["Een aanvrager geeft bewust een hoger inkomen op dan hij verdient om een lening te krijgen. Hoe is dit te kwalificeren?", [["Als fraude, die tot weigering of opeising van het krediet kan leiden", "Opzettelijk onjuiste informatie ondermijnt de kredietwaardigheidstoets en is fraude."], ["Als een toelaatbare inschatting van het toekomstige inkomen", "Bewust een hoger inkomen opgeven is geen inschatting maar misleiding."], ["Als een fout die de bemiddelaar in het dossier moet verzwijgen", "Verzwijgen maakt de bemiddelaar medeplichtig en is in strijd met de integriteitsnormen."], ["Als irrelevant, omdat BKR het opgegeven inkomen toch controleert", "BKR registreert geen inkomen en controleert het dus niet."]]],
["Waarom vraagt een kredietaanbieder naar de gezinssituatie van de aanvrager?", [["Omdat het normbedrag voor levensonderhoud afhangt van de samenstelling van het huishouden", "Een gezin met kinderen heeft hogere vaste kosten dan een alleenstaande, wat de afloscapaciteit beïnvloedt."], ["Om te bepalen of de partner automatisch hoofdelijk aansprakelijk wordt", "De gezinssituatie maakt een partner niet automatisch aansprakelijk."], ["Omdat alleen gehuwden en geregistreerd partners een lening mogen afsluiten", "Ook alleenstaanden en samenwoners kunnen krediet krijgen."], ["Om de BKR-registratie mede op naam van de kinderen te kunnen zetten", "Kredieten worden niet op naam van kinderen geregistreerd."]]]
],
"schade-particulier":[
["Op welk moment geldt de wettelijke mededelingsplicht van de verzekeringnemer volgens BW 7 titel 17?", [["Vóór het sluiten van de verzekeringsovereenkomst.", "De wettelijke mededelingsplicht ziet op de precontractuele fase; wijzigingen tijdens de looptijd moeten alleen worden gemeld als de polis dat bepaalt."], ["Gedurende de hele looptijd van de verzekering.", "De wet regelt geen doorlopende mededelingsplicht; een meldplicht voor risicowijziging volgt alleen uit de polisvoorwaarden."], ["Uitsluitend op het moment van een schademelding.", "Bij schade geldt een meldings- en informatieplicht, maar dat is een andere verplichting dan de precontractuele mededelingsplicht."], ["Alleen bij elke stilzwijgende verlenging van de polis.", "Een verlenging is geen nieuwe totstandkoming waarbij de wettelijke mededelingsplicht opnieuw ontstaat."]]],
["Welke feiten moet een verzekeringnemer op grond van de mededelingsplicht melden?", [["Feiten die hij kent of behoort te kennen en die relevant zijn voor de beslissing van de verzekeraar.", "Dat is de wettelijke maatstaf: het gaat om kennis van de verzekeringnemer en de relevantie voor de acceptatie- en premiebeslissing."], ["Alleen feiten die de verzekeringnemer zelf van belang vindt voor de hoogte van de premie.", "De maatstaf is niet het subjectieve oordeel van de klant, maar wat hij behoort te begrijpen over de beslissing van de verzekeraar."], ["Alle feiten over zijn persoon, gezin en financiën, ook als die voor het risico of de premie geen rol spelen.", "De plicht is beperkt tot feiten die van belang kunnen zijn voor de beslissing van de verzekeraar."], ["Alleen feiten die blijken uit openbare registers, zoals het Kadaster of het handelsregister.", "Openbaarheid is niet bepalend; ook niet-geregistreerde feiten, zoals eerdere schades, kunnen gemeld moeten worden."]]],
["Een verzekeraar gebruikt bij het aanvragen een vragenlijst. Na een schade blijkt een relevant feit waar niet naar gevraagd is. Wat geldt?", [["Zij kan zich er niet op beroepen, tenzij de klant opzet had de verzekeraar te misleiden.", "Bij een vragenlijst mag de klant afgaan op de gestelde vragen; alleen bij opzet om de verzekeraar te misleiden ligt dat anders."], ["Zij mag de uitkering naar evenredigheid verminderen, omdat het feit relevant was.", "Proportionele vermindering is een sanctie bij schending van de mededelingsplicht, maar over niet-gevraagde feiten kan de verzekeraar in beginsel geen beroep doen."], ["Zij mag de polis met terugwerkende kracht vernietigen wegens dwaling over het risico.", "Voor niet-gevraagde feiten is er zonder opzet tot misleiding geen grond voor zo'n beroep."], ["Zij hoeft niet uit te keren, omdat de klant ook ongevraagd alles moest melden.", "Juist bij een vragenlijst beperkt de wet de mededelingsplicht feitelijk tot de gestelde vragen."]]],
["Mevrouw Bakker meldt bij het afsluiten van een inboedelverzekering een eerdere inbraak niet. De verzekeraar had haar bij juiste melding geaccepteerd tegen een hogere premie. Na een nieuwe inbraak ontdekt de verzekeraar dit. Wat is in beginsel het gevolg (geen opzet tot misleiding)?", [["Uitkering naar verhouding van de betaalde premie tot de premie bij juiste melding.", "De wet kiest voor een proportionele uitkering: de klant krijgt wat bij de juiste premie in verhouding zou zijn verzekerd."], ["Geen uitkering, omdat elke schending van de mededelingsplicht tot verval leidt.", "Volledige weigering geldt pas als de verzekeraar bij kennis van de ware stand van zaken geen verzekering zou hebben gesloten, of bij opzet tot misleiding."], ["Volledige uitkering, waarbij de verzekeraar alleen de premie alsnog verhoogt.", "De wet laat de verzekeraar de uitkering verminderen; volledige vergoeding met naheffing van premie is niet de wettelijke regel."], ["Uitkering van de helft van de schade, omdat schuld bij beide partijen ligt.", "Er bestaat geen vaste 50%-regel; de vermindering volgt uit de verhouding tussen de premies."]]],
["Binnen welke termijn moet een verzekeraar na ontdekking van schending van de mededelingsplicht de verzekeringnemer daarop wijzen om zich op de gevolgen te kunnen beroepen?", [["Binnen twee maanden na de ontdekking.", "De verzekeraar moet binnen twee maanden na ontdekking op de niet-nakoming wijzen en de gevolgen noemen; anders vervalt zijn beroep daarop."], ["Binnen veertien dagen na de ontdekking.", "Veertien dagen is de aanmaningstermijn bij premiebetaling, niet de termijn bij de mededelingsplicht."], ["Binnen drie jaar na de ontdekking.", "Drie jaar is de verjaringstermijn voor vorderingen tegen de verzekeraar; voor dit beroep geldt een veel kortere termijn."], ["Er geldt geen termijn; de verzekeraar kan zich er altijd op beroepen.", "De wet stelt juist een termijn om de verzekeringnemer duidelijkheid te geven."]]],
["Wat mag een verzekeraar doen als de verzekeringnemer de mededelingsplicht heeft geschonden met het opzet de verzekeraar te misleiden?", [["Uitkering weigeren en de verzekering opzeggen met onmiddellijke ingang.", "Bij opzet tot misleiding vervalt het recht op uitkering en mag de verzekeraar de overeenkomst direct beëindigen."], ["Alleen de premie met terugwerkende kracht verhogen.", "Bij opzet tot misleiding gaat de wet verder dan premieherstel; de klant verliest zijn recht op uitkering."], ["Alleen naar evenredigheid uitkeren.", "Proportionele uitkering is de hoofdregel zonder opzet; bij opzet tot misleiding hoeft de verzekeraar niets uit te keren."], ["De verzekering pas opzeggen tegen de eerstvolgende contractvervaldatum, met behoud van uitkering.", "De wet staat bij opzet tot misleiding opzegging met onmiddellijke ingang toe en het recht op uitkering vervalt."]]],
["De verzekeringnemer betaalt een vervolgpremie niet op tijd. Wanneer mag de verzekeraar de dekking opschorten?", [["Na een vergeefse aanmaning om binnen veertien dagen te betalen.", "Voor vervolgpremies treedt verzuim pas in na een aanmaning met een betalingstermijn van veertien dagen; daarna mag de dekking worden opgeschort."], ["Direct op de dag na de vervaldag, zonder aanmaning vooraf.", "Voor vervolgpremies is eerst een aanmaning nodig; opschorting zonder aanmaning is niet toegestaan."], ["Pas nadat de premieachterstand drie maanden heeft geduurd.", "De wet kent geen termijn van drie maanden; beslissend is de vergeefse aanmaning met een termijn van veertien dagen."], ["Pas nadat de rechter de opschorting van dekking heeft toegestaan.", "Tussenkomst van de rechter is niet nodig; de opschorting volgt uit de polis na intreden van verzuim."]]],
["Wat moet een verzekerde volgens de wet doen zodra hij weet of behoort te weten dat er een schade is waarvoor dekking kan bestaan?", [["De schade zo spoedig redelijkerwijs mogelijk melden en de nodige informatie geven.", "Dit is de wettelijke meldings- en informatieplicht na een schadevoorval."], ["Eerst zelf de schade laten herstellen en daarna de herstelnota met foto's insturen.", "Eigenmachtig herstel kan de schadevaststelling bemoeilijken; de wet vraagt eerst tijdige melding en informatie."], ["De schade pas melden als vaststaat welke partij aansprakelijk is.", "De meldplicht hangt niet af van de aansprakelijkheidsvraag; melden moet zo spoedig mogelijk."], ["De schade binnen een jaar melden, omdat anders elk recht vervalt.", "De wet noemt geen vaste meldtermijn van een jaar; maatstaf is 'zo spoedig redelijkerwijs mogelijk'."]]],
["Een verzekerde meldt een waterschade te laat, maar zonder opzet tot misleiding. Wat mag de verzekeraar in beginsel doen?", [["De uitkering verminderen met het nadeel dat hij door de late melding lijdt.", "Bij schending van de meldplicht mag de verzekeraar de schade verhalen die hij daardoor lijdt; verval van het hele recht kan alleen als hij in een redelijk belang is geschaad en dit is bedongen."], ["De hele uitkering weigeren, ook als hij geen enkel nadeel heeft geleden.", "Volledig verval is alleen mogelijk als de verzekeraar in een redelijk belang is geschaad en dat in de polis staat, of bij opzet tot misleiding."], ["De verzekering met terugwerkende kracht ontbinden wegens wanprestatie.", "Late melding geeft geen grond om de overeenkomst met terugwerkende kracht te ontbinden."], ["Niets, omdat de wet geen gevolgen verbindt aan een late schademelding.", "De wet geeft de verzekeraar wel een sanctie, namelijk vermindering met het nadeel dat hij lijdt."]]],
["Welke vergoeding geldt volgens BW 7 voor redelijke kosten die de verzekerde maakt om dreigende schade te voorkomen of te beperken (bereddingskosten)?", [["Ze worden vergoed, ook als daardoor de verzekerde som wordt overschreden.", "Bereddingskosten komen voor rekening van de verzekeraar, ook boven de verzekerde som, omdat beredding ook de verzekeraar dient."], ["Ze worden alleen vergoed als de maatregel de schade daadwerkelijk heeft beperkt.", "Ook redelijke maatregelen zonder resultaat worden vergoed; succes is geen voorwaarde."], ["Ze worden niet vergoed, omdat ze onder het eigen risico van de verzekerde vallen.", "De wet verplicht de verzekeraar juist om redelijke bereddingskosten te vergoeden."], ["Ze worden vergoed tot maximaal de helft van de verzekerde som van de polis.", "De wet kent geen maximum van de halve verzekerde som; vergoeding kan zelfs boven de som uitkomen."]]],
["Wat zegt de wet over schade die een verzekerde met opzet of door roekeloosheid veroorzaakt bij een schadeverzekering?", [["De verzekeraar keert aan die verzekerde geen schadevergoeding uit.", "De wet sluit uitkering uit aan de verzekerde die de schade met opzet of door roekeloosheid veroorzaakte."], ["De verzekeraar keert de helft uit.", "De wet kent bij opzet of roekeloosheid geen gedeeltelijke uitkering aan die verzekerde."], ["De verzekeraar keert volledig uit, maar mag de polis daarna opzeggen.", "Uitkering is bij opzet of roekeloosheid van die verzekerde juist uitgesloten."], ["Alleen opzet is wettelijk uitgesloten; roekeloosheid valt altijd onder de dekking.", "De wettelijke regeling noemt naast opzet ook roekeloosheid."]]],
["Wat is volgens BW 7 de hoofdregel voor schade door een eigen gebrek van de verzekerde zaak?", [["Die schade wordt niet vergoed, tenzij anders is overeengekomen.", "Eigen gebrek is een wettelijke uitsluiting van regelend recht; de polis mag dekking geven."], ["Die schade wordt altijd vergoed, omdat de zaak verzekerd is.", "De wet sluit schade door eigen gebrek juist uit, tenzij de polis anders bepaalt."], ["Die schade wordt alleen vergoed bij een allriskdekking, op grond van de wet.", "Het is de polis, niet de wet, die eigen gebrek eventueel meeverzekert."], ["Die schade valt onder de bereddingskosten.", "Bereddingskosten zijn kosten om schade te beperken; eigen gebrek is een oorzaak van schade."]]],
["Een woning met een waarde van € 250.000 is verzekerd voor € 200.000. Er ontstaat een schade van € 50.000. Er is geen garantie tegen onderverzekering of eerste-risicodekking. Hoeveel keert de verzekeraar uit?", [["€ 40.000.", "Bij onderverzekering wordt evenredig vergoed: € 50.000 × 200.000 / 250.000 = € 40.000."], ["€ 50.000.", "Volledige vergoeding zou gelden bij een eerste-risicodekking of garantie tegen onderverzekering, die hier ontbreken."], ["€ 37.500.", "Dit bedrag volgt niet uit de evenredigheidsregel; de verhouding verzekerde som / waarde is 0,8."], ["€ 30.000.", "Hier is ten onrechte het verschil van € 50.000 tussen waarde en som van de schade afgetrokken; dat is niet de evenredigheidsregel."]]],
["Iemand heeft hetzelfde risico bij twee verzekeraars gedekt (samenloop). Wat is het uitgangspunt in BW 7?", [["Hij krijgt zijn schade één keer vergoed; de verzekeraars verdelen die onderling.", "Samenloop doorbreekt het indemniteitsbeginsel niet: de verzekerde krijgt zijn schade één keer vergoed en de verzekeraars hebben onderling regres."], ["Hij ontvangt van beide verzekeraars de volledige schade, omdat hij twee premies betaalt.", "Dubbele vergoeding is in strijd met het indemniteitsbeginsel."], ["Alleen de verzekeraar met de oudste polis keert uit; de jongere polis vervalt.", "Ouderdom van de polis is niet de wettelijke maatstaf voor samenloop."], ["Beide verzekeringen zijn nietig, omdat dubbele dekking wettelijk verboden is.", "Samenloop maakt verzekeringen niet nietig; de wet regelt juist hoe zij samen uitkeren."]]],
["Wat houdt subrogatie in bij een schadeverzekering?", [["Na uitkering gaat de verhaalsvordering op de aansprakelijke derde over op de verzekeraar.", "Door subrogatie kan de verzekeraar de uitgekeerde schade verhalen op de veroorzaker."], ["De verzekerde mag zowel de verzekeraar als de aansprakelijke derde volledig laten betalen.", "Dan zou de verzekerde dubbel ontvangen; subrogatie voorkomt dat juist."], ["De verzekeraar mag na een uitkering de premie van de verzekerde eenzijdig verhogen.", "Premieaanpassing heeft niets te maken met subrogatie."], ["Een nieuwe verzekeraar neemt bij een overstap de lopende polis met alle rechten over.", "Overstappen is een nieuwe overeenkomst; subrogatie gaat over overgang van verhaalsrechten."]]],
["Wat is de verjaringstermijn van een rechtsvordering tot uitkering tegen een verzekeraar?", [["Drie jaar na de dag na bekendwording met de opeisbaarheid van de uitkering.", "Dat is de wettelijke termijn; stuiting is mogelijk door een schriftelijke mededeling."], ["Vijf jaar na de dag waarop het schadevoorval heeft plaatsgevonden of is ontdekt.", "Vijf jaar is de relatieve verjaringstermijn bij onrechtmatige daad, niet de termijn voor vorderingen op een verzekeraar."], ["Twintig jaar na de dag waarop de verzekeringsovereenkomst is gesloten.", "Twintig jaar is een absolute termijn uit het aansprakelijkheidsrecht, niet de termijn voor vorderingen op een verzekeraar."], ["Eén jaar na de dag waarop de schade bij de verzekeraar is gemeld.", "De wet kent geen termijn van één jaar voor deze vordering."]]],
["De verzekeraar wijst een claim ondubbelzinnig schriftelijk af en wijst op de gevolgen. Wat gebeurt er met de verjaring?", [["Er begint een nieuwe verjaringstermijn van zes maanden.", "Na een ondubbelzinnige erkenning of afwijzing loopt een nieuwe termijn van zes maanden."], ["De verjaringstermijn van drie jaar begint opnieuw te lopen.", "Na een duidelijke afwijzing is de nieuwe termijn juist korter: zes maanden."], ["De vordering is vanaf de dag van afwijzing direct verjaard.", "Een afwijzing laat de vordering niet direct verjaren; de klant heeft nog zes maanden om actie te nemen."], ["De verjaring is voorgoed gestuit en kan niet meer intreden.", "Stuiting leidt tot een nieuwe termijn, niet tot een vordering die nooit meer verjaart."]]],
["Een consument heeft een inboedelverzekering die na het eerste contractjaar stilzwijgend is verlengd. Wat geldt voor opzegging door de consument?", [["Hij kan op elk moment opzeggen met ten hoogste één maand opzegtermijn.", "Na stilzwijgende verlenging mag een consument dagelijks opzeggen met maximaal een maand opzegtermijn."], ["Hij kan alleen opzeggen tegen de eerstvolgende jaarlijkse contractvervaldatum.", "Dat geldt niet meer na stilzwijgende verlenging; de consument mag op elk moment opzeggen."], ["Hij kan opzeggen, maar moet een opzegtermijn van drie maanden aanhouden.", "Een opzegtermijn van meer dan een maand mag na stilzwijgende verlenging niet worden bedongen."], ["Hij kan alleen opzeggen nadat de verzekeraar de premie heeft verhoogd.", "De wet beperkt het opzegrecht niet tot een premieverhoging."]]],
["Wat is het wezenlijke verschil tussen een schadeverzekering en een sommenverzekering?", [["Een schadeverzekering vergoedt vermogensschade; een sommenverzekering keert een vast bedrag uit.", "Dit is het wettelijke onderscheid; het indemniteitsbeginsel geldt alleen voor schadeverzekeringen."], ["Een schadeverzekering is altijd wettelijk verplicht; een sommenverzekering is altijd een vrijwillige keuze.", "Verplichting staat los van het type: de meeste schadeverzekeringen zijn vrijwillig."], ["Een sommenverzekering kent altijd een eigen risico; een schadeverzekering nooit.", "Een eigen risico komt vooral voor bij schadeverzekeringen; het is geen onderscheidend kenmerk."], ["Een schadeverzekering keert alleen uit bij overlijden; een sommenverzekering bij schade.", "Uitkering bij overlijden is typisch voor een sommenverzekering, zoals een levensverzekering."]]],
["Een verzamelaar laat zijn schilderij vóór het afsluiten van de verzekering door een deskundige taxeren en de verzekeraar aanvaardt de taxatie. Wat is daarvan het gevolg bij schade?", [["De getaxeerde waarde geldt in beginsel, tenzij de verzekeraar bedrog aantoont.", "Een vooraf door een deskundige vastgestelde taxatie voorkomt discussie over de waarde; de verzekeraar kan die in beginsel alleen bij bedrog aantasten."], ["De verzekeraar mag de waarde na een schade altijd opnieuw laten vaststellen.", "Juist daarom wordt vooraf getaxeerd: de verzekeraar is in beginsel aan de taxatie gebonden."], ["De verzekeraar keert bij totaalverlies het dubbele van de getaxeerde waarde uit.", "Taxatie legt de waarde vast; het indemniteitsbeginsel staat geen dubbele uitkering toe."], ["De taxatie heeft alleen betekenis voor de hoogte van de premie, niet voor de schade.", "De taxatie heeft vooral betekenis voor de schadeuitkering."]]],
["Een consument sluit online een reisverzekering voor een reis van twee weken. Kan hij de overeenkomst binnen veertien dagen kosteloos ontbinden op grond van de regels voor financiële diensten op afstand?", [["Nee, kortlopende reis- en bagageverzekeringen (korter dan een maand) zijn uitgezonderd.", "Kortlopende reis- en bagageverzekeringen zijn uitgezonderd van de bedenktijd bij financiële diensten op afstand."], ["Ja, voor elke verzekering die op afstand is gesloten geldt veertien dagen bedenktijd.", "Er gelden uitzonderingen, waaronder kortlopende reis- en bagageverzekeringen."], ["Ja, maar alleen zolang de reis nog niet is begonnen en er geen schade is gemeld.", "De wet maakt die uitzondering niet; voor deze verzekeringen is er geen ontbindingsrecht."], ["Nee, een ontbindingsrecht op afstand bestaat bij geen enkele schadeverzekering.", "Voor veel schadeverzekeringen op afstand geldt wel een bedenktijd van veertien dagen."]]],
["Wat is het 'verzekerd belang' bij een schadeverzekering?", [["Het financiële belang van de verzekerde bij het uitblijven van schade.", "Zonder belang lijdt de verzekerde geen schade en heeft een schadeverzekering geen zin."], ["Het bedrag van de jaarlijkse premie die de verzekeringnemer betaalt.", "De premie is de prijs van de dekking, niet het belang."], ["De winst die de verzekeraar naar verwachting op de polis maakt.", "Het verzekerd belang is dat van de verzekerde, niet dat van de verzekeraar."], ["Het deel van de schade dat de verzekerde per gebeurtenis zelf als eigen risico draagt.", "Het eigen risico is het deel van de schade voor eigen rekening, niet het verzekerd belang."]]],
["Wat houdt het indemniteitsbeginsel in?", [["De verzekerde mag er door de uitkering financieel niet op vooruitgaan.", "Een schadeverzekering vergoedt de schade, niet meer; zo wordt verrijking en een prikkel tot schade voorkomen."], ["De verzekeraar moet bij elke schade de volledige verzekerde som uitkeren.", "De verzekerde som is een maximum; uitgekeerd wordt de werkelijke schade."], ["De verzekerde heeft op grond van de wet altijd recht op nieuwwaarde.", "Nieuwwaarde is een toegestane, maar contractuele afwijking; het beginsel zelf gaat over het voorkomen van verrijking."], ["De verzekerde mag dezelfde schade bij meerdere verzekeraars claimen.", "Dubbele vergoeding is juist in strijd met het indemniteitsbeginsel."]]],
["Waarom wordt vergoeding op basis van nieuwwaarde bij inboedel aanvaard, ondanks het indemniteitsbeginsel?", [["Omdat anders de verzekerde moet bijbetalen voor vervanging; polisgrenzen beperken verrijking.", "Nieuwwaarde is een geaccepteerde afwijking; met grenzen, zoals dagwaarde voor sterk verouderde zaken, blijft verrijking beperkt."], ["Omdat het indemniteitsbeginsel volgens de wet niet geldt voor inboedelverzekeringen.", "Het beginsel geldt voor alle schadeverzekeringen; nieuwwaarde is een contractuele afwijking."], ["Omdat de wet nieuwwaardevergoeding voorschrijft voor alle particuliere schadeverzekeringen.", "De wet schrijft nieuwwaarde niet voor; het is een polisafspraak."], ["Omdat nieuwwaarde in de praktijk altijd lager uitvalt dan de dagwaarde van een zaak.", "Het is andersom: nieuwwaarde is gelijk aan of hoger dan dagwaarde."]]],
["Wat is het verschil tussen een aftrekfranchise en een integrale franchise?", [["Aftrek: eigen risico gaat altijd van de schade af; integraal: boven de grens alles vergoed.", "Bij een integrale franchise is de grens een drempel: schade eronder wordt niet vergoed, schade erboven volledig."], ["Integraal: de verzekerde betaalt altijd de hele schade; aftrek: alleen kleine schades.", "Boven de drempel vergoedt de verzekeraar bij een integrale franchise juist alles."], ["Aftrek: geldt alleen bij aansprakelijkheid; integraal: geldt alleen bij brand- en stormverzekeringen.", "Aftrekfranchises komen bij vrijwel alle schadeverzekeringen voor."], ["Er is geen verschil; beide termen beschrijven hetzelfde vaste eigen risico per schade.", "De werking verschilt duidelijk bij schades boven de grens."]]],
["Meneer De Vries heeft een volledige cascoverzekering met een eigen risico van € 250. Zijn schade bedraagt € 3.000 en is gedekt. Wat keert de verzekeraar uit (aftrekfranchise)?", [["€ 2.750.", "Bij een aftrekfranchise wordt het eigen risico van de gedekte schade afgetrokken: € 3.000 − € 250."], ["€ 3.000.", "Het eigen risico wordt hier niet vergoed; dat komt voor rekening van de verzekerde."], ["€ 3.250.", "Het eigen risico wordt afgetrokken, niet opgeteld."], ["€ 2.500.", "Hier is het eigen risico twee keer afgetrokken."]]],
["Waarom kiezen klanten soms voor een hoger vrijwillig eigen risico?", [["Om een lagere premie te betalen en kleine schades zelf te dragen.", "Een hoger eigen risico verlaagt de premie; passend als de klant kleine schades zelf kan opvangen."], ["Om bij een grote schade een hogere uitkering boven de verzekerde som te ontvangen.", "Een hoger eigen risico verlaagt juist de uitkering per schade en verhoogt de verzekerde som niet."], ["Omdat de wet dit verplicht stelt voor beginnende bestuurders.", "Een verhoogd eigen risico voor jonge bestuurders volgt uit polisvoorwaarden, niet uit de wet, en is dan niet vrijwillig."], ["Om de evenredigheidsregel bij onderverzekering te voorkomen.", "Onderverzekering hangt af van de verhouding verzekerde som en waarde, niet van het eigen risico."]]],
["Wat kenmerkt een allriskdekking bij inboedel of woonhuis ten opzichte van een dekking op basis van genoemde gevaren?", [["Plotselinge, onvoorziene schade is gedekt, behalve wat is uitgesloten.", "Bij allrisk geldt in beginsel dekking tenzij een uitsluiting van toepassing is; bij genoemde gevaren moet de oorzaak in de opsomming staan."], ["Alle denkbare schade is gedekt, zonder enige uitsluiting in de polis.", "Ook allrisk kent uitsluitingen, zoals slijtage, eigen gebrek of opzet."], ["Alleen schade door brand, storm en inbraak is gedekt, en verder niets.", "Dat is een beperkte dekking op basis van genoemde gevaren."], ["Schade is gedekt zonder eigen risico, omdat allrisk de duurste vorm is.", "Allriskdekkingen hebben juist vaak een eigen risico, zeker voor de 'overige' schades."]]],
["Wat houdt een verzekering 'op eerste risico' in?", [["Vergoeding tot de verzekerde som, zonder evenredigheid bij onderverzekering.", "Bij eerste risico wordt geen onderverzekering toegepast; de som is het maximum."], ["Vergoeding van alleen de eerste schade per verzekeringsjaar, daarna niet meer.", "Eerste risico gaat niet over het aantal schades, maar over het ontbreken van evenredigheid."], ["De verzekerde draagt zelf het eerste deel van elke schade als eigen risico.", "Dat is een eigen risico, geen eerste-risicodekking."], ["De dekking gaat pas in na een wachttijd vanaf de ingangsdatum van de polis.", "Een wachttijd heeft niets te maken met eerste risico."]]],
["Welke schade valt doorgaans ook bij een allriskdekking niet onder de verzekering?", [["Geleidelijke slijtage en veroudering van een zaak.", "Slijtage is niet plotseling en onvoorzien en daarmee standaard uitgesloten."], ["Een televisie die plotseling van de kast valt en daarbij kapotgaat.", "Dit is een plotselinge en onvoorziene gebeurtenis, het typische voorbeeld van een allriskschade."], ["Inkt die per ongeluk op een bank wordt gemorst.", "Een onverwacht ongeluk in huis is bij allrisk in de regel gedekt, eventueel met een eigen risico."], ["Een brandschade aan de keuken.", "Brand is ook bij beperktere dekkingen gedekt, dus zeker bij allrisk."]]],
["Op wie rust de verzekeringsplicht op grond van de Wet aansprakelijkheidsverzekering motorrijtuigen (WAM)?", [["Op de kentekenhouder van het motorrijtuig.", "De WAM legt de plicht bij de houder; de RDW controleert of voor elk kenteken een WA-verzekering bestaat."], ["Op iedere bestuurder afzonderlijk.", "De verzekering dekt wel de aansprakelijkheid van iedere bestuurder, maar de plicht om te verzekeren ligt bij de houder."], ["Op de fabrikant of dealer van het voertuig.", "Fabrikant en dealer hebben geen WAM-verplichting voor auto's van klanten."], ["Op de eigenaar van de grond waarop de auto geparkeerd staat.", "De verzekeringsplicht hangt aan het voertuig en de houder, niet aan de parkeerplaats."]]],
["Welk bijzonder recht geeft de WAM aan een benadeelde?", [["Een eigen recht om de WA-verzekeraar van de veroorzaker rechtstreeks aan te spreken.", "Dankzij deze directe actie hoeft de benadeelde niet via de veroorzaker te procederen."], ["Het recht om de premie van de veroorzaker te laten verhogen.", "De benadeelde heeft geen zeggenschap over de premie van een ander."], ["Het recht op vergoeding van alle schade door de eigen cascoverzekeraar, ongeacht schuld.", "De WAM regelt de positie van de benadeelde tegenover de WA-verzekeraar, niet tegenover de eigen casco."], ["Het recht om het rijbewijs van de veroorzaker te laten innemen.", "Rijbewijsmaatregelen zijn strafrechtelijk of bestuursrechtelijk, niet geregeld in de WAM."]]],
["Een bestuurder veroorzaakt onder invloed van alcohol een aanrijding. De polis sluit rijden onder invloed uit. Wat geldt voor de benadeelde tegenpartij?", [["De WA-verzekeraar vergoedt de benadeelde en verhaalt dit daarna op de verzekerde.", "Polisuitsluitingen kunnen niet aan de benadeelde worden tegengeworpen; de verzekeraar heeft wel regres op de verzekerde."], ["De benadeelde krijgt niets, omdat de polis rijden onder invloed uitdrukkelijk uitsluit.", "Juist om benadeelden te beschermen, mag de WA-verzekeraar zulke verweren niet tegen hen inroepen."], ["Het Waarborgfonds Motorverkeer betaalt altijd in plaats van de verzekeraar.", "Het Waarborgfonds springt vooral bij als er geen verzekering is of de veroorzaker onbekend is; hier is een verzekeraar."], ["De benadeelde moet de bestuurder eerst strafrechtelijk laten veroordelen.", "Voor vergoeding via de WA-verzekeraar is geen strafrechtelijke veroordeling nodig."]]],
["Wanneer kan een benadeelde in het verkeer een beroep doen op het Waarborgfonds Motorverkeer?", [["Als de schade is veroorzaakt door een onbekend of onverzekerd motorrijtuig.", "Het Waarborgfonds vangt schade op die anders onvergoed blijft, bijvoorbeeld bij doorrijden na een ongeval."], ["Altijd, als de eigen cascoverzekering de schade aan de auto niet dekt.", "Het fonds is geen vangnet voor een ontbrekende eigen cascodekking."], ["Als de benadeelde de aanrijding zelf heeft veroorzaakt en geen casco heeft.", "Wie zelf de schade veroorzaakt, heeft geen aanspraak op het fonds voor eigen schade."], ["Alleen bij schade die in het buitenland door een Nederlander is veroorzaakt.", "Het fonds is bedoeld voor schade in Nederland door onbekende of onverzekerde motorrijtuigen."]]],
["Een automobilist rijdt een fietsend kind van 10 jaar aan. Wat geldt op grond van art. 185 Wegenverkeerswet voor de letselschade van het kind?", [["Volledige vergoeding, tenzij het kind opzettelijk of bewust roekeloos handelde.", "Voor kinderen onder de 14 jaar geldt de 100%-regel; alleen opzet of bewuste roekeloosheid doorbreekt die."], ["Vergoeding van 50%, omdat het kind zelf ook een verkeersfout heeft gemaakt.", "De 50%-regel geldt voor letsel van volwassen fietsers en voetgangers, niet voor kinderen onder de 14 jaar."], ["Geen vergoeding als het kind door rood licht reed, wegens eigen schuld.", "Een verkeersfout van een kind onder de 14 jaar is geen opzet of bewuste roekeloosheid."], ["Vergoeding naar rato van schuld, zoals bij botsingen tussen twee auto's.", "Bij kinderen onder de 14 jaar wordt niet naar rato van schuld verdeeld; de 100%-regel gaat voor."]]],
["Een volwassen fietser raakt gewond bij een aanrijding met een auto. Hij heeft zelf een verkeersfout gemaakt, maar er is geen overmacht voor de automobilist. Wat geldt voor zijn letselschade?", [["Hij krijgt ten minste 50% vergoed; bij minder eigen schuld meer.", "De 50%-regel waarborgt dat een volwassen niet-gemotoriseerde verkeersdeelnemer minimaal de helft van zijn letselschade vergoed krijgt."], ["Hij krijgt niets, omdat hij zelf een fout maakte.", "Een eigen fout leidt niet tot nul, tenzij er opzet of bewuste roekeloosheid is."], ["Hij krijgt altijd 100% vergoed.", "De 100%-regel geldt voor kinderen onder de 14 jaar."], ["Hij krijgt een vast bedrag dat jaarlijks door de overheid wordt bepaald.", "De vergoeding hangt af van de werkelijke schade en de eigen schuld, niet van een vast bedrag."]]],
["Een automobilist rijdt door eigen schuld tegen een boom en raakt gewond. Hij heeft alleen een WA-verzekering. Welke verzekering zou zijn eigen letselschade wél dekken?", [["Een schadeverzekering voor inzittenden (SVI).", "De SVI vergoedt letsel- en zaakschade van inzittenden, inclusief de bestuurder, ook als hij zelf schuld heeft."], ["De WA-verzekering, als hij het eigen risico betaalt.", "De WA-verzekering dekt alleen schade aan anderen, nooit de eigen letselschade van de bestuurder."], ["Het Waarborgfonds Motorverkeer.", "Het Waarborgfonds keert niet uit aan een bestuurder die het ongeval zelf veroorzaakt."], ["De aansprakelijkheidsverzekering voor particulieren (AVP).", "De AVP sluit schade met motorrijtuigen uit en dekt geen eigen letsel."]]],
["Wat is het verschil tussen een schadeverzekering voor inzittenden (SVI) en een ongevallenverzekering voor inzittenden (OVI)?", [["De SVI vergoedt de werkelijke schade; de OVI keert vaste bedragen uit.", "De SVI is een schadeverzekering, de OVI een sommenverzekering; daardoor biedt de SVI meestal een ruimere vergoeding."], ["De SVI geldt alleen voor de bestuurder; de OVI alleen voor de passagiers.", "Beide verzekeringen gelden in beginsel voor alle inzittenden, inclusief de bestuurder."], ["De OVI vergoedt ook schade aan de auto; de SVI dekt alleen letselschade.", "Geen van beide is een cascoverzekering; de SVI vergoedt wel schade aan spullen van inzittenden."], ["Er is geen verschil; het zijn twee namen voor hetzelfde verzekeringsproduct.", "Het verschil tussen werkelijke schade en vaste bedragen is wezenlijk."]]],
["Welke schade is bij een beperkt-cascoverzekering doorgaans NIET gedekt?", [["Schade aan de eigen auto door een aanrijding door eigen schuld.", "Eigen-schuldschade is het onderscheidende verschil tussen beperkt en volledig casco."], ["Diefstal van de auto vanaf een openbare parkeerplaats.", "Diefstal is een kerngevaar van beperkt casco."], ["Ruitschade door een opspattend steentje op de snelweg.", "Ruitschade valt doorgaans onder beperkt casco."], ["Schade door een boom die tijdens een storm op de geparkeerde auto valt.", "Storm en ander natuurgeweld vallen doorgaans onder beperkt casco."]]],
["Meneer Jansen rijdt bij het inparkeren met zijn auto tegen een paaltje. Er is geen tegenpartij. Onder welke dekking valt de schade aan zijn auto?", [["Een volledige cascoverzekering.", "Alleen volledig casco dekt schade aan de eigen auto door eigen toedoen."], ["De WA-verzekering van de auto.", "WA dekt schade die de bestuurder aan anderen toebrengt, niet aan zijn eigen auto."], ["De beperkt-cascoverzekering.", "Beperkt casco dekt van buiten komende gevaren zoals brand, diefstal en storm, niet eigen-schuldschade."], ["De schadeverzekering inzittenden.", "De SVI dekt schade van inzittenden, niet schade aan het voertuig zelf."]]],
["Een verzekerde meldt een schade bij zijn autoverzekeraar. De schade wordt volledig verhaald op de aansprakelijke tegenpartij. Wat betekent dit doorgaans voor zijn bonus-malustrede?", [["Hij valt niet terug, omdat de schade volledig is verhaald.", "Bonus-malusregelingen laten volledig verhaalde schades meestal buiten beschouwing."], ["Hij valt evenveel treden terug als bij een eigen-schuldschade.", "Een volledig verhaalde schade kost de verzekeraar per saldo niets en leidt in de regel niet tot terugval."], ["Hij verliest in één keer al zijn opgebouwde schadevrije jaren.", "Volledig verlies van schadevrije jaren hoort niet bij een volledig verhaalde schade."], ["Hij valt één trede terug, omdat elke gemelde schade meetelt.", "Een volledig verhaalde schade kost de verzekeraar per saldo niets en telt in de regel niet mee."]]],
["Een klant heeft een kleine eigen-schuldschade van enkele honderden euro's aan een andere auto gereden. Welk advies kan passend zijn om terugval op de bonus-malusladder te voorkomen?", [["Nagaan of hij de schade bij de verzekeraar kan terugkopen door het bedrag terug te betalen.", "Veel verzekeraars bieden de mogelijkheid een schade terug te kopen; bij kleine schades kan dat goedkoper zijn dan de premiestijging."], ["De schade niet melden en de tegenpartij vragen te wachten tot na de premievervaldatum.", "De schade aan een ander moet worden gemeld; niet melden schaadt de benadeelde en kan het recht op dekking aantasten."], ["De polis direct opzeggen en de auto elders verzekeren zonder de schade te vermelden.", "Dat is misleiding; schadevrije jaren worden centraal geregistreerd en gecontroleerd."], ["De schade bij de verzekeraar opgeven als cascoschade in plaats van als WA-schade.", "Een schade onjuist voorstellen is fraude en geen passend advies."]]],
["Hoe weet een nieuwe autoverzekeraar hoeveel schadevrije jaren een overstappende klant heeft opgebouwd?", [["Via de centrale registratie van schadevrije jaren (Roy-data).", "Verzekeraars registreren schadevrije jaren centraal, zodat de nieuwe verzekeraar die kan controleren."], ["Uitsluitend via de verklaring van de klant op het aanvraagformulier.", "De opgave van de klant wordt gecontroleerd aan de hand van de centrale registratie."], ["Via een opgave van de RDW op basis van de kentekenregistratie.", "De RDW registreert kentekens en verzekeringsplicht, maar niet de opgebouwde schadevrije jaren."], ["Via de Belastingdienst, die de schadehistorie van auto's bijhoudt.", "De Belastingdienst houdt geen schadehistorie van autoverzekeringen bij."]]],
["Een klant schaft een speed pedelec aan (elektrische fiets met trapondersteuning tot ongeveer 45 km/u). Wat geldt voor de verzekering?", [["Het is een bromfiets met kenteken en valt onder de WAM-verzekeringsplicht.", "Speed pedelecs gelden als bromfiets; voor bromfietsen geldt de WAM-plicht."], ["Schade aan derden valt onder de AVP, net als bij een gewone fiets of e-bike.", "De AVP sluit motorrijtuigen zoals bromfietsen uit; voor de speed pedelec is een WA-verzekering nodig."], ["Verzekeren is niet nodig, omdat de berijder zelf moet blijven trappen.", "Bij een gewone e-bike tot 25 km/u is dat zo, maar een speed pedelec is wettelijk een bromfiets."], ["Alleen een cascoverzekering is wettelijk verplicht voor dit voertuig.", "De wettelijke plicht betreft aansprakelijkheid (WA), niet casco."]]],
["Wat is de herbouwwaarde van een woning?", [["De kosten om de woning na schade op dezelfde plek en met dezelfde bestemming te herbouwen.", "De herbouwwaarde is de basis voor de verzekerde som van een opstalverzekering."], ["De marktwaarde die de eigenaar bij verkoop van de woning inclusief grond zou ontvangen.", "Marktwaarde bevat onder meer de grondwaarde en de ligging; die worden niet herbouwd."], ["De WOZ-waarde die de gemeente jaarlijks voor de onroerendezaakbelasting vaststelt.", "De WOZ-waarde is een fiscale waarde inclusief grond en zegt weinig over de herbouwkosten."], ["De executiewaarde die een taxateur voor de hypotheekverstrekker vaststelt.", "De executiewaarde is een waarde bij gedwongen verkoop voor de geldverstrekker, niet de kosten van herbouw."]]],
["Wat houdt een garantie tegen onderverzekering bij een woonhuisverzekering in?", [["Geen onderverzekering, mits de waarde volgens de voorgeschreven methode is bepaald en wijzigingen zijn gemeld.", "De garantie geeft zekerheid over volledige vergoeding, maar is gebonden aan voorwaarden zoals een herbouwwaardemeter of taxatie en het melden van verbouwingen."], ["Bij schade wordt altijd de volledige verzekerde som uitgekeerd, ongeacht de werkelijke omvang van de schade.", "De garantie voorkomt onderverzekering, maar laat het indemniteitsbeginsel intact."], ["De klant hoeft verbouwingen en uitbreidingen van de woning nooit meer aan de verzekeraar door te geven.", "Ingrijpende verbouwingen of uitbreidingen moeten juist worden gemeld om de garantie te behouden."], ["De verzekeraar garandeert dat de premie gedurende de looptijd niet stijgt, ook niet bij indexering.", "De garantie gaat over de vergoeding bij schade, niet over premiestabiliteit."]]],
["Na een brand besluit de eigenaar zijn woning niet te herbouwen. Wat bepalen woonhuispolissen hier gebruikelijk voor de schadevergoeding?", [["Vergoeding op basis van de verkoopwaarde zonder grond, als die lager is dan de herbouwwaarde.", "Wie niet herbouwt, heeft geen herbouwkosten; vergoeding op verkoopwaarde voorkomt verrijking."], ["Vergoeding van de volledige herbouwwaarde, omdat de premie altijd op die waarde is gebaseerd.", "Bij niet-herbouwen zou volledige herbouwwaarde kunnen leiden tot verrijking; polissen beperken dat."], ["Geen vergoeding, omdat de verzekerde niet aan zijn herbouwplicht voldoet.", "Ook zonder herbouw is er schade; die wordt vergoed, alleen op een andere basis."], ["Vergoeding van de WOZ-waarde inclusief grond, omdat de woning verloren is.", "Grond gaat bij brand niet verloren en wordt niet vergoed."]]],
["Wat is het verschil tussen nieuwwaarde en dagwaarde bij inboedel?", [["Nieuwwaarde: prijs van nieuwe gelijkwaardige zaken; dagwaarde: nieuwwaarde minus slijtage en veroudering.", "Dit zijn vaste begrippen; polissen bepalen wanneer op dagwaarde wordt vergoed, bijvoorbeeld bij sterk verouderde zaken."], ["Dagwaarde: de oorspronkelijke aankoopprijs; nieuwwaarde: de huidige verkoopprijs op een tweedehandsmarkt.", "Dagwaarde houdt rekening met slijtage en veroudering; nieuwwaarde is de prijs van nieuwe vergelijkbare zaken."], ["Nieuwwaarde geldt alleen voor kunst en antiek; dagwaarde geldt voor alle overige inboedel.", "Voor kunst en antiek wordt juist vaak de vervangingswaarde of taxatiewaarde gebruikt."], ["Er is geen verschil bij zaken jonger dan tien jaar; daarna geldt automatisch en altijd de dagwaarde.", "Ook jonge zaken slijten; het verschil hangt niet af van een vaste leeftijdsgrens."]]],
["Welke gebeurtenis valt doorgaans onder het begrip 'brand' in een woonhuis- of inboedelpolis?", [["Een vuur met vlammen buiten een haard dat zich zelfstandig kan uitbreiden.", "Dit is de gangbare definitie; zonder vlammen en zelfstandige uitbreiding is het geen brand."], ["Een broeiende stapel natte kleding die veel rook ontwikkelt, maar geen vlammen.", "Broeien zonder vlammen voldoet niet aan de branddefinitie."], ["Een tafelblad dat schroeit doordat er een hete pan op is gezet.", "Schroeien en zengen zijn in polissen uitdrukkelijk geen brand."], ["Een kunststof bak die naast de kachel door de hitte is gesmolten.", "Smelten zonder vlammen geldt niet als brand."]]],
["Vanaf welke windsnelheid spreken de meeste woonhuis- en inboedelpolissen van 'storm'?", [["Ten minste 14 meter per seconde (windkracht 7).", "Dit is de gangbare definitie in Nederlandse polissen; de verzekerde kan gegevens van het KNMI gebruiken."], ["Bij elke windstoot die zichtbare schade veroorzaakt.", "Polissen noemen juist een minimum windsnelheid."], ["Pas vanaf windkracht 12, oftewel orkaankracht.", "Dat zou de dekking sterk beperken; de gangbare grens ligt bij windkracht 7."], ["Alleen als het KNMI code rood heeft afgegeven.", "Een weeralarm is geen dekkingsvoorwaarde; bepalend is de windsnelheid."]]],
["Na een diefstal uit een woning stelt de verzekeraar dat er geen dekking is. Welke voorwaarde stellen veel inboedelpolissen bij diefstal?", [["Dat er sporen van braak zijn bij het binnendringen van de woning.", "Veel polissen eisen sporen van braak; zonder sporen is diefstal moeilijk te onderscheiden van verlies of fraude."], ["Dat de dader binnen een maand door de politie is aangehouden.", "Opsporing van de dader is geen dekkingsvoorwaarde."], ["Dat de verzekerde zelf thuis was op het moment van de diefstal.", "Diefstal tijdens afwezigheid is juist de klassieke gedekte situatie."], ["Dat de gestolen zaken jonger zijn dan vijf jaar op de schadedatum.", "De leeftijd van de zaken bepaalt de waardering, niet of er dekking is."]]],
["Welke waterschade is in een standaard woonhuispolis doorgaans gedekt?", [["Water dat plotseling uit een leiding of aangesloten toestel stroomt door een defect.", "Leidingwater is het klassieke gedekte watergevaar."], ["Water dat de kelder binnenkomt door langzaam stijgend grondwater na een natte periode.", "Grondwater is doorgaans uitgesloten; het is geen plotselinge gebeurtenis."], ["Vocht dat ontstaat door langdurig achterstallig onderhoud aan het dak van de woning.", "Slecht onderhoud is een standaard uitsluiting."], ["Optrekkend vocht in de muren dat in de loop van jaren schimmel heeft veroorzaakt.", "Optrekkend vocht is een geleidelijk proces en niet gedekt."]]],
["Een huurder heeft op eigen kosten een nieuwe keuken in de huurwoning laten plaatsen. Hoe is dit gewoonlijk verzekerd?", [["Als huurdersbelang op de inboedelverzekering van de huurder.", "Veranderingen en verbeteringen die een huurder op eigen kosten aanbrengt, vallen meestal onder huurdersbelang in de inboedelpolis."], ["Automatisch op de opstalverzekering van de verhuurder van de woning.", "De verhuurder heeft geen belang bij een door de huurder betaalde keuken en verzekert die niet."], ["Op de aansprakelijkheidsverzekering van de huurder.", "De AVP dekt schade aan anderen, niet eigen investeringen."], ["Dit kan niet worden verzekerd.", "Het huurdersbelang is juist een gangbare dekking."]]],
["Een klant koopt een appartement in een gebouw met een Vereniging van Eigenaars (VvE). Wat is gebruikelijk voor de opstalverzekering?", [["De VvE verzekert het gebouw; de eigenaar verzekert zijn inboedel en eigen verbeteringen.", "De opstal van een appartementencomplex wordt doorgaans door de VvE verzekerd; de eigenaar regelt de rest zelf."], ["Iedere eigenaar sluit een eigen opstalverzekering af voor het volledige gebouw.", "Dat zou tot dubbele dekking leiden; de VvE verzekert het gebouw."], ["Een appartement hoeft niet te worden verzekerd, omdat de VvE een reservefonds heeft.", "Het gebouw moet wel worden verzekerd, alleen gebeurt dat via de VvE."], ["De gemeente verzekert het gebouw, omdat het om gestapelde bouw gaat.", "De gemeente heeft geen rol bij de verzekering van particuliere gebouwen."]]],
["Waarvoor dient een inboedelwaardemeter?", [["Om de inboedelwaarde in te schatten op basis van kenmerken van het huishouden.", "Bij gebruik van de waardemeter bieden verzekeraars vaak een garantie tegen onderverzekering."], ["Om de marktwaarde van de woning voor de hypotheekaanvraag vast te stellen.", "Voor de woningwaarde bij een hypotheek is een taxatierapport nodig, geen inboedelwaardemeter."], ["Om na een schade de dagwaarde van elk afzonderlijk voorwerp te bepalen.", "De waardemeter schat de totale inboedel vooraf; de schade wordt per schade vastgesteld."], ["Om de premie van de opstalverzekering op basis van de herbouwwaarde te bepalen.", "De opstalpremie is gebaseerd op de herbouwwaarde, niet op een inboedelwaardemeter."]]],
["De familie Smit gaat voor een jaar naar het buitenland en laat de woning leeg staan. Wat is het passende advies?", [["De verzekeraar vooraf informeren, omdat leegstand de dekking kan beperken.", "Leegstand vergroot onder meer het risico op inbraak en onopgemerkte schade; veel polissen eisen melding en beperken de dekking."], ["Niets doen, omdat een woonhuispolis altijd geldt, ongeacht bewoning of leegstand.", "Veel polissen beperken de dekking bij leegstand of als die niet is gemeld."], ["De verzekeringen opzeggen, omdat een lege woning geen risico loopt.", "Het gebouw loopt nog steeds risico op brand en storm; opzeggen is onverstandig."], ["Alleen de AVP aanpassen, omdat die het buitenlandverblijf moet dekken.", "Leegstand raakt vooral de woonhuis- en inboedelverzekering, niet de AVP."]]],
["Waarom kennen inboedelpolissen vaak een apart maximum voor lijfsieraden en andere kostbaarheden?", [["Omdat zij klein, waardevol en diefstalgevoelig zijn.", "Een maximum beperkt het risico voor de verzekeraar; wie meer heeft, kan een aparte kostbaarhedendekking afsluiten."], ["Omdat de wet sieraden van inboedeldekking uitsluit.", "De maxima volgen uit de polis, niet uit de wet."], ["Omdat sieraden juridisch niet tot de inboedel horen.", "Sieraden horen tot de inboedel; alleen de vergoeding is beperkt."], ["Omdat de premie anders onder de assurantiebelasting valt.", "Assurantiebelasting staat los van de maxima voor sieraden in de polis."]]],
["Welke aansprakelijkheid dekt een aansprakelijkheidsverzekering voor particulieren (AVP)?", [["Aansprakelijkheid als particulier, niet in de uitoefening van beroep of bedrijf.", "De AVP is bedoeld voor het privéleven; beroeps- en bedrijfsaansprakelijkheid vraagt een andere verzekering."], ["Alle aansprakelijkheid, dus ook bij werkzaamheden als zelfstandig ondernemer.", "Aansprakelijkheid als ondernemer valt buiten de AVP."], ["Schade die de verzekerde per ongeluk aan zijn eigen spullen toebrengt.", "Een AVP dekt schade aan anderen, niet eigen schade."], ["Schade aan derden veroorzaakt met de eigen auto of motor van de verzekerde.", "Schade met motorrijtuigen is uitgesloten; daarvoor dient de WA-verzekering."]]],
["Wat zijn de vereisten voor aansprakelijkheid uit onrechtmatige daad?", [["Onrechtmatigheid, toerekenbaarheid, schade, causaal verband en relativiteit.", "Alle vereisten moeten zijn vervuld voordat iemand op grond van onrechtmatige daad aansprakelijk is."], ["Schade en een geldige aansprakelijkheidsverzekering bij de veroorzaker.", "Een verzekering is geen vereiste voor aansprakelijkheid; de wettelijke vereisten zijn veel uitgebreider."], ["Opzet van de dader en een onherroepelijke strafrechtelijke veroordeling.", "Ook nalatigheid kan onrechtmatig zijn; een strafrechtelijke veroordeling is niet nodig."], ["Een schriftelijke overeenkomst tussen partijen en een ingebrekestelling.", "Aansprakelijkheid uit onrechtmatige daad bestaat juist zonder overeenkomst; een ingebrekestelling hoort bij wanprestatie."]]],
["Een kind van 9 jaar gooit met een steen de ruit van de buren in. Wie is aansprakelijk?", [["De ouders, op grond van risicoaansprakelijkheid voor kinderen onder de 14 jaar.", "Ouders zijn aansprakelijk voor kinderen jonger dan 14 jaar als de gedraging een onrechtmatige daad zou zijn bij een ouder persoon."], ["Het kind zelf, omdat het de ruit heeft ingegooid.", "Een kind onder de 14 jaar is niet zelf aansprakelijk; de wet legt de aansprakelijkheid bij de ouders."], ["Niemand; kinderen onder de 14 jaar en hun ouders zijn wettelijk niet aansprakelijk te maken.", "Het kind zelf niet, maar de ouders wel; zij zijn risicoaansprakelijk."], ["Alleen de school, als het na schooltijd gebeurde.", "De school heeft na schooltijd geen toezicht; de wet wijst de ouders aan."]]],
["Een jongen van 15 jaar veroorzaakt schade bij een ander. Wat geldt voor de aansprakelijkheid van zijn ouders?", [["Zij zijn aansprakelijk, tenzij hun niet te verwijten valt dat zij het niet beletten.", "Voor kinderen van 14 en 15 jaar geldt een schuldaansprakelijkheid van de ouders met een omgekeerde bewijslast."], ["Zij zijn altijd aansprakelijk, zonder dat tegenbewijs mogelijk is.", "De zuivere risicoaansprakelijkheid geldt alleen voor kinderen onder de 14 jaar."], ["Zij zijn nooit aansprakelijk; alleen de jongen zelf kan worden aangesproken.", "De jongen kan zelf aansprakelijk zijn, maar de ouders kunnen dat daarnaast ook zijn."], ["Zij zijn alleen aansprakelijk als de jongen nog bij hen inwoont en geen inkomen heeft.", "Inwoning of inkomen is niet het wettelijke criterium; de regel hangt af van leeftijd en verwijtbaarheid."]]],
["De hond van mevrouw Visser bijt een voorbijganger. Wat geldt voor haar aansprakelijkheid?", [["Als bezitter van de hond is zij risicoaansprakelijk, ook zonder schuld.", "De bezitter van een dier is aansprakelijk voor schade door het eigen gedrag van het dier; schuld is niet nodig."], ["Zij is alleen aansprakelijk als zij de hond slecht heeft opgevoed of niet aanlijnde.", "Schuld is niet vereist; het gaat om risicoaansprakelijkheid, ongeacht opvoeding of aanlijnen."], ["De gemeente is aansprakelijk als de hond aangelijnd was.", "De gemeente is geen bezitter van het dier."], ["Zij is niet aansprakelijk als de hond een stamboom heeft.", "Een stamboom speelt geen rol bij de aansprakelijkheid."]]],
["Sanne leent de laptop van een vriendin en laat die per ongeluk vallen. Wat is het belangrijkste aandachtspunt bij de AVP?", [["Schade aan zaken onder opzicht is in veel AVP-polissen uitgesloten of beperkt gedekt.", "Bij geleende of gehuurde zaken speelt de opzichtsbepaling; de dekking verschilt per polis."], ["Schade aan geleende zaken is bij elke AVP-polis zonder beperking volledig gedekt.", "Veel polissen beperken of sluiten opzichtschade uit."], ["De schade valt onder de inboedelverzekering van Sanne, omdat zij de laptop gebruikte.", "De laptop is niet van Sanne en hoort niet tot haar inboedel."], ["De schade valt onder de inboedelverzekering van de vriendin, die moet daar eerst claimen.", "De vriendin hoeft niet eerst haar eigen polis aan te spreken; de vraag is of Sanne via haar AVP dekking heeft voor opzichtschade."]]],
["Een groep jongeren vernielt opzettelijk een bushokje. Tim hoorde bij de groep maar deed zelf niet mee en had geen opzet. Hij wordt op grond van groepsaansprakelijkheid aangesproken. Wat bepalen veel AVP-polissen hierover?", [["Tim kan dekking hebben; de verzekerden met opzet hebben geen dekking.", "Veel polissen beperken de opzetuitsluiting tot de verzekerde die zelf opzet had."], ["Alle groepsleden hebben volledige dekking, ook wie zelf opzet had.", "Wie zelf opzet had, is uitgesloten van dekking."], ["Niemand van de groep heeft dekking, omdat er opzettelijk is vernield.", "Veel polissen geven juist dekking voor een verzekerde zonder eigen opzet."], ["Tim heeft alleen dekking als de politie tegen hem geen proces-verbaal opmaakt.", "Een proces-verbaal is geen criterium voor dekking."]]],
["Wat is de relatieve verjaringstermijn voor een vordering tot schadevergoeding uit onrechtmatige daad?", [["Vijf jaar na bekendheid met de schade en de aansprakelijke persoon.", "Daarnaast geldt een absolute termijn; de termijn van vijf jaar loopt vanaf bekendheid."], ["Drie jaar na de dag waarop de schade is ontstaan, ongeacht bekendheid.", "Drie jaar is de termijn voor vorderingen tegen een verzekeraar; bij onrechtmatige daad telt bovendien de bekendheid."], ["Eén jaar na de dag waarop de benadeelde de schade heeft ontdekt.", "Een termijn van één jaar geldt niet voor onrechtmatige daad."], ["Tien jaar na de dag waarop de schadeveroorzakende gebeurtenis plaatsvond.", "Een termijn van tien jaar geldt niet als relatieve termijn; de relatieve termijn is vijf jaar vanaf bekendheid."]]],
["Wat is de vrije advocaatkeuze bij een rechtsbijstandverzekering?", [["Het recht om in een procedure zelf een advocaat of andere bevoegde rechtshulpverlener te kiezen.", "Dit recht volgt uit Europees recht; de verzekeraar mag de kosten wel binnen redelijke grenzen beperken."], ["Het recht om voor elk juridisch probleem direct een eigen advocaat op kosten van de verzekeraar te nemen.", "De vrije keuze geldt voor procedures en bij belangenconflicten; daarbuiten mag de verzekeraar eigen juristen inzetten."], ["Het recht van de verzekeraar om in een procedure de advocaat van de tegenpartij aan te wijzen.", "De verzekeraar heeft geen zeggenschap over de advocaat van de tegenpartij."], ["Het recht om de kosten van de gekozen advocaat altijd onbeperkt vergoed te krijgen.", "Vrije keuze betekent niet onbeperkte vergoeding; een redelijk kostenmaximum is toegestaan."]]],
["Een klant sluit een rechtsbijstandverzekering en schakelt een maand later hulp in bij een conflict met zijn aannemer dat al maanden speelt. Wat is het waarschijnlijke antwoord van de verzekeraar?", [["Geen dekking, omdat het geschil al bestond of voorzienbaar was.", "Rechtsbijstandverzekeringen dekken geen conflicten die al bestonden of te verwachten waren toen de polis werd afgesloten."], ["Volledige dekking, omdat de premie vanaf de ingangsdatum is betaald.", "Premiebetaling verandert niets aan de voorwaarde dat het geschil na aanvang onzeker moet zijn."], ["Gedeeltelijke dekking, namelijk voor de helft van de juridische kosten.", "Er bestaat geen gedeeltelijke dekking voor bestaande geschillen."], ["Dekking, mits de klant een hoger eigen risico voor deze zaak betaalt.", "Een eigen risico maakt een bestaand geschil niet alsnog verzekerd."]]],
["Wat is het doel van een wachttijd in een rechtsbijstandverzekering?", [["Voorkomen dat iemand zich verzekert als een conflict al dreigt.", "Gedurende de wachttijd ontstane geschillen zijn niet gedekt; zo blijft de verzekering betaalbaar voor iedereen."], ["De verzekeraar tijd geven om een geschikte advocaat te zoeken.", "De wachttijd gaat over de ingangsdatum van de dekking, niet over de behandeling."], ["De premie pas te innen nadat de wachttijd is verstreken.", "Premie is vanaf de ingangsdatum verschuldigd, ook tijdens de wachttijd."], ["De klant de kans geven de polis kosteloos te ontbinden.", "Kosteloos ontbinden hoort bij een bedenktijd, niet bij een wachttijd."]]],
["Verzekerde en rechtsbijstandverzekeraar verschillen van mening over de haalbaarheid van een procedure. Wat biedt de geschillenregeling in de meeste polissen?", [["Een oordeel van een externe advocaat naar keuze, op kosten van de verzekeraar.", "De geschillenregeling waarborgt een onafhankelijk oordeel over de aanpak van de zaak."], ["Een verplichte gang naar Kifid voordat de zaak inhoudelijk verder kan worden behandeld.", "Kifid gaat over klachten, niet over de inhoudelijke aanpak; de geschillenregeling zit in de polis."], ["Een definitieve beslissing door de verzekeraar zelf, zonder verdere toetsing.", "De geschillenregeling bestaat juist om dat te voorkomen."], ["Een procedure bij de rechter, waarvan de verzekerde de kosten zelf voorschiet.", "De geschillenregeling is een interne regeling met een extern advocaatoordeel, geen gerechtelijke procedure op eigen kosten."]]],
["Welke annuleringsreden is bij een annuleringsverzekering doorgaans gedekt?", [["Ernstige ziekte of overlijden van een naast familielid vóór vertrek.", "Annuleringsverzekeringen dekken alleen onvoorziene, in de polis genoemde gebeurtenissen; ernstige ziekte en overlijden zijn kernredenen."], ["Geen zin meer in de reis door een verandering van plannen.", "Een eigen keuze is geen onvoorziene gebeurtenis en dus niet gedekt."], ["Een goedkopere aanbieding voor dezelfde reis bij een ander bureau.", "Prijsverschil is geen verzekerde annuleringsreden."], ["Slechte weersvoorspellingen voor de periode van de reis.", "Slecht weer is geen gedekte annuleringsreden."]]],
["Hoe verhoudt de dekking voor geneeskundige kosten in een reisverzekering zich tot de basisverzekering (Zvw)?", [["Zij vult aan: zij dekt buitenlandse kosten die de zorgverzekering niet vergoedt.", "Een zorgverzekering vergoedt in het buitenland vaak niet alles; de reisverzekering vult het verschil aan, afhankelijk van de voorwaarden."], ["Zij vervangt de zorgverzekering volledig zolang de verzekerde op reis is.", "De zorgverzekering blijft gelden; de reisverzekering vult aan."], ["Zij vergoedt alleen zorgkosten die na terugkeer in Nederland worden gemaakt.", "Een reisverzekering is juist bedoeld voor kosten tijdens een reis, ook in het buitenland."], ["Zij is wettelijk verplicht voor iedereen die buiten Europa op reis gaat.", "Een reisverzekering is vrijwillig, ook voor reizen buiten Europa."]]],
["Op welke basis vergoedt een reisverzekering doorgaans gestolen bagage?", [["Op dagwaarde, met maxima per categorie en een eigen risico.", "Reisverzekeringen werken meestal met dagwaarde en limieten, bijvoorbeeld voor elektronica en sieraden."], ["Altijd op nieuwwaarde, zonder maximum.", "Een onbeperkte nieuwwaardevergoeding is ongebruikelijk bij bagage."], ["Op basis van de aankoopprijs, ook als die decennia geleden was.", "De aankoopprijs houdt geen rekening met slijtage en veroudering."], ["Op basis van een vast bedrag per koffer.", "Vergoeding hangt af van de werkelijke waarde, niet van het aantal koffers."]]],
["Een vakantiegebied wordt kort voor vertrek getroffen door een natuurramp. Welke regeling kan bij een pakketreis van een aangesloten reisorganisatie uitkomst bieden?", [["Het Calamiteitenfonds Reizen, dat calamiteiten op de bestemming dekt.", "Het Calamiteitenfonds dekt calamiteiten op de bestemming bij aangesloten reisorganisaties, iets wat annuleringsverzekeringen vaak uitsluiten."], ["Stichting Garantiefonds Reisgelden, dat ook natuurrampen vergoedt.", "SGR beschermt bij insolventie van de reisorganisatie, niet bij calamiteiten."], ["Kifid, dat bij rampen een tegemoetkoming aan reizigers uitkeert.", "Kifid behandelt klachten en keert zelf geen schade uit."], ["Het Waarborgfonds, dat schade door onvoorziene rampen opvangt.", "Het Waarborgfonds Motorverkeer gaat over verkeersschade met onverzekerde of onbekende voertuigen."]]],
["Wat is het verschil tussen een naturauitvaartverzekering en een kapitaaluitvaartverzekering?", [["Natura levert uitvaartdiensten en -goederen; kapitaal keert een geldbedrag uit.", "Bij natura krijgen nabestaanden een pakket uitvaartdiensten; bij kapitaal is het bedrag vrij te besteden."], ["Natura keert een hoger geldbedrag uit; kapitaal keert een lager bedrag uit.", "De naturaverzekering keert geen geld uit, maar levert diensten."], ["Kapitaal geldt alleen bij crematie; natura alleen bij een begrafenis.", "Het type uitvaart staat los van de vorm van de verzekering."], ["Er is geen verschil; beide termen beschrijven dezelfde geldsomverzekering.", "Het verschil tussen diensten en geld is wezenlijk."]]],
["Tot welk type verzekering behoort een kapitaaluitvaartverzekering?", [["Een levensverzekering (sommenverzekering).", "Een kapitaaluitvaartverzekering keert bij overlijden een vooraf bepaald bedrag uit en is daarmee een levensverzekering."], ["Een schadeverzekering (indemniteitsverzekering).", "De uitkering hangt niet af van een vermogensschade, maar van het overlijden."], ["Een aansprakelijkheidsverzekering voor nabestaanden.", "Er is geen aansprakelijkheid in het spel."], ["Een aanvullende zorgverzekering bij overlijden.", "Een uitvaartverzekering vergoedt geen zorgkosten."]]],
["Een klant heeft twintig jaar geleden een kapitaaluitvaartverzekering met een vast bedrag gesloten. Wat is een belangrijk aandachtspunt bij nazorg?", [["Of het verzekerde bedrag nog toereikend is voor de huidige uitvaartkosten.", "Zonder indexatie kan het vaste bedrag te laag zijn geworden; dat is een belangrijk adviespunt."], ["Of de polis inmiddels onder de WAM-verzekeringsplicht is komen te vallen.", "De WAM gaat over motorrijtuigen, niet over uitvaartverzekeringen."], ["Of de verzekering kan worden omgezet in een inboedelverzekering.", "Dat is geen zinvolle of gangbare omzetting."], ["Of er bonus-malustreden zijn opgebouwd die de premie verlagen.", "Bonus-malus speelt bij autoverzekeringen, niet bij uitvaart."]]],
["Welk informatiedocument moet een klant op grond van de IDD vóór het sluiten van een schadeverzekering ontvangen?", [["Het gestandaardiseerde informatiedocument (IPID).", "Het IPID geeft in een vaste opzet de belangrijkste kenmerken, dekkingen en uitsluitingen van een schadeverzekering."], ["Een essentiële-informatiedocument (EID) onder PRIIPs.", "Het EID is bedoeld voor verpakte beleggingsproducten, niet voor schadeverzekeringen."], ["Een Europees gestandaardiseerd informatieblad (ESIS).", "Het ESIS hoort bij hypothecair krediet."], ["Een jaaropgave met de premie en de dekkingen.", "Een jaaropgave is geen precontractueel productdocument."]]],
["Moet een distributeur onder de IDD ook bij verkoop zonder advies (execution-only) de eisen en behoeften van de klant vaststellen?", [["Ja, elke verkoop moet passen bij de eisen en behoeften van de klant.", "De IDD verplicht bij iedere distributie tot vaststelling van eisen en behoeften, ook zonder advies."], ["Nee, bij execution-only is de klant volledig zelf verantwoordelijk.", "De eisen-en-behoeftentoets geldt ook bij verkoop zonder advies."], ["Alleen als het verzekerde bedrag boven een wettelijke grens ligt.", "De IDD maakt geen onderscheid naar verzekerd bedrag."], ["Alleen bij levensverzekeringen, niet bij schadeverzekeringen.", "De verplichting geldt voor alle verzekeringen, ook schadeverzekeringen."]]],
["Welke informatie over zijn beloning moet een bemiddelaar onder de IDD vóór het sluiten van een schadeverzekering in ieder geval geven?", [["De aard van de beloning: provisie, fee of een combinatie.", "De IDD verplicht tot transparantie over de aard van de beloning, zodat de klant mogelijke belangenconflicten ziet."], ["Het jaarinkomen van de adviseur over het afgelopen jaar.", "Het inkomen van de adviseur valt niet onder de verplichte informatie."], ["De winstmarge van de verzekeraar op het betreffende product.", "Die informatie hoeft de bemiddelaar niet te verstrekken."], ["Niets, omdat beloningsinformatie alleen bij leven verplicht is.", "Informatie over de aard van de beloning is ook bij schadeverzekeringen verplicht."]]],
["Mag een adviseur provisie ontvangen voor bemiddeling in een particuliere inboedelverzekering?", [["Ja, het provisieverbod geldt niet voor deze schadeverzekering.", "Het provisieverbod geldt voor complexe producten en impactvolle producten zoals hypotheken; schadeverzekeringen vallen er niet onder."], ["Nee, provisie is sinds 2013 voor alle verzekeringen verboden.", "Het provisieverbod van 2013 geldt niet voor schadeverzekeringen."], ["Alleen als de klant daar vooraf schriftelijk om heeft gevraagd.", "Er is geen wettelijke eis dat de klant vooraf om provisie vraagt."], ["Alleen als de premie onder een wettelijk vastgesteld bedrag ligt.", "Het provisieverbod kent geen premiegrens; het hangt af van het soort product."]]],
["Een verzekeraar biedt een inboedelverzekering aan als pakket samen met een AVP. Welke informatie moet de klant op grond van de IDD dan krijgen?", [["Of de onderdelen ook afzonderlijk kunnen worden gekocht, en zo ja, wat zij los kosten.", "Bij koppelverkoop verplicht de IDD tot informatie over de mogelijkheid tot losse aankoop en de kosten per onderdeel."], ["Een overzicht van alle vergelijkbare pakketten van concurrerende verzekeraars in de markt.", "Een marktoverzicht van concurrenten is geen IDD-verplichting bij koppelverkoop."], ["Een schriftelijke goedkeuring van de AFM voor de combinatie van producten.", "De AFM keurt pakketten niet vooraf goed."], ["Een berekening van de winst die de verzekeraar op het pakket maakt.", "De winstmarge van de verzekeraar hoeft niet te worden verstrekt."]]],
["Een klant wil een doorlopende reisverzekering afsluiten. Uit inventarisatie blijkt dat hij via zijn creditcard al een reisdekking heeft. Wat past bij de zorgplicht van de adviseur?", [["De bestaande dekking analyseren en wijzen op mogelijke dubbele dekking.", "Passend advies houdt rekening met bestaande voorzieningen; dubbele dekking kost de klant onnodig premie."], ["De reisverzekering afsluiten zonder de creditcarddekking te bekijken.", "Dan voldoet het advies niet aan de inventarisatie- en zorgplicht."], ["De klant adviseren de creditcard op te zeggen om dubbele kosten te vermijden.", "De creditcard opzeggen valt buiten de vraag en is niet per se in het belang van de klant; eerst moet worden vergeleken."], ["De klant naar de creditcardmaatschappij verwijzen en zelf geen advies geven.", "De adviseur moet de bestaande dekking zelf meenemen in zijn advies."]]],
["Wat houdt het productontwikkelings- en beoordelingsproces (PARP) voor verzekeraars in?", [["Dat producten de belangen van de doelgroep evenwichtig dienen en worden getoetst.", "Het PARP vraagt dat producten kostenefficiënt, veilig, nuttig en begrijpelijk zijn voor de beoogde doelgroep."], ["Dat de AFM elk nieuw verzekeringsproduct vooraf toetst en goedkeurt voor de markt.", "De AFM keurt producten niet vooraf goed; zij houdt toezicht op het proces."], ["Dat de adviseur elk product zelf ontwikkelt voor zijn eigen klantenkring.", "Productontwikkeling ligt bij de aanbieder; de distributeur levert wel informatie."], ["Dat verzekeraars hun premies elk jaar verplicht aan de consumentenprijsindex aanpassen.", "Het PARP gaat over het dienen van klantbelangen, niet over verplichte premie-indexatie."]]],
["Wat is gangbaar als een verzekerde het niet eens is met de schadevaststelling door de expert van de verzekeraar?", [["Een eigen contra-expert inschakelen, met kostenvergoeding tot het niveau van de expert van de verzekeraar.", "Polissen bieden meestal deze regeling; boven dat bedrag alleen als de kosten redelijk zijn."], ["De schadevaststelling zonder meer accepteren, omdat de expert van de verzekeraar bindend beslist.", "De verzekerde mag een contra-expert inschakelen; de expert van de verzekeraar beslist niet bindend."], ["Direct een procedure bij de rechter beginnen, omdat een contra-expertise niet is toegestaan.", "Contra-expertise is juist gebruikelijk en toegestaan voordat een geschil naar de rechter gaat."], ["Een klacht bij de AFM indienen, die vervolgens de omvang van de schade opnieuw vaststelt.", "De AFM behandelt geen individuele schadegeschillen en stelt geen schades vast."]]],
["Wat is een belangrijke eis aan een schade-expert die door de verzekeraar wordt ingeschakeld?", [["Hij moet de schade onafhankelijk en deskundig vaststellen.", "Het Nederlands Instituut van Register Experts (NIVRE) stelt eisen aan vakbekwaamheid en gedrag."], ["Hij moet in dienst zijn van de verzekerde om belangen te waarborgen.", "Een expert van de verzekeraar werkt in opdracht van de verzekeraar; de verzekerde kan zelf een contra-expert nemen."], ["Hij moet de schade zo laag mogelijk vaststellen voor de verzekeraar.", "Een expert moet de schade objectief vaststellen, niet zo laag mogelijk."], ["Hij moet bij elke schade ook de nieuwe premie van de polis bepalen.", "De premie is geen taak van de schade-expert."]]],
["Hoe is de bewijslast meestal verdeeld bij een schadeclaim?", [["Verzekerde: gedekte gebeurtenis aannemelijk maken; verzekeraar: uitsluiting bewijzen.", "Wie een recht inroept, moet het bewijzen; een uitsluiting is een verweer van de verzekeraar."], ["De verzekeraar moet in alle gevallen bewijzen dat er geen schade is ontstaan.", "De verzekerde moet eerst zijn claim aannemelijk maken."], ["De verzekerde moet aantonen dat geen enkele uitsluiting van de polis van toepassing is.", "Het beroep op een uitsluiting moet de verzekeraar bewijzen."], ["De schade-expert draagt de volledige bewijslast voor zowel dekking als uitsluiting.", "De expert stelt de schade vast, maar is geen procespartij en draagt geen bewijslast."]]],
["Wat moet een consument doen voordat hij een klacht over zijn verzekeraar bij Kifid kan indienen?", [["Eerst bij de verzekeraar zelf klagen en diens standpunt afwachten.", "Kifid behandelt een klacht pas nadat de interne klachtenprocedure is doorlopen."], ["Eerst een procedure bij de kantonrechter beginnen en het vonnis afwachten.", "Kifid is juist een alternatief voor de rechter; een vonnis is niet nodig."], ["Eerst de AFM om toestemming vragen voor het indienen van de klacht.", "De AFM speelt geen rol bij de toegang tot Kifid."], ["Eerst de verzekering opzeggen, zodat er geen lopende relatie meer is.", "Opzegging is geen voorwaarde voor een klacht bij Kifid."]]],
["Welke financiële dienstverleners moeten zijn aangesloten bij Kifid?", [["Wft-vergunninghouders die diensten verlenen aan consumenten.", "De Wft verplicht vergunninghouders met consumentendienstverlening tot aansluiting bij een erkende geschilleninstantie, in de praktijk Kifid."], ["Alleen banken die betaal- en spaarrekeningen aan consumenten aanbieden.", "Ook verzekeraars en adviseurs moeten zijn aangesloten."], ["Alleen dienstverleners met meer dan vijftig werknemers.", "Er geldt geen grens naar aantal werknemers."], ["Geen enkele; aansluiting bij Kifid is altijd vrijwillig.", "Aansluiting is wettelijk verplicht voor consumentendienstverlening."]]],
["Wat kan Kifid NIET doen?", [["Boetes opleggen aan financiële dienstverleners.", "Boetes zijn een bevoegdheid van toezichthouders zoals de AFM; Kifid beslecht geschillen."], ["Een uitspraak doen in een geschil tussen consument en verzekeraar.", "Dat is de kerntaak van de Geschillencommissie."], ["Bemiddelen tussen consument en verzekeraar.", "Kifid probeert vaak eerst te bemiddelen."], ["In hoger beroep een geschil behandelen via de Commissie van Beroep.", "De Commissie van Beroep is onderdeel van Kifid."]]],
["Wat is de belangrijkste functie van Stichting CIS?", [["Centrale databanken beheren voor risicobeoordeling en fraudebestrijding.", "Verzekeraars raadplegen CIS bij acceptatie en schadebehandeling, binnen de privacyregels."], ["Klachten van consumenten over verzekeraars bindend behandelen.", "Klachten worden behandeld door de verzekeraar en daarna Kifid."], ["Toezicht houden op de solvabiliteit van particuliere schade- en levensverzekeraars.", "Prudentieel toezicht ligt bij DNB."], ["Terrorismeschade herverzekeren voor aangesloten verzekeraars.", "Dat is de rol van de NHT."]]],
["Een consument wil weten welke gegevens over hem bij Stichting CIS zijn geregistreerd. Wat kan hij doen?", [["Een inzageverzoek indienen bij CIS op grond van de AVG.", "Iedereen heeft onder de AVG het recht te weten welke persoonsgegevens over hem worden verwerkt."], ["Niets; CIS-gegevens zijn geheim voor consumenten.", "De AVG geeft wel een recht op inzage."], ["Een verzoek indienen bij de AFM.", "De AFM beheert de CIS-gegevens niet."], ["Een rechtszaak beginnen, omdat inzage alleen via de rechter mogelijk is.", "Inzage kan zonder rechter; een inzageverzoek bij CIS is de aangewezen weg."]]],
["Wat is de rol van de Nederlandse Herverzekeringsmaatschappij voor Terrorismeschaden (NHT)?", [["Zij herverzekert terrorismeschade voor verzekeraars, tot een jaarlijks maximum.", "Via de NHT kunnen verzekeraars terrorismeschade dekken; de uitkering wordt bepaald volgens het uitkeringsprotocol."], ["Zij keert terrorismeschade rechtstreeks uit aan onverzekerde consumenten en bedrijven.", "De NHT keert uit aan verzekeraars, niet rechtstreeks aan onverzekerde consumenten of bedrijven."], ["Zij houdt namens DNB toezicht op de solvabiliteit van verzekeraars.", "Toezicht ligt bij AFM en DNB; de NHT is een herverzekeraar."], ["Zij herverzekert overstromingsschade door het bezwijken van dijken.", "Overstroming is een ander risico; de NHT gaat over terrorisme."]]],
["Welke vormen van molest worden in Nederlandse polissen standaard uitgesloten?", [["Gewapend conflict, burgeroorlog, opstand, binnenlandse onlusten, oproer en muiterij.", "Dit zijn de zes vaste vormen van molest volgens de gangbare definitie van het Verbond van Verzekeraars."], ["Terrorisme, kwaadwillige besmetting, sabotage, gijzeling, ontvoering en cyberaanvallen.", "Terrorisme en verwante risico's vallen onder de terrorismeclausule en de NHT, niet onder de molestdefinitie."], ["Inbraak, diefstal, vandalisme, beroving, afpersing en brandstichting door derden.", "Dit zijn gewone (al dan niet gedekte) gevaren, geen molest."], ["Storm, hagel, overstroming, aardbeving, vulkanische uitbarsting en blikseminslag.", "Dit zijn natuurgevaren, geen molest."]]],
["Welke overstromingsschade is bij woonhuis- en inboedelpolissen in Nederland doorgaans NIET gedekt?", [["Schade door het bezwijken van een primaire waterkering, zoals een zeedijk.", "Dit catastroferisico is meestal uitgesloten; overstroming door een niet-primaire (regionale) kering is in veel polissen wel gedekt."], ["Schade door hevige regen die onvoorzien via het dak de woning binnenstroomt.", "Neerslagschade is in veel polissen juist gedekt."], ["Schade door een gesprongen waterleiding in de woning tijdens vorst.", "Leidingwater is een standaard gedekt gevaar."], ["Schade door het bezwijken van een kleine regionale kering langs een polder.", "Veel polissen dekken dit tegenwoordig wel."]]],
["Wat geldt voor een tegemoetkoming onder de Wet tegemoetkoming schade bij rampen (Wts)?", [["Er is geen tegemoetkoming voor schade die redelijkerwijs verzekerbaar was.", "De Wts is een vangnet voor niet-verzekerbare schade en wordt per ramp van toepassing verklaard."], ["De Wts vergoedt alle schade, ook als de klant een verzekering had kunnen afsluiten.", "Verzekerbare schade is juist uitgesloten."], ["De Wts is een verplichte verzekering voor huiseigenaren.", "De Wts is een overheidsregeling, geen verzekering."], ["De Wts geldt automatisch bij elke storm.", "De Wts moet per ramp van toepassing worden verklaard."]]],
["Wat betekent 'herstel gaat voor vervangen' bij duurzame schadebehandeling?", [["Repareren waar mogelijk in plaats van vervangen, om grondstoffen te besparen.", "Steeds meer verzekeraars sturen op herstel, mits de kwaliteit gelijkwaardig is."], ["De verzekerde moet beschadigde zaken voortaan altijd zelf en op eigen kosten herstellen.", "Herstel wordt door of via de verzekeraar geregeld en niet aan de verzekerde opgelegd."], ["Vervanging van beschadigde zaken is wettelijk niet meer toegestaan.", "Vervanging blijft mogelijk als herstel niet zinvol is."], ["Herstel is verplicht omdat het in alle gevallen goedkoper is.", "Duurzaamheid, niet kosten, is het uitgangspunt."]]],
["Bij welk product moet een adviseur onder de IDD-regels de duurzaamheidsvoorkeuren van de klant uitvragen?", [["Bij advies over verzekeringsgebaseerde beleggingsproducten.", "De verplichting tot het uitvragen van duurzaamheidsvoorkeuren geldt voor beleggingsverzekeringen, niet voor schadeverzekeringen."], ["Bij advies over een inboedel- of woonhuisverzekering.", "Voor schadeverzekeringen bestaat deze uitvraagplicht niet."], ["Bij advies over een WA- of cascoverzekering voor de auto.", "Ook hier geldt de uitvraagplicht niet."], ["Bij advies over een doorlopende reis- en annuleringsverzekering.", "Een reisverzekering is geen beleggingsproduct."]]],
["Een adviseur bemiddelt uitsluitend in particuliere schadeverzekeringen. Valt hij onder de Wwft?", [["Nee, de Wwft wijst alleen bemiddelaars in levensverzekeringen aan.", "De Wwft-verplichtingen gelden voor bemiddelaars in levensverzekeringen, niet voor pure schadebemiddelaars."], ["Ja, de Wwft geldt voor alle financiële dienstverleners met een vergunning.", "De Wwft geldt alleen voor aangewezen instellingen."], ["Ja, zodra de jaarpremie van een klant een wettelijke grens overschrijdt.", "De Wwft kent geen premiegrens die schadebemiddeling onder de wet brengt."], ["Nee, de Wwft geldt uitsluitend voor banken en betaalinstellingen.", "De Wwft geldt ook voor andere instellingen, waaronder bemiddelaars in levensverzekeringen."]]],
["Binnen welke termijn moet een organisatie een datalek dat een risico vormt voor betrokkenen melden bij de Autoriteit Persoonsgegevens?", [["Binnen 72 uur na ontdekking.", "De AVG verplicht tot melding zonder onredelijke vertraging en uiterlijk binnen 72 uur."], ["Binnen 14 dagen.", "Veertien dagen is te laat onder de AVG."], ["Binnen een maand.", "Een maand is de termijn voor het beantwoorden van een inzageverzoek, niet voor een datalekmelding."], ["Alleen als de verzekerde daarom vraagt.", "De meldplicht geldt los van een verzoek van de betrokkene."]]],
["Bij letselschade verwerkt een verzekeraar medische gegevens. Wat is daarvoor gebruikelijk om de privacy te waarborgen?", [["Beoordeling door een medisch adviseur met medisch beroepsgeheim.", "Gezondheidsgegevens zijn bijzondere persoonsgegevens; toegang is beperkt tot de medisch adviseur en wie dat strikt nodig heeft."], ["Inzage door alle schadebehandelaars die aan het dossier werken.", "Toegang tot gezondheidsgegevens moet strikt worden beperkt."], ["Doorsturen van het volledige medische dossier naar de tegenpartij.", "Delen met de tegenpartij zonder noodzaak en toestemming is in strijd met de AVG."], ["Opslag in een gezamenlijke databank die alle verzekeraars inzien.", "Zo'n gedeelde medische databank is in strijd met dataminimalisatie en het medisch beroepsgeheim."]]]
],
"schade-zakelijk":[
["Welke volgorde past bij een systematische zakelijke risico-inventarisatie?", [["Risico's in kaart brengen, analyseren op kans en impact en dan een maatregel kiezen.", "Eerst moet duidelijk zijn welke risico's er zijn en hoe zwaar ze wegen; pas dan kun je kiezen tussen vermijden, verminderen, overdragen of zelf dragen."], ["Eerst het premiebudget vaststellen en daarna bekijken welke risico's daarbinnen passen.", "Het budget is een randvoorwaarde, maar het startpunt is het risicoprofiel van het bedrijf; anders blijven grote risico's mogelijk onbelicht."], ["Alle denkbare risico's verzekeren en na een schade bekijken welke dekkingen overbodig waren.", "Dat is geen inventarisatie maar het omgekeerde ervan; het leidt tot onnodige premie en mogelijk toch tot gaten in de dekking."], ["Alleen de risico's uitwerken die de ondernemer zelf in het intakegesprek noemt.", "De adviseur moet juist ook risico's signaleren die de ondernemer niet ziet; de klant kent zijn eigen blinde vlekken niet."]]],
["Een ondernemer heeft elk jaar een paar kleine glasschades van enkele honderden euro's. Welke risicobeheersing ligt het meest voor de hand?", [["Het risico grotendeels zelf dragen, bijvoorbeeld via een hoger eigen risico.", "Kleine, voorspelbare schaden betaalt de ondernemer via de premie toch zelf, vermeerderd met de kosten van de verzekeraar; zelf dragen is dan vaak doelmatiger."], ["Het risico volledig verzekeren, zonder eigen risico en met een zo ruim mogelijke dekking.", "Bij frequente kleine schaden betaalt de ondernemer die schaden plus kosten en marge terug in de premie; dat is zelden efficiënt."], ["Het risico vermijden door het bedrijfspand te verlaten.", "Vermijden is hier volstrekt disproportioneel; het bedrijf zou zijn activiteiten moeten opgeven voor een beperkt risico."], ["Het risico rechtstreeks overdragen aan een herverzekeraar die kleine schaden afhandelt.", "Een herverzekeraar verzekert verzekeraars, niet individuele ondernemers; dat is geen keuze die de ondernemer zelf kan maken."]]],
["Welk risico komt bij uitstek in aanmerking om via een verzekering over te dragen?", [["Een risico met een kleine kans maar een zeer grote, continuïteitsbedreigende schade.", "Dit soort risico's kan de onderneming niet zelf dragen, terwijl de lage kans de premie betaalbaar houdt; daarvoor is verzekeren bedoeld."], ["Een risico met een grote kans en een kleine schade, die het bedrijf goed kan opvangen.", "Zulke schaden zijn voorspelbaar en worden via de premie toch door de ondernemer betaald; zelf dragen ligt meer voor de hand."], ["Een schade die zeker optreedt, zoals normale slijtage van machines.", "Verzekeren vereist onzekerheid; een gebeurtenis die zeker plaatsvindt is geen verzekerbaar risico maar een kostenpost."], ["Een ondernemersrisico, zoals een teruglopende vraag naar de producten van het bedrijf.", "Het algemene ondernemersrisico van tegenvallende omzet is niet verzekerbaar; dat hoort bij het ondernemen zelf."]]],
["Een adviseur gebruikt bij de risico-inventarisatie een matrix van kans en impact. Hoe wordt een risico met zowel een hoge kans als een hoge impact het best benaderd?", [["Vooral met maatregelen die kans of impact verkleinen, of door het risico te vermijden.", "Een risico dat vaak én zwaar toeslaat is meestal niet of alleen tegen zeer hoge premie verzekerbaar; preventie of vermijden staat dan voorop."], ["Uitsluitend door het risico zelf te dragen en daarvoor een reserve op te bouwen.", "Zelf dragen past bij kleine, voorspelbare schaden; bij hoge impact kan het de continuïteit van het bedrijf bedreigen."], ["Door het risico te accepteren omdat het toch niet te beheersen is.", "Juist dit soort risico's vraagt actief beheer; accepteren zonder maatregelen is onverantwoord."], ["Door het te verzekeren met een zo laag mogelijk eigen risico en een ruime verzekerde som.", "Een verzekeraar zal een risico met hoge kans en hoge impact niet of alleen tegen een zeer hoge premie accepteren; verzekeren is hier niet de eerste stap."]]],
["Wat is het belangrijkste doel van een bedrijfsbezoek bij de risico-inventarisatie van een productiebedrijf?", [["Zien hoe het bedrijf feitelijk werkt: bouwaard, preventie en afhankelijkheden.", "Ter plaatse ziet de adviseur risico's zoals brandcompartimentering, opslag van gevaarlijke stoffen en kritieke machines, wat nodig is voor een passend advies."], ["Vaststellen welke verzekeraar voor dit bedrijf de laagste premie rekent.", "Een premievergelijking kan zonder bezoek; het bezoek dient om het risico zelf te begrijpen."], ["Controleren of de fiscale en financiële administratie van het bedrijf op orde is.", "Dat is geen taak van de schadeadviseur; voor de risico-inventarisatie gaat het om de verzekerbare risico's."], ["Vooraf afspreken hoe hoog een toekomstige schade-uitkering zal zijn.", "De uitkering hangt af van de omvang van een toekomstige schade en de polis; die kan bij een bedrijfsbezoek niet worden vastgesteld."]]],
["Wat wordt in schadeverzekeringen volgens de gangbare definitie verstaan onder brand?", [["Een vuur buiten een haard, met vlammen die zich op eigen kracht kunnen uitbreiden.", "Dit is de kern van de standaarddefinitie die verzekeraars hanteren; het gaat om een zich zelfstandig voortplantend vuur."], ["Iedere schade door hitte of vuur, waaronder ook schroeien, zengen, smelten en verkolen.", "Schroeien, zengen, smelten, verkolen en broeien zonder vlammen gelden juist niet als brand."], ["Elk vuur dat schade veroorzaakt, ook als het binnen een haard of kachel blijft.", "Vuur in een haard is een beoogd vuur en geen brand; er moet sprake zijn van vuur buiten een haard."], ["Elke gebeurtenis waarbij rook ontstaat, ook zonder vlammen.", "Rook alleen is geen brand; rook- en roetschade is wel vaak gedekt, maar als afzonderlijke gebeurtenis."]]],
["In een restaurant schroeit een te heet strijkijzer een tafelkleed, zonder dat er vlammen ontstaan. Is dit brandschade in de zin van de brandverzekering?", [["Nee, schroeien zonder vlammen valt niet onder het begrip brand.", "Zonder vlammen die zich op eigen kracht kunnen uitbreiden is er geen brand; schroeischade valt daarbuiten."], ["Ja, want de schade is door hitte ontstaan.", "Hitte alleen is onvoldoende; de definitie vraagt om vuur met vlammen buiten een haard."], ["Ja, mits de schade hoger is dan het eigen risico.", "Het eigen risico bepaalt alleen hoeveel er wordt uitgekeerd, niet of een gebeurtenis als brand geldt."], ["Nee, omdat een restaurant met open keuken een verhoogd brandrisico heeft.", "De aard van het bedrijf beïnvloedt premie en acceptatie, maar niet de vraag of schroeien brand is."]]],
["Een ondernemer huurt een winkelpand en heeft voor eigen rekening een nieuwe pui en een vaste winkelinrichting laten aanbrengen. Hoe verzekert hij dit belang het best?", [["Via een dekking voor huurdersbelang, meestal op de inventaris- of bedrijfsmiddelenpolis.", "De verbeteringen zijn voor rekening van de huurder; de huurdersbelangdekking is precies voor dit risico bedoeld."], ["Niet apart, omdat aanpassingen van de huurder altijd op de opstalpolis van de verhuurder zijn meeverzekerd.", "Dat is niet vanzelfsprekend; de verhuurder verzekert zijn eigen belang en de huurder loopt dan het risico onverzekerd te zijn."], ["Via zijn aansprakelijkheidsverzekering voor bedrijven.", "De AVB dekt aansprakelijkheid tegenover derden, geen schade aan eigen investeringen."], ["Via een bedrijfsschadeverzekering.", "Bedrijfsschade dekt het verlies aan brutowinst na een schade, niet de materiële schade aan de inrichting."]]],
["Op welke waarde wordt een bedrijfspand bij een opstalverzekering in de regel verzekerd als het na een schade wordt herbouwd?", [["De herbouwwaarde.", "De herbouwwaarde is het bedrag dat nodig is om het pand direct na de schade in dezelfde vorm en voor hetzelfde gebruik te herbouwen."], ["De WOZ-waarde.", "De WOZ-waarde is een fiscale waarde inclusief grond en sluit niet aan bij de kosten van herbouw."], ["De marktwaarde inclusief grond.", "Grond gaat bij brand niet verloren en de marktwaarde volgt de vastgoedmarkt, niet de bouwkosten."], ["De boekwaarde volgens de jaarrekening.", "De boekwaarde is na afschrijving vaak veel lager dan de herbouwkosten en zou tot een tekort leiden."]]],
["Op welke waarde worden handelsgoederen (voorraad) bij een goederenverzekering in de regel verzekerd?", [["De vervangingswaarde: wat opnieuw inkopen of maken van de goederen kost.", "De verzekering vergoedt het materiële verlies; de gemiste winstmarge valt onder een bedrijfsschadeverzekering."], ["De verkoopprijs, inclusief de winstmarge die op de goederen zou zijn gemaakt.", "Dan zou de verzekering ook winst vergoeden die niet is gemaakt; dat verlies hoort bij bedrijfsschade."], ["De fiscale boekwaarde van de voorraad na afschrijving.", "Voorraad wordt niet op die manier afgeschreven en de boekwaarde zegt weinig over de kosten van vervanging."], ["De gemiddelde waarde van de voorraad over het afgelopen jaar.", "Een gemiddelde zegt niets over de waarde op het moment van de schade en kan tot onderverzekering leiden."]]],
["Een tuincentrum heeft in het voorjaar een veel grotere voorraad dan in de winter. Welke oplossing voorkomt onderverzekering in de piek zonder het hele jaar op het piekbedrag te verzekeren?", [["Een seizoens- of piekdekking, of verzekering van de voorraad op declaratiebasis.", "Daarmee volgt de verzekerde som de werkelijke voorraad; de premie wordt afgestemd op de feitelijke waarde gedurende het jaar."], ["Verzekeren op het jaargemiddelde van de voorraad.", "In de piekperiode ligt de waarde dan boven de verzekerde som, waardoor onderverzekering kan worden toegepast."], ["Verzekeren op de laagste voorraadstand en bij een schade het verschil met de piek bijbetalen.", "Na een schade kan de dekking niet met terugwerkende kracht worden verhoogd; de onderverzekering is dan een feit."], ["De voorraad onderbrengen op de opstalpolis van het pand.", "De opstalpolis dekt het gebouw, niet de roerende zaken zoals voorraad die erin liggen."]]],
["Welke van de volgende vormen hoort bij de zes vormen van molest uit de gangbare Verbondsdefinitie?", [["Binnenlandse onlusten.", "Molest omvat gewapend conflict, burgeroorlog, opstand, binnenlandse onlusten, oproer en muiterij."], ["Terrorisme.", "Terrorisme is geen vorm van molest; voor terrorismeschade geldt een afzonderlijke regeling met de NHT."], ["Overstroming door een dijkdoorbraak.", "Overstroming is een natuurrisico en geen molest; het kent een eigen uitsluiting of dekking."], ["Een grootschalige cyberaanval.", "Een cyberaanval is geen van de zes molestvormen; cyber wordt in polissen afzonderlijk geregeld."]]],
["Hoe is terrorismeschade bij Nederlandse schadeverzekeringen doorgaans geregeld?", [["Gedekt via een terrorismeclausule met de NHT, waarbij de uitkering beperkt kan worden.", "Verzekeraars hebben dit risico samen herverzekerd bij de Nederlandse Herverzekeringsmaatschappij voor Terrorismeschaden; bij een grote ramp kan de uitkering naar verhouding worden beperkt."], ["Volledig uitgesloten op alle zakelijke polissen, net als molest en atoomkernreacties, zonder uitzondering.", "Terrorisme is juist binnen de grenzen van de clausule meeverzekerd; een volledige uitsluiting is niet de standaard."], ["Gedekt door de overheid via de Wet tegemoetkoming schade bij rampen.", "De WTS is bedoeld voor niet redelijkerwijs verzekerbare rampschade en vervangt de terrorismedekking via de NHT niet."], ["Onbeperkt gedekt, zonder enig voorbehoud over de omvang van de uitkering.", "De terrorismeclausule bevat juist een voorbehoud: de NHT kan bij grote schadelast een uitkeringspercentage vaststellen."]]],
["Een inventarispolis bevat als voorwaarde dat een inbraakalarm met doormelding aanwezig en ingeschakeld moet zijn. Na een inbraak blijkt het alarm uit te staan. Wat is juist?", [["De verzekeraar kan zich op de preventievoorwaarde beroepen en de dekking weigeren of beperken.", "Preventievoorwaarden zijn contractuele afspraken; of het beroep slaagt hangt af van de formulering en de redelijkheid, maar het risico van weigering is reëel."], ["Er zijn geen gevolgen, want preventie-eisen in een polis zijn slechts vrijblijvende aanbevelingen.", "Preventie-eisen in de polis zijn bindende voorwaarden en geen vrijblijvende adviezen."], ["De verzekeraar moet altijd volledig uitkeren, omdat inbraak op de polis een gedekt evenement is.", "Dat een evenement gedekt is, betekent niet dat de dekking geldt als de verzekerde zich niet aan de voorwaarden houdt."], ["De verzekering eindigt automatisch met terugwerkende kracht tot de oorspronkelijke ingangsdatum.", "Het gevolg is geen automatische ontbinding met terugwerkende kracht; het gaat om de dekking voor deze schade."]]],
["Wat wordt bij een bedrijfsschadeverzekering doorgaans verstaan onder brutowinst?", [["Omzet minus variabele kosten, ofwel vaste kosten plus nettowinst.", "Bij stilstand vallen de variabele kosten weg; de vaste kosten lopen door en de winst gaat verloren. Die som is het verzekerde belang."], ["Omzet minus alle kosten, inclusief de vaste kosten van het bedrijf.", "Dat is de nettowinst; de vaste kosten die bij stilstand doorlopen zouden dan buiten de dekking vallen."], ["De totale omzet van het bedrijf, inclusief de btw.", "Omzet bevat ook variabele kosten die bij stilstand niet worden gemaakt; vergoeding daarvan zou de ondernemer verrijken."], ["De nettowinst vermeerderd met de vennootschapsbelasting.", "Dat is de winst vóór belasting en laat de doorlopende vaste kosten buiten beschouwing."]]],
["Wat is de uitkeringstermijn bij een bedrijfsschadeverzekering?", [["De periode na de schadedatum waarover de verzekeraar het verlies aan brutowinst vergoedt.", "Binnen deze termijn moet het bedrijf weer op het oude niveau zijn; verlies daarna valt buiten de dekking."], ["De termijn waarbinnen de verzekeraar na een schademelding het vastgestelde schadebedrag moet betalen.", "Dat is een betalingstermijn; de uitkeringstermijn gaat over de periode waarover het verlies wordt vergoed."], ["De contractstermijn waarvoor de verzekering is gesloten.", "De looptijd van de polis staat los van de periode waarover na een schade bedrijfsschade wordt vergoed."], ["De wachttijd waarin het bedrijfsverlies voor rekening van de ondernemer blijft.", "Dat is een eigen risico in tijd; de uitkeringstermijn is de periode van vergoeding."]]],
["Een machinefabriek heeft na een brand naar verwachting achttien maanden nodig om met nieuw te bouwen machines weer volledig te produceren. De bedrijfsschadepolis heeft een uitkeringstermijn van 52 weken. Wat is het gevolg?", [["Het verlies na de 52 weken wordt niet vergoed, terwijl de bedrijfsschade dan nog doorloopt.", "De uitkeringstermijn is te kort gekozen voor de hersteltijd; de adviseur had een langere termijn moeten overwegen."], ["De verzekeraar verlengt de uitkeringstermijn automatisch tot het bedrijf hersteld is.", "De uitkeringstermijn is een contractuele grens; een automatische verlenging is geen standaard."], ["De uitkeringstermijn begint pas te lopen als de nieuwe machines zijn geleverd.", "De termijn begint in de regel op de schadedatum, niet op het moment van herstel."], ["De verzekeraar vergoedt binnen de 52 weken alsnog het volledige verlies over alle achttien maanden.", "De verzekeraar vergoedt alleen het verlies dat binnen de uitkeringstermijn wordt geleden."]]],
["Wat is bij een traditionele bedrijfsschadeverzekering doorgaans een voorwaarde voor dekking?", [["De stilstand is het gevolg van materiële schade door een gedekte gebeurtenis, zoals brand.", "Bedrijfsschade is gekoppeld aan een materiële schade die onder de polis valt; zonder die oorzaak is er geen dekking."], ["Elke omzetdaling die het bedrijf lijdt, ook als die door minder vraag wordt veroorzaakt.", "Teruglopende vraag is ondernemersrisico en valt niet onder een bedrijfsschadeverzekering."], ["De ondernemer heeft geen personeel in dienst dat tijdens de stilstand moet worden doorbetaald.", "Personeelskosten horen juist vaak bij de doorlopende vaste kosten die worden vergoed."], ["De stilstand duurt langer dan de uitkeringstermijn.", "De uitkeringstermijn is de maximale vergoedingsperiode, geen minimale duur van de stilstand."]]],
["Een bakkerij betrekt al haar meel van één molen. De molen brandt af en de bakkerij kan wekenlang niet bakken. Welke dekking had deze schade kunnen opvangen?", [["Een afhankelijkheidsdekking bij leveranciers.", "Deze uitbreiding vergoedt het verlies aan brutowinst als de stilstand wordt veroorzaakt door schade bij een bedrijf waarvan de verzekerde afhankelijk is."], ["Een huurdersbelangdekking op de inventarispolis.", "Huurdersbelang dekt verbeteringen van een huurder aan een gehuurd pand, niet schade door uitval van een leverancier."], ["Een aansprakelijkheidsverzekering voor bedrijven (AVB).", "De AVB dekt aansprakelijkheid tegenover derden, niet eigen omzetverlies door schade bij een leverancier."], ["Een productaansprakelijkheidsdekking op de AVB.", "Productaansprakelijkheid gaat over schade door gebrekkige producten bij derden, niet over leveringsproblemen."]]],
["Een accountantskantoor wil na een brand vooral direct op een andere locatie doorwerken, ook als dat extra huur en kosten met zich meebrengt. Welke dekking sluit hier het best op aan?", [["Een meerkostenverzekering.", "Een meerkostenverzekering vergoedt de extra kosten die nodig zijn om de bedrijfsvoering na een schade zo veel mogelijk voort te zetten."], ["Een opstalverzekering op herbouwwaarde.", "Die dekt het herstel van het gebouw, niet de kosten van tijdelijk elders werken."], ["Een rechtsbijstandverzekering.", "Rechtsbijstand helpt bij juridische geschillen en vergoedt geen tijdelijke huisvesting."], ["Een aansprakelijkheidsverzekering met opzichtdekking.", "Opzicht gaat over schade aan zaken van derden onder de hoede van de verzekerde, niet over eigen extra kosten."]]],
["Waarom is het belangrijk dat de verzekerde brutowinst bij een bedrijfsschadeverzekering regelmatig wordt geactualiseerd?", [["Omdat bij een te lage verzekerde brutowinst onderverzekering kan gelden.", "Groeit het bedrijf, dan dekt de oude som het verlies niet meer volledig en wordt de uitkering mogelijk naar verhouding verlaagd."], ["Omdat de uitkeringstermijn bij een verouderde opgave automatisch korter wordt.", "De uitkeringstermijn is een vaste afspraak en hangt niet af van de hoogte van de opgegeven brutowinst."], ["Omdat de verzekeraar de polis bij een verouderde opgave automatisch beëindigt.", "Een verouderde opgave leidt niet tot beëindiging; het risico zit in een te lage uitkering."], ["Omdat de hoogte van de brutowinst bepaalt hoeveel wachtdagen er gelden.", "De wachttijd is een afzonderlijke afspraak in de polis en staat los van de verzekerde brutowinst."]]],
["Welke schade is op een aansprakelijkheidsverzekering voor bedrijven (AVB) in de regel gedekt?", [["Personen- en zaakschade van derden, inclusief de gevolgschade daarvan.", "De AVB is gericht op letsel en schade aan zaken van derden, inclusief de schade die daaruit voortvloeit."], ["Zuivere vermogensschade van klanten door een onjuist of onvolledig advies.", "Schade zonder letsel of zaakschade valt doorgaans buiten de AVB; daarvoor is een beroepsaansprakelijkheidsverzekering bedoeld."], ["Schade aan de eigen inventaris en voorraad van het verzekerde bedrijf.", "Eigen schade valt onder een inventaris- of goederenverzekering; de AVB dekt schade bij derden."], ["Contractuele boetes die het bedrijf aan zijn klanten verschuldigd is.", "Boetes en verplichtingen die alleen uit een contract voortvloeien zijn op een AVB in de regel uitgesloten."]]],
["Een installateur beschadigt bij het repareren van een cv-ketel de ketel zelf. Waarom is deze schade op de AVB vaak niet of maar beperkt gedekt?", [["Vanwege de opzichtclausule voor zaken waaraan de verzekerde werkt.", "Schade aan zaken die de verzekerde onder zich heeft of waaraan hij werkt, is uitgesloten of beperkt meeverzekerd; verzekeraars willen het kwaliteitsrisico van het eigen werk niet dekken."], ["Omdat installatiebedrijven niet verzekerbaar zijn voor aansprakelijkheid.", "Installateurs kunnen prima een AVB sluiten; het gaat hier om een specifieke uitsluiting."], ["Omdat het om personenschade gaat, die buiten de AVB valt.", "Het gaat hier om zaakschade; personenschade is op een AVB juist een kerndekking."], ["Omdat de AVB alleen schade buiten de werkzaamheden dekt.", "De AVB dekt juist de aansprakelijkheid uit de bedrijfsuitoefening, dus ook tijdens het werk."]]],
["Welke vorm van aansprakelijkheid geldt volgens het BW voor de producent van een gebrekkig product?", [["Risicoaansprakelijkheid: schuld van de producent hoeft niet te worden aangetoond.", "De productaansprakelijkheidsregeling in het BW legt de aansprakelijkheid bij de producent, ongeacht verwijtbaarheid."], ["Schuldaansprakelijkheid: de benadeelde moet verwijtbaar handelen van de producent aantonen.", "Juist het schuldvereiste is bij productaansprakelijkheid losgelaten om de benadeelde te beschermen."], ["Uitsluitend contractuele aansprakelijkheid tegenover de directe koper van het product.", "De regeling geldt ook tegenover benadeelden zonder contract met de producent, zoals gebruikers en omstanders."], ["Aansprakelijkheid alleen als de producent opzettelijk heeft gehandeld.", "Opzet is geen vereiste; de producent is ook zonder enige schuld aansprakelijk voor een gebrekkig product."]]],
["Een voedselproducent ontdekt dat een partij besmet is en haalt alle producten uit de winkels. Zijn de terugroepkosten gedekt op een standaard AVB?", [["Doorgaans niet; daarvoor is een afzonderlijke terugroepkostenverzekering nodig.", "Standaard AVB-polissen sluiten terugroepkosten in de regel uit; dit risico wordt apart verzekerd."], ["Ja, terugroepkosten vallen op een AVB altijd onder de productaansprakelijkheidsdekking.", "Productaansprakelijkheid dekt schade bij derden; de kosten van het terughalen van producten zijn meestal uitgesloten."], ["Ja, maar alleen als een rechter het terugroepen heeft bevolen.", "Een rechterlijk bevel maakt terugroepkosten niet gedekt als de polis ze uitsluit."], ["Nee, deze kosten vallen standaard onder de bedrijfsschadeverzekering.", "Bedrijfsschade vereist meestal materiële schade door een gedekte gebeurtenis; terugroepkosten zijn daar geen standaarddekking."]]],
["Binnen welke termijnen kan een benadeelde een producent aanspreken op grond van de productaansprakelijkheidsregeling in het BW?", [["Verjaring drie jaar na bekendheid met schade, gebrek en producent; verval tien jaar na het in het verkeer brengen.", "Deze combinatie van verjarings- en vervaltermijn komt uit de Europese productaansprakelijkheidsrichtlijn en staat in het BW."], ["Verjaring vijf jaar na bekendheid met schade en aansprakelijke; verval twintig jaar na de schadeveroorzakende gebeurtenis.", "Dit zijn de algemene termijnen bij schadevergoeding; voor productaansprakelijkheid gelden kortere termijnen."], ["Verjaring één jaar na bekendheid met schade en producent; verval vijf jaar na aankoop van het product.", "Deze termijnen zijn te kort en sluiten niet aan bij de wettelijke regeling."], ["Verjaring twee jaar na het ontstaan van de schade; een vervaltermijn bestaat bij producten niet.", "Er geldt wel degelijk een vervaltermijn, zodat de producent na verloop van tijd zekerheid heeft."]]],
["Een werknemer raakt gewond tijdens zijn werk. Wat moet de werkgever volgens het BW in beginsel aantonen om niet aansprakelijk te zijn?", [["Dat hij zijn zorgplicht is nagekomen, of dat er opzet of bewuste roekeloosheid van de werknemer was.", "De bewijslast ligt bij de werkgever; lichte onvoorzichtigheid van de werknemer ontslaat hem niet van aansprakelijkheid."], ["Niets; de gewonde werknemer moet bewijzen dat de werkgever verwijtbaar tekort is geschoten.", "Bij werkgeversaansprakelijkheid is de bewijslast omgekeerd; de werkgever moet aantonen dat hij voldoende heeft gedaan."], ["Dat de werknemer zelf licht onvoorzichtig was bij het uitvoeren van het werk.", "Gewone onvoorzichtigheid van de werknemer komt voor rekening van de werkgever; alleen opzet of bewuste roekeloosheid telt."], ["Dat hij een passende aansprakelijkheidsverzekering voor bedrijven heeft afgesloten en de premie betaald.", "Een verzekering zegt niets over de aansprakelijkheid zelf; zij financiert alleen de gevolgen."]]],
["Een bouwbedrijf laat werk uitvoeren door een ingehuurde zzp'er, die op de bouwplaats gewond raakt door een ondeugdelijke steiger. Wat is juist?", [["Het bouwbedrijf kan net als een werkgever aansprakelijk zijn voor de veiligheid van de werkplek.", "Het BW breidt de werkgeversaansprakelijkheid uit tot wie in zijn bedrijf arbeid laat verrichten door niet-werknemers; de AVB moet dit risico dan ook dekken."], ["Het bouwbedrijf is nooit aansprakelijk, want een zzp'er draagt altijd zelf zijn eigen ongevalsrisico.", "Dat is te stellig; de zorgplicht voor een veilige werkplek kan ook tegenover ingehuurde krachten gelden."], ["Het bouwbedrijf is alleen aansprakelijk als de zzp'er een schijnzelfstandige blijkt.", "Ook zonder arbeidsovereenkomst kan de opdrachtgever op grond van de verruimde werkgeversaansprakelijkheid aansprakelijk zijn."], ["Alleen de leverancier van de steiger kan voor deze schade aansprakelijk zijn.", "De leverancier kan aansprakelijk zijn, maar dat sluit aansprakelijkheid van het bouwbedrijf voor de werkplek niet uit."]]],
["Een werknemer krijgt tijdens een zakelijke rit met zijn eigen auto buiten zijn schuld een ongeval; de veroorzaker is onbekend. Op welke grond kan de werkgever toch aansprakelijk zijn voor de schade?", [["Op grond van goed werkgeverschap, omdat hij moet zorgen voor een behoorlijke verzekering.", "Volgens vaste rechtspraak moet de werkgever voor een passende verzekering zorgen; ontbreekt die, dan kan hij zelf voor de schade opdraaien."], ["Op grond van de WAM-polis van de werkgever, die ook auto's van werknemers dekt.", "Een WAM-polis van de werkgever dekt alleen de daarop verzekerde voertuigen en vergoedt geen schade van de eigen bestuurder."], ["Op grond van de productaansprakelijkheid van de werkgever voor de door de werknemer gebruikte auto.", "Productaansprakelijkheid gaat over gebrekkige producten en heeft hier geen betekenis."], ["Niet, want bij een rit in een eigen auto is de werkgever nooit aansprakelijk.", "Juist bij zakelijke ritten kan de werkgever op grond van goed werkgeverschap aansprakelijk zijn, ook in een eigen auto."]]],
["Welke schade dekt een beroepsaansprakelijkheidsverzekering typisch, die op een AVB meestal buiten de dekking valt?", [["Zuivere vermogensschade van een opdrachtgever door een beroepsfout.", "Beroepsbeoefenaren als adviseurs, accountants en architecten veroorzaken vooral financiële schade zonder letsel of zaakschade; daarvoor is deze verzekering bedoeld."], ["Letselschade van een bezoeker die op kantoor uitglijdt over een natte vloer.", "Dat is personenschade van een derde en valt onder de AVB."], ["Schade aan de eigen kantoorinventaris door een gesprongen waterleiding.", "Eigen schade valt onder een inventarisverzekering, niet onder een aansprakelijkheidsverzekering."], ["Schade aan de eigen bedrijfsauto na een aanrijding op weg naar een klant.", "Schade aan een eigen voertuig valt onder een cascodekking van de autoverzekering."]]],
["Een beroepsaansprakelijkheidsverzekering is gesloten op claims-made-basis. Wat betekent dat?", [["Gedekt zijn aanspraken die tijdens de looptijd worden ingesteld en gemeld, binnen de inloopregeling.", "Bepalend is het moment van de aanspraak, niet het moment van de fout; daarom zijn inloop- en uitloopregelingen belangrijk bij wisselen of stoppen."], ["De dekking geldt voor fouten tijdens de looptijd, ook als de claim pas jaren na beëindiging wordt ingediend.", "Dat beschrijft een dekking op basis van het moment van de gebeurtenis; bij claims-made is het moment van de aanspraak bepalend."], ["Het eigen risico geldt per claim in plaats van per gebeurtenis.", "Claims-made zegt iets over de tijdsafbakening van de dekking, niet over de toepassing van het eigen risico."], ["De verzekeraar keert alleen uit als de opdrachtgever een procedure bij de rechter begint.", "Ook een schriftelijke aansprakelijkstelling buiten rechte geldt als aanspraak; een procedure is niet vereist."]]],
["Een medewerker van een schoonmaakbedrijf stoot tijdens het werk bij een klant per ongeluk een kostbaar beeld om. Wie is tegenover de klant in beginsel aansprakelijk?", [["De werkgever, die aansprakelijk is voor fouten van zijn werknemers.", "Een werkgever is aansprakelijk voor fouten van werknemers die in het kader van hun werk worden gemaakt; de klant kan het bedrijf aanspreken."], ["Uitsluitend de medewerker die het beeld persoonlijk heeft omgestoten.", "De klant kan de werkgever aanspreken; werknemers worden tegenover de werkgever bovendien beschermd tegen regres, behoudens opzet of bewuste roekeloosheid."], ["Niemand, omdat het om een ongeluk zonder opzet ging.", "Een onrechtmatige daad vereist geen opzet; een onvoorzichtige handeling tijdens het werk kan voldoende zijn."], ["De klant zelf, omdat hij het beeld niet veilig had weggezet.", "Eigen schuld van de klant kan hooguit een rol spelen bij de verdeling, maar maakt de klant niet in beginsel zelf aansprakelijk."]]],
["Wie is bij een bestuurdersaansprakelijkheidsverzekering (D&O) doorgaans verzekeringnemer en wie zijn de verzekerden?", [["De vennootschap is verzekeringnemer; bestuurders en commissarissen zijn verzekerden.", "De rechtspersoon sluit en betaalt de polis, maar die dekt de persoonlijke aansprakelijkheid van de bestuurders en toezichthouders."], ["Elke bestuurder is zelf verzekeringnemer en de vennootschap is de verzekerde partij.", "De D&O-polis dekt juist de persoonlijke aansprakelijkheid van bestuurders, niet primair de vennootschap."], ["De aandeelhouders zijn verzekerden voor het verlies op hun belegging in de vennootschap.", "Aandeelhouders zijn juist vaak de partij die bestuurders aanspreekt; hun beleggingsrisico is niet verzekerd."], ["Alle werknemers zijn verzekerd voor fouten in hun werk.", "De D&O richt zich op bestuurders en toezichthouders; werknemers vallen hier in beginsel niet onder."]]],
["Een curator spreekt de bestuurders van een failliete bv aan omdat de jaarrekening te laat is gedeponeerd in de drie jaar voor het faillissement. Wat is het gevolg?", [["Onbehoorlijk bestuur staat vast en wordt vermoed een belangrijke oorzaak van het faillissement te zijn.", "Schending van de publicatieplicht geeft een vaststaand onbehoorlijk bestuur en een weerlegbaar vermoeden van oorzakelijk verband."], ["Er zijn geen gevolgen, omdat te laat deponeren slechts een administratieve fout is.", "De wet verbindt aan het niet nakomen van de publicatieplicht juist ingrijpende gevolgen in faillissement (een onbelangrijk verzuim daargelaten)."], ["De bestuurder krijgt alleen een bestuurlijke boete en is niet civiel aansprakelijk.", "Het gaat hier om civiele aansprakelijkheid tegenover de boedel, niet om een boete."], ["De bestuurder is hoofdelijk aansprakelijk voor het hele tekort en kan op geen enkele wijze nog tegenbewijs leveren.", "Het vermoeden dat het onbehoorlijk bestuur een belangrijke oorzaak is van het faillissement, kan de bestuurder weerleggen."]]],
["Wanneer is een bestuurder volgens vaste rechtspraak intern aansprakelijk tegenover de vennootschap wegens onbehoorlijke taakvervulling?", [["Als hem een ernstig verwijt kan worden gemaakt.", "De Hoge Raad legt de lat hoog om bestuurders ruimte te geven voor ondernemerschap; een gewone fout is niet genoeg."], ["Bij iedere fout die tot schade leidt.", "Dan zou besturen onwerkbaar worden; de maatstaf is een ernstig verwijt."], ["Alleen na een strafrechtelijke veroordeling.", "Civiele aansprakelijkheid vereist geen strafrechtelijke veroordeling."], ["Alleen als alle aandeelhouders daarmee unaniem instemmen.", "De aansprakelijkheid volgt uit de wet en de rechtspraak, niet uit instemming van aandeelhouders."]]],
["Welke kosten vormen een kernonderdeel van de D&O-verzekering, ook als de aanspraak uiteindelijk ongegrond blijkt?", [["De kosten van verweer en juridische bijstand van de bestuurder.", "Juist bij claims tegen bestuurders lopen de verweerkosten snel op; de D&O vergoedt die ook als de bestuurder uiteindelijk niet aansprakelijk is."], ["De bestuurlijke boetes die aan de vennootschap zijn opgelegd.", "Boetes zijn in de regel niet of slechts beperkt verzekerbaar en betreffen hier de vennootschap zelf."], ["Het omzetverlies van de vennootschap door de claim.", "Bedrijfsverlies van de vennootschap valt buiten de D&O, die de persoonlijke aansprakelijkheid van bestuurders dekt."], ["De doorbetaling van het salaris van de bestuurder tijdens de procedure.", "Inkomensderving van de bestuurder is geen onderdeel van de D&O-dekking."]]],
["Welke uitsluiting is in een D&O-polis gebruikelijk?", [["Schade door opzet of fraude van de bestuurder, als die vaststaat.", "Ook het bewust genieten van onrechtmatig voordeel is vaak uitgesloten; tot opzet of fraude bij uitspraak of erkenning vaststaat, worden verweerkosten vaak wel voorgeschoten."], ["Elke claim die een curator na het faillissement tegen bestuurders indient.", "Claims van curatoren zijn juist een belangrijk risico waarvoor de D&O bedoeld is."], ["Claims die zijn gebaseerd op onbehoorlijke taakvervulling door het bestuur.", "Onbehoorlijke taakvervulling is juist de kern van de bestuurdersaansprakelijkheid en dus van de dekking."], ["Alle kosten van juridisch verweer die een bestuurder maakt.", "Verweerkosten zijn een kerndekking van de D&O, geen uitsluiting."]]],
["Welke twee onderdelen vormen de kern van een Construction All Risks-verzekering (CAR)?", [["Schade aan het werk in uitvoering en aansprakelijkheid tegenover derden.", "De CAR dekt het bouwproject zelf en de aansprakelijkheid die uit de bouwactiviteiten voortvloeit, aangevuld met optionele rubrieken."], ["Inkomensverlies van de aannemer en verzuimkosten van zijn personeel tijdens de bouw.", "Dat zijn inkomens- en verzuimrisico's die met andere verzekeringen worden gedekt."], ["De opstal van de opdrachtgever na oplevering en glasbreuk.", "Na oplevering is het gebouw een opstalrisico van de eigenaar; de CAR gaat over de bouwfase."], ["Het vervoer van bouwmaterialen en de CMR-aansprakelijkheid van de vervoerder.", "Transportrisico's en vervoerdersaansprakelijkheid vallen onder transportverzekeringen."]]],
["Wie zijn op een projectgebonden CAR-verzekering doorgaans gezamenlijk verzekerd?", [["Opdrachtgever, hoofdaannemer en onderaannemers, vaak ook ontwerpers.", "Een gezamenlijke verzekering voorkomt discussie en verhaal tussen bouwpartners; wie precies verzekerd is, staat in de polis."], ["Alleen de opdrachtgever, omdat die het project laat uitvoeren.", "De CAR is juist bedoeld om alle betrokken bouwpartijen onder één polis te brengen."], ["Alleen de hoofdaannemer; onderaannemers zijn nooit meeverzekerd.", "Onderaannemers zijn op een project-CAR in de regel meeverzekerd."], ["Alleen de toekomstige huurders en gebruikers van het gebouw.", "Toekomstige gebruikers hebben geen rol in de bouwfase en zijn geen verzekerden op de CAR."]]],
["Door een ontwerpfout bezwijkt tijdens de bouw een betonvloer, waarbij ook installaties eronder worden beschadigd. Hoe gaat een CAR-polis hier doorgaans mee om?", [["Herstel van het gebrekkige onderdeel zelf is vaak uitgesloten, de gevolgschade doorgaans gedekt.", "De CAR is geen garantie voor kwaliteit, maar beschermt wel tegen de schade die een gebrek elders in het werk veroorzaakt."], ["Alle kosten, ook het opnieuw ontwerpen en aanleggen van de vloer, zijn volledig gedekt.", "Het herstel van het gebrek zelf valt doorgaans buiten de dekking; anders zou de CAR een kwaliteitsgarantie worden."], ["Niets is gedekt, omdat de oorzaak van de schade een ontwerpfout is.", "Een ontwerpfout sluit niet alle dekking uit; de gevolgschade aan andere onderdelen is in de regel gedekt."], ["Alleen de beroepsaansprakelijkheidsverzekering van de architect kan iets vergoeden.", "De BAV van de ontwerper kan een rol spelen bij verhaal, maar de CAR zelf vergoedt doorgaans de gevolgschade."]]],
["Voor wiens risico is het werk volgens de UAV 2012 in beginsel tot het moment van oplevering?", [["Voor risico van de aannemer.", "Tot de oplevering draagt de aannemer in beginsel het risico van schade aan het werk; een CAR-verzekering sluit daarop aan."], ["Voor risico van de opdrachtgever.", "Het risico gaat in beginsel pas bij oplevering over; tot dat moment ligt het bij de aannemer, behoudens uitzonderingen."], ["Voor gezamenlijk risico van aannemer en opdrachtgever, ieder voor de helft.", "De UAV kent geen standaard verdeling bij helfte; de hoofdregel legt het risico bij de aannemer."], ["Voor risico van de architect.", "De architect is ontwerper en geen partij die het risico van het werk in uitvoering draagt."]]],
["Op welk vervoer is het CMR-verdrag van toepassing?", [["Betaald internationaal wegvervoer van goederen tussen twee landen, waarvan minstens één CMR-land.", "Dit is de kern van het toepassingsgebied van het verdrag; binnenlands vervoer valt erbuiten."], ["Al het betaalde goederenvervoer over de weg, ook als het geheel binnen Nederland of de Benelux plaatsvindt.", "Binnenlands wegvervoer valt niet onder het CMR maar onder het nationale recht."], ["Internationaal goederenvervoer over zee tussen havens van verschillende landen.", "Zeevervoer kent eigen verdragen en regels; het CMR gaat over wegvervoer."], ["Uitsluitend internationale verhuizingen en het vervoer van stoffelijke overschotten.", "Deze vormen van vervoer zijn juist uitgezonderd van het CMR."]]],
["Tot welk bedrag is de aansprakelijkheid van de wegvervoerder onder het CMR in beginsel beperkt bij verlies of beschadiging van de lading?", [["8,33 rekeneenheden (SDR) per kilogram ontbrekend brutogewicht.", "Deze limiet geldt tenzij een hogere waarde of bijzonder belang is aangegeven, of er sprake is van opzet of daarmee gelijk te stellen schuld."], ["De volledige werkelijke waarde van de goederen, zonder enige limiet.", "Het CMR kent juist een limiet per kilogram; daardoor kan de ladingbelanghebbende met een tekort blijven zitten."], ["Een vast bedrag per zending, ongeacht het gewicht.", "De limiet wordt berekend per kilogram brutogewicht, niet per zending."], ["2 rekeneenheden (SDR) per kilogram ontbrekend brutogewicht.", "Een limiet in die orde kom je tegen bij zeevervoer; het CMR hanteert 8,33 SDR per kilogram."]]],
["Een exporteur vindt een transportverzekering overbodig, omdat de vervoerder een CMR-verzekering heeft. Wat is het belangrijkste tegenargument?", [["De CMR-verzekering dekt alleen de beperkte aansprakelijkheid van de vervoerder, niet de lading zelf.", "Bij schade waarvoor de vervoerder niet aansprakelijk is, of boven de limiet, krijgt de exporteur niets; een goederentransportverzekering dekt zijn eigen belang."], ["De CMR-verzekering van de vervoerder geldt alleen voor binnenlands wegvervoer.", "De CMR-verzekering dekt juist internationaal wegvervoer; het probleem zit in de beperkte aansprakelijkheid."], ["De CMR-verzekering is alleen geldig als de exporteur zelf ook verzekeringnemer is.", "De vervoerder is verzekeringnemer; daarom dekt de polis ook alleen zijn aansprakelijkheid."], ["De ontvanger is wettelijk verplicht de lading tijdens het gehele internationale vervoer zelf te verzekeren.", "Er bestaat geen algemene wettelijke verplichting voor de ontvanger; wie verzekert, volgt uit de afspraken, zoals de Incoterms."]]],
["Binnen welke termijn verjaart een vordering op grond van het CMR in de regel?", [["Eén jaar; bij opzet of gelijk te stellen schuld drie jaar.", "Het CMR kent een korte verjaringstermijn; ladingbelanghebbenden en hun verzekeraars moeten daarom snel handelen."], ["Drie jaar; bij opzet of gelijk te stellen schuld vijf jaar.", "Deze termijnen zijn langer dan het verdrag bepaalt."], ["Zes maanden; bij opzet of gelijk te stellen schuld één jaar.", "De verjaringstermijn is korter dan bij gewone vorderingen, maar niet zo kort als zes maanden."], ["Vijf jaar; bij opzet of gelijk te stellen schuld twintig jaar.", "Dit lijkt op de algemene termijnen voor schadevergoeding in het BW, niet op het CMR."]]],
["Een Nederlandse exporteur verkoopt goederen aan een koper in Azië op basis van de Incoterm CIF. Wie moet volgens deze Incoterm de transportverzekering voor de goederen sluiten?", [["De verkoper, ten behoeve van de koper, met ten minste een minimale dekking.", "Bij CIF (Cost, Insurance and Freight) zorgt de verkoper voor vracht én verzekering; het risico gaat al over bij inlading."], ["De koper, omdat het risico al bij inlading op het schip op hem overgaat.", "Het risico gaat inderdaad vroeg over, maar bij CIF is de verkoper verplicht de verzekering te regelen."], ["De vervoerder, als vast onderdeel van de vervoersovereenkomst met de verkoper.", "De vervoerder verzekert hooguit zijn eigen aansprakelijkheid, niet de goederen ten behoeve van koper of verkoper."], ["Niemand; bij CIF is een verzekering niet nodig.", "De 'I' in CIF staat juist voor de verzekeringsplicht van de verkoper."]]],
["Wat is een kenmerk van een wagenparkverzekering ten opzichte van losse autopolissen?", [["Alle voertuigen staan op één polis; de premie volgt vaak het schadeverloop van het geheel.", "In plaats van een bonus-malustrede per auto kijkt de verzekeraar naar de schadelast van het totale wagenpark."], ["Voor voertuigen op een wagenparkpolis geldt de wettelijke WAM-verzekeringsplicht niet.", "De WAM-plicht geldt voor ieder motorrijtuig dat aan het verkeer deelneemt, ook op een wagenparkpolis."], ["Een wagenparkpolis dekt uitsluitend cascoschade.", "Een wagenparkpolis bevat in elk geval de verplichte WAM-dekking, met daarnaast eventueel casco."], ["Een wagenparkpolis is alleen mogelijk voor privéauto's die werknemers voor zakelijke ritten gebruiken.", "De wagenparkpolis is juist bedoeld voor de bedrijfsvoertuigen van een onderneming."]]],
["Een werknemer rijdt onder invloed van alcohol met een bedrijfsbus en verwondt een fietser. Kan de WAM-verzekeraar de fietser tegenwerpen dat de polis rijden onder invloed uitsluit?", [["Nee; de fietser heeft een eigen recht tegen de WAM-verzekeraar, die later kan verhalen.", "De WAM beschermt het slachtoffer: de verzekeraar kan polisuitsluitingen niet aan de benadeelde tegenwerpen, maar kan na uitkering wel verhaal nemen op de verzekerde."], ["Ja; de fietser moet zijn schade dan verhalen op de werknemer persoonlijk.", "Dan zou de bescherming van verkeersslachtoffers afhangen van het gedrag van de bestuurder, wat de WAM juist voorkomt."], ["Ja; de fietser moet zich dan wenden tot het Waarborgfonds Motorverkeer.", "Het Waarborgfonds springt bij als er geen verzekering is of de veroorzaker onbekend is, niet bij een polisuitsluiting."], ["Nee, en de verzekeraar kan de uitgekeerde schade daarna ook op niemand verhalen.", "De verzekeraar keert uit aan de benadeelde, maar kan bij een uitsluiting wel verhaal nemen op de verzekerde."]]],
["Waarom is naast de WAM-dekking een schadeverzekering voor inzittenden (SVI) relevant voor een wagenpark?", [["De WAM dekt de eigen bestuurder niet; de SVI wel, ongeacht schuld.", "Voor werkgevers sluit dit aan bij de plicht als goed werkgever te zorgen voor een behoorlijke verzekering van werknemers in het verkeer."], ["De SVI is wettelijk verplicht voor elk bedrijfsvoertuig op de weg.", "Alleen de WAM is wettelijk verplicht; de SVI is een aanvullende, vrijwillige dekking."], ["De SVI dekt schade aan de lading die in bestelbussen wordt vervoerd.", "Lading valt onder een goederen- of transportverzekering, niet onder een inzittendenverzekering."], ["De SVI vervangt de cascodekking van de voertuigen in het wagenpark.", "Casco dekt schade aan het voertuig zelf; de SVI dekt schade van personen in het voertuig."]]],
["Een bedrijf met een wagenparkpolis koopt tussentijds drie nieuwe bestelbussen. Wat regelt een wagenparkpolis hierover vaak?", [["Ze zijn automatisch meeverzekerd, mits tijdig gemeld voor de premieafrekening.", "Dit voorkomt dat nieuwe voertuigen onverzekerd de weg op gaan; de premie wordt achteraf verrekend."], ["Ze zijn pas gedekt nadat voor elk voertuig een afzonderlijke polis is gesloten.", "Juist het automatisch meeverzekeren is een voordeel van een wagenparkpolis."], ["Ze kunnen pas per het volgende contractjaar aan de polis worden toegevoegd.", "Tussentijds toevoegen is gebruikelijk; anders zouden voertuigen maandenlang onverzekerd zijn."], ["Ze zijn automatisch casco verzekerd, maar nog zonder WAM-dekking.", "De WAM-dekking is het minimum dat voor ieder voertuig op de polis geldt."]]],
["Welke combinatie van dekkingen is kenmerkend voor een cyberverzekering?", [["Eigen schade (zoals dataherstel en stilstand) plus aansprakelijkheid bij een datalek.", "Een cyberpolis combineert eerstepartijschade met aansprakelijkheid en biedt vaak ook directe hulp bij een incident."], ["Alleen schade aan computers en servers door brand, water of inbraak.", "Fysieke schade aan apparatuur valt onder de inventaris- of elektronicaverzekering."], ["Alleen aansprakelijkheid tegenover klanten, zonder dekking voor eigen schade.", "Een groot deel van de cyberschade is juist eigen schade, zoals herstel en stilstand."], ["Alleen boetes die de Autoriteit Persoonsgegevens na een datalek oplegt.", "Boetes zijn hooguit beperkt en alleen voor zover wettelijk toegestaan verzekerd; ze zijn niet de kern van de dekking."]]],
["Een adviesbureau ontdekt dat bij een hack persoonsgegevens van klanten zijn buitgemaakt. Binnen welke termijn moet het datalek in de regel bij de Autoriteit Persoonsgegevens worden gemeld?", [["Zonder onredelijke vertraging en zo mogelijk binnen 72 uur na ontdekking.", "Dit volgt uit de AVG, tenzij het lek waarschijnlijk geen risico voor betrokkenen oplevert; cyberverzekeraars helpen vaak met deze melding."], ["Binnen 30 dagen na ontdekking van het lek, via het meldloket van de AP.", "Die termijn is te ruim; de AVG vraagt om melding zo mogelijk binnen 72 uur."], ["Pas in de jaarlijkse privacyrapportage van het bureau.", "Een datalek moet direct worden gemeld, niet pas achteraf in een jaarverslag."], ["Pas nadat de cyberverzekeraar daarvoor uitdrukkelijk toestemming heeft gegeven.", "De meldplicht is een wettelijke plicht van de verwerkingsverantwoordelijke en hangt niet af van de verzekeraar."]]],
["Waarom vragen cyberverzekeraars bij acceptatie vaak naar maatregelen als multifactorauthenticatie en offline back-ups?", [["Omdat ze kans en impact sterk verkleinen en dus premie en acceptatie bepalen.", "Cyberrisico hangt sterk af van basisbeveiliging; ontbreken van zulke maatregelen kan leiden tot een hogere premie, extra voorwaarden of weigering."], ["Omdat deze maatregelen voor ieder bedrijf wettelijk zijn voorgeschreven.", "Er bestaat geen algemene wettelijke plicht tot precies deze maatregelen voor alle bedrijven; het gaat om acceptatiebeleid van de verzekeraar."], ["Alleen voor statistische doeleinden; de antwoorden hebben geen invloed op de polis.", "De antwoorden hebben juist directe invloed op acceptatie, premie en voorwaarden."], ["Om de dekking voor eigen schade bij voorbaat uit te kunnen sluiten.", "De vragen dienen om het risico in te schatten, niet om de dekking uit te sluiten."]]],
["Een medewerker maakt na een vervalste e-mail van 'de directeur' een groot bedrag over naar een oplichter. Waarom is deze schade niet vanzelfsprekend gedekt op een cyberpolis?", [["Zulke fraude is vaak uitgesloten of beperkt gedekt: er is geen hack, maar een eigen betaling.", "Voor CEO-fraude en social engineering is soms een aparte module of fraudeverzekering nodig; de adviseur moet de voorwaarden nauwkeurig nalezen."], ["Deze schade valt altijd onder de aansprakelijkheidsverzekering voor bedrijven (AVB).", "De AVB dekt aansprakelijkheid voor schade bij derden, geen eigen vermogensverlies door fraude."], ["Deze schade is op elke cyberpolis zonder beperking of sublimiet gedekt.", "Dat is niet zo; veel polissen sluiten deze vorm van fraude uit of kennen een lage sublimiet."], ["De bank is wettelijk altijd verplicht zo'n frauduleuze zakelijke betaling volledig aan de klant te vergoeden.", "Een zakelijke klant die zelf een betaling autoriseert, kan zich in de regel niet op zo'n vergoedingsplicht van de bank beroepen."]]],
["Wanneer heeft een verzekerde met een rechtsbijstandverzekering op grond van de Europese regels in elk geval recht op vrije keuze van een advocaat?", [["Zodra een gerechtelijke of administratieve procedure nodig is, en bij belangenconflict.", "Volgens de Europese regels en de rechtspraak van het Hof van Justitie mag de verzekeraar de keuze van de advocaat in die situaties niet beperken."], ["Nooit; de verzekeraar bepaalt in alle gevallen zelf welke jurist of advocaat de zaak inhoudelijk behandelt.", "De vrije advocaatkeuze is juist een Europees gewaarborgd recht bij procedures en belangenconflicten."], ["Alleen als de verzekeraar daar vooraf schriftelijk mee instemt.", "Het recht op vrije keuze hangt niet af van toestemming van de verzekeraar."], ["Vanaf het eerste contact, dus ook al voor advies en minnelijke onderhandelingen.", "In de fase vóór een procedure mag de verzekeraar de zaak in beginsel door eigen juristen laten behandelen."]]],
["Een ondernemer sluit een zakelijke rechtsbijstandverzekering af omdat een conflict met een leverancier al loopt. Wat is waarschijnlijk het gevolg?", [["Geen dekking, omdat het geschil al bestond of voorzienbaar was bij het sluiten.", "Een verzekering dekt onzekere toekomstige gebeurtenissen; bestaande of te verwachten geschillen zijn uitgesloten."], ["Volledige dekking, omdat het geschil pas na de ingangsdatum bij de verzekeraar wordt gemeld.", "Bepalend is wanneer het geschil is ontstaan of voorzienbaar was, niet wanneer het wordt gemeld."], ["Dekking zodra de ondernemer het eigen risico van de polis heeft betaald.", "Een eigen risico verandert niets aan de uitsluiting van een geschil dat al bestond."], ["Dekking, mits het financiële belang onder de polisgrens blijft.", "Een minimum- of maximumbelang regelt de omvang, niet de uitsluiting van bestaande geschillen."]]],
["Waarom is de schadebehandeling van rechtsbijstand bij veel verzekeraars ondergebracht in een afzonderlijke rechtspersoon?", [["Om belangenconflicten te voorkomen; dit vloeit voort uit Europese regels.", "Bijvoorbeeld als dezelfde verzekeraar ook de tegenpartij verzekert; de Europese regels verlangen een waarborg zoals een aparte schadebehandelingsorganisatie."], ["Om fiscale redenen, omdat rechtsbijstand dan niet onder de assurantiebelasting valt.", "De afzondering heeft een toezichtrechtelijke reden: het voorkomen van belangenconflicten."], ["Omdat Kifid dat voorschrijft als voorwaarde voor aansluiting van de verzekeraar.", "Kifid is een klachteninstituut en stelt die eis niet; de regel komt uit Europese wetgeving."], ["Om de kosten en daarmee de premie voor rechtsbijstand lager te maken.", "Kostenbeheersing is niet de reden; het gaat om onafhankelijke behandeling van de zaak."]]],
["Wat bepalen veel zakelijke rechtsbijstandpolissen als het financiële belang van een geschil veel kleiner is dan de te verwachten behandelkosten?", [["De verzekeraar mag de zaak afkopen door het financiële belang te vergoeden.", "Met zo'n afkoopregeling voorkomt de verzekeraar onevenredig hoge kosten; de verzekerde krijgt dan het belang vergoed in plaats van de procedure."], ["De verzekeraar moet de zaak in dat geval altijd tot in de hoogste instantie voeren.", "Polissen kennen juist afwegingen over proportionaliteit; een onbeperkte procesplicht bestaat niet."], ["De verzekerde moet het geschil dan zelf verzekeren via de AVB.", "De AVB dekt aansprakelijkheid voor schade bij derden en geen juridische geschillen van de verzekerde zelf."], ["De dekking vervalt en de premie wordt teruggestort.", "De dekking vervalt niet; de verzekeraar kiest voor een andere manier om het belang te vergoeden."]]],
["Hoe lang is een werkgever bij ziekte van een werknemer in beginsel verplicht het loon door te betalen?", [["104 weken.", "De loondoorbetalingsplicht bij ziekte duurt in beginsel twee jaar; dit risico kan de werkgever met een verzuimverzekering afdekken."], ["52 weken.", "Na één jaar loopt de loondoorbetaling in beginsel door; de wettelijke periode is twee jaar."], ["26 weken.", "Dat is veel korter dan de wettelijke termijn van twee jaar."], ["13 weken.", "Na dertien weken moet de werkgever het verzuim melden bij het UWV, maar de loondoorbetaling loopt door tot twee jaar."]]],
["Wat dekt een verzuimverzekering voor werkgevers?", [["De loonkosten die de werkgever bij ziekte moet doorbetalen, na het eigen risico.", "Het is een schadeverzekering voor de werkgever: de verzekeraar vergoedt (een deel van) de doorbetaalde loonkosten."], ["Het inkomen van de werknemer, dat de verzekeraar rechtstreeks aan hem betaalt.", "De werknemer houdt recht op loon van de werkgever; de verzekering vergoedt de werkgever, niet de werknemer."], ["De WIA-uitkering van de werknemer na twee jaar ziekte.", "Na twee jaar gaat het om de WIA; daarvoor bestaan aparte (eigenrisicodragers)verzekeringen."], ["De transitievergoeding bij ontslag van een langdurig zieke werknemer.", "Een ontslagvergoeding is geen verzuimrisico en valt niet onder een verzuimverzekering."]]],
["Een werkgever wordt eigenrisicodrager voor de WGA. Welk risico neemt hij daarmee op zich?", [["De kosten van WGA-uitkeringen en re-integratie, voor maximaal tien jaar.", "In plaats van een gedifferentieerde premie aan het UWV draagt de werkgever zelf de WGA-lasten; dit risico kan hij verzekeren met een WGA-eigenrisicoverzekering."], ["De WW-uitkeringen van werknemers die door de werkgever worden ontslagen.", "Het eigenrisicodragerschap in deze vraag betreft de WGA, niet de werkloosheidswet."], ["De loondoorbetaling bij ziekte in de eerste twee ziektejaren.", "Die plicht heeft iedere werkgever al; eigenrisicodragerschap voor de WGA betreft de periode daarna."], ["De IVA-uitkering van volledig en duurzaam arbeidsongeschikte werknemers.", "Voor de IVA kan de werkgever geen eigenrisicodrager worden; die blijft bij het UWV."]]],
["Welke verplichting uit de Arbeidsomstandighedenwet is relevant bij de beoordeling van werkgeversaansprakelijkheid en de acceptatie van een AVB?", [["Een werkgever met personeel moet een risico-inventarisatie en -evaluatie (RI&E) hebben.", "Een ontbrekende of verouderde RI&E maakt het voor de werkgever lastig aan te tonen dat hij zijn zorgplicht is nagekomen."], ["Een werkgever moet zijn bedrijfsauto's jaarlijks laten keuren door de Arbeidsinspectie.", "Voertuigkeuringen hebben een eigen regeling en zijn geen kernverplichting uit de Arbowet."], ["Een werkgever is wettelijk verplicht een aansprakelijkheidsverzekering voor bedrijven te sluiten.", "Een AVB is voor de meeste bedrijven niet wettelijk verplicht, al is zij wel sterk aan te raden."], ["Een werkgever met personeel moet altijd een verzuimverzekering hebben afgesloten.", "Een verzuimverzekering is vrijwillig; de werkgever mag het risico van loondoorbetaling ook zelf dragen."]]],
["Wat houdt een volmacht in de schadeverzekeringsmarkt in?", [["Een verzekeraar machtigt een gevolmachtigde om namens hem risico's te accepteren.", "Vaak mag de gevolmachtigde ook polissen afgeven en schaden afhandelen; het verzekeringsrisico blijft bij de verzekeraar (de volmachtgever)."], ["De gevolmachtigde neemt het verzekeringsrisico over en draagt de schaden zelf.", "De gevolmachtigde is geen risicodrager; de verzekeraar blijft het risico dragen."], ["De klant machtigt zijn adviseur om namens hem een polis te ondertekenen.", "Dat is een machtiging van de klant aan de adviseur, niet de volmacht van een verzekeraar aan een bemiddelaar."], ["Een verzekeraar draagt een deel van zijn risico's over aan een herverzekeraar.", "Dat is herverzekering; daarbij gaat het om risicospreiding tussen verzekeraars."]]],
["Een gevolmachtigde handelt een schade af namens de verzekeraar en wijst de claim onterecht af. Wie is tegenover de verzekeringnemer gehouden de verzekeringsovereenkomst na te komen?", [["De verzekeraar, omdat de gevolmachtigde in zijn naam heeft gehandeld.", "De overeenkomst is gesloten met de verzekeraar; die blijft verantwoordelijk, ook voor werkzaamheden die hij heeft uitbesteed."], ["Alleen de gevolmachtigde, omdat die de beslissing heeft genomen.", "De gevolmachtigde is vertegenwoordiger en geen contractspartij als verzekeraar."], ["De adviseur van de verzekeringnemer.", "De adviseur heeft een eigen zorgplicht, maar is geen partij bij de verzekeringsovereenkomst."], ["Het Kifid, als de klacht daar wordt ingediend.", "Kifid beslecht geschillen, maar is geen partij die de overeenkomst moet nakomen."]]],
["Wat is een collectief contract bij schade- en verzuimverzekeringen?", [["Een raamovereenkomst waaronder leden of werknemers van een groep verzekerd zijn.", "Collectieve contracten bieden schaal: vaak gunstigere voorwaarden of premies voor de aangesloten groep."], ["Een polis waarin meerdere verzekeraars ieder voor een vast aandeel een deel van één risico dragen.", "Dat is coassurantie; een collectief contract gaat over het verzekeren van een groep."], ["Een overeenkomst waarbij een verzekeraar een deel van zijn eigen risico's herverzekert.", "Herverzekering speelt tussen verzekeraars en staat los van het collectief verzekeren van een groep."], ["Een contract dat uitsluitend voor collectieve pensioenregelingen kan worden gebruikt.", "Collectieve contracten komen ook voor bij onder meer verzuim, ongevallen en aansprakelijkheid."]]],
["Een adviseur wil een mkb-klant onderbrengen in een collectief contract van een brancheorganisatie met een aantrekkelijke collectiviteitskorting. Wat is juist?", [["De adviseur moet nog steeds nagaan of de voorwaarden passen bij de wensen en behoeften en de risico's van de klant.", "Een korting zegt niets over de passendheid van de dekking; de zorgplicht en de wensen-en-behoeftentoets blijven gelden."], ["Bij een collectief contract vervalt de zorgplicht, omdat de brancheorganisatie de voorwaarden al vooraf heeft beoordeeld.", "De brancheorganisatie adviseert de individuele klant niet; die verantwoordelijkheid ligt bij de adviseur."], ["Een collectief contract is altijd beter dan een individuele polis.", "Collectieve voorwaarden zijn standaard en sluiten niet altijd aan op het specifieke risico van de klant."], ["De adviseur hoeft alleen de premie te vergelijken met andere aanbieders.", "Passend advies gaat over dekking, uitsluitingen en voorwaarden, niet alleen over de prijs."]]],
["Wat is coassurantie?", [["Meerdere verzekeraars dragen ieder rechtstreeks een vast aandeel van hetzelfde risico.", "Bij coassurantie is elke deelnemende verzekeraar voor zijn eigen aandeel risicodrager tegenover de verzekeringnemer."], ["Een verzekeraar draagt een deel van het risico over aan een of meer herverzekeraars.", "Bij herverzekering heeft de verzekeringnemer alleen een contract met de directe verzekeraar."], ["Twee los van elkaar gesloten polissen bij verschillende verzekeraars voor hetzelfde belang.", "Dat is dubbele verzekering, die meestal niet is afgestemd; coassurantie is een bewust verdeelde plaatsing."], ["De verzekeringnemer draagt zelf een deel van iedere schade als eigen risico.", "Een eigen risico is risicobehoud door de verzekeringnemer, geen verdeling tussen verzekeraars."]]],
["Bij een coassurantiepolis gaat één van de deelnemende verzekeraars failliet. Wat betekent dit voor de verzekeringnemer?", [["De anderen betalen alleen hun eigen aandeel; het aandeel van de failliete verzekeraar niet.", "Coassuradeuren zijn niet hoofdelijk aansprakelijk; ieder is alleen gebonden voor het getekende aandeel."], ["De andere verzekeraars nemen het aandeel van de failliete verzekeraar automatisch over.", "Er is geen hoofdelijkheid; zonder bijzondere afspraak nemen de anderen dat aandeel niet over."], ["De leidende verzekeraar betaalt het volledige schadebedrag aan de verzekeringnemer.", "De leider voert het beheer, maar draagt alleen zijn eigen aandeel van het risico."], ["De polis vervalt in zijn geheel met terugwerkende kracht tot de ingangsdatum.", "De polis blijft bestaan voor de aandelen van de overige verzekeraars."]]],
["Welke rol heeft de leidende verzekeraar bij een beurspolis?", [["Hij voert namens alle deelnemers het beheer en de schadebehandeling.", "Via de leidende-verzekeraarsclausule binden zijn beslissingen de volgers, voor zover de polis dat bepaalt; de verzekeringnemer hoeft niet met elke verzekeraar apart te onderhandelen."], ["Hij draagt altijd 100% van het risico en herverzekert dat bij de volgers.", "De leider draagt alleen zijn eigen aandeel; de volgers zijn zelfstandig risicodrager voor hun aandeel."], ["Hij int alleen de premie; over schaden beslist elke verzekeraar afzonderlijk.", "De leider heeft juist een centrale rol in de schadebehandeling, binnen de grenzen van de polis."], ["Hij is de makelaar die het risico namens de klant op de beurs plaatst.", "De makelaar plaatst het risico; de leidende verzekeraar is een van de risicodragers."]]],
["Wat is voor de verzekeringnemer het belangrijkste verschil tussen coassurantie en herverzekering?", [["Bij coassurantie heeft hij een vordering op elke deelnemende verzekeraar, bij herverzekering niet op de herverzekeraar.", "De herverzekeraar heeft geen contract met de verzekeringnemer; bij coassurantie is iedere verzekeraar zijn wederpartij voor zijn aandeel."], ["Bij herverzekering heeft hij een rechtstreekse vordering op de herverzekeraar; bij coassurantie alleen op de leidende verzekeraar.", "Dit is precies omgekeerd; de herverzekeraar staat buiten de relatie met de verzekeringnemer."], ["Er is geen verschil; beide termen betekenen hetzelfde en worden door elkaar gebruikt in de markt.", "Het zijn verschillende constructies met een andere rechtspositie voor de verzekeringnemer."], ["Herverzekering is in Nederland verboden voor zakelijke risico's, coassurantie is wel toegestaan.", "Herverzekering is een normaal en toegestaan instrument voor risicospreiding tussen verzekeraars."]]],
["Waarom worden grote zakelijke risico's vaak via een makelaar op de beursmarkt geplaatst?", [["Omdat het risico zo over meerdere verzekeraars kan worden gespreid, met maatwerk.", "Eén verzekeraar heeft vaak onvoldoende capaciteit of risicobereidheid; spreiding via coassurantie lost dat op."], ["Omdat de Wft-gedragsregels op de beursmarkt nooit van toepassing zijn.", "Dat is te stellig; ook bij plaatsing via de beurs gelden regels voor bemiddeling en advies."], ["Omdat het voor één verzekeraar wettelijk verboden is een groot risico alleen te dragen.", "Zo'n verbod bestaat niet; het is een kwestie van capaciteit en risicobereidheid."], ["Omdat bij een beurspolis wettelijk nooit onderverzekering kan worden toegepast.", "Onderverzekering hangt af van de polisvoorwaarden, niet van de vraag of het een beurspolis is."]]],
["Wat houdt de mededelingsplicht van de verzekeringnemer vóór het sluiten van de verzekering in?", [["Hij moet de feiten meedelen die hij kent of behoort te kennen en die voor de verzekeraar van belang kunnen zijn.", "Dit is de kern van de precontractuele mededelingsplicht in het BW; ook feiten waarnaar niet uitdrukkelijk wordt gevraagd kunnen eronder vallen."], ["Hij hoeft alleen feiten te melden waarnaar uitdrukkelijk is gevraagd, ook als er helemaal geen vragenlijst is gebruikt.", "Zonder vragenlijst geldt de algemene mededelingsplicht; de beperking tot gestelde vragen hoort bij een vragenlijst van de verzekeraar."], ["Hij moet tijdens de gehele looptijd iedere wijziging van het risico direct aan de verzekeraar melden.", "De wettelijke mededelingsplicht ziet op de periode vóór het sluiten; meldplichten tijdens de looptijd volgen uit de polis."], ["Hij hoeft alleen feiten te melden die hij zeker weet, niet feiten die hij had behoren te kennen.", "Ook feiten die hij behoort te kennen vallen onder de plicht; onwetendheid door nalatigheid beschermt niet."]]],
["Een verzekeraar heeft voor een AVB een eigen vragenlijst gebruikt. Er is niet gevraagd naar eerdere faillissementen van de directeur. Kan de verzekeraar zich later beroepen op het niet melden daarvan?", [["Nee, tenzij het feit is verzwegen met het opzet de verzekeraar te misleiden.", "Bij een vragenlijst van de verzekeraar komt het risico van niet-gestelde vragen voor zijn rekening, behalve bij opzet tot misleiding."], ["Ja, want de verzekeringnemer moet alle relevante feiten altijd uit zichzelf melden.", "Bij gebruik van een vragenlijst is de mededelingsplicht in beginsel beperkt tot de gestelde vragen."], ["Ja, mits het feit relevant was voor de acceptatie.", "Relevantie is niet genoeg; zonder vraag kan de verzekeraar zich alleen bij opzet tot misleiding beroepen."], ["Nee, zelfs niet als met opzet tot misleiding is verzwegen.", "Opzet tot misleiding vormt juist de uitzondering; dan kan de verzekeraar zich wel beroepen op het verzwijgen."]]],
["Na een schade blijkt dat de verzekeringnemer bij het sluiten feiten niet heeft gemeld. De verzekeraar zou de verzekering dan wel hebben gesloten, maar tegen een hogere premie. Wat is het gevolg?", [["De uitkering wordt verminderd naar verhouding van de betaalde tot de verschuldigde premie.", "Het BW kiest voor proportionaliteit: de verzekerde krijgt wat bij de werkelijk betaalde premie hoort."], ["Er wordt niets uitgekeerd, omdat de verzekeringnemer zijn mededelingsplicht heeft geschonden.", "Een volledige afwijzing past bij de situatie dat de verzekeraar de verzekering helemaal niet zou hebben gesloten, of bij opzet tot misleiding."], ["Er wordt volledig uitgekeerd, omdat de verzekeraar de verzekering toch had gesloten.", "De verzekeraar zou een hogere premie hebben gevraagd; dat verschil komt tot uitdrukking in een lagere uitkering."], ["Er wordt volledig uitgekeerd, minus het premieverschil over de looptijd.", "De wet hanteert een evenredige vermindering van de uitkering, geen verrekening van het premieverschil."]]],
["Een ondernemer heeft bij het sluiten van een inventarisverzekering een eerdere inbraak niet gemeld. Later ontstaat schade door blikseminslag. Mag de verzekeraar de uitkering op grond van de verzwijging weigeren?", [["Nee; het verzwegen feit staat los van de schade, dus de verzekeraar moet in beginsel uitkeren.", "Het BW kent een causaliteitsregel: verzwijging van een feit dat niet van belang is voor het risico zoals het zich heeft verwezenlijkt, leidt niet tot vermindering, behalve bij opzet tot misleiding."], ["Ja; iedere verzwijging, ook van een niet-gerelateerd feit, geeft de verzekeraar het recht de uitkering te weigeren.", "De wet stelt grenzen aan de gevolgen van verzwijging, waaronder het vereiste van verband met de verwezenlijkte schade."], ["Ja, maar de verzekeraar mag dan alleen de helft van de schade vergoeden.", "Een vaste halvering kent de wet niet; de gevolgen hangen af van de causaliteit en van wat de verzekeraar zou hebben gedaan."], ["Nee, omdat verzwijging bij zakelijke verzekeringen nooit gevolgen heeft.", "De regels over de mededelingsplicht gelden ook bij zakelijke verzekeringen."]]],
["Binnen welke termijn na ontdekking van een schending van de mededelingsplicht moet de verzekeraar de verzekeringnemer daarop wijzen, om zich op de gevolgen te kunnen beroepen?", [["Binnen twee maanden.", "De verzekeraar moet binnen twee maanden na ontdekking op de niet-nakoming wijzen, onder vermelding van de mogelijke gevolgen; doet hij dat niet, dan kan hij zich er niet meer op beroepen."], ["Binnen veertien dagen.", "Die termijn is korter dan de wet bepaalt."], ["Binnen zes maanden.", "Die termijn is langer dan de wet bepaalt."], ["Binnen één jaar.", "De wettelijke termijn is aanzienlijk korter, zodat de verzekeringnemer snel duidelijkheid krijgt."]]],
["Een inventaris met een werkelijke waarde van € 200.000 is verzekerd voor € 150.000. Er ontstaat een schade van € 40.000. Hoeveel keert de verzekeraar uit bij toepassing van de evenredigheidsregel, zonder eigen risico?", [["€ 30.000.", "Er is voor 75% verzekerd (€ 150.000 / € 200.000), dus wordt 75% van € 40.000 vergoed."], ["€ 40.000.", "Dat zou gelden bij een verzekering op eerste risico of als de evenredigheidsregel is uitgesloten."], ["€ 0.", "Onderverzekering leidt tot een evenredige vermindering, niet tot een volledige afwijzing."], ["€ 22.500.", "Dit ontstaat als de verhouding van 75% twee keer wordt toegepast; de regel wordt maar één keer toegepast."]]],
["Wat betekent het als een inventaris 'op eerste risico' is verzekerd?", [["De schade wordt vergoed tot het verzekerde bedrag, zonder beroep op onderverzekering.", "Bij een eerste-risicoverzekering is de werkelijke waarde niet van belang zolang de schade binnen het verzekerde bedrag blijft."], ["Alleen de eerste schade in een verzekeringsjaar is gedekt; latere schaden niet.", "Eerste risico zegt niets over het aantal schaden per jaar."], ["De verzekeraar keert alleen het deel van de schade boven het eigen risico uit.", "Dat geldt bij iedere polis met een eigen risico; het begrip eerste risico gaat over onderverzekering."], ["Bij dubbele verzekering betaalt deze verzekeraar altijd als eerste uit.", "De volgorde bij samenloop wordt geregeld via samenloopbepalingen, niet via het begrip eerste risico."]]],
["Een bedrijf heeft zijn inventaris bij verzekeraar A verzekerd op eerste risico tot € 100.000 en bij verzekeraar B op tweede risico. Wanneer komt verzekeraar B aan bod?", [["Voor het deel van de schade boven het bedrag van het eerste risico.", "De tweede-risicoverzekering is een aanvullende laag boven het eerste risico, volgens de eigen voorwaarden van die polis."], ["Altijd als eerste, waarna verzekeraar A het eventuele restant betaalt.", "De volgorde is juist omgekeerd: eerst het eerste risico, daarna het tweede."], ["Bij iedere schade voor de helft, naast verzekeraar A.", "Er is geen verdeling bij helfte; elke verzekeraar dekt een eigen laag van de schade."], ["Alleen als verzekeraar A failliet is of om een andere reden niet betaalt.", "Het tweede risico is een dekkingslaag en geen vangnet voor insolventie van de eerste verzekeraar."]]],
["Een zaak is bij twee verzekeraars voor hetzelfde belang tegen hetzelfde risico verzekerd, zonder bijzondere samenloopclausules. Wat is de hoofdregel?", [["Elke verzekeraar is gehouden alsof hij de enige is, maar in totaal niet meer dan de schade.", "De verzekerde mag kiezen wie hij aanspreekt; de verzekeraars verdelen de last onderling naar verhouding, zodat het indemniteitsbeginsel overeind blijft."], ["De verzekerde kan bij beide verzekeraars de volledige schade claimen en ontvangt die dubbel.", "Een schadeverzekering mag niet leiden tot verrijking; de totale uitkering is beperkt tot de schade."], ["Alleen de verzekeraar met de oudste polis is gehouden de schade te vergoeden.", "De wet legt de last niet bij de oudste polis; elke verzekeraar is in beginsel gehouden."], ["Beide verzekeraars betalen automatisch de helft en de verzekerde mag niet kiezen.", "De verzekerde mag juist kiezen wie hij aanspreekt; de onderlinge verdeling volgt daarna."]]],
["Bij een beginnende brand zet een ondernemer zijn blusmiddelen in en laat hij een bedrijf goederen in veiligheid brengen. Hoe worden deze kosten op grond van het BW vergoed?", [["Als redelijke bereddingskosten, zo nodig ook boven de verzekerde som.", "De wet stimuleert het beperken van schade: redelijke kosten van bereddingsmaatregelen komen voor rekening van de verzekeraar, zelfs boven de verzekerde som."], ["Alleen voor zover er na de schade nog ruimte is binnen de verzekerde som.", "Juist voor bereddingskosten geldt dat ze ook boven de verzekerde som worden vergoed."], ["Niet, want het gaat om eigen kosten die de ondernemer vrijwillig heeft gemaakt.", "Het BW bepaalt dat redelijke bereddingskosten voor rekening van de verzekeraar komen."], ["Alleen als de brandweer opdracht heeft gegeven voor de maatregelen.", "Een opdracht van de brandweer is geen voorwaarde; bepalend is of de maatregelen redelijk waren om schade te voorkomen of te beperken."]]],
["De verzekeraar keert een brandschade uit die door een aannemer van de buren is veroorzaakt. Wat gebeurt er met de vordering van de verzekerde op die aannemer?", [["Die gaat over op de verzekeraar voor zover deze heeft uitgekeerd (subrogatie).", "De verzekeraar kan daarna zelf verhaal nemen op de aansprakelijke derde; de verzekerde kan niet dubbel vergoed krijgen."], ["Die blijft volledig bij de verzekerde, die dus ook de aannemer nog kan aanspreken.", "Dan zou de verzekerde dubbel worden vergoed; voor het uitgekeerde deel gaat de vordering over op de verzekeraar."], ["Die vervalt door de uitkering.", "De vordering vervalt niet, maar gaat over op de verzekeraar."], ["Die gaat over op het Waarborgfonds.", "Het Waarborgfonds Motorverkeer speelt alleen bij verkeersschade zonder verzekering of met een onbekende veroorzaker."]]],
["Een kapper met een eenmanszaak heeft weinig verzekeringskennis en vraagt advies over zijn bedrijfsverzekeringen. Wat betekent dit voor de zorgplicht van de adviseur?", [["Hoe minder deskundig de klant, hoe actiever de adviseur moet waarschuwen.", "De zorgplicht is afhankelijk van de omstandigheden; bij een niet-professionele zakelijke klant reikt die verder dan bij een professionele inkoper."], ["Een zakelijke klant geldt altijd als professioneel, zodat de zorgplicht niet geldt.", "Ook bij zakelijke klanten geldt een zorgplicht; een kleine ondernemer is lang niet altijd deskundig."], ["De adviseur hoeft alleen te antwoorden op vragen die de klant zelf stelt.", "De adviseur moet ook uit zichzelf relevante risico's signaleren die de klant niet kent."], ["Toezending van de polisvoorwaarden is voldoende om aan de zorgplicht te voldoen.", "Voorwaarden toesturen vervangt geen uitleg; de adviseur moet belangrijke beperkingen actief toelichten."]]],
["Een adviseur heeft met een mkb-klant een doorlopende adviesrelatie. De klant heeft sinds het afsluiten flink geïnvesteerd in machines. Wat volgt uit de zorgplicht van de adviseur?", [["Hij moet periodiek nagaan of de verzekerde bedragen nog passen en de klant wijzen op het risico van onderverzekering.", "Bij een doorlopende relatie hoort nazorg; ontwikkelingen in het bedrijf kunnen de dekking ontoereikend maken."], ["Niets; de klant is zelf verantwoordelijk voor het melden van nieuwe investeringen, de adviseur hoeft daarin niets te doen.", "De klant moet wijzigingen melden, maar bij een doorlopende relatie heeft de adviseur een eigen actieve rol."], ["Hij moet de verzekerde som zonder overleg met de klant verhogen.", "Wijzigen zonder overleg past niet; de adviseur moet de klant informeren en samen een keuze maken."], ["Hij moet de polis opzeggen en een nieuwe offerte aanvragen.", "Opzeggen is niet nodig; een aanpassing van de bestaande verzekering is meestal voldoende."]]],
["Een installateur gaat naast het uitvoeren van installaties ook betaalde ontwerp- en adviesopdrachten doen. De adviseur weet dit. Wat moet hij doen?", [["De klant wijzen op het ontbreken van dekking voor adviesfouten en een BAV bespreken.", "Zuivere vermogensschade door adviesfouten valt doorgaans buiten de AVB; een gewijzigde bedrijfsactiviteit kan zo een gat in de dekking veroorzaken."], ["Niets, omdat de AVB alle activiteiten van het bedrijf automatisch meeverzekert.", "De AVB dekt de omschreven activiteiten en meestal geen zuivere vermogensschade."], ["De AVB direct opzeggen, omdat die niet meer bij het bedrijf past.", "De AVB blijft nodig voor de installatiewerkzaamheden; er moet hooguit iets worden aangevuld."], ["Wachten tot er een claim komt en dan nagaan wat er gedekt is.", "Zorgplicht is vooruitkijken; achteraf vaststellen dat er geen dekking is, is te laat."]]],
["Een klant besluit na advies bewust geen bedrijfsschadeverzekering te sluiten. Waarom is het belangrijk dit in het dossier vast te leggen?", [["Om te kunnen aantonen dat de klant op het risico is gewezen en bewust heeft gekozen.", "Een goed dossier is bij een klacht of aansprakelijkstelling het bewijs dat de adviseur zijn zorgplicht is nagekomen."], ["Omdat de verzekeraar het adviesdossier van de adviseur vooraf moet goedkeuren.", "Het adviesdossier is van de adviseur en hoeft niet door een verzekeraar te worden goedgekeurd."], ["Omdat de klant daarmee afstand doet van alle toekomstige claims tegen de adviseur.", "Vastlegging is bewijs van de advisering, geen afstand van rechten door de klant."], ["Omdat de klant de verzekering dan later niet meer kan afsluiten.", "De klant kan later alsnog verzekeren; vastlegging beperkt die mogelijkheid niet."]]],
["Wat moet een distributeur op grond van de IDD-regels vóór het sluiten van iedere schadeverzekering in elk geval doen, ook bij een zakelijke klant?", [["De verlangens en behoeften van de klant vaststellen en daarop aansluitend aanbieden.", "Deze wensen-en-behoeftentoets geldt voor alle verzekeringsdistributie, met of zonder advies."], ["Een premievergelijking maken tussen ten minste drie verschillende verzekeraars.", "De IDD verplicht niet tot een vergelijking van drie verzekeraars; de kern is aansluiting op wensen en behoeften."], ["De klant laten verklaren dat hij de polisvoorwaarden volledig heeft gelezen.", "Zo'n verklaring vervangt de plicht van de distributeur om wensen en behoeften vast te stellen niet."], ["Niets bijzonders, want de IDD geldt alleen voor levensverzekeringen.", "De IDD geldt voor alle verzekeringsdistributie, dus ook voor schadeverzekeringen."]]],
["Welk gestandaardiseerd document moet bij een schadeverzekering (niet-leven) vóór het sluiten aan de klant worden verstrekt op grond van de IDD?", [["Het informatiedocument over het verzekeringsproduct (IPID).", "Het IPID geeft in een vast format beknopt weer wat wel en niet is verzekerd, zodat producten vergelijkbaar zijn."], ["Het essentiële-informatiedocument (EID) onder PRIIPs.", "Het EID is bedoeld voor verpakte beleggingsproducten, zoals beleggingsverzekeringen, niet voor schadeverzekeringen."], ["Het ESIS-formulier.", "Het ESIS-formulier hoort bij hypothecair krediet."], ["Het Uniform Pensioenoverzicht.", "Het UPO is een pensioenoverzicht en heeft niets met schadeverzekeringen te maken."]]],
["Hoeveel uur bijscholing per jaar schrijft de IDD minimaal voor aan personen die verzekeringen distribueren?", [["15 uur.", "De IDD vraagt ten minste 15 uur per jaar; Nederland vult dit in via het stelsel van permanente educatie, zoals deze PA-module."], ["8 uur.", "Dat is minder dan het Europese minimum van 15 uur."], ["40 uur.", "Zo veel schrijft de IDD niet voor; het minimum is 15 uur."], ["Geen minimum; alleen het initiële diploma telt.", "De IDD verlangt juist dat kennis en vaardigheden op peil blijven via jaarlijkse bijscholing."]]],
["Wat geldt op grond van de IDD voor de beloning van een adviseur die zakelijke schadeverzekeringen bemiddelt?", [["De beloning mag het klantbelang niet schaden en de klant hoort de aard ervan te kennen.", "Provisie is bij schadeverzekeringen toegestaan, maar mag geen prikkel geven die het klantbelang schaadt; transparantie over de aard van de beloning is verplicht."], ["Provisie is bij alle schadeverzekeringen, ook zakelijke, wettelijk verboden.", "Het Nederlandse provisieverbod geldt voor onder meer hypotheken en complexe producten, niet voor gewone schadeverzekeringen."], ["Bij zakelijke klanten hoeft de adviseur niets over zijn beloning te vertellen.", "De informatieplicht over de aard van de beloning geldt bij verzekeringsdistributie ook tegenover zakelijke klanten."], ["Alleen een vaste fee per uur is als beloning toegestaan.", "De IDD schrijft geen beloningsvorm voor; ook provisie kan, mits in lijn met het klantbelang."]]],
["Een assurantiekantoor bemiddelt uitsluitend in schadeverzekeringen. Valt het als bemiddelaar onder de Wwft?", [["Nee; de Wwft wijst wel bemiddelaars in levensverzekeringen aan, maar niet in schade.", "De sanctieregelgeving geldt wel voor iedereen; het kantoor moet dus nog steeds alert zijn op gesanctioneerde personen."], ["Ja, iedere financiële dienstverlener met een AFM-vergunning valt onder de Wwft.", "De Wwft geldt voor aangewezen instellingen; een AFM-vergunning voor schadebemiddeling maakt een kantoor niet automatisch Wwft-plichtig."], ["Ja, maar alleen voor zakelijke klanten en niet voor particulieren.", "Het onderscheid zakelijk of particulier bepaalt niet of de Wwft geldt; dat doet het soort dienstverlening."], ["Alleen als het kantoor meer dan tien medewerkers in dienst heeft.", "De omvang van het kantoor bepaalt niet of het onder de Wwft valt."]]],
["Wie is bij een bv in elk geval aan te merken als uiteindelijk belanghebbende (UBO)?", [["Een natuurlijk persoon met direct of indirect meer dan 25% van de aandelen of stemrechten.", "Dit is het kerncriterium voor UBO's bij vennootschappen; als niemand daaraan voldoet, geldt het hoger leidinggevend personeel als pseudo-UBO."], ["Iedere aandeelhouder, ongeacht de omvang van zijn direct of indirect gehouden aandelenbelang in de bv.", "Een klein aandelenbelang maakt iemand nog geen UBO; de drempel ligt boven de 25%."], ["Uitsluitend de statutair bestuurder, ongeacht wie de aandelen houdt.", "De bestuurder is niet automatisch UBO; die rol is pas aan de orde als er geen UBO op grond van eigendom of zeggenschap is."], ["De accountant die de jaarrekening van de bv controleert en goedkeurt.", "De accountant is een externe dienstverlener en geen belanghebbende in de vennootschap."]]],
["Een Wwft-instelling stelt een ongebruikelijke transactie vast. Waar moet zij die melden en wat mag zij de cliënt daarover vertellen?", [["Bij FIU-Nederland; de cliënt mag niet over de melding worden ingelicht.", "De geheimhoudingsplicht voorkomt dat de cliënt wordt gewaarschuwd en een onderzoek wordt gefrustreerd."], ["Bij de AFM; de cliënt moet direct na de melding worden ingelicht.", "Meldingen gaan naar FIU-Nederland, en de cliënt informeren is juist niet toegestaan."], ["Bij de politie; de cliënt mag worden ingelicht na afloop van het onderzoek.", "Ongebruikelijke transacties worden bij FIU-Nederland gemeld; het informeren van de cliënt is verboden."], ["Bij de Belastingdienst; de cliënt moet schriftelijk toestemming geven.", "Een melding vereist geen toestemming van de cliënt en gaat niet naar de Belastingdienst."]]],
["Voor wie gelden de verboden uit de Europese sanctieverordeningen, zoals het verbod om tegoeden ter beschikking te stellen aan gesanctioneerde personen?", [["Voor iedereen in de EU, ook voor kantoren die niet onder de Wwft vallen.", "Sanctieregels werken rechtstreeks en gelden voor alle personen en ondernemingen in de EU, los van de Wwft."], ["Alleen voor banken en andere instellingen die betalingen verwerken.", "Banken hebben een belangrijke rol, maar de verboden gelden voor iedereen."], ["Alleen voor instellingen die onder de Wwft vallen.", "Sanctieregelgeving en de Wwft zijn verschillende regimes; ook niet-Wwft-instellingen moeten de sancties naleven."], ["Alleen voor ondernemingen die zaken doen buiten de EU.", "Ook binnenlandse transacties met een gesanctioneerde persoon zijn verboden."]]],
["Bij de behandeling van een schadeclaim blijkt dat de UBO van de zakelijke klant op een EU-sanctielijst staat. Wat is juist?", [["Niet uitkeren, de tegoeden bevriezen en de treffer melden volgens de sanctieregels.", "Betalen aan of ten behoeve van een gesanctioneerde persoon is verboden, ook als de claim op zich gedekt is."], ["De uitkering gewoon doen, omdat de claim onder de polisdekking valt.", "Een gedekte claim maakt een betaling niet toegestaan als sanctieregels zich daartegen verzetten."], ["De uitkering doen, mits de betrokken UBO daarvoor schriftelijk toestemming geeft.", "Toestemming van de gesanctioneerde persoon verandert niets aan het verbod."], ["Alleen het eigen risico inhouden en de rest van de schade uitbetalen.", "Een gedeeltelijke betaling is evengoed in strijd met het sanctieverbod."]]],
["Wat regelt een sanctieclausule in een zakelijke polis?", [["De verzekeraar hoeft niet te dekken of uit te keren als dat sanctieregels schendt.", "De clausule voorkomt dat de verzekeraar contractueel tot iets verplicht is wat wettelijk verboden is."], ["De verzekeringnemer betaalt een boete bij te late betaling van de premie.", "Dat gaat over premiebetaling en heeft niets met internationale sancties te maken."], ["De verzekeraar mag zelf sancties opleggen als hij fraude ontdekt.", "Fraudemaatregelen zijn iets anders; de sanctieclausule gaat over internationale sanctieregelgeving."], ["Schade in landen buiten de EU is in alle gevallen uitgesloten van dekking.", "De clausule sluit geen landen uit als zodanig, maar alleen dekking die in strijd is met sanctieregels."]]],
["Wat is in schadeverzekeringen het verschil tussen schade door neerslag en schade door overstroming?", [["Neerslag komt uit de lucht; overstroming ontstaat door falende of overlopende waterkeringen.", "Neerslag is regen, sneeuw, hagel of smeltwater dat het gebouw binnendringt; overstroming komt van het bezwijken of overlopen van dijken, kaden of andere waterkeringen. Neerslag is meestal gedekt, overstroming vaak uitgesloten of beperkt verzekerbaar."], ["Neerslag ontstaat door een dijkdoorbraak of kadeval; overstroming is water door hevige regenval.", "Dit is precies omgekeerd."], ["Er is geen verschil; beide termen worden in polissen zonder onderscheid gebruikt.", "Polissen maken juist een scherp onderscheid, met grote gevolgen voor de dekking."], ["Neerslag is alleen hagel en sneeuw; al het andere water heet overstroming.", "Ook regen en smeltwater vallen onder neerslag."]]],
["Wanneer kan een ondernemer een tegemoetkoming krijgen op grond van de Wet tegemoetkoming schade bij rampen (WTS)?", [["Als de schade door een aangewezen ramp komt en redelijkerwijs niet verzekerbaar was.", "De WTS is een vangnet; schade die redelijkerwijs verzekerbaar was, komt niet voor een tegemoetkoming in aanmerking."], ["Altijd, als aanvulling op de uitkering die de verzekeraar al heeft gedaan.", "De WTS vult geen verzekeringsuitkering aan; zij is bedoeld voor niet verzekerbare schade."], ["Ook als de schade verzekerbaar was, maar de ondernemer geen verzekering had.", "Wie een verzekerbaar risico niet verzekert, kan geen beroep doen op de WTS."], ["Alleen als het gaat om schade aan een particuliere woning, niet aan een bedrijf.", "Ook ondernemers kunnen onder voorwaarden in aanmerking komen."]]],
["Een klant legt een groot zonnepanelendak op zijn bedrijfshal en plaatst een batterijopslag. Wat is voor de adviseur relevant?", [["Het risico verandert; dit melden en verzekerde som en preventie-eisen beoordelen.", "Zonnepanelen en batterijen verhogen de waarde en kunnen het brandrisico beïnvloeden; veel polissen kennen een meldplicht voor risicowijziging."], ["Niets; verduurzaming van een pand heeft geen invloed op het verzekerde risico.", "Nieuwe installaties veranderen zowel de waarde als het brandrisico van het pand."], ["Zonnepanelen en batterijen op bedrijfspanden zijn wettelijk onverzekerbaar.", "Zonnepanelen zijn verzekerbaar, al kunnen verzekeraars voorwaarden stellen."], ["Alleen de AVB moet worden aangepast; de opstalpolis blijft ongewijzigd.", "Juist de opstal- of brandverzekering wordt direct geraakt door de nieuwe installatie."]]],
["Is de Verordening duurzaamheidsinformatie (SFDR) van toepassing op het advies over een brandverzekering voor een bedrijf?", [["Nee; de SFDR ziet op producten met een beleggingscomponent, niet op schadeverzekeringen.", "De SFDR ziet op onder meer verzekeringsgebaseerde beleggingsproducten en pensioenproducten; bij schadeadvies spelen klimaatrisico's wel inhoudelijk een rol."], ["Ja, de SFDR geldt voor iedere verzekering die een adviseur in Nederland bemiddelt.", "De SFDR is beperkt tot onder meer beleggingsproducten, beleggingsverzekeringen en pensioenen."], ["Ja, maar alleen als de klant een beursgenoteerde onderneming is.", "De SFDR knoopt aan bij het soort financieel product, niet bij de beursnotering van de klant."], ["Nee, omdat de SFDR uitsluitend voor banken en vermogensbeheerders geldt.", "De SFDR geldt ook voor onder meer verzekeraars en adviseurs, maar alleen voor bepaalde producten."]]]
],
"vermogen":[
["Wat is in een financiële planning doorgaans de eerste stap voordat een klant vrij vermogen gaat beleggen?", [["Een voldoende financiële buffer aanhouden voor onvoorziene uitgaven", "Met een buffer hoeft de klant beleggingen niet op een ongunstig moment te verkopen als er onverwachte kosten zijn."], ["Het volledige spaargeld direct in aandelen omzetten", "Zonder buffer moet de klant bij tegenvallers mogelijk met verlies verkopen; dat is geen verantwoorde eerste stap."], ["Een beleggingsverzekering met overlijdensdekking afsluiten", "Een verzekering kan passend zijn, maar is geen vaste eerste stap in de planning."], ["Eerst een vaste beleggingshorizon van minimaal dertig jaar vastleggen", "De horizon volgt uit de doelen van de klant; er bestaat geen vaste minimale horizon als eerste stap."]]],
["Wat wordt bedoeld met het rente-op-rente-effect bij vermogensopbouw?", [["Behaald rendement levert in latere jaren zelf ook rendement op", "Doordat rendement wordt herbelegd, groeit het vermogen steeds sneller naarmate de looptijd langer is."], ["De bank vergoedt een hogere rente naarmate het saldo hoger is", "Dat is een staffelrente, geen rente-op-rente-effect."], ["De rente op een lening stijgt automatisch mee als de spaarrente stijgt", "Dat beschrijft een renteontwikkeling, niet het samengestelde rendement."], ["Rendement wordt alleen over de oorspronkelijke inleg berekend", "Dat is juist enkelvoudige rente, het tegenovergestelde van rente-op-rente."]]],
["Een klant legt eenmalig € 10.000 in tegen een vast rendement van 5% per jaar, dat wordt herbelegd. Wat is het vermogen na twee jaar, zonder kosten en belasting?", [["€ 11.025,00", "Na jaar 1 is het € 10.500,00; 5% daarover geeft € 525,00 extra, samen € 11.025,00."], ["€ 11.000,00", "Dat is enkelvoudige rente; het rendement over het rendement van jaar 1 ontbreekt."], ["€ 10.500,00", "Dat is het vermogen na één jaar, niet na twee jaar."], ["€ 11.050,00", "Dit bedrag is te hoog; 5% over € 10.500,00 is € 525,00, niet € 550,00."]]],
["Waarom is het voor een vermogensadvies belangrijk het doel van het vermogen te kennen?", [["Het doel bepaalt mede de horizon en het risico dat past", "Een buffer voor de korte termijn vraagt een andere aanpak dan vermogen voor pensioen over twintig jaar."], ["Het doel bepaalt welke toezichthouder bevoegd is", "Het toezicht hangt af van de dienst en de onderneming, niet van het doel van de klant."], ["Zonder doel mag een klant wettelijk niet sparen", "Sparen is niet aan een doel gebonden; het doel is vooral relevant voor passend advies."], ["Het doel bepaalt de hoogte van de box 3-heffing over het vermogen", "De box 3-heffing hangt af van de bezittingen en schulden, niet van het doel van het vermogen."]]],
["Wat is het verschil tussen nominaal en reëel rendement?", [["Reëel rendement is het nominale rendement gecorrigeerd voor inflatie", "Het reële rendement laat zien hoeveel de koopkracht van het vermogen werkelijk toeneemt."], ["Reëel rendement is het nominale rendement na aftrek van box 3-belasting", "Rendement na belasting heet netto rendement; reëel gaat over inflatie."], ["Nominaal rendement is het rendement na kosten", "Nominaal rendement is juist niet gecorrigeerd voor inflatie; kosten zijn een aparte factor."], ["Er is geen verschil, beide termen zijn synoniemen", "De termen verschillen wezenlijk: alleen reëel rendement houdt rekening met geldontwaarding."]]],
["Een klant behaalt een nominaal rendement van 3% terwijl de inflatie 3% bedraagt. Wat betekent dit voor de koopkracht van zijn vermogen?", [["De koopkracht blijft ongeveer gelijk", "Het vermogen groeit even hard als het prijspeil, dus het reële rendement is ongeveer nul."], ["De koopkracht stijgt met ongeveer 3%", "Die stijging wordt volledig tenietgedaan door de inflatie."], ["De koopkracht stijgt met ongeveer 6%", "Inflatie en rendement worden niet bij elkaar opgeteld; inflatie verlaagt de koopkracht."], ["De koopkracht daalt met ongeveer 3% per jaar", "Dat zou gelden bij een rendement van 0%; hier compenseert het rendement de inflatie."]]],
["Een klant van 30 jaar wil vermogen opbouwen voor zijn pensioen en kan maandelijks inleggen. Welk voordeel heeft periodiek inleggen in een beleggingsfonds ten opzichte van wachten tot er een groot bedrag is?", [["Het risico van een ongunstig instapmoment wordt kleiner", "Door vaste bedragen op verschillende momenten in te leggen koopt de klant bij lage koersen meer en bij hoge koersen minder participaties."], ["Periodiek inleggen garandeert op termijn een positief rendement", "Spreiding in de tijd verkleint het timingrisico, maar sluit verlies niet uit."], ["Periodiek inleggen valt buiten box 3", "De fiscale behandeling hangt niet af van de manier van inleggen."], ["Periodiek inleggen maakt een beleggersprofiel overbodig", "Ook bij periodiek inleggen moet het advies passen bij het profiel van de klant."]]],
["Wat dekt het depositogarantiestelsel (DGS) op hoofdlijnen?", [["Banktegoeden tot € 100.000 per rekeninghouder per bank bij faillissement van de bank", "Het DGS beschermt spaarders en rekeninghouders tegen het verlies van hun tegoed bij een bankfaillissement."], ["Koersverliezen op aandelen tot € 100.000 per persoon", "Koersverliezen zijn beleggingsrisico en vallen nooit onder het DGS."], ["Alle bezittingen van de klant bij een bank, inclusief effecten en kluisinhoud, zonder maximum", "Effecten vallen niet onder het DGS en het DGS kent een maximum."], ["Tegoeden tot € 20.000 per persoon bij een beleggingsonderneming", "€ 20.000 is het maximum van het beleggerscompensatiestelsel, niet van het DGS."]]],
["Wie voert in Nederland het depositogarantiestelsel uit?", [["De Nederlandsche Bank", "DNB voert het DGS uit en keert uit aan rekeninghouders als een bank failliet gaat."], ["De Autoriteit Financiële Markten", "De AFM houdt gedragstoezicht en voert het DGS niet uit."], ["Het Kifid", "Het Kifid behandelt klachten en geschillen en heeft geen rol bij uitkering van het DGS."], ["Het ministerie van Financiën", "Het ministerie maakt beleid, maar de uitvoering van het DGS ligt bij DNB."]]],
["Een echtpaar heeft samen een gezamenlijke spaarrekening met een saldo van € 180.000 bij één bank. De bank gaat failliet. Hoeveel valt er in beginsel onder het depositogarantiestelsel?", [["€ 180.000, omdat ieders aandeel van € 90.000 gedekt is", "Bij een gezamenlijke rekening wordt het tegoed gelijk verdeeld; elk deel van € 90.000 valt binnen de garantie per persoon."], ["€ 100.000, omdat de garantie per rekening en niet per persoon geldt", "De garantie geldt per rekeninghouder per bank, niet per rekening."], ["€ 200.000, omdat ieder recht heeft op de volle garantie", "De garantie is niet hoger dan het werkelijke tegoed; er wordt nooit meer uitgekeerd dan er stond."], ["€ 90.000, omdat alleen de eerste rekeninghouder is gedekt", "Beide rekeninghouders zijn gedekt voor hun aandeel in de gezamenlijke rekening."]]],
["Een klant spaart bij twee banknamen die onder één en dezelfde bankvergunning vallen. Wat betekent dit voor het depositogarantiestelsel?", [["Hij heeft voor beide banknamen samen één keer de garantie", "De garantie geldt per bank met een vergunning; merknamen onder één vergunning tellen samen."], ["Hij heeft per banknaam afzonderlijk de volle garantie", "Afzonderlijke merknamen geven geen extra garantie als zij onder dezelfde vergunning vallen."], ["Hij heeft geen garantie, omdat hij bij twee labels spaart", "Sparen bij meerdere labels heft de garantie niet op; het maximum geldt alleen gezamenlijk."], ["Hij heeft alleen garantie voor het label waar hij het eerst klant werd", "Er is geen rangorde naar aanmeldingsdatum; alle tegoeden onder de vergunning tellen samen."]]],
["Hoe wordt het depositogarantiestelsel in Nederland gefinancierd?", [["Banken dragen vooraf premies af aan een depositogarantiefonds", "Sinds de herziening van het stelsel betalen banken risicogewogen premies in een fonds dat vooraf wordt opgebouwd."], ["Spaarders betalen een jaarlijkse bijdrage van 0,1% over hun saldo", "Spaarders betalen geen bijdrage voor de garantie."], ["Uitsluitend uit de algemene belastingmiddelen", "Het stelsel wordt in de eerste plaats door de banken zelf gefinancierd."], ["Door de AFM uit de toezichtheffing", "De AFM-heffingen dienen voor het gedragstoezicht, niet voor het DGS."]]],
["Wat gebeurt er in de regel met de koers van een bestaande obligatie met vaste coupon als de marktrente stijgt?", [["De koers daalt", "Nieuwe obligaties bieden een hogere rente, dus de bestaande obligatie is minder waard en daalt in koers."], ["De koers stijgt", "Een koersstijging hoort bij een dalende marktrente."], ["De koers blijft gelijk omdat de coupon vast is", "Juist door de vaste coupon reageert de koers op veranderingen in de marktrente."], ["De coupon wordt automatisch verhoogd", "Bij een vastrentende obligatie verandert de coupon niet tussentijds."]]],
["Welke obligatie is bij een gelijke rentewijziging het meest koersgevoelig?", [["Een obligatie met een lange resterende looptijd en een lage coupon", "Hoe langer de (gemiddelde) looptijd van de kasstromen, hoe hoger de duration en dus de rentegevoeligheid."], ["Een obligatie met een korte resterende looptijd en een hoge coupon", "Deze heeft juist een lage duration en is weinig rentegevoelig."], ["Een obligatie die over drie maanden wordt afgelost", "Bij een zeer korte looptijd is de koers vrijwel ongevoelig voor de rente."], ["Een obligatie met een variabele rente die elk kwartaal wordt aangepast", "Een rente die vaak wordt aangepast beperkt juist het renterisico."]]],
["Een obligatie met een nominale waarde van € 1.000 en een coupon van 4% noteert op 80%. Wat is het lopend (direct) rendement, afgerond?", [["5,0%", "De couponrente is € 40 per jaar; gedeeld door de koerswaarde van € 800 is dat 5,0%."], ["4,0%", "4% is de couponrente over de nominale waarde, niet het rendement over de koerswaarde."], ["3,2%", "Dit is 80% van 4%; de berekening moet de coupon delen door de koerswaarde."], ["20,0%", "Dit is het koersverschil ten opzichte van de nominale waarde, niet het lopend rendement."]]],
["Een belegger koopt een aandeel voor € 50, ontvangt € 2 dividend en het aandeel staat aan het eind van het jaar op € 53. Wat is het totaalrendement over dat jaar, zonder kosten en belasting?", [["10%", "Het totaalrendement is koerswinst (€ 3) plus dividend (€ 2) is € 5, gedeeld door € 50."], ["6%", "Dit is alleen de koerswinst; het dividend hoort bij het totaalrendement."], ["4%", "Dit is alleen het dividendrendement; de koerswinst ontbreekt."], ["9,4%", "Dit is € 5 gedeeld door € 53; het rendement wordt berekend over de aankoopwaarde."]]],
["Welk risico kan een belegger met spreiding over veel verschillende aandelen grotendeels wegnemen?", [["Het ondernemingsspecifieke risico van één aandeel", "Tegenvallers bij één bedrijf hebben in een breed gespreide portefeuille weinig invloed."], ["Het marktrisico van de aandelenmarkt als geheel, zoals bij een crisis", "Marktrisico (systematisch risico) treft alle aandelen en is niet weg te diversifiëren."], ["Het inflatierisico over de hele portefeuille", "Inflatie raakt de hele economie en verdwijnt niet door meer aandelen te kopen."], ["Het renterisico van de obligatiemarkt", "Renterisico wordt niet weggenomen door aandelen te spreiden."]]],
["Wat drukt de standaarddeviatie van het rendement van een belegging uit?", [["De spreiding van het rendement rond het gemiddelde", "Een hogere standaarddeviatie betekent grotere uitschieters en dus meer risico."], ["Het gemiddelde rendement per jaar", "Het gemiddelde is een andere maatstaf; de standaarddeviatie meet de spreiding eromheen."], ["De totale kosten van het fonds", "Kosten worden uitgedrukt in bijvoorbeeld lopende kosten, niet in de standaarddeviatie."], ["De kans dat de uitgevende instelling van de belegging failliet gaat", "Dat is kredietrisico; de standaarddeviatie zegt iets over koersschommelingen."]]],
["Wat kenmerkt een ETF (exchange traded fund) die een index volgt?", [["Een beursverhandeld fonds dat passief een index volgt", "Een index-ETF probeert het rendement van een index te repliceren en is meestal goedkoop."], ["Het is een fonds dat actief probeert de index te verslaan", "Actief beheer met als doel de index te verslaan past niet bij een index-ETF."], ["Het is een gegarandeerd product zonder koersrisico", "Een ETF beweegt mee met de onderliggende index en kent dus koersrisico."], ["Het is een obligatie van één onderneming", "Een ETF bevat een mandje waarden en is geen enkele obligatie."]]],
["Wat is het verschil tussen een open-end en een closed-end beleggingsfonds?", [["Open-end: doorlopende uitgifte en inkoop van participaties; closed-end: een vast aantal deelnemingsrechten", "Daardoor sluit de koers van een open-end fonds nauw aan bij de intrinsieke waarde, terwijl een closed-end fonds met agio of disagio kan noteren."], ["Een open-end fonds is altijd duurzaam, een closed-end fonds nooit", "Duurzaamheid staat los van de juridische vorm van het fonds."], ["Een open-end fonds belegt alleen in obligaties en een closed-end fonds alleen in beursgenoteerde aandelen", "De vorm zegt niets over de beleggingscategorie."], ["Een closed-end fonds kan dagelijks onbeperkt nieuwe participaties uitgeven en inkopen tegen intrinsieke waarde", "Juist een open-end fonds doet dat; een closed-end fonds heeft een vast aantal stukken."]]],
["Wat is het belangrijkste nadeel van beleggen met geleend geld (hefboom)?", [["Verliezen worden vergroot, terwijl lening en rente gewoon terugbetaald moeten worden", "Een hefboom versterkt zowel winst als verlies; bij koersdalingen kan het verlies groter zijn dan de eigen inleg."], ["Het rendement wordt altijd lager", "Bij stijgende koersen kan het rendement op eigen vermogen juist hoger zijn."], ["Geleend geld mag fiscaal nooit worden belegd", "Er bestaat geen algemeen fiscaal verbod; het risico is het probleem."], ["De belegger verliest het stemrecht op zijn aandelen aan de geldverstrekker van de lening", "Stemrecht hangt niet af van de financiering van de aankoop."]]],
["Waarom kan een langere beleggingshorizon in het algemeen meer ruimte geven voor aandelen in de portefeuille?", [["Er is meer tijd om tijdelijke koersdalingen op te vangen", "Over langere perioden middelen schommelingen meer uit, waardoor de kans op een tegenvallend eindresultaat kleiner wordt."], ["Aandelen kunnen op lange termijn niet in waarde dalen", "Ook op lange termijn kunnen aandelen verlies opleveren; het risico neemt af, maar verdwijnt niet."], ["Bij een lange horizon gelden lagere kosten", "De kosten hangen af van het product, niet van de horizon van de klant."], ["Bij een lange horizon is een beleggersprofiel volgens MiFID II niet nodig", "Het profiel blijft altijd nodig; de horizon is daar juist een onderdeel van."]]],
["Een klant van 60 jaar belegt voor een aanvulling op zijn pensioen die over vijf jaar ingaat. Wat is in het algemeen een passende aanpak naarmate de einddatum nadert?", [["Het risico in de portefeuille geleidelijk afbouwen", "Door het aandelenbelang te verlagen beperkt de klant het risico dat een koersdaling vlak voor de einddatum het doel in gevaar brengt."], ["Het aandelenbelang juist verhogen om achterstand in te halen", "Dit vergroot het risico op een tekort precies wanneer er weinig hersteltijd is."], ["Alles in één aandeel beleggen om de kosten te beperken", "Dat vergroot het specifieke risico sterk en past niet bij een korte horizon."], ["De beleggingen ongewijzigd laten, omdat de horizon geen rol speelt", "De resterende horizon is juist een kernfactor voor het passende risico."]]],
["Wat wordt bedoeld met herbalanceren (rebalancing) van een beleggingsportefeuille?", [["Terugbrengen naar de afgesproken verdeling over beleggingscategorieën", "Door koersbewegingen wijkt de verdeling af; herbalanceren houdt het risico in lijn met het profiel."], ["Het overboeken van de volledige portefeuille naar een andere bank of beleggingsonderneming", "Dat is een overboeking, geen herbalancering."], ["Het jaarlijks opnieuw vaststellen van de kosten", "Kostenvaststelling staat los van de verdeling van de portefeuille."], ["Het uitkeren van alle ontvangen dividenden", "Uitkeren van dividend verandert niet vanzelf de verdeling naar de afgesproken verhouding."]]],
["Een fonds heeft lopende kosten van 1,5% per jaar, een vergelijkbaar indexfonds 0,2%. Bij gelijk bruto rendement, wat is het effect op lange termijn?", [["Het duurdere fonds geeft door rente-op-rente een aanzienlijk lager eindvermogen", "Kosten worden elk jaar van het vermogen afgehaald en het misgelopen rendement daarover groeit mee."], ["Het effect is te verwaarlozen omdat het om kleine percentages gaat", "Kleine verschillen per jaar tellen over lange looptijden juist sterk op."], ["Het duurdere fonds levert altijd meer op, omdat actief beheer de hogere kosten terugverdient", "Hogere kosten garanderen geen hoger rendement; bij gelijk bruto rendement levert het minder op."], ["Kosten hebben alleen invloed in het eerste jaar", "Lopende kosten worden elk jaar in rekening gebracht."]]],
["Wat is valutarisico voor een Nederlandse belegger in Amerikaanse aandelen?", [["Het risico dat een daling van de dollar het rendement in euro's verlaagt", "Ook als de koers in dollars gelijk blijft, levert een lagere dollar in euro's minder op."], ["Het risico dat de Amerikaanse beurs tijdelijk sluit en de aandelen niet verhandelbaar zijn", "Dat is een vorm van liquiditeits- of marktrisico, geen valutarisico."], ["Het risico dat de Amerikaanse onderneming failliet gaat", "Dat is ondernemingsrisico, los van de wisselkoers."], ["Het risico dat de rente in de eurozone gaat stijgen", "Dat is renterisico, geen valutarisico."]]],
["Wat is liquiditeitsrisico bij een belegging?", [["Het risico niet snel of alleen met flink koersverlies te kunnen verkopen", "Bij weinig handel in een belegging kan de belegger niet altijd tegen een redelijke prijs uitstappen."], ["Het risico dat de koers stijgt na verkoop", "Dat is gemiste winst, geen liquiditeitsrisico."], ["Het risico dat de belegger te veel contant geld aanhoudt", "Te veel contanten geeft vooral inflatierisico en gemist rendement."], ["Het risico dat de uitgevende instelling de rente of aflossing niet op tijd betaalt", "Dat is kredietrisico (debiteurenrisico)."]]],
["Wat is het verschil tussen een accumulerend en een uitkerend fonds?", [["Accumulerend herbelegt de opbrengsten, uitkerend keert ze uit", "Bij een accumulerend fonds komt de opbrengst tot uitdrukking in een hogere waarde per participatie."], ["Een accumulerend fonds belegt alleen in groeiaandelen", "De term zegt iets over wat met de opbrengst gebeurt, niet over de beleggingsstijl."], ["Een uitkerend fonds garandeert een vaste jaarlijkse uitkering van ten minste 4%", "De uitkering hangt af van de ontvangen opbrengsten en is niet gegarandeerd."], ["Een accumulerend fonds valt buiten box 3", "Beide soorten fondsen vallen bij een particulier in box 3."]]],
["Wat is in het algemeen het risico van een achtergestelde obligatie ten opzichte van een gewone (senior) obligatie van dezelfde uitgevende instelling?", [["Het risico is hoger, omdat zij bij faillissement pas na gewone schuldeisers worden terugbetaald", "Daarom bieden achtergestelde obligaties doorgaans een hogere rente als vergoeding."], ["Het risico is lager, omdat zij voorrang hebben bij faillissement", "Achtergesteld betekent juist dat zij achter andere schuldeisers aan komen."], ["Het risico is gelijk, omdat de uitgevende instelling dezelfde is", "De rangorde bij faillissement maakt het risico wezenlijk anders."], ["Er is geen risico, omdat achtergestelde obligaties onder het depositogarantiestelsel tot € 100.000 vallen", "Obligaties vallen niet onder het depositogarantiestelsel."]]],
["Een klant wil weten wat de correlatie tussen twee beleggingen betekent voor spreiding. Welke uitspraak is juist?", [["Hoe lager de correlatie tussen beleggingen, hoe groter het spreidingsvoordeel", "Beleggingen die niet gelijk bewegen dempen elkaars schommelingen, waardoor het portefeuillerisico daalt."], ["Hoe hoger de correlatie, hoe groter het spreidingsvoordeel", "Bij hoge correlatie bewegen beleggingen gelijk op en levert combineren weinig risicovermindering op."], ["Correlatie heeft geen invloed op het risico van een portefeuille, alleen op het rendement", "Correlatie is juist bepalend voor het effect van spreiding."], ["Correlatie zegt alleen iets over de kosten van beleggingen", "Correlatie gaat over de samenhang van koersbewegingen, niet over kosten."]]],
["Wat is een wezenlijk verschil tussen een beleggingsverzekering en een beleggingsrekening bij een bank?", [["Een beleggingsverzekering heeft daarnaast een verzekeringselement, zoals een overlijdensuitkering", "Daardoor worden er ook risicopremies en verzekeringskosten ingehouden, wat het rendement kan drukken."], ["Een beleggingsverzekering kent geen koersrisico", "Ook bij een beleggingsverzekering hangt de waarde af van de beleggingen."], ["Een beleggingsrekening valt altijd onder het depositogarantiestelsel", "Beleggingen vallen niet onder het DGS, ook niet als ze bij een bank worden aangehouden."], ["Een beleggingsverzekering wordt door een bank aangeboden onder een bankvergunning van De Nederlandsche Bank", "Een verzekering wordt aangeboden door een verzekeraar."]]],
["Wat werd in de discussie over 'woekerpolissen' vooral als probleem gezien?", [["Hoge en onduidelijke kosten en risicopremies die het rendement fors drukten", "Klanten konden vaak niet zien welk deel van hun inleg naar kosten ging, waardoor de verwachte opbouw tegenviel."], ["Dat beleggingsverzekeringen altijd een gegarandeerd minimumrendement van 4% boden", "Een garantie was juist meestal niet aanwezig; de opbouw hing van de beurs af."], ["Dat beleggingsverzekeringen niet onder Nederlands recht vielen", "De producten vielen gewoon onder Nederlands recht en toezicht."], ["Dat de premie fiscaal niet aftrekbaar kon zijn", "De fiscale behandeling was niet de kern van de woekerpolisaffaire."]]],
["Wat is banksparen?", [["Fiscaal gefacilieerd sparen of beleggen via een geblokkeerde bankrekening", "Sinds 2008 kan wat eerder alleen met een verzekering kon ook via een geblokkeerde bankrekening."], ["Sparen op iedere vrij opneembare spaarrekening, ongeacht het doel van het geld", "Een vrij opneembare spaarrekening is gewoon sparen in box 3, geen banksparen."], ["Geld lenen bij een bank om daarmee te kunnen beleggen", "Dat is beleggen met een effectenkrediet of hefboom."], ["Contant geld bewaren in een gehuurde bankkluis", "Een kluis is geen geblokkeerde fiscale spaarrekening."]]],
["Wat staat voor de afkortingen KEW, SEW en BEW?", [["Kapitaalverzekering eigen woning, spaarrekening eigen woning en beleggingsrecht eigen woning", "Dit zijn de fiscale producten om kapitaal op te bouwen voor aflossing van de eigenwoningschuld."], ["Kapitaalverzekering erfrecht, spaarrekening erfrecht en beleggingsrecht erfrecht", "De producten hebben betrekking op de eigen woning, niet op erfrecht."], ["Koopsom eigen woning, schuld eigen woning en belasting eigen woning", "Dit zijn geen fiscale begrippen voor vermogensopbouw."], ["Kapitaal extra werkgever, sparen extra werkgever en beleggen extra werkgever", "Deze begrippen bestaan niet; het gaat om de eigen woning."]]],
["Een klant heeft in 2010 een kapitaalverzekering eigen woning (KEW) gesloten. Wat geldt sinds 1 januari 2013 op hoofdlijnen?", [["Er geldt overgangsrecht, zodat de vrijstelling onder voorwaarden blijft", "Vanaf 2013 kunnen geen nieuwe KEW's meer worden gesloten, maar bestaande producten vallen onder overgangsrecht."], ["De KEW moest per 2013 verplicht worden afgekocht", "Er was geen verplichte afkoop; het overgangsrecht laat het product doorlopen."], ["De KEW is per 2013 automatisch en zonder heffing omgezet in een lijfrenteverzekering", "Er heeft geen automatische omzetting naar lijfrente plaatsgevonden."], ["Sinds 2013 kunnen KEW's onbeperkt opnieuw worden afgesloten", "Juist sinds 2013 kunnen geen nieuwe KEW's met fiscale faciliteit worden gesloten."]]],
["Wat houdt de bandbreedte-eis 1:10 bij een kapitaalverzekering eigen woning in?", [["De hoogste jaarpremie is maximaal tien keer de laagste jaarpremie", "Deze eis voorkomt dat de premiebetaling sterk wordt geconcentreerd in een paar jaren."], ["De uitkering mag niet hoger zijn dan tien keer het totaal van de betaalde premies", "De bandbreedte gaat over de verhouding tussen premies, niet over de uitkering."], ["De verzekering moet minstens tien jaar lopen", "Dat is geen beschrijving van de bandbreedte-eis."], ["Maximaal 10% van de premie mag aan kosten opgaan", "De bandbreedte zegt niets over de kosten van het product."]]],
["Wat is een beleggingsrecht eigen woning (BEW)?", [["Een geblokkeerd beleggingsrecht voor aflossing van de eigenwoningschuld", "Het BEW is de beleggingsvariant van banksparen voor de eigen woning en valt onder hetzelfde overgangsrecht als KEW en SEW."], ["Een recht van de bank om de eigen woning te verkopen", "Dat is het recht van parate executie van de hypotheekhouder."], ["Een vrij opneembare beleggingsrekening in box 3 met een hoger heffingsvrij vermogen", "Een BEW is juist geblokkeerd en heeft een fiscaal bijzondere status."], ["Een recht om in een beleggingspand te wonen", "Het BEW is een financieel product, geen woonrecht."]]],
["Welk document moet een klant op grond van de PRIIPs-verordening ontvangen voordat hij een beleggingsverzekering afsluit?", [["Een essentiële-informatiedocument (EID)", "Een beleggingsverzekering is een verzekeringsproduct met een beleggingscomponent en valt onder PRIIPs."], ["Een ESIS-formulier", "Het ESIS-formulier hoort bij hypothecair krediet."], ["Een Uniform Pensioenoverzicht", "Het UPO is een pensioenoverzicht van een pensioenuitvoerder."], ["Een Standaard Europees Consumentenkredietinformatieformulier", "Dat formulier hoort bij consumptief krediet."]]],
["Welke vermogenscategorieën kent de Overbruggingswet box 3 voor het berekenen van het forfaitaire rendement?", [["Banktegoeden, overige bezittingen en schulden", "Voor elke categorie geldt een eigen forfaitair rendement, zodat beter wordt aangesloten bij de werkelijke verhouding."], ["Spaargeld, eigen woning en pensioen", "De eigen woning valt in box 1 en pensioen valt niet in box 3."], ["Aandelen, obligaties en vastgoed, ieder met een gelijk percentage", "Er zijn drie categorieën met elk een eigen percentage, en die zijn anders ingedeeld."], ["Box 1, box 2 en box 3", "Dit zijn de boxen van de inkomstenbelasting, geen vermogenscategorieën binnen box 3."]]],
["In welke box 3-categorie van de Overbruggingswet vallen aandelen en een verhuurde tweede woning?", [["Overige bezittingen", "Beleggingen en onroerend goed dat niet de eigen woning is, vallen in de categorie overige bezittingen."], ["Banktegoeden", "Banktegoeden zijn spaar- en betaalrekeningen; aandelen en vastgoed vallen daar niet onder."], ["Schulden", "Dit zijn bezittingen, geen schulden."], ["Ze vallen buiten box 3", "Zowel aandelen als een tweede woning vallen bij een particulier in box 3."]]],
["Wat is het belangrijkste uitgangspunt van de tegenbewijsregeling in box 3 na de arresten van de Hoge Raad van juni 2024?", [["Wie aantoont dat zijn werkelijke rendement lager is dan het forfaitaire, wordt belast naar het werkelijke rendement", "Zo wordt voorkomen dat iemand belasting betaalt over een rendement dat hij niet heeft behaald."], ["Als het werkelijke rendement hoger is dan het forfaitaire, moet de belastingplichtige het verschil altijd bijbetalen", "De regeling werkt alleen ten gunste van de belastingplichtige bij een lager werkelijk rendement."], ["De box 3-heffing is volledig afgeschaft voor beleggers", "De heffing is niet afgeschaft; alleen de berekening kan anders uitvallen."], ["Alleen spaarders zonder beleggingen mogen tegenbewijs leveren", "Tegenbewijs staat open voor alle belastingplichtigen in box 3, niet alleen voor spaarders."]]],
["Welke opbrengsten tellen bij het werkelijke rendement in de box 3-tegenbewijsregeling mee?", [["Rente, dividend en ook ongerealiseerde waardeveranderingen", "Het werkelijke rendement omvat ook koersstijgingen en -dalingen, ook als de belegging niet is verkocht."], ["Alleen gerealiseerde verkoopwinsten", "Ongerealiseerde waardeveranderingen tellen ook mee."], ["Alleen ontvangen rente op spaarrekeningen", "Ook dividend, huur en waardeveranderingen horen bij het werkelijke rendement."], ["Alleen het rendement dat uitgaat boven het heffingsvrij vermogen per persoon", "Het werkelijke rendement wordt over het hele vermogen bepaald; het heffingsvrij vermogen is een ander begrip."]]],
["Een klant heeft een eigen woning die hij zelf bewoont als hoofdverblijf, en een vakantiewoning. In welke box vallen deze woningen?", [["De eigen woning in box 1, de vakantiewoning in box 3", "Alleen de woning die als hoofdverblijf dient is fiscaal een eigen woning; een tweede woning is een box 3-bezitting."], ["Beide woningen in box 1", "Een vakantiewoning is geen hoofdverblijf en valt niet in box 1."], ["Beide woningen in box 3", "De eigen woning die als hoofdverblijf dient valt in box 1."], ["De eigen woning in box 3, de vakantiewoning in box 1", "Dit is precies omgekeerd."]]],
["Twee fiscale partners hebben samen box 3-vermogen. Wat geldt in de aangifte voor de verdeling van hun box 3-inkomen?", [["Zij mogen het in elke gewenste verhouding verdelen", "Fiscale partners kunnen hun gezamenlijke box 3-inkomen vrij toerekenen, los van wie juridisch eigenaar is."], ["Het wordt altijd volgens de juridische eigendom verdeeld", "Bij fiscaal partnerschap is vrije verdeling toegestaan, los van de eigendom."], ["Alleen de partner met het hoogste inkomen geeft het aan", "Beide partners kunnen box 3-inkomen aangeven; de verdeling is vrij."], ["Het moet verplicht precies gelijk worden verdeeld", "Een gelijke verdeling mag, maar is niet verplicht; partners kiezen zelf de verhouding."]]],
["Waarom kreeg de Overbruggingswet box 3 haar naam?", [["Zij overbrugt de periode tot een nieuw stelsel op basis van werkelijk rendement", "De wet is bedoeld als tijdelijke regeling totdat een nieuw box 3-stelsel in werking treedt."], ["Zij overbrugt de verschillen tussen box 1 en box 2", "De wet gaat alleen over box 3."], ["Zij regelt de overgang van vermogen naar de erfgenamen", "Overgang van vermogen bij overlijden valt onder het erfrecht en de Successiewet."], ["Zij verbindt de Nederlandse box 3 met buitenlandse vermogensbelastingen via belastingverdragen", "Internationale aspecten vallen onder verdragen en het Besluit voorkoming dubbele belasting."]]],
["Hoe tellen schulden mee in box 3 onder de Overbruggingswet, afgezien van de eigenwoningschuld?", [["Schulden verminderen de grondslag voor zover zij boven een drempel uitkomen", "Kleine schulden worden zo buiten beschouwing gelaten; de schulden boven de drempel vormen een eigen categorie met een eigen forfait."], ["Schulden tellen in box 3 nooit mee", "Schulden die niet in box 1 vallen, tellen boven de drempel juist mee in box 3."], ["Schulden worden volledig opgeteld bij de bezittingen en verhogen zo de grondslag", "Schulden verlagen de grondslag; zij worden niet bij de bezittingen opgeteld."], ["Alleen schulden bij een bank tellen mee", "Ook andere schulden, zoals een lening bij familie, kunnen in box 3 meetellen."]]],
["Wat is het fiscale principe van een lijfrente in box 1?", [["De premie is binnen grenzen aftrekbaar, de uitkeringen zijn belast", "Dit heet de omkeerregel: belasting wordt uitgesteld tot de uitkeringsfase."], ["De premie is niet aftrekbaar en de latere uitkering is daardoor onbelast", "Dat past niet bij een lijfrente waarvoor premieaftrek is genoten."], ["Premie en uitkering vallen in box 3", "Een fiscaal gefacilieerde lijfrente valt in box 1, niet in box 3."], ["De premie is aftrekbaar en de uitkering is onbelast", "Dan zou er een dubbel voordeel zijn; de uitkering is juist belast."]]],
["Waarvoor is de jaarruimte bedoeld?", [["Om een pensioentekort aan te vullen met fiscaal aftrekbare lijfrentepremie", "De jaarruimte hangt af van het inkomen en de pensioenopbouw van dat jaar."], ["Om de hypotheekrente extra af te trekken", "De jaarruimte gaat over lijfrentepremie, niet over hypotheekrente."], ["Om schenkingen aan kinderen vrij te stellen", "Schenkingsvrijstellingen staan in de Successiewet."], ["Om box 3-vermogen tot het heffingsvrij vermogen vrij te stellen van inkomstenheffing", "Het heffingsvrij vermogen staat los van de jaarruimte."]]],
["Een werknemer bouwt via zijn werkgever een volledig pensioen op. Wat betekent dit in de regel voor zijn jaarruimte?", [["Zijn jaarruimte is beperkt of nihil, omdat de pensioenopbouw (factor A) die verlaagt", "Wie al veel pensioen opbouwt heeft weinig tekort en dus weinig fiscale ruimte voor lijfrente."], ["Zijn jaarruimte is juist extra hoog", "Pensioenopbouw vermindert de jaarruimte, niet andersom."], ["Hij heeft altijd dezelfde jaarruimte als een zelfstandige zonder pensioenopbouw of lijfrente", "De berekening houdt rekening met de opgebouwde pensioenaanspraken."], ["Pensioenopbouw speelt geen rol bij de jaarruimte", "De factor A uit de pensioenregeling is juist een onderdeel van de berekening."]]],
["Wat gebeurt er fiscaal als een klant zijn lijfrentepolis, waarvan de premies zijn afgetrokken, in één keer afkoopt?", [["De afkoopwaarde is belast in box 1, in de regel met daarnaast revisierente", "Afkoop is een afwijking van het lijfrentedoel; de afkoopsom is belast en revisierente compenseert het eerdere voordeel."], ["De afkoopwaarde is onbelast omdat het om eigen geld gaat", "Over de afgetrokken premies is nooit belasting betaald, dus de afkoop is belast."], ["De afkoopwaarde valt in box 3 tegen het forfaitaire rendement, zonder revisierente", "Een lijfrente valt in box 1; afkoop leidt tot belasting in box 1."], ["Afkoop is wettelijk altijd verboden", "Afkoop is mogelijk, maar heeft fiscale gevolgen."]]],
["Hoeveel bedraagt de revisierente bij afkoop van een lijfrente waarvoor premieaftrek is genoten, als geen uitzondering van toepassing is?", [["20% van de afkoopwaarde", "De revisierente bedraagt 20% en komt bovenop de belasting in box 1 over de afkoopwaarde."], ["52% van de afkoopwaarde", "Dit is geen percentage van de revisierente."], ["10% van de afkoopwaarde", "De revisierente is hoger dan 10%."], ["Het volledige afgetrokken premiebedrag", "De revisierente is een percentage over de afkoopwaarde, niet een terugbetaling van de premie."]]],
["Wat is een lijfrentebeleggingsrecht?", [["Een geblokkeerd beleggingsrecht bestemd voor een fiscaal gefacilieerde lijfrente", "Het is de beleggingsvariant van banksparen voor lijfrente, naast de lijfrentespaarrekening en de lijfrenteverzekering."], ["Een recht om lijfrentepremie in box 3 af te trekken", "Lijfrentepremie wordt in box 1 afgetrokken, niet in box 3."], ["Een beleggingsfonds dat verplicht is voor alle werknemers zonder pensioenregeling bij hun werkgever", "Het is een vrijwillig fiscaal product, geen verplichte pensioenregeling."], ["Een lening van de bank om lijfrentepremie te betalen", "Een lening is geen lijfrenteproduct."]]],
["Een zelfstandige zonder pensioenopbouw heeft vorig jaar zijn jaarruimte niet benut. Wat kan hij doen?", [["De onbenutte ruimte onder voorwaarden alsnog benutten via reserveringsruimte", "Met de reserveringsruimte kan onbenutte jaarruimte uit eerdere jaren later worden ingehaald."], ["Niets, onbenutte jaarruimte vervalt direct aan het einde van het kalenderjaar", "Onbenutte jaarruimte kan via de reserveringsruimte later worden benut."], ["De ruimte laten uitbetalen door de Belastingdienst", "Jaarruimte is aftrekruimte, geen tegoed dat wordt uitbetaald."], ["De ruimte overdragen aan zijn kinderen", "Jaarruimte is persoonlijk en niet overdraagbaar."]]],
["Wie is op grond van de Successiewet de belastingplichtige voor de schenkbelasting?", [["De ontvanger van de schenking (verkrijger)", "De Successiewet belast de verkrijging; de ontvanger moet aangifte doen en betalen."], ["Altijd de schenker", "In beginsel is de verkrijger belastingplichtig, niet de schenker."], ["De notaris die de schenking vastlegt", "De notaris is geen belastingplichtige voor de schenkbelasting."], ["De bank waar het geschonken geld naartoe wordt overgemaakt", "Een bank voert alleen de betaling uit."]]],
["Waar hangt de hoogte van het tarief van de schenk- en erfbelasting onder meer van af?", [["Van de verwantschap met de verkrijger en de hoogte van de verkrijging", "De wet kent tariefgroepen naar verwantschap en binnen elke groep een oplopend tarief."], ["Alleen van het belastbaar inkomen van de ontvanger in het jaar van verkrijging", "Het inkomen van de ontvanger speelt geen rol bij het tarief."], ["Alleen van de leeftijd van de schenker of erflater", "De leeftijd van de schenker bepaalt het tarief niet."], ["Van de box 3-categorie waarin het vermogen viel", "Box 3-categorieën hebben geen invloed op de Successiewet."]]],
["Een grootouder schenkt een bedrag aan een kleinkind. Wat geldt in vergelijking met een gelijke schenking aan een kind?", [["Over het belaste deel betalen kleinkinderen een hoger tarief dan kinderen", "Kleinkinderen vallen in een aparte tariefgroep met hogere percentages dan kinderen."], ["Kleinkinderen betalen nooit schenkbelasting", "Ook kleinkinderen kunnen schenkbelasting verschuldigd zijn boven de vrijstelling."], ["Het tarief voor kleinkinderen is gelijk aan dat voor overige verkrijgers", "Kleinkinderen betalen minder dan overige verkrijgers, maar meer dan kinderen."], ["Schenkingen aan kleinkinderen zijn verboden zonder toestemming van de ouders", "Er bestaat geen dergelijk verbod."]]],
["Een vader schenkt zijn dochter een bedrag en overlijdt binnen 180 dagen daarna. Wat is het gevolg voor de Successiewet?", [["De schenking geldt als verkrijging krachtens erfrecht en valt onder de erfbelasting", "Eventueel betaalde schenkbelasting wordt dan verrekend met de erfbelasting."], ["De schenking wordt teruggedraaid en het geld valt terug in de nalatenschap", "De fictie werkt fiscaal; de schenking zelf wordt niet civielrechtelijk ongedaan gemaakt."], ["Er is dan zowel schenk- als erfbelasting verschuldigd, zonder enige verrekening tussen beide", "Dubbele heffing wordt voorkomen doordat schenkbelasting wordt verrekend."], ["De schenking is dan altijd vrijgesteld", "De fictie leidt niet tot een vrijstelling, maar tot heffing van erfbelasting."]]],
["Wat houdt de wettelijke verdeling bij overlijden zonder testament in op hoofdlijnen, als de overledene een echtgenoot en kinderen achterlaat?", [["De echtgenoot krijgt alle goederen, de kinderen een geldvordering ter hoogte van hun erfdeel", "De vordering is in de regel pas opeisbaar bij overlijden of faillissement van de langstlevende."], ["De kinderen krijgen direct de helft van alle goederen in eigendom, de echtgenoot de andere helft", "Bij de wettelijke verdeling krijgen kinderen geen goederen, maar een vordering."], ["De echtgenoot erft niets als er kinderen zijn", "De echtgenoot is erfgenaam naast de kinderen en krijgt de goederen."], ["De nalatenschap gaat naar de Staat", "De Staat erft alleen als er geen erfgenamen tot en met de zesde graad zijn."]]],
["Wat is de legitieme portie?", [["Het minimumdeel waarop een kind ook na onterving aanspraak kan maken", "De legitieme is een geldvordering op de erfgenamen ter hoogte van de helft van het erfdeel bij versterf."], ["Het deel van de nalatenschap dat aan de Staat toekomt", "De Staat heeft geen legitieme portie."], ["De vrijstelling voor erfbelasting van de partner", "Een fiscale vrijstelling is iets anders dan het civielrechtelijke recht op de legitieme."], ["Het deel van de nalatenschap dat aan de notaris toekomt voor de afwikkeling", "De notaris heeft recht op zijn honorarium, niet op een portie."]]],
["Binnen welke termijn na het overlijden moet in beginsel aangifte erfbelasting worden gedaan?", [["Binnen acht maanden", "De wettelijke termijn is acht maanden na het overlijden; uitstel kan worden aangevraagd."], ["Binnen drie maanden", "Drie maanden is te kort; de wet noemt acht maanden."], ["Binnen twee jaar", "Twee jaar is veel langer dan de wettelijke termijn."], ["Er geldt geen termijn", "Er geldt wel degelijk een termijn van acht maanden."]]],
["Een Nederlander emigreert naar het buitenland en overlijdt vijf jaar later. Wat geldt in beginsel voor de Nederlandse erfbelasting?", [["Hij geldt nog als inwoner, omdat de woonplaatsfictie voor Nederlanders tien jaar na vertrek geldt", "Door deze fictie kan Nederland erfbelasting heffen; verdragen en regels ter voorkoming van dubbele belasting kunnen dat beperken."], ["Nederland heft geen erfbelasting zodra iemand is geëmigreerd", "Voor Nederlanders geldt na emigratie nog tien jaar een woonplaatsfictie."], ["Nederland heft alleen erfbelasting als de erfgenamen op het moment van overlijden in Nederland wonen", "Het aanknopingspunt is de (fictieve) woonplaats van de erflater, niet van de erfgenamen."], ["De woonplaatsfictie geldt slechts één jaar", "Voor Nederlanders geldt de fictie voor erfbelasting tien jaar."]]],
["In welke drie categorieën deelt een beleggingsonderneming haar cliënten onder MiFID II in?", [["Niet-professioneel, professioneel en in aanmerking komende tegenpartij", "De indeling bepaalt het beschermingsniveau: hoe professioneler de cliënt, hoe minder gedragsregels gelden."], ["Particuliere, zakelijke en institutionele cliënt, afhankelijk van de rechtsvorm", "Dit zijn geen MiFID II-categorieën, al lijken ze er op."], ["Starter, gevorderde en ervaren belegger", "Kennis en ervaring tellen mee in de geschiktheidstoets, maar zijn geen klantcategorieën."], ["Defensieve, neutrale en offensieve cliënt", "Dit zijn mogelijke risicoprofielen, geen klantclassificatie."]]],
["Welke cliëntcategorie krijgt onder MiFID II de meeste bescherming?", [["De niet-professionele cliënt", "Voor niet-professionele cliënten gelden de uitgebreidste informatie-, zorg- en onderzoeksverplichtingen."], ["De professionele cliënt", "Van een professionele cliënt wordt meer kennis verwacht; er gelden minder beschermende regels."], ["De in aanmerking komende tegenpartij", "Deze categorie, zoals banken en verzekeraars, krijgt juist de minste bescherming."], ["Alle categorieën krijgen precies dezelfde bescherming", "Het doel van de indeling is juist om bescherming te differentiëren."]]],
["Een vermogende particuliere cliënt vraagt om als professionele cliënt te worden behandeld. Wat geldt?", [["Dat kan, mits hij aan de criteria voldoet en gewaarschuwd is voor minder bescherming", "De onderneming moet beoordelen of de cliënt voldoende deskundig en ervaren is en vastleggen dat hij de gevolgen kent."], ["Dat kan altijd zonder nadere toets, omdat de cliënt dat zelf wil", "De onderneming moet toetsen of aan de criteria is voldaan; een verzoek alleen is niet genoeg."], ["Dat kan nooit, een particulier blijft altijd een niet-professionele cliënt, ongeacht zijn vermogen", "Een particulier kan onder voorwaarden op verzoek als professioneel worden behandeld."], ["Dat kan alleen met voorafgaande toestemming van de AFM per cliënt", "De AFM geeft geen toestemming per cliënt; de onderneming beoordeelt zelf."]]],
["Welke informatie moet een beleggingsonderneming onder MiFID II inwinnen voor de geschiktheidstoets bij beleggingsadvies?", [["Kennis en ervaring, financiële situatie, doelstellingen en risicotolerantie, en duurzaamheidsvoorkeur", "Alleen met deze informatie kan worden beoordeeld of een aanbevolen belegging geschikt is voor de cliënt."], ["Alleen kennis en ervaring met de betreffende soort financiële instrumenten, zoals bij de passendheidstoets", "Dat is de passendheidstoets; voor advies is een volledige geschiktheidstoets nodig."], ["Alleen het gewenste rendement, de looptijd en de hoogte van de inleg", "Doelen zijn één onderdeel, maar financiële situatie en kennis en ervaring horen er ook bij."], ["Alleen de identiteit, het BSN en het adres van de cliënt", "Identificatie hoort bij het Wwft-cliëntenonderzoek, niet bij de geschiktheidstoets."]]],
["Wat is het verschil tussen de geschiktheidstoets en de passendheidstoets onder MiFID II?", [["Geschiktheid (bij advies en beheer) is breder; passendheid (zonder advies) toetst kennis en ervaring", "Bij passendheid gaat het om de vraag of de cliënt de risico's van het product begrijpt, niet of het past bij zijn doelen en financiële situatie."], ["Er is geen verschil, het zijn twee namen voor één en dezelfde toets", "Het zijn twee verschillende toetsen met een eigen reikwijdte."], ["De passendheidstoets is breder en geldt juist bij advies en vermogensbeheer", "Bij vermogensbeheer geldt juist de geschiktheidstoets."], ["De geschiktheidstoets geldt alleen voor professionele cliënten, de passendheidstoets voor alle overige cliënten", "De geschiktheidstoets geldt juist voor alle cliënten, met de uitgebreidste invulling bij niet-professionele cliënten."]]],
["Onder welke voorwaarden mag een beleggingsonderneming orders uitvoeren op basis van execution only, zonder passendheidstoets?", [["Op initiatief van de cliënt, in niet-complexe instrumenten, na waarschuwing dat niet wordt getoetst", "Execution only is alleen toegestaan als aan al deze voorwaarden is voldaan."], ["De cliënt heeft een belegbaar vermogen boven een wettelijk bepaald bedrag en ruime beleggingservaring", "De hoogte van het vermogen is geen voorwaarde voor execution only."], ["Het gaat om complexe instrumenten zoals turbo's en opties", "Complexe instrumenten zijn juist uitgesloten van execution only."], ["De cliënt tekent een verklaring dat hij afziet van alle informatie", "De cliënt kan niet afzien van de informatieverplichtingen; het gaat om initiatief, product en waarschuwing."]]],
["Een klant wil via zijn online beleggingsrekening zelf turbo's kopen, zonder advies. Wat moet de beleggingsonderneming doen?", [["Een passendheidstoets doen en de klant waarschuwen als het product niet passend is", "Turbo's zijn complexe instrumenten; execution only zonder passendheidstoets is daarvoor niet toegestaan."], ["De order direct uitvoeren zonder toets, omdat er geen advies wordt gegeven", "Bij complexe instrumenten is een passendheidstoets verplicht, ook zonder advies."], ["Een volledige geschiktheidstoets inclusief duurzaamheidsvoorkeuren uitvoeren voor de order", "De geschiktheidstoets hoort bij advies en vermogensbeheer, niet bij een zelf geplaatste order."], ["De order weigeren, omdat particulieren nooit turbo's mogen kopen", "Er geldt geen absoluut verbod; de onderneming moet de passendheid toetsen en zo nodig waarschuwen."]]],
["Wanneer moet een niet-professionele cliënt onder MiFID II een geschiktheidsverklaring ontvangen?", [["Voordat de geadviseerde transactie wordt uitgevoerd", "De verklaring legt uit waarom het advies past bij de cliënt en moet in beginsel vóór de transactie worden verstrekt."], ["Alleen als de cliënt erom vraagt", "Het verstrekken is een verplichting, niet afhankelijk van een verzoek."], ["Pas bij het jaarlijkse kostenoverzicht", "Het jaaroverzicht gaat over kosten achteraf, niet over de geschiktheid van een advies."], ["Uitsluitend bij execution only-transacties in complexe producten", "Bij execution only wordt juist geen advies gegeven en geen geschiktheid beoordeeld."]]],
["Welke kosteninformatie moet een beleggingsonderneming onder MiFID II aan cliënten verstrekken?", [["Vooraf de verwachte en achteraf, minstens jaarlijks, de werkelijke kosten, met het effect op rendement", "De cliënt moet zien wat de dienst en de producten samen kosten en hoeveel dat van het rendement afhaalt."], ["Alleen de transactiekosten per order, direct na uitvoering van de order", "Ook dienst- en productkosten moeten worden vermeld, niet alleen transactiekosten."], ["Alleen een kostenoverzicht als de cliënt daarom vraagt of een klacht indient", "Kostentransparantie is een vaste verplichting, los van klachten."], ["Alleen de lopende kosten van het fonds vooraf, niet de kosten van de dienstverlening of de transacties", "Juist de optelsom van dienst- en productkosten moet inzichtelijk zijn."]]],
["Een vermogensbeheerder beheert de portefeuille van een niet-professionele cliënt. De totale waarde daalt met 10% ten opzichte van het begin van de rapportageperiode. Wat moet de vermogensbeheerder doen?", [["De cliënt uiterlijk aan het einde van die werkdag informeren", "MiFID II verplicht de beheerder te melden bij een daling van 10% en bij elk volgend veelvoud van 10%."], ["Niets, de daling wordt pas in het periodieke overzicht vermeld", "Er geldt juist een directe meldplicht bij een daling van 10%."], ["De portefeuille onmiddellijk volledig omzetten in liquiditeiten", "De regel verplicht tot informeren, niet tot verkopen."], ["De AFM dezelfde dag over het verlies inlichten", "De meldplicht geldt richting de cliënt, niet richting de toezichthouder."]]],
["Wat geldt in Nederland voor provisie bij beleggingsdienstverlening aan niet-professionele cliënten?", [["In beginsel een verbod op het ontvangen en betalen van provisie van of aan derden", "Nederland kent sinds 2014 een provisieverbod voor beleggingsdienstverlening, strenger dan de Europese minimumregels."], ["Provisie is onbeperkt toegestaan, mits het bedrag vooraf aan de cliënt wordt genoemd", "Nederland gaat verder dan transparantie en verbiedt deze vergoedingen in beginsel."], ["Provisie is alleen verboden bij execution only, niet bij advies of beheer", "Het verbod geldt voor beleggingsdienstverlening breed, niet alleen voor execution only."], ["Er gelden voor beleggingsdienstverlening geen regels over provisie", "Er geldt juist een provisieverbod."]]],
["Een adviseur wil klanten adviseren over de aankoop van individuele aandelen en obligaties. Welke vergunning is daarvoor in beginsel nodig?", [["Een vergunning als beleggingsonderneming van de AFM", "Beleggingsadvies over financiële instrumenten is een beleggingsdienst onder MiFID II, waarvoor een vergunning als beleggingsonderneming nodig is."], ["Een vergunning van DNB als bank", "Een bankvergunning is niet nodig voor het geven van beleggingsadvies."], ["Geen vergunning, zolang de adviseur geen geld van klanten aanhoudt", "Ook zonder het aanhouden van klantgelden is beleggingsadvies vergunningplichtig."], ["Alleen een inschrijving bij de Kamer van Koophandel", "Een KvK-inschrijving is geen toezichtvergunning."]]],
["Wat houdt productgovernance (productontwikkeling en -distributie) onder MiFID II in?", [["Ontwikkelaar en distributeur bepalen een doelgroep en richten de verkoop daarop", "Zo moet worden voorkomen dat producten terechtkomen bij cliënten voor wie ze niet bedoeld zijn."], ["De AFM keurt elk beleggingsproduct goed voordat het wordt verkocht", "De AFM keurt producten niet vooraf goed; de verantwoordelijkheid ligt bij ontwikkelaar en distributeur."], ["Alleen de ontwikkelaar is verantwoordelijk voor het product, de distributeur nooit", "Ook de distributeur heeft eigen verplichtingen bij doelgroepbepaling en distributie."], ["Beleggingsproducten mogen alleen aan professionele cliënten worden verkocht", "Productgovernance regelt doelgroepen, maar sluit niet-professionele cliënten niet uit."]]],
["Wanneer mag een beleggingsonderneming haar advies onder MiFID II 'onafhankelijk' noemen?", [["Als zij een breed aanbod van aanbieders beoordeelt en geen vergoedingen van derden behoudt", "Onafhankelijk advies is niet beperkt tot eigen of gelieerde producten en vrij van inducements."], ["Als zij alleen eigen producten adviseert en daarover volledig transparant is", "Advies dat beperkt is tot eigen producten is juist niet onafhankelijk."], ["Als de cliënt een vaste fee per jaar betaalt, ongeacht hoe breed het beoordeelde productaanbod is", "Een fee alleen is niet genoeg; ook een breed aanbod is vereist."], ["Als zij naast de AFM-vergunning ook een vergunning van DNB heeft", "Een DNB-vergunning zegt niets over de onafhankelijkheid van het advies."]]],
["Wie is verantwoordelijk voor het opstellen van het essentiële-informatiedocument (EID) onder PRIIPs?", [["De ontwikkelaar van het product", "De ontwikkelaar stelt het EID op en publiceert het; de verkoper of adviseur verstrekt het aan de belegger."], ["De adviseur die het product aanbeveelt", "De adviseur moet het EID verstrekken, maar stelt het niet op."], ["De AFM", "De AFM houdt toezicht, maar stelt geen EID's op."], ["De klant zelf", "De klant ontvangt het EID; hij stelt het niet op."]]],
["Wat geeft de samenvattende risico-indicator (SRI) in het EID weer?", [["Een risicoklasse van 1 (laag) tot 7 (hoog) op basis van markt- en kredietrisico", "Met de SRI kunnen beleggers het risico van verschillende producten in één oogopslag vergelijken."], ["Het gegarandeerde minimale rendement over de looptijd", "De SRI is een risicoklasse, geen rendementsgarantie."], ["Een score van 1 tot 10 voor de duurzaamheid van het product, gebaseerd op de SFDR-indeling", "Duurzaamheid wordt niet in de SRI uitgedrukt."], ["De totale kosten van het product in euro's per jaar", "Kosten staan in een apart onderdeel van het EID."]]],
["Voor welk product hoeft onder PRIIPs geen EID te worden opgesteld?", [["Een rechtstreeks gekocht beursgenoteerd aandeel", "Een aandeel is geen verpakt product; PRIIPs geldt voor verpakte beleggingsproducten en verzekeringen met beleggingscomponent."], ["Een beleggingsverzekering", "Een beleggingsverzekering is juist een verzekeringsproduct met beleggingscomponent onder PRIIPs."], ["Een gestructureerd product met kapitaalbescherming", "Gestructureerde producten zijn verpakte producten en vallen onder PRIIPs."], ["Een participatie in een beleggingsfonds", "Beleggingsfondsen vallen onder PRIIPs; ook icbe's verstrekken sinds 2023 een EID."]]],
["Wanneer moet een niet-professionele belegger het EID ontvangen?", [["Tijdig voordat hij door een overeenkomst gebonden is", "De belegger moet de informatie kunnen gebruiken bij zijn beslissing, dus vóór de aankoop."], ["Binnen een maand na de aankoop", "Ontvangst achteraf heeft geen zin voor de beslissing; het EID moet vooraf worden verstrekt."], ["Alleen als hij er schriftelijk om vraagt", "Het verstrekken van het EID is een verplichting, ook zonder verzoek."], ["Pas bij de eerste jaarlijkse rapportage over de portefeuille", "De jaarlijkse rapportage komt na de aankoop; het EID gaat ervoor."]]],
["Wat is de functie van de prestatiescenario's in een EID?", [["Tonen wat de belegger bij verschillende marktomstandigheden kan terugkrijgen", "De scenario's (zoals stress, ongunstig, gematigd en gunstig) geven een beeld van de bandbreedte van mogelijke uitkomsten."], ["Het gegarandeerde eindbedrag van het product vastleggen", "Prestatiescenario's zijn geen toezegging of garantie."], ["Het historische rendement van de adviseur en het fonds over de afgelopen vijf jaar tonen", "Het EID gaat over het product, niet over de adviseur."], ["De persoonlijke fiscale gevolgen in box 3 berekenen", "Het EID bevat geen persoonlijke fiscale berekening."]]],
["Welk type product wordt onder de SFDR aangeduid als een artikel 9-product?", [["Een product met duurzame beleggingen als doelstelling", "Artikel 9-producten worden in de praktijk 'donkergroen' genoemd."], ["Een product dat ecologische of sociale kenmerken promoot, zonder duurzame beleggingsdoelstelling", "Dat is een artikel 8-product ('lichtgroen')."], ["Elk product zonder enige duurzaamheidsinformatie", "Ook producten zonder duurzaamheidsfocus moeten op grond van de SFDR informatie geven over duurzaamheidsrisico's."], ["Een product dat uitsluitend in staatsobligaties belegt", "Het type belegging bepaalt niet of iets een artikel 9-product is."]]],
["Wat kenmerkt een artikel 8-product onder de SFDR?", [["Het promoot ecologische of sociale kenmerken, mits de ondernemingen goed bestuur hebben", "Een artikel 8-product hoeft geen duurzame belegging als doel te hebben, maar moet die kenmerken wel toelichten."], ["Het heeft duurzame beleggingen als uitdrukkelijke en enige doelstelling, zoals een impactfonds", "Dat is de omschrijving van een artikel 9-product."], ["Het is door de AFM vooraf als duurzaam product gecertificeerd", "De SFDR is een openbaarmakingsregime; de AFM certificeert geen producten."], ["Het belegt verplicht volledig in taxonomie-conforme activiteiten", "Een artikel 8-product hoeft niet volledig taxonomie-conform te beleggen."]]],
["Sinds 2 augustus 2022 moet een adviseur bij beleggingsadvies naar de duurzaamheidsvoorkeuren van de klant vragen. Welke vormen van voorkeur onderscheiden de regels?", [["Minimumaandeel taxonomie-conform, minimumaandeel duurzaam (SFDR), of meewegen van ongunstige effecten", "De klant kan een of meer van deze voorkeuren aangeven, of aangeven dat hij geen voorkeur heeft."], ["Alleen een voorkeur voor of tegen beleggingen in fossiele brandstoffen", "De regels werken met drie omschreven categorieën, niet met één sectorvraag."], ["Een voorkeur voor fondsen met een groen, geel of rood duurzaamheidslabel van de AFM of de fondsbeheerder", "Een kleurindeling is geen wettelijke categorie van duurzaamheidsvoorkeuren."], ["Alleen de keuze tussen artikel 6-, artikel 8- en artikel 9-producten", "De voorkeuren zijn anders gedefinieerd en niet beperkt tot deze productindeling."]]],
["In welke volgorde beoordeelt een adviseur volgens de ESMA-richtsnoeren de geschiktheid en de duurzaamheidsvoorkeuren?", [["Eerst de geschiktheid op de gewone criteria, daarna pas de duurzaamheidsvoorkeuren", "Duurzaamheidsvoorkeuren mogen niet zwaarder wegen dan de overige geschiktheidscriteria."], ["Eerst de duurzaamheidsvoorkeuren, en alleen als er tijd over is de overige geschiktheidscriteria", "De overige geschiktheidscriteria gaan voor en zijn altijd verplicht."], ["Alleen de duurzaamheidsvoorkeuren, omdat die de andere criteria vervangen", "Duurzaamheid is een aanvulling op en geen vervanging van de geschiktheidstoets."], ["De volgorde is vrij, zolang de klant tekent", "ESMA geeft juist aan dat de traditionele criteria eerst worden beoordeeld."]]],
["Een klant heeft een duidelijke duurzaamheidsvoorkeur, maar geen enkel product in het aanbod van de adviseur voldoet daaraan. Wat is juist?", [["Niets aanbevelen als passend bij de voorkeur; de klant mag die aanpassen, wat wordt vastgelegd", "Een aanpassing van de voorkeur moet een keuze van de klant zijn en in de geschiktheidsverklaring worden toegelicht."], ["De adviseur mag een willekeurig product aanbevelen en de voorkeur negeren", "Duurzaamheidsvoorkeuren maken deel uit van de geschiktheidstoets en mogen niet worden genegeerd."], ["De adviseur moet de klant voor een productkeuze doorverwijzen naar de AFM", "De AFM geeft geen individueel advies."], ["De adviseur mag het product als duurzaam presenteren als het bijna voldoet", "Dat is misleidend en in strijd met de eis van correcte, duidelijke en niet-misleidende informatie."]]],
["Wat wordt in de SFDR bedoeld met de 'belangrijkste ongunstige effecten' (principal adverse impacts)?", [["De negatieve gevolgen van beleggingen voor milieu, sociale omstandigheden en mensenrechten", "Het gaat om de impact van de belegging op de buitenwereld, niet om het effect van duurzaamheid op het rendement."], ["De negatieve invloed van klimaat- en duurzaamheidsrisico's op het rendement van een belegging", "Dat is een duurzaamheidsrisico; de belangrijkste ongunstige effecten gaan juist over impact naar buiten."], ["De hoogste kostenposten van een duurzaam beleggingsfonds", "Kosten zijn geen duurzaamheidseffecten."], ["De grootste koersdalingen van duurzame fondsen in het afgelopen jaar", "Koersdalingen zijn marktrisico, geen ongunstige duurzaamheidseffecten."]]],
["Wat is het verschil tussen risicobereidheid en risicodraagvermogen in een beleggersprofiel?", [["Bereidheid is wat de klant aan risico wil, draagvermogen wat hij aan verlies kan opvangen", "Beide moeten worden vastgesteld; het profiel mag niet meer risico bevatten dan de klant financieel kan dragen."], ["Risicobereidheid gaat over kosten, risicodraagvermogen over rendement", "Beide begrippen gaan over risico, niet over kosten of rendement."], ["Het zijn twee woorden voor precies hetzelfde begrip", "Het verschil tussen willen en kunnen is juist wezenlijk voor passend advies."], ["Risicodraagvermogen is alleen relevant voor professionele cliënten en niet voor particulieren", "Ook en juist bij particulieren moet het verliesdragend vermogen worden vastgesteld."]]],
["Een klant zegt veel risico te willen lopen, maar het te beleggen bedrag is vrijwel zijn hele vermogen en hij heeft het over twee jaar nodig voor een verbouwing. Wat is passend?", [["Uitgaan van het beperkte draagvermogen en een defensief profiel adviseren", "Als bereidheid en draagvermogen uiteenlopen, is het lagere draagvermogen bepalend voor passend advies."], ["De risicobereidheid volgen en een offensief profiel adviseren, omdat de klant dat zelf wil", "Een adviseur mag niet blind de voorkeur volgen als de klant het risico financieel niet kan dragen."], ["Adviseren om met geleend geld extra te beleggen", "Dat vergroot het risico juist verder en is niet passend."], ["Geen profiel vaststellen, omdat de horizon kort is", "Ook bij een korte horizon moet een beleggersprofiel worden vastgesteld."]]],
["Een klant wil advies over beleggen, maar weigert informatie te geven over zijn inkomen, vermogen en schulden. Wat moet de adviseur doen?", [["Geen beleggingsadvies geven, omdat zonder deze informatie geschiktheid niet te beoordelen is", "Zonder voldoende klantinformatie kan geen geschiktheidstoets worden uitgevoerd en mag niet worden geadviseerd."], ["Een standaardportefeuille adviseren met gemiddeld risico", "Een gemiddeld profiel aannemen is geen vervanging voor de verplichte klantinformatie."], ["Het advies geven en de weigering in het dossier vermelden", "Vastleggen van de weigering maakt een advies zonder basis niet toelaatbaar."], ["De informatie zelf schatten op basis van de woonplaats en de leeftijd van de klant en dat vastleggen", "Schattingen zonder gegevens van de klant voldoen niet aan de informatieplicht."]]],
["Waarom vraagt een adviseur bij een beleggingsadvies naar de kennis en ervaring van de klant?", [["Om te beoordelen of de klant de risico's van de beleggingen begrijpt", "Een product kan financieel passen, maar ongeschikt zijn als de klant de werking en risico's niet begrijpt."], ["Om het tarief van de adviseur te bepalen", "De vergoeding hangt niet af van de kennis van de klant."], ["Om te bepalen of de klant onder de Wwft valt", "De Wwft-plicht hangt niet af van beleggingskennis."], ["Omdat ervaren klanten geen advies meer nodig hebben en execution only krijgen", "Ook ervaren klanten hebben recht op passend advies; kennis is één van de factoren."]]],
["Een klant heeft een doorlopend krediet met een hoge rente en wil zijn spaargeld beleggen in een aandelenfonds. Wat ligt het meest voor de hand als passend advies?", [["Eerst bespreken of het aflossen van de dure lening verstandiger is dan beleggen", "Aflossen levert een zeker voordeel ter hoogte van de rente op, terwijl het rendement op aandelen onzeker is."], ["Het spaargeld volledig beleggen, omdat aandelen altijd meer opleveren dan de kredietrente", "Een hoger rendement op aandelen is niet zeker en vaak niet hoger dan de rente op duur krediet."], ["Extra krediet opnemen om meer te kunnen beleggen", "Dit vergroot de schuldenlast en het risico en is niet passend."], ["De lening buiten beschouwing laten, omdat die niets met beleggen te maken heeft", "Schulden horen bij de financiële situatie en zijn juist relevant voor passend advies."]]],
["Een klant besluit, tegen het advies in, een veel risicovollere belegging te kiezen dan geadviseerd. Wat moet de adviseur in elk geval doen?", [["De klant wijzen op de risico's en de afwijking van het advies vastleggen", "Zo is duidelijk dat de klant geïnformeerd heeft gekozen en dat het advies passend was."], ["Het advies aanpassen zodat het aansluit bij de keuze van de klant", "Het advies achteraf aanpassen aan de keuze is misleidend en niet zorgvuldig."], ["De keuze negeren en niets vastleggen, omdat de klant daar zelf verantwoordelijk voor is", "De zorgplicht vraagt de adviseur de klant actief te waarschuwen en dit vast te leggen."], ["De klant melden bij de AFM", "Een afwijkende keuze van een klant is geen reden voor een melding bij de AFM."]]],
["Een klant met een defensief beleggersprofiel heeft als doel zijn vermogen vooral te behouden. Wat is in strijd met passend advies?", [["Een sterk geconcentreerde belegging in één volatiele opkomende markt adviseren", "Dit risico past niet bij het doel van kapitaalbehoud en een defensief profiel."], ["Een gespreide portefeuille met een groot deel kortlopende obligaties adviseren", "Dit past goed bij een defensief profiel."], ["Een deel van het vermogen op een spaarrekening laten staan", "Sparen kan passend zijn bij een doel van vermogensbehoud."], ["Het profiel periodiek met de klant actualiseren", "Periodieke actualisering is juist zorgvuldig."]]],
["Een nieuwe klant blijkt een politiek prominent persoon (PEP) te zijn. Wat moet de instelling onder de Wwft in elk geval doen?", [["Verscherpt cliëntenonderzoek doen, inclusief de bron van vermogen en middelen", "Bij een PEP is daarnaast goedkeuring van het hoger leidinggevend personeel voor de zakelijke relatie vereist."], ["De klant weigeren, omdat een PEP geen klant mag worden", "PEP's mogen klant zijn; er geldt alleen een strenger onderzoek."], ["Volstaan met vereenvoudigd cliëntenonderzoek vanwege de publieke functie van de klant", "Bij een PEP geldt juist een hoger risico en dus verscherpt onderzoek."], ["Alleen een kopie van het paspoort maken en bewaren", "Identificatie is een begin, maar bij een PEP is veel meer onderzoek nodig."]]],
["Een Wwft-instelling meldt een ongebruikelijke transactie van een klant. Mag zij de klant daarover informeren?", [["Nee, de instelling mag de klant niet laten weten dat er is gemeld", "De Wwft kent een geheimhoudingsplicht om te voorkomen dat een onderzoek wordt gefrustreerd."], ["Ja, de klant moet altijd vooraf worden geïnformeerd over de melding bij de FIU", "Vooraf informeren zou de melding en een eventueel onderzoek ondermijnen."], ["Ja, mits de klant schriftelijk toestemming geeft", "Toestemming van de klant heft de geheimhoudingsplicht niet op."], ["Ja, maar pas na een jaar", "Er is geen termijn waarna de klant wel mag worden ingelicht."]]],
["Een instelling kan het cliëntenonderzoek bij een nieuwe klant niet afronden, omdat de klant de herkomst van zijn vermogen niet wil toelichten. Wat geldt onder de Wwft?", [["De instelling mag geen zakelijke relatie aangaan en geen transactie uitvoeren", "Als het cliëntenonderzoek niet tot het beoogde resultaat leidt, moet de instelling afzien van de dienstverlening en beoordelen of een melding nodig is."], ["De instelling mag doorgaan als de klant een verklaring tekent over de herkomst van zijn geld", "Een verklaring vervangt het verplichte cliëntenonderzoek niet."], ["De instelling mag de klant alleen bedienen via execution only", "De Wwft maakt geen uitzondering voor execution only."], ["De instelling moet de klant een boete opleggen", "Een instelling legt geen boetes op; zij moet afzien van de relatie."]]],
["Wie is onder de Wwft de uiteindelijk belanghebbende (UBO) van een klant die een rechtspersoon is?", [["De natuurlijke persoon met de uiteindelijke eigendom of zeggenschap", "De instelling moet de UBO identificeren en redelijke maatregelen nemen om diens identiteit te verifiëren."], ["De rechtspersoon zelf, als contractspartij", "De UBO is altijd een natuurlijke persoon achter de rechtspersoon."], ["De bank waar de rechtspersoon zijn rekening heeft", "Een bank is geen UBO van haar klanten."], ["De notaris die de oprichtingsakte van de rechtspersoon heeft verleden", "De notaris heeft geen eigendom of zeggenschap en is geen UBO."]]],
["Wat dekt het beleggerscompensatiestelsel (BCS)?", [["Geld of effecten die een failliete instelling niet kan teruggeven, tot € 20.000", "Het stelsel beschermt tegen het onvermogen van de instelling, niet tegen beleggingsrisico."], ["Koersverliezen op beleggingen van particulieren tot € 20.000 per persoon per jaar", "Koersverliezen zijn beleggingsrisico en vallen niet onder het BCS."], ["Spaartegoeden bij een failliete bank tot € 100.000 per persoon", "Spaartegoeden vallen onder het depositogarantiestelsel."], ["Schade door ondeugdelijk beleggingsadvies tot € 20.000 per persoon", "Schade door advies is een kwestie van aansprakelijkheid of klachtprocedure, niet van het BCS."]]],
["Een belegger lijdt in een jaar een verlies van € 15.000 omdat de aandelenkoersen sterk zijn gedaald. Zijn beleggingsonderneming is gezond. Kan hij een beroep doen op het beleggerscompensatiestelsel?", [["Nee, koersverliezen vallen niet onder het stelsel", "Zolang de instelling haar verplichtingen nakomt, is er geen grond voor compensatie."], ["Ja, omdat het verlies onder de € 20.000 blijft", "Het bedrag is niet bepalend; koersverlies valt simpelweg buiten de dekking."], ["Ja, maar alleen voor de helft van het geleden verlies", "Er bestaat geen gedeeltelijke vergoeding van koersverliezen."], ["Alleen als hij als professionele cliënt is ingedeeld", "Professionele status geeft geen recht op vergoeding van koersverlies."]]],
["Waarom zijn effecten van beleggers bij een faillissement van hun bank of beleggingsonderneming in de regel beschermd, ook boven het maximum van het beleggerscompensatiestelsel?", [["Effecten worden afgescheiden bewaard en vallen buiten de faillissementsboedel", "Door deze afscheiding kunnen beleggers hun effecten in de regel terugkrijgen; het BCS is een vangnet als dat toch misgaat."], ["De Staat garandeert alle effecten zonder maximum", "Er bestaat geen onbeperkte staatsgarantie op effecten."], ["Effecten vallen onder het depositogarantiestelsel tot € 100.000", "Het DGS dekt alleen geldtegoeden, geen effecten."], ["De AFM koopt de effecten bij een faillissement van de instelling terug tegen de laatste koers", "De AFM heeft geen rol bij het terugkopen van effecten."]]]
],
"hypothecair-krediet":[
["Aan welke twee maatstaven toetst de kredietgever op grond van de Tijdelijke regeling hypothecair krediet (TRHK) de maximale hypotheek?", [["De financieringslast ten opzichte van het toetsinkomen en de verhouding lening/woningwaarde (LTV)", "De TRHK begrenst de hypotheek zowel op basis van de lasten die de consument kan dragen als op basis van de waarde van de woning."], ["Het netto besteedbaar inkomen na belasting en het totale vermogen van de consument", "De TRHK werkt met een bruto toetsinkomen en financieringslastpercentages, niet met netto inkomen of vermogen."], ["De WOZ-waarde van de woning en het aantal jaren dat de consument al onafgebroken in loondienst werkt", "De WOZ-waarde is geen hoofdmaatstaf en het dienstverband is geen wettelijke leennorm; die zijn hooguit relevant voor acceptatie."], ["De koopsom van de woning en de hoogte van de NHG-kostengrens", "De koopsom en de NHG-grens bepalen niet de wettelijke leennormen; de TRHK kijkt naar lasten en woningwaarde."]]],
["Een klant kiest voor een rentevaste periode van 20 jaar. Met welke rente wordt de financieringslast volgens de TRHK berekend?", [["Met de werkelijke debetrentevoet die voor die rentevaste periode in de offerte staat", "Bij een rentevaste periode van tien jaar of langer is het renterisico beperkt en wordt getoetst op de werkelijke rente."], ["Met de door de AFM vastgestelde toetsrente, ongeacht de rentevaste periode", "De AFM-toetsrente is alleen bepalend bij een rentevaste periode korter dan tien jaar."], ["Met de gemiddelde rente van de afgelopen vijf jaar voor die rentevaste periode bij deze kredietgever", "Een historisch gemiddelde speelt geen rol in de toets; het gaat om de rente van deze lening."], ["Met de werkelijke rente verhoogd met een vaste opslag van twee procentpunt", "De TRHK kent geen vaste opslag op de werkelijke rente bij lange rentevaste perioden."]]],
["Een klant kiest een rentevaste periode van 5 jaar. De rente in de offerte is hoger dan de actuele AFM-toetsrente. Met welke rente wordt getoetst?", [["Met de offerterente, omdat bij korte rentevastperioden de hoogste van beide geldt", "Bij een rentevaste periode korter dan tien jaar geldt de hoogste van de werkelijke rente en de toetsrente; hier is dat de offerterente."], ["Met de AFM-toetsrente, omdat die bij rentevastperioden korter dan tien jaar altijd geldt", "De toetsrente is een ondergrens; ligt de werkelijke rente hoger, dan wordt met de werkelijke rente gerekend."], ["Met het gemiddelde van de offerterente en de AFM-toetsrente", "Middelen van beide rentes is niet de systematiek; de hoogste van de twee geldt."], ["Met de laagste van beide, omdat de klant daar recht op heeft", "De toets is bedoeld om renterisico op te vangen; daarom geldt juist de hoogste, niet de laagste rente."]]],
["Een deel van de gevraagde hypotheek is aflossingsvrij. Hoe wordt dit deel volgens de TRHK in beginsel meegenomen in de financieringslast?", [["Alsof het annuïtair in dertig jaar wordt afgelost", "De financieringslast wordt berekend op basis van een annuïtaire aflossing over dertig jaar, ook voor delen zonder aflossingsverplichting."], ["Alleen met de werkelijk te betalen rente, zonder aflossingscomponent", "Rekenen met alleen rente zou een te hoge leencapaciteit geven; de TRHK gaat uit van een annuïtaire last."], ["Helemaal niet, omdat er tijdens de looptijd niet op wordt afgelost", "Ook een aflossingsvrij deel brengt lasten mee en telt dus mee in de toets."], ["Alsof het lineair in twintig jaar wordt afgelost", "De TRHK rekent niet met een lineaire aflossing in twintig jaar maar met een annuïteit over dertig jaar."]]],
["Welke organisatie adviseert jaarlijks over de financieringslastpercentages die in de TRHK worden opgenomen?", [["Het Nibud", "Het Nibud berekent op basis van uitgavenpatronen welk deel van het inkomen verantwoord aan woonlasten kan worden besteed; de minister stelt de percentages vervolgens vast."], ["De Nederlandsche Bank", "DNB houdt prudentieel toezicht en stelt de financieringslastpercentages niet voor."], ["Het Kifid", "Het Kifid behandelt klachten en geschillen en adviseert niet over leennormen."], ["De Stichting Waarborgfonds Eigen Woningen", "De Stichting WEW beheert de NHG; zij stelt de wettelijke financieringslastpercentages niet voor."]]],
["Waarom rekent de TRHK met bruto woonlasten (rente en aflossing vóór belasting) en niet met netto lasten?", [["Omdat het fiscale effect van de renteaftrek al in de financieringslastpercentages zit", "De tabellen houden rekening met de belastingdruk en de aftrek, zodat de toets op bruto lasten plaatsvindt."], ["Omdat hypotheekrente sinds 2013 niet meer aftrekbaar is", "Hypotheekrente op een eigenwoningschuld is nog steeds aftrekbaar, mits aan de voorwaarden wordt voldaan."], ["Omdat de kredietgever het fiscale voordeel van de klant volgens de AVG niet mag meewegen", "De kredietgever mag fiscale informatie wel kennen en gebruiken; het netto effect zit al in de percentages."], ["Omdat netto lasten pas na de eerste aangifte inkomstenbelasting definitief vaststaan", "Netto lasten zijn vooraf goed te berekenen; de reden is dat de percentages al op bruto lasten zijn afgestemd."]]],
["Een woning staat op erfpachtgrond waarvoor jaarlijks canon wordt betaald. Hoe telt de canon mee bij de leennormen?", [["De canon telt mee als last in de financieringslast", "De TRHK rekent erfpachtcanon tot de jaarlijkse lasten, naast rente en aflossing."], ["De canon wordt opgeteld bij de woningwaarde voor de LTV", "Canon is een last en geen waardebestanddeel; erfpacht verlaagt eerder de marktwaarde."], ["De canon is alleen relevant voor de taxateur en niet voor de leennormen", "Canon raakt ook de betaalbaarheid en is daarom onderdeel van de financieringslast."], ["De canon verhoogt het toetsinkomen omdat zij fiscaal aftrekbaar is", "Canon verhoogt het toetsinkomen niet; het is juist een extra last voor de consument."]]],
["Wat houdt 'explain' bij de leennormen in?", [["De kredietgever mag verantwoord afwijken, mits gemotiveerd en vastgelegd", "De TRHK staat afwijking toe als die op basis van de persoonlijke situatie verantwoord is; de onderbouwing moet worden vastgelegd."], ["De adviseur legt de klant schriftelijk uit hoe de maximale hypotheek is berekend", "Uitleg aan de klant is goede dienstverlening, maar 'explain' is de bevoegdheid van de kredietgever om gemotiveerd af te wijken."], ["De klant mag zelf afwijken van de normen door een verklaring te tekenen", "De consument kan niet zelf de normen buiten werking stellen; de afwijking is een verantwoorde beslissing van de kredietgever."], ["De AFM keurt vooraf elke afwijking van de leennormen goed", "De AFM keurt individuele dossiers niet vooraf goed; zij houdt achteraf toezicht op het gebruik van explain."]]],
["Een klant wil zijn bestaande hypotheek oversluiten naar een lagere rente, zonder verhoging van de lening. Door een inkomensdaling past de lening niet meer binnen de huidige leennormen. Wat is juist?", [["Via explain kan de kredietgever verantwoord afwijken, omdat de klant er in lasten niet op achteruitgaat", "Oversluiten zonder verhoging waarbij de lasten dalen is een erkende situatie waarin afwijken verantwoord kan zijn, mits gemotiveerd vastgelegd."], ["Oversluiten is verboden zolang de lening niet binnen de leennormen past", "Er geldt geen absoluut verbod; juist voor deze situatie biedt explain ruimte."], ["De klant moet eerst het bedrag boven de nieuwe norm aflossen, uit eigen middelen of met een schenking", "Een verplichte aflossing is niet vereist als afwijken verantwoord is en wordt onderbouwd."], ["De leennormen gelden niet bij oversluiten binnen dezelfde geldverstrekker, ook niet als het inkomen daalt", "Ook bij een interne oversluiting is de TRHK van toepassing; afwijken gaat via explain."]]],
["De taxateur stelt de marktwaarde van een woning vast op € 350.000. De kosten koper bedragen € 15.000 en er worden geen energiebesparende voorzieningen gefinancierd. Wat is volgens de LTV-norm de maximale hypotheek?", [["€ 350.000, de kosten koper moet de klant uit eigen middelen betalen", "Bij een LTV van maximaal 100% van de marktwaarde is € 350.000 het maximum; kosten koper vallen daarbuiten."], ["€ 365.000, omdat kosten koper altijd mogen worden meegefinancierd", "Meefinancieren van kosten koper boven de marktwaarde past niet binnen de LTV-norm van 100%."], ["€ 371.000, omdat de LTV 106% van de marktwaarde mag zijn", "Een LTV van 106% gold tijdens de afbouw tot 2018; nu is de hoofdregel 100%."], ["€ 335.000, omdat de kosten koper van de marktwaarde worden afgetrokken", "De kosten koper verlagen de toegestane hypotheek niet; ze moeten alleen uit eigen middelen komen."]]],
["Een klant leent € 315.000 op een woning met een marktwaarde van € 350.000. Wat is de loan-to-value (LTV)?", [["90%", "€ 315.000 gedeeld door € 350.000 is 0,90, dus een LTV van 90%."], ["111%", "Dat is de omgekeerde verhouding (waarde gedeeld door lening), niet de LTV."], ["10%", "10% is het deel van de woningwaarde dat niet is gefinancierd, niet de LTV."], ["85%", "85% van € 350.000 is € 297.500; de lening is hoger, dus de LTV is 90%."]]],
["Wat geldt in de TRHK voor consumenten die de AOW-leeftijd hebben bereikt?", [["Voor hen gelden aparte financieringslastpercentages", "De TRHK bevat afzonderlijke tabellen voor AOW-gerechtigden, afgestemd op hun andere belastingdruk en uitgaven."], ["Zij mogen geen nieuwe hypotheek meer afsluiten", "Er geldt geen leeftijdsverbod; ook na de AOW-leeftijd kan een hypotheek verantwoord zijn."], ["Voor hen geldt altijd een maximale LTV van 50%", "De TRHK kent geen lagere LTV-grens op basis van leeftijd."], ["Hun AOW-uitkering telt niet mee als toetsinkomen", "AOW en pensioen tellen juist mee als inkomen bij de toets."]]],
["Voor wie is de Gedragscode Hypothecaire Financieringen (GHF) bindend?", [["Voor geldverstrekkers die zich via hun brancheorganisatie aan de code hebben verbonden", "De GHF is zelfregulering; zij bindt de aangesloten aanbieders, zoals banken en verzekeraars die de code onderschrijven."], ["Voor iedere consument die een hypotheek afsluit", "Een gedragscode bindt de partijen die zich eraan verbinden, niet de consument."], ["Voor alle Nederlandse notarissen bij het opstellen en passeren van hypotheekakten voor consumenten", "Notarissen hebben hun eigen beroepsregels; de GHF is gericht op geldverstrekkers."], ["Alleen voor hypotheekadviseurs met een AFM-vergunning", "De GHF is opgesteld door en voor geldverstrekkers, niet primair voor adviseurs."]]],
["De leennormen stonden vroeger in de Gedragscode Hypothecaire Financieringen. Waarom zijn ze naar regelgeving (de TRHK) overgebracht?", [["Om de normen wettelijk voor alle kredietgevers te laten gelden", "Met de TRHK gelden de normen niet alleen voor aangesloten partijen maar wettelijk voor alle aanbieders, onder toezicht van de AFM."], ["Omdat de Europese Unie Nederland verplichtte tot een LTV van 100%", "De MCD schrijft geen LTV van 100% voor; de keuze voor wettelijke normen is nationaal."], ["Omdat de GHF sindsdien alleen nog voor verzekeraars geldt", "De GHF bestaat nog en geldt nog steeds voor aangesloten banken en verzekeraars."], ["Om het Kifid de bevoegdheid te geven leennormen vast te stellen", "Het Kifid stelt geen normen vast; de normen worden door de minister vastgesteld."]]],
["Waarop ziet de huidige Gedragscode Hypothecaire Financieringen vooral?", [["Minimumeisen aan de offerte, de voorwaarden en de informatie over kosten en rente", "De GHF regelt onder meer wat in een offerte moet staan en hoe de aanbieder informeert over voorwaarden, kosten en rente."], ["De hoogte van de financieringslastpercentages per inkomensklasse", "Die percentages staan in de TRHK, niet in de GHF."], ["De fiscale voorwaarden voor aftrek van hypotheekrente", "De fiscale regels staan in de Wet IB 2001."], ["De voorwaarden voor kwijtschelding van een restschuld met NHG", "Die voorwaarden staan in de Voorwaarden & Normen van de NHG."]]],
["Bij een annuïteitenhypotheek met een gelijkblijvende rente stijgen de netto maandlasten in de loop van de tijd. Wat is daarvan de oorzaak?", [["Het rentedeel daalt, waardoor de renteaftrek en dus het fiscale voordeel afnemen", "De bruto annuïteit blijft gelijk, maar omdat het aftrekbare rentedeel daalt, stijgt de netto last."], ["Het aflossingsdeel wordt elk jaar door de geldverstrekker verhoogd volgens een vast schema", "Het aflossingsdeel groeit vanzelf binnen dezelfde bruto annuïteit; de bruto last stijgt niet."], ["De rente wordt automatisch aan de inflatie aangepast", "Bij een vaste rente vindt geen inflatiecorrectie plaats."], ["Het eigenwoningforfait daalt elk jaar mee met de resterende hypotheekschuld", "Het forfait hangt af van de WOZ-waarde, niet van de schuld."]]],
["Een klant vergelijkt een annuïtaire en een lineaire hypotheek van hetzelfde bedrag, met dezelfde looptijd en rente. Wat is juist?", [["Bij lineair betaalt hij in totaal minder rente, maar zijn de aanvangslasten hoger", "Bij lineair daalt de schuld in het begin sneller, waardoor minder rente wordt betaald; daar staan hogere startlasten tegenover."], ["Bij lineair betaalt hij over de hele looptijd meer rente, maar de aanvangslasten zijn juist lager", "Het is andersom: lineair begint hoger en kost in totaal minder rente."], ["Beide vormen kosten over de hele looptijd evenveel rente", "Omdat de schuld bij lineair sneller daalt, is de totale rente lager."], ["Alleen de annuïtaire vorm voldoet aan de fiscale aflossingseis van minimaal annuïtair in 30 jaar", "Lineair aflossen is sneller dan annuïtair en voldoet dus ook aan de aflossingseis."]]],
["Een klant sluit een lineaire hypotheek van € 240.000 af met een looptijd van 30 jaar en een rente van 4,8%. Wat is de bruto maandlast in de eerste maand?", [["€ 1.626,67", "De aflossing is € 240.000 / 360 = € 666,67 en de rente € 240.000 × 4,8% / 12 = € 960,00; samen € 1.626,67."], ["€ 1.259,20", "Dit is ongeveer de bruto annuïteit voor dezelfde lening, niet de lineaire aanvangslast."], ["€ 960,00", "Dit is alleen het rentedeel; bij lineair komt de vaste aflossing daar nog bij."], ["€ 666,67", "Dit is alleen het vaste aflossingsdeel; de rente moet er nog bij worden opgeteld."]]],
["Een klant heeft een aflossingsvrij leningdeel van € 180.000 tegen een rente van 3,9%. Wat is de bruto maandlast van dit leningdeel?", [["€ 585,00", "€ 180.000 × 3,9% = € 7.020 per jaar; gedeeld door 12 is dat € 585,00 per maand."], ["€ 702,00", "Dit is het jaarbedrag gedeeld door 10 in plaats van door 12."], ["€ 1.085,00", "Bij aflossingsvrij wordt niet afgelost; er komt dus geen aflossingsbedrag bij de rente."], ["€ 7.020,00", "Dit is de rente per jaar, niet per maand."]]],
["Wat kenmerkt een bankspaarhypotheek?", [["Er wordt gespaard op een geblokkeerde rekening die aan het einde de lening aflost", "De lening zelf is aflossingsvrij; de inleg op de geblokkeerde spaarrekening eigen woning wordt aan het einde gebruikt voor aflossing."], ["De lening wordt maandelijks lineair afgelost via een gewone, vrij opneembare bankrekening bij dezelfde bank", "Bij bankspaar wordt niet tussentijds op de lening afgelost; er wordt apart gespaard."], ["De inleg wordt belegd in fondsen naar keuze van de klant", "Dat is een beleggingshypotheek; bij bankspaar wordt gespaard tegen een rente."], ["De klant betaalt alleen rente en bouwt geen spaartegoed op", "Dat is een aflossingsvrije hypotheek zonder spaarcomponent."]]],
["Voor een kapitaalverzekering eigen woning of spaarrekening eigen woning onder het overgangsrecht geldt een bandbreedte voor de inleg. Wat houdt die in?", [["De hoogste jaarinleg is maximaal tien keer de laagste", "De bandbreedte 1:10 voorkomt dat de inleg sterk wordt geconcentreerd, als voorwaarde voor de vrijstelling."], ["De inleg moet elk jaar precies gelijk zijn", "Variatie is toegestaan, zolang de verhouding 1:10 niet wordt overschreden."], ["De inleg mag maximaal tien jaar duren", "De bandbreedte gaat over de hoogte van de inleg, niet over de duur."], ["De uitkering mag maximaal tien keer de jaarpremie bedragen", "De bandbreedte gaat over de verhouding tussen de premies onderling, niet over de uitkering."]]],
["Wat is het doel van een overbruggingskrediet bij de aankoop van een nieuwe woning?", [["Tijdelijk de overwaarde van de oude, nog onverkochte woning beschikbaar maken voor de nieuwe", "Het overbruggingskrediet financiert de periode tussen aankoop van de nieuwe en verkoop van de oude woning."], ["De kosten koper van de nieuwe woning permanent meefinancieren boven de marktwaarde van de nieuwe woning", "Een overbrugging is tijdelijk en bedoeld voor de overwaarde, niet om kosten koper blijvend te financieren."], ["De rentevaste periode van de oude hypotheek verlengen tot de verkoop", "Een overbrugging verandert niets aan de rentevaste periode van de bestaande lening."], ["Een eventuele restschuld van de oude woning blijvend financieren", "Een restschuld is geen overwaarde; een overbrugging gaat juist uit van overwaarde."]]],
["Welk risico is kenmerkend voor een beleggingshypotheek?", [["Het belegde vermogen kan aan het einde onvoldoende zijn om de lening af te lossen", "Bij tegenvallende rendementen ontstaat een tekort, waardoor aan het einde een deel van de schuld blijft staan."], ["De hypotheekrente stijgt automatisch mee met de koersen van de fondsen waarin de klant belegt", "De hypotheekrente staat los van de beleggingsresultaten."], ["De lening wordt bij koersdaling direct opeisbaar", "Een koersdaling maakt de hypotheek niet automatisch opeisbaar."], ["De klant betaalt over de looptijd dubbel overdrachtsbelasting, bij aankoop en bij aflossing", "Overdrachtsbelasting heeft niets te maken met de hypotheekvorm."]]],
["Een starter sluit in 2026 een volledig aflossingsvrije hypotheek af voor de aankoop van zijn eigen woning. Wat is het fiscale gevolg?", [["Geen eigenwoningschuld: de rente is niet aftrekbaar en de schuld valt in box 3", "Een na 2012 aangegane lening moet minimaal annuïtair in 30 jaar worden afgelost om als eigenwoningschuld te gelden."], ["De rente is aftrekbaar, maar alleen tegen het basistarief", "Het basistarief beperkt de aftrek van een eigenwoningschuld; deze lening is echter geen eigenwoningschuld."], ["De rente is de eerste tien jaar aftrekbaar en daarna niet meer, omdat er niet wordt afgelost", "Zo'n tijdelijke aftrek bestaat niet; zonder aflossingsverplichting is er geen aftrek."], ["De lening valt in box 2 omdat er niet wordt afgelost", "Box 2 gaat over aanmerkelijk belang; een niet-kwalificerende woningschuld valt in box 3."]]],
["Wat houdt het overgangsrecht voor bestaande eigenwoningschulden per 31 december 2012 in?", [["Die schulden behouden recht op renteaftrek zonder aan de aflossingseis te hoeven voldoen", "Wie op 31 december 2012 al een eigenwoningschuld had, valt voor dat bedrag niet onder de verplichting om annuïtair af te lossen."], ["Die schulden moeten alsnog vóór 2030 volledig zijn afgelost om de renteaftrek te behouden", "Het overgangsrecht kent geen verplichte aflossing vóór een bepaald jaar."], ["Die schulden zijn vanaf 2013 onbeperkt in tijd aftrekbaar", "Ook onder het overgangsrecht blijft de maximale aftrekperiode van 30 jaar gelden."], ["Die schulden mogen onbeperkt worden verhoogd met behoud van overgangsrecht", "Een verhoging na 2012 valt onder de nieuwe regels en moet aan de aflossingseis voldoen."]]],
["Een klant heeft sinds 2009 een aflossingsvrije eigenwoningschuld. In 2026 leent hij € 40.000 bij voor een verbouwing van zijn woning. Wat geldt voor de nieuwe lening als hij renteaftrek wil?", [["Het nieuwe deel moet minimaal annuïtair in 30 jaar aflossen; het oude deel mag aflossingsvrij blijven", "De verhoging valt onder de regels vanaf 2013; het bestaande bedrag houdt het overgangsrecht."], ["Het nieuwe deel mag aflossingsvrij zijn, omdat de oude lening van vóór 2013 dat ook is en zo blijft", "Het overgangsrecht geldt alleen voor de schuld die er op 31 december 2012 al was."], ["De hele lening, inclusief het oude deel, moet nu annuïtair in de resterende looptijd worden afgelost", "Het oude deel verliest het overgangsrecht niet door een aparte verhoging."], ["Rente over leningen voor een verbouwing is nooit aftrekbaar", "Een lening voor verbetering of onderhoud van de eigen woning kan een eigenwoningschuld zijn."]]],
["Een klant verkoopt zijn woning voor € 420.000 met € 12.000 verkoopkosten; zijn eigenwoningschuld is € 260.000. Hij koopt een woning van € 525.000 met € 23.000 kosten koper. Wat is de maximale nieuwe eigenwoningschuld?", [["€ 400.000", "De eigenwoningreserve is € 420.000 − € 12.000 − € 260.000 = € 148.000; de verwervingskosten zijn € 548.000; € 548.000 − € 148.000 = € 400.000."], ["€ 388.000", "Hier zijn de verkoopkosten vergeten, waardoor de eigenwoningreserve te hoog (€ 160.000) is berekend."], ["€ 377.000", "Hier zijn de kosten koper niet meegenomen in de verwervingskosten van de nieuwe woning."], ["€ 548.000", "Hier is de eigenwoningreserve genegeerd; de bijleenregeling vraagt dat de overwaarde wordt ingebracht."]]],
["Een klant verkoopt zijn woning met overwaarde en gaat huren. Vier jaar later koopt hij opnieuw een eigen woning. Wat is fiscaal juist?", [["De eigenwoningreserve is na drie jaar vervallen; de oude overwaarde hoeft niet meer te worden ingebracht", "Een eigenwoningreserve geldt drie jaar na vervreemding; daarna vervalt zij en beperkt zij de nieuwe eigenwoningschuld niet meer."], ["Hij moet de overwaarde alsnog volledig inbrengen in de nieuwe woning, ongeacht het tijdsverloop", "De eigenwoningreserve is in tijd beperkt tot drie jaar."], ["Hij heeft voor de nieuwe woning helemaal geen recht op renteaftrek meer", "Na het vervallen van de reserve kan hij een nieuwe eigenwoningschuld aangaan, mits aan de aflossingseis wordt voldaan."], ["De overwaarde wordt na drie jaar belast in box 1", "Er volgt geen belastingheffing over de overwaarde; de reserve vervalt alleen."]]],
["Welke kosten zijn bij de aankoop van een eigen woning direct aftrekbaar als financieringskosten in box 1?", [["De advies- en bemiddelingskosten voor de hypotheek", "Kosten die samenhangen met het afsluiten van de lening, zoals advies, taxatie voor de lening en de hypotheekakte, zijn aftrekbaar."], ["De overdrachtsbelasting", "Overdrachtsbelasting is een verwervingskost van de woning, geen financieringskost, en dus niet aftrekbaar."], ["De notariskosten van de leveringsakte bij de overdracht", "De leveringsakte hoort bij de verwerving van de woning; alleen de hypotheekakte is aftrekbaar."], ["De kosten van de aankoopmakelaar en de bouwkundige keuring", "Makelaarskosten zijn verwervingskosten en niet aftrekbaar als financieringskosten."]]],
["Hoe werkt het eigenwoningforfait in de inkomstenbelasting?", [["Als bijtelling in box 1, berekend als percentage van de WOZ-waarde", "Het forfait is het fiscale voordeel van het wonen in de eigen woning; aftrekbare rente en kosten worden ervan afgetrokken."], ["Als aftrekpost die het belastbaar inkomen uit werk en woning in box 1 verlaagt", "Het forfait verhoogt juist het inkomen; de rente is de aftrekpost."], ["Als gemeentelijke belasting die jaarlijks wordt geheven", "Gemeenten heffen OZB; het forfait is onderdeel van de inkomstenbelasting."], ["Als percentage van de hypotheekschuld, belast in box 3", "Het forfait hangt af van de WOZ-waarde en valt in box 1, niet in box 3."]]],
["Een klant heeft zijn hypotheek volledig afgelost en woont nog in de woning. Wat geldt voor de aftrek wegens geen of geringe eigenwoningschuld (Wet Hillen)?", [["Hij krijgt een aftrek die het forfait deels compenseert en wordt afgebouwd", "Sinds 2019 wordt de Hillen-aftrek in dertig jaar afgebouwd, waardoor een steeds groter deel van het forfait wordt belast."], ["Het eigenwoningforfait vervalt omdat er geen schuld meer is", "Het forfait blijft bestaan zolang de woning het hoofdverblijf is, ook zonder schuld."], ["Hij mag het volledige forfait voor altijd buiten de heffing laten", "Dat was het effect vóór 2019; de compensatie wordt nu afgebouwd."], ["Hij krijgt een teruggave van de rente die hij in het verleden heeft betaald", "De Wet Hillen gaat over het forfait, niet over teruggave van betaalde rente."]]],
["Een klant verhuist naar een nieuwe woning; de oude woning staat leeg en te koop. Hoe lang kan de oude woning fiscaal nog als eigen woning gelden?", [["In het jaar van leegkomen en de drie jaren daarna", "Een leegstaande woning die te koop staat en eerder hoofdverblijf was, blijft deze periode een eigen woning."], ["Alleen tot het einde van de maand van verhuizing", "De wet biedt ruimere tijd om de oude woning te verkopen."], ["Maximaal zes maanden na de verhuizing", "De termijn is het jaar van leegkomen plus drie jaar, niet zes maanden."], ["Onbeperkt, zolang de woning te koop staat", "De periode is wettelijk beperkt; daarna valt de woning in box 3."]]],
["Een klant koopt een nieuwbouwwoning die over anderhalf jaar wordt opgeleverd. Hij woont tot die tijd in een huurhuis. Wat geldt voor de renteaftrek in de periode tot oplevering?", [["De woning kan al eigen woning zijn als hij haar binnen drie jaar betrekt", "De wet geeft een tijdelijke eigenwoningstatus voor een woning in aanbouw die binnen die termijn wordt betrokken."], ["Rente is pas aftrekbaar vanaf de dag van inschrijving op het nieuwe adres", "Dankzij de regeling voor woningen in aanbouw kan de aftrek al eerder ingaan."], ["Bouwrente is nooit aftrekbaar, alleen hypotheekrente na oplevering", "Rente tijdens de bouw kan onder voorwaarden als eigenwoningrente aftrekbaar zijn."], ["De rente valt tot oplevering verplicht in box 2", "Box 2 heeft geen relatie met de eigen woning."]]],
["Wat geldt voor de rente over een restschuld na verkoop van een eigen woning?", [["Alleen bij ontstaan tussen 29-10-2012 en 31-12-2017: maximaal 15 jaar aftrek", "Deze tijdelijke regeling is beëindigd; voor later ontstane restschulden is de rente niet meer aftrekbaar."], ["Rente over iedere restschuld is altijd 30 jaar aftrekbaar", "Een restschuld is geen eigenwoningschuld; alleen de tijdelijke regeling gaf beperkte aftrek."], ["Rente over een restschuld is aftrekbaar als de klant opnieuw een woning koopt", "Een nieuwe aankoop maakt een restschuld niet tot eigenwoningschuld."], ["Rente over een restschuld is alleen aftrekbaar bij een NHG-hypotheek", "NHG kan een restschuld kwijtschelden, maar regelt geen renteaftrek."]]],
["Een klant verhoogt zijn hypotheek met € 25.000 om een auto te kopen. Hoe wordt dit leningdeel fiscaal behandeld?", [["Het deel valt in box 3, omdat het niet aan de woning is besteed", "Het bestedingsvereiste bepaalt of een lening een eigenwoningschuld is; voor een auto is dat niet zo."], ["Het deel is aftrekbaar omdat er hypotheekrecht op de woning is gevestigd", "De zekerheid is niet doorslaggevend; het gaat om waaraan het geld is besteed."], ["Het deel is aftrekbaar als het annuïtair wordt afgelost", "Ook met annuïtaire aflossing blijft het een consumptieve besteding buiten de eigenwoningregeling."], ["Het deel valt in box 2, omdat het om een vermogensbestanddeel gaat", "Box 2 gaat over aanmerkelijk belang; een schuld voor een auto valt in box 3."]]],
["Een klant koopt naast zijn hoofdverblijf een vakantiewoning, die hij met een aparte hypotheek financiert. Wat is juist?", [["De vakantiewoning en de lening vallen in box 3; de rente is niet aftrekbaar in box 1", "Alleen het hoofdverblijf kan een eigen woning zijn; een tweede woning valt in box 3."], ["Beide woningen gelden als eigen woning als hij er beide regelmatig verblijft", "Een belastingplichtige kan maar één hoofdverblijf tegelijk hebben (behoudens tijdelijke situaties)."], ["De rente op de vakantiewoning is aftrekbaar tegen het basistarief", "Dat geldt voor de eigen woning; een tweede woning valt buiten de eigenwoningregeling."], ["Over de vakantiewoning wordt eigenwoningforfait berekend", "Het forfait geldt voor de eigen woning in box 1, niet voor een tweede woning."]]],
["Een klant leent een deel van de koopsom van zijn ouders. Wat is onder meer vereist om de rente als eigenwoningrente te kunnen aftrekken?", [["Voldoen aan de aflossingseis en de leninggegevens in de aangifte vermelden", "Ook een familielening moet minimaal annuïtair in 30 jaar worden afgelost en de klant moet de leninggegevens doorgeven."], ["De lening moet bij de notaris worden vastgelegd en worden gecombineerd met een NHG-borgtocht", "NHG is geen voorwaarde voor renteaftrek op een familielening."], ["De ouders moeten een bankvergunning van DNB hebben", "Particulieren kunnen zonder vergunning incidenteel geld lenen aan hun kinderen."], ["De lening moet aflossingsvrij zijn om schenkbelasting te voorkomen", "Een aflossingsvrije familielening na 2012 voldoet juist niet aan de aflossingseis."]]],
["Twee fiscale partners bezitten samen hun eigen woning. Hoe mogen zij het saldo van eigenwoningforfait en aftrekbare kosten verdelen?", [["In elke gewenste verhouding tussen beide partners", "Fiscale partners mogen gemeenschappelijke bestanddelen, zoals het saldo eigen woning, in elke gewenste verhouding verdelen."], ["Altijd verplicht bij helfte, ongeacht wie de rente betaalt", "Verdeling bij helfte is niet verplicht voor fiscale partners."], ["Volledig bij de partner met het laagste inkomen", "Er is geen verplichting om het saldo bij de partner met het laagste inkomen te leggen."], ["Naar rato van de eigendomsverhouding in de leveringsakte", "Voor fiscale partners is de eigendomsverhouding niet bepalend voor de verdeling."]]],
["Een klant sluit een in 2016 afgesloten annuïtaire eigenwoningschuld over naar een andere geldverstrekker. Wat geldt fiscaal voor de nieuwe lening?", [["Het aflossingsschema en de resterende looptijd van de oude lening lopen door", "Bij oversluiten loopt het oorspronkelijke aflossingsschema door; de klant krijgt geen nieuwe periode van 30 jaar."], ["Er begint een nieuwe looptijd van 30 jaar voor renteaftrek", "Oversluiten geeft geen nieuwe aftrekperiode; de al verstreken looptijd telt mee."], ["De nieuwe lening mag aflossingsvrij zijn als de rente lager is", "Een lagere rente verandert niets aan de aflossingseis."], ["De nieuwe lening valt automatisch onder het overgangsrecht voor schulden van vóór 2013", "Een lening uit 2016 heeft nooit overgangsrecht gehad."]]],
["Welke organisatie verstrekt de Nationale Hypotheek Garantie?", [["De Stichting WEW", "De Stichting WEW voert de NHG uit en staat borg tegenover de geldverstrekker."], ["De Nederlandsche Bank", "DNB is toezichthouder en geeft geen hypotheekgaranties af."], ["De gemeente", "Gemeenten waren vroeger betrokken bij achtervang, maar de NHG zelf wordt door de Stichting WEW verstrekt."], ["Het Kadaster", "Het Kadaster registreert eigendom en hypotheken, maar verstrekt geen garanties."]]],
["Waarom krijgt een klant met NHG doorgaans een lagere rente?", [["Omdat de borgtocht het risico voor de geldverstrekker verkleint", "De borgtocht beperkt het verlies van de geldverstrekker bij gedwongen verkoop; dat lagere risico wordt in de rente doorgegeven."], ["Omdat de overheid een deel van de rente rechtstreeks betaalt", "Er is geen rentesubsidie; het voordeel komt voort uit het lagere risico."], ["Omdat NHG-hypotheken niet onder de TRHK vallen", "NHG-hypotheken vallen gewoon onder de TRHK, met aanvullende NHG-normen."], ["Omdat bij NHG geen hypotheekrecht wordt gevestigd", "Ook bij NHG wordt een hypotheekrecht gevestigd; NHG komt daar bovenop."]]],
["Een klant met NHG moet zijn woning gedwongen verkopen na een echtscheiding en houdt een restschuld over. Wanneer kan de Stichting WEW de restschuld kwijtschelden?", [["Bij een erkende oorzaak, mits de klant verantwoord heeft gehandeld", "Kwijtschelding is mogelijk bij oorzaken als relatie-einde, werkloosheid, arbeidsongeschiktheid of overlijden, mits de klant zich verantwoord heeft opgesteld."], ["Altijd, ongeacht de oorzaak en het gedrag van de klant", "Kwijtschelding is geen automatisme; de oorzaak en het gedrag van de klant worden beoordeeld."], ["Alleen als de klant ouder is dan de AOW-leeftijd en geen pensioenvermogen heeft", "Leeftijd is geen voorwaarde voor kwijtschelding."], ["Nooit; NHG dekt alleen de geldverstrekker en nooit de consument zelf", "NHG beschermt ook de consument, die onder voorwaarden geen restschuld hoeft te betalen."]]],
["Hoe ontwikkelt de NHG-borgtocht zich tijdens de looptijd?", [["De borgtocht daalt elke maand alsof de lening annuïtair in 30 jaar wordt afgelost", "De dekking neemt af volgens een annuïtair schema, ook als de lening in werkelijkheid anders wordt afgelost."], ["De borgtocht blijft altijd gelijk aan het oorspronkelijke leenbedrag", "De borgtocht daalt juist in de tijd."], ["De borgtocht stijgt mee met de woningwaarde", "De borgtocht volgt een vast afbouwschema, niet de woningwaarde."], ["De borgtocht vervalt automatisch na tien jaar", "De borgtocht loopt in beginsel de hele looptijd, maar daalt wel."]]],
["Hoe wordt de eenmalige borgtochtprovisie voor NHG fiscaal behandeld?", [["Als aftrekbare financieringskosten van de eigenwoningschuld", "De NHG-provisie is een kostenpost voor het verkrijgen van de lening en is daarom aftrekbaar in box 1."], ["Als verwervingskost van de woning die niet aftrekbaar is in box 1", "De provisie hoort bij de financiering, niet bij de verwerving van de woning."], ["Als premie die in box 3 wordt vrijgesteld", "Box 3 speelt hier geen rol; het gaat om aftrekbare kosten in box 1."], ["Als schenking aan de Stichting WEW, aftrekbaar als gift", "De provisie is een vergoeding voor de borgtocht, geen schenking."]]],
["Wat wordt in een taxatierapport voor hypothecaire financiering verstaan onder de marktwaarde?", [["De geschatte prijs bij verkoop tussen een bereidwillige koper en verkoper", "De marktwaarde gaat uit van een zakelijke transactie na behoorlijke marketing, waarbij partijen zonder dwang handelen."], ["Het bedrag dat bij een executieveiling van de woning minimaal wordt opgebracht", "Dat is de executiewaarde of veilingwaarde, die doorgaans lager ligt."], ["De WOZ-waarde die de gemeente heeft vastgesteld", "De WOZ-waarde is een fiscale waarde met een andere peildatum en doelstelling."], ["De koopsom uit de koopovereenkomst", "De koopsom kan afwijken van de marktwaarde; de taxateur stelt zelfstandig de waarde vast."]]],
["Wat is de rol van een validatie-instituut bij een taxatierapport?", [["Het controleert of het rapport volgens de normen is opgesteld", "Validatie toetst kwaliteit en onderbouwing van het rapport, zodat de geldverstrekker erop kan vertrouwen."], ["Het stelt zelf de definitieve woningwaarde vast", "De taxateur stelt de waarde vast; het instituut controleert het rapport."], ["Het bepaalt de hoogte van de hypotheekrente", "De rente wordt door de geldverstrekker bepaald, niet door een validatie-instituut."], ["Het voert een bouwkundige keuring van de woning uit en rapporteert de gebreken", "Validatie is een controle op het taxatierapport, geen bouwkundig onderzoek."]]],
["Een klant koopt een woning van € 300.000 en verbouwt voor € 40.000. De taxateur stelt de marktwaarde na verbouwing vast op € 350.000. Op welke waarde wordt de LTV-toets gebaseerd?", [["De marktwaarde na verbouwing van € 350.000", "Bij financiering van een verbouwing mag de marktwaarde na verbouwing als woningwaarde worden gehanteerd."], ["De koopsom van € 300.000", "De koopsom zonder verbouwing doet geen recht aan de waarde die met de verbouwing ontstaat."], ["De koopsom plus verbouwingskosten van € 340.000", "De LTV gaat uit van de getaxeerde marktwaarde, niet van de optelsom van kosten."], ["De WOZ-waarde van vóór de verbouwing", "De WOZ-waarde is niet de maatstaf voor de LTV bij deze financiering."]]],
["Waarom moet een taxateur onafhankelijk zijn van de transactie die hij taxeert?", [["Om te voorkomen dat belangen bij verkoop of financiering de waardebepaling beïnvloeden", "De geldverstrekker baseert de lening op de waarde; die moet objectief zijn vastgesteld."], ["Omdat de taxateur anders geen overdrachtsbelasting over de koopsom van de woning mag berekenen", "Taxateurs berekenen geen overdrachtsbelasting; dat doet de notaris bij de aangifte."], ["Omdat de taxateur de koopovereenkomst moet ondertekenen", "De taxateur is geen partij bij de koopovereenkomst."], ["Omdat alleen een onafhankelijke taxateur het energielabel van de woning mag registreren", "Een energielabel wordt door een erkend energieadviseur geregistreerd, los van de taxatie."]]],
["Een klant denkt dat een taxatierapport ook uitsluitsel geeft over verborgen gebreken aan de woning. Wat is juist?", [["Een taxatie is geen bouwkundige keuring; voor de bouwkundige staat is apart onderzoek nodig", "De taxateur beoordeelt de waarde en zichtbare staat op hoofdlijnen, maar doet geen diepgaand bouwkundig onderzoek."], ["Een gevalideerd taxatierapport garandeert dat er geen gebreken zijn", "Validatie gaat over de kwaliteit van het rapport, niet over de afwezigheid van gebreken."], ["De taxateur is aansprakelijk voor alle later ontdekte gebreken", "De taxateur staat niet in voor gebreken die bij een taxatie redelijkerwijs niet zichtbaar zijn."], ["De geldverstrekker vergoedt de herstelkosten als de taxateur bij de taxatie gebreken heeft gemist", "De geldverstrekker geeft geen garantie op de bouwkundige staat van de woning."]]],
["Hoe komt een hypotheekrecht op een woning tot stand?", [["Door een notariële akte die wordt ingeschreven in de openbare registers (Kadaster)", "Voor vestiging van hypotheek op een registergoed zijn een notariële akte en inschrijving in de openbare registers vereist."], ["Door ondertekening van het bindend aanbod van de geldverstrekker door de klant en eventuele partner", "Het aanbod leidt tot een kredietovereenkomst, maar vestigt nog geen hypotheekrecht."], ["Door registratie van de lening bij het BKR", "Het BKR registreert kredieten, maar vestigt geen zakelijk recht."], ["Door een onderhandse akte tussen klant en geldverstrekker, gewaarmerkt door het Kadaster", "Een onderhandse akte is onvoldoende, ook niet met een waarmerk; een notariële akte is verplicht."]]],
["Wat houdt het recht van parate executie van de hypotheekhouder in?", [["Hij mag het onderpand bij wanprestatie zelf laten verkopen zonder voorafgaand rechterlijk vonnis", "Parate executie geeft de hypotheekhouder het recht de woning via een openbare veiling bij de notaris te verkopen."], ["Hij mag de woning zelf gaan bewonen of verhuren totdat de volledige achterstand is ingelopen", "Het hypotheekrecht geeft geen recht om de woning zelf te bewonen."], ["Hij mag de rente eenzijdig verhogen bij een betalingsachterstand", "Parate executie gaat over verkoop van het onderpand, niet over rentewijzigingen."], ["Hij moet altijd eerst toestemming van de AFM vragen voordat hij het onderpand openbaar laat veilen", "De AFM speelt geen rol bij de executie van een onderpand."]]],
["Een hypotheekhouder wil een executiewoning niet veilen maar onderhands verkopen. Wat is daarvoor nodig?", [["Toestemming van de voorzieningenrechter voor de onderhandse verkoop", "Onderhandse executoriale verkoop is mogelijk als de voorzieningenrechter de koopovereenkomst goedkeurt."], ["Alleen een nieuwe taxatie door een erkend taxateur", "Een taxatie is nuttig, maar vervangt de rechterlijke toestemming niet."], ["Toestemming van de Stichting WEW, ook als de lening zonder NHG is verstrekt", "Zonder NHG heeft de Stichting WEW geen rol, en toestemming van de rechter blijft nodig."], ["Een besluit van de algemene ledenvergadering van de VvE van het appartementencomplex", "De VvE beslist niet over de executie van een appartementsrecht."]]],
["Op een woning rusten twee hypotheekrechten van verschillende geldverstrekkers. Wat bepaalt in beginsel welke hypotheek voorrang heeft bij executie?", [["Het tijdstip van inschrijving in de openbare registers", "De rangorde van hypotheken volgt in beginsel de volgorde van inschrijving; de eerste inschrijving heeft voorrang."], ["De hoogte van het geleende bedrag per hypotheekrecht", "Een hogere lening geeft geen hogere rang."], ["De hoogte van de rente en de looptijd van elke lening", "Rentehoogte speelt geen rol bij de rangorde."], ["De datum van de koopovereenkomst bij de notaris", "De koopovereenkomst bepaalt de rang van hypotheken niet."]]],
["Wat is kenmerkend voor een bankhypotheek?", [["Het dekt ook toekomstige schulden, tot het ingeschreven bedrag", "Daardoor kan binnen de inschrijving later worden bijgeleend zonder nieuwe hypotheekakte."], ["Het dekt uitsluitend de oorspronkelijke lening", "Dat beschrijft een vaste (gewone) hypotheek, niet een bankhypotheek."], ["Het kan alleen worden gevestigd door een bank, niet door een verzekeraar", "De term gaat over de reikwijdte van de zekerheid, niet over het soort geldverstrekker."], ["Het vervalt na het einde van de rentevaste periode", "Een hypotheekrecht vervalt niet door het einde van een rentevaste periode."]]],
["Een gehuwde klant is als enige eigenaar van de woning die hij met zijn echtgenote bewoont. Hij wil er een hypotheek op vestigen. Wat is juist?", [["Hij heeft toestemming van zijn echtgenote nodig", "Boek 1 BW vereist toestemming van de echtgenoot voor bezwaring van de woning die door de echtgenoten samen wordt bewoond."], ["Hij heeft geen toestemming nodig, omdat hij de enige eigenaar is", "Ook als één echtgenoot eigenaar is, is toestemming van de ander vereist voor bezwaring van de gezamenlijke woning."], ["Hij heeft altijd toestemming van de rechter nodig", "De rechter komt alleen in beeld voor vervangende toestemming als de echtgenoot zonder goede grond weigert; primair is toestemming van de echtgenoot nodig."], ["Alleen bij huwelijkse voorwaarden is toestemming nodig", "De toestemmingseis geldt ongeacht het huwelijksvermogensregime."]]],
["Wat is erfpacht volgens Boek 5 BW?", [["Een zakelijk recht om andermans onroerende zaak te gebruiken, tegen canon", "De erfpachter heeft een zelfstandig zakelijk recht op de grond van de eigenaar en betaalt daarvoor doorgaans een canon."], ["Een huurovereenkomst voor grond die jaarlijks opzegbaar is", "Erfpacht is een zakelijk recht en geen huur, en is niet zomaar jaarlijks opzegbaar."], ["Een hypotheekrecht ten gunste van de gemeente", "Erfpacht is een gebruiksrecht, geen zekerheidsrecht."], ["Het recht om eigen gebouwen in, op of boven andermans grond te hebben", "Dat is het opstalrecht, een ander zakelijk recht uit Boek 5 BW."]]],
["Wat is een belangrijk nadeel van een variabele hypotheekrente voor de consument?", [["De maandlasten kunnen bij een rentestijging direct oplopen", "Bij variabele rente draagt de consument het renterisico; stijgt de marktrente, dan stijgen de lasten."], ["Extra aflossen is bij variabele rente nooit toegestaan", "Juist bij variabele rente is boetevrij aflossen doorgaans ruim mogelijk."], ["De rente is bij variabel altijd hoger dan bij een lange rentevaste periode", "Dat hangt af van de rentestructuur; variabel is vaak juist lager."], ["Variabele rente is fiscaal niet aftrekbaar", "De aftrekbaarheid hangt niet af van de rentevorm."]]],
["Wat is een plafondrente?", [["Een variabele rente die niet boven een afgesproken maximum kan stijgen", "De klant profiteert van rentedalingen, terwijl het plafond het risico op stijging begrenst."], ["Een vaste rente die na tien jaar automatisch daalt naar het marktniveau", "Een plafondrente is variabel met een maximum, geen vaste rente met een daling."], ["De maximale rente die de AFM jaarlijks voor alle hypotheken vaststelt", "De AFM stelt geen maximumrente voor hypotheken vast; het plafond is een productafspraak."], ["Een rente die gelijk is aan de wettelijke rente", "De wettelijke rente geldt bij betalingsachterstanden en staat los van de plafondrente."]]],
["Tussen het uitbrengen van de offerte en het passeren van de akte daalt de hypotheekrente. Welke productvoorwaarde zorgt ervoor dat de klant van die daling profiteert?", [["Een rentedaalgarantie (rentepluk)", "Daarmee krijgt de klant bij passeren de laagste rente uit de periode tussen offerte en passeren."], ["Rentemiddeling bij oversluiten", "Rentemiddeling betreft het verwerken van een boete bij tussentijds oversluiten in een nieuwe rente."], ["Een plafondrente op de lening", "Een plafond begrenst een variabele rente naar boven, maar geeft geen recht op een lagere offerterente."], ["Een verlengde rentevaste periode", "Een langere rentevaste periode verandert niets aan rentedalingen in de offerteperiode."]]],
["Veel geldverstrekkers werken met risico-opslagen per LTV-klasse. Wat kan een klant doen als zijn woning flink in waarde stijgt?", [["Een nieuwe waardering laten doen voor een mogelijk lagere risico-opslag", "Een lagere LTV betekent minder risico voor de geldverstrekker; afhankelijk van de voorwaarden kan de opslag dalen."], ["Een hogere renteaftrek aanvragen bij de Belastingdienst", "De woningwaarde heeft geen invloed op de hoogte van de aftrekbare rente."], ["Zijn rentevaste periode kosteloos laten verlengen tot dertig jaar tegen dezelfde rente", "Een waardestijging geeft geen recht op kosteloze verlenging van de rentevaste periode tegen dezelfde rente."], ["De NHG-borgtocht laten verhogen tot de nieuwe waarde", "De NHG-borgtocht volgt een vast afbouwschema en wordt niet verhoogd bij waardestijging."]]],
["Een klant met een krap budget wil zekerheid over zijn maandlasten. Waarom past een lange rentevaste periode vaak bij hem?", [["Omdat zijn lasten langdurig vaststaan en hij minder kwetsbaar is voor rentestijgingen", "Een lange rentevaste periode beperkt het renterisico, wat belangrijk is als een lastenstijging niet kan worden opgevangen."], ["Omdat de rente bij een lange rentevaste periode altijd het laagst is van alle looptijden", "Een langere rentevaste periode heeft vaak juist een hogere rente; het voordeel is zekerheid."], ["Omdat hij dan nooit een vergoeding bij vervroegde aflossing hoeft te betalen, ook niet bij verhuizing", "Ook bij een lange rentevaste periode kan bij extra aflossing boven de boetevrije ruimte een vergoeding verschuldigd zijn."], ["Omdat hij dan geen kredietwaardigheidstoets hoeft te ondergaan", "De toets geldt altijd; alleen de toetsrente kan verschillen."]]],
["Wat is volgens de Wft de maximale vergoeding die een kredietgever mag vragen bij vervroegde aflossing van een hypotheek?", [["Niet meer dan het financiële nadeel dat de kredietgever door de vervroegde aflossing lijdt", "De vergoeding is een compensatie voor renteverlies en mag het werkelijke nadeel niet overstijgen."], ["Een vast percentage van de oorspronkelijke hoofdsom, ongeacht de marktrente en de resterende rentevaste periode", "Een vast percentage los van het werkelijke nadeel is niet toegestaan."], ["De volledige rente over de resterende looptijd van de lening", "Dat zou veel hoger zijn dan het werkelijke nadeel."], ["Het bedrag dat de klant met de oversluiting bespaart", "De besparing van de klant is niet de maatstaf; het gaat om het nadeel van de kredietgever."]]],
["Een klant wil zijn hypotheek tussentijds volledig aflossen. De huidige marktrente voor de resterende rentevaste periode is hoger dan zijn contractrente. Wat is in beginsel juist?", [["Er is geen vergoeding verschuldigd, omdat de kredietgever geen renteverlies lijdt", "De kredietgever kan het geld tegen een hogere rente opnieuw uitlenen; er is dus geen financieel nadeel."], ["Hij betaalt de volledige vergoeding, omdat hij binnen de rentevaste periode aflost", "Zonder nadeel voor de kredietgever mag geen vergoeding worden gevraagd."], ["De kredietgever moet hem een vergoeding voor het renteverschil betalen", "De kredietgever is niet verplicht de klant te vergoeden voor een hogere marktrente."], ["Aflossen is niet toegestaan zolang de rente hoger ligt", "De consument heeft altijd het recht om vervroegd af te lossen."]]],
["Van welke factoren hangt de hoogte van de vergoeding bij vervroegde aflossing vooral af?", [["Het renteverschil, de resterende rentevaste periode en het bedrag boven de boetevrije ruimte", "Hoe groter het renteverschil, hoe langer de resterende periode en hoe hoger het boeteplichtige bedrag, des te hoger de vergoeding."], ["De WOZ-waarde van de woning, het energielabel en de leeftijd van de klant bij het oversluiten", "Deze factoren bepalen de vergoeding niet."], ["Het inkomen van de klant, de woningwaarde en het aantal al betaalde maandtermijnen", "Inkomen speelt geen rol, en het gaat om de resterende rentevaste periode in plaats van de betaalde termijnen."], ["De hoogte van de oorspronkelijke advieskosten en notariskosten", "Afsluitkosten van destijds zijn niet bepalend voor de vergoeding."]]],
["De rentevaste periode van een klant loopt af. Hij wil op de renteherzieningsdatum volledig oversluiten naar een andere geldverstrekker. Wat geldt voor een vergoeding wegens vervroegde aflossing?", [["Er is geen vergoeding verschuldigd, omdat de rentevaste periode is afgelopen", "Op de renteherzieningsdatum eindigt de renteafspraak; er is dan geen renteverlies te vergoeden."], ["Hij betaalt een vergoeding over de volgende rentevaste periode, berekend over de resterende hoofdsom", "Een nieuwe periode is nog niet afgesproken, dus daarover is geen vergoeding verschuldigd."], ["Hij betaalt altijd een vaste vergoeding van één maand rente", "Er is geen wettelijke vaste vergoeding bij aflossing op de herzieningsdatum."], ["Hij mag pas boetevrij oversluiten als de looptijd van 30 jaar volledig is verstreken", "Oversluiten op de renteherzieningsdatum is gewoon mogelijk."]]],
["Een klant sluit zijn eigenwoningschuld over naar een lagere rente en betaalt daarbij een vergoeding wegens vervroegde aflossing. Hoe wordt die vergoeding fiscaal behandeld?", [["Als aftrekbare kosten van de eigenwoningschuld", "Een boete bij oversluiten van een eigenwoningschuld is aftrekbaar als financieringskosten."], ["Als niet-aftrekbare verwervingskost van de woning", "De vergoeding hangt samen met de financiering, niet met de verwerving van de woning."], ["Als schuld in box 3", "De vergoeding is een kostenpost, geen schuld; zij is aftrekbaar in box 1."], ["Als inkomen dat bij de geldverstrekker belastingvrij is", "Wat de geldverstrekker met de vergoeding doet, bepaalt de fiscale positie van de klant niet."]]],
["Wat is het ESIS bij hypothecair krediet?", [["Een Europees standaardinformatieblad over het aangeboden krediet", "Het ESIS komt voort uit de hypothekenrichtlijn en maakt aanbiedingen vergelijkbaar door een vaste opbouw."], ["Een Europees register van hypotheken met betalingsachterstanden bij consumenten", "Het ESIS is geen register; registratie van achterstanden gebeurt in Nederland bij het BKR."], ["Een fiscaal formulier voor de aangifte van hypotheekrente", "Het ESIS is precontractuele informatie, geen belastingformulier."], ["Een certificaat waarmee de adviseur zijn vakbekwaamheid aantoont", "Vakbekwaamheid blijkt uit Wft-diploma's en PE, niet uit het ESIS."]]],
["Wanneer moet de consument het ESIS uiterlijk ontvangen?", [["Tijdig voordat hij gebonden is aan een kredietovereenkomst of aanbod", "De consument moet de informatie kunnen vergelijken en overwegen voordat hij zich bindt."], ["Pas na het passeren van de hypotheekakte", "Na het passeren is het te laat om de informatie te gebruiken bij de keuze."], ["Binnen een jaar na het afsluiten, bij de eerste jaaropgave van de geldverstrekker", "Het ESIS is precontractueel en hoort vóór de binding te worden verstrekt."], ["Alleen als de consument er uitdrukkelijk om vraagt", "Verstrekking is een verplichting voor de aanbieder, niet afhankelijk van een verzoek."]]],
["Wat drukt het jaarlijks kostenpercentage (JKP) uit dat in het ESIS staat?", [["De totale kosten van het krediet als percentage per jaar", "Het JKP omvat rente en bijkomende kosten, zodat aanbiedingen beter vergelijkbaar zijn."], ["Alleen de nominale debetrente op jaarbasis", "Het JKP omvat meer dan de rente, zoals verplichte bijkomende kosten."], ["Het percentage van het inkomen dat aan woonlasten opgaat", "Dat is de financieringslast, geen JKP."], ["Het deel van de woningwaarde dat wordt gefinancierd", "Dat is de LTV, geen kostenpercentage."]]],
["Welke informatie hoort onder meer in het ESIS te staan?", [["De voorwaarden en mogelijke kosten van vervroegde aflossing", "Het ESIS bevat een vast onderdeel over het recht op vervroegde aflossing en de vergoeding die daarbij kan gelden."], ["Het advies van de adviseur over de best passende verzekering", "Het ESIS beschrijft het krediet; het advies wordt apart vastgelegd."], ["De WOZ-beschikking van de gemeente", "De WOZ-beschikking is geen onderdeel van het ESIS."], ["De uitkomst van de BKR-toets van de partner", "Persoonlijke toetsingsresultaten zijn geen standaardonderdeel van het ESIS."]]],
["Een klant heeft een tijdelijk arbeidscontract. Welke verklaring van de werkgever maakt het voor geldverstrekkers doorgaans mogelijk dit inkomen volledig als vast inkomen mee te nemen?", [["Een werkgeversverklaring met een intentie tot een vast contract", "Met een intentieverklaring wordt het tijdelijke dienstverband behandeld als vast inkomen voor de toets."], ["Een verklaring dat de werknemer goed functioneert en zijn proeftijd heeft doorstaan", "Een functioneringsoordeel zonder intentie voor een vast contract is meestal onvoldoende."], ["Een salarisstrook van de laatste maand", "Een salarisstrook toont het inkomen, maar zegt niets over de duurzaamheid ervan."], ["Een verklaring van de vakbond over de cao-lonen", "De vakbond kan niets verklaren over de duurzaamheid van dit specifieke dienstverband."]]],
["Wat is een perspectiefverklaring?", [["Een verklaring over het arbeidsmarktperspectief van een flexwerker", "Een perspectiefverklaring kan het mogelijk maken een hypotheek te verkrijgen als er geen intentieverklaring van de werkgever is."], ["Een verklaring van de geldverstrekker over de verwachte renteontwikkeling", "De perspectiefverklaring gaat over het inkomen van de klant, niet over de rente."], ["Een verklaring van de taxateur over de verwachte waardestijging", "Waardeverwachtingen zijn geen basis voor deze verklaring en ook niet voor de kredietwaardigheidstoets."], ["Een verklaring van het UWV over een lopende WW-uitkering", "Een WW-uitkering is geen arbeidsmarktperspectief en het UWV geeft deze verklaring niet af."]]],
["Wat is Inkomensbepaling Loondienst (IBL)?", [["Een methode om het toetsinkomen te bepalen met UWV-gegevens", "IBL gebruikt het verzekeringsbericht van het UWV om het inkomen over de afgelopen periode vast te stellen."], ["Een fiscale regeling om hypotheekrente via de loonheffing te verrekenen", "Dat is de voorlopige aanslag of teruggaaf, geen inkomensbepaling voor de hypotheek."], ["Een verplichte verzekering tegen inkomensverlies bij werkloosheid", "IBL is geen verzekering, maar een rekenmethode voor het inkomen."], ["Een inkomensverklaring voor zelfstandig ondernemers", "IBL is bedoeld voor werknemers in loondienst; voor ondernemers gelden andere methoden."]]],
["Een zelfstandig ondernemer vraagt een hypotheek aan. Hoe wordt zijn inkomen doorgaans vastgesteld?", [["Op basis van cijfers over meerdere jaren of een inkomensverklaring", "Bij ondernemers wordt gekeken naar de resultaten over meerdere jaren, omdat het inkomen kan schommelen."], ["Alleen op basis van de omzet van de laatste maand", "Eén maand omzet zegt weinig over het duurzame inkomen."], ["Op basis van een werkgeversverklaring die hij zelf ondertekent", "Een ondernemer kan geen werkgeversverklaring over zichzelf afgeven als bewijs van inkomen."], ["Op basis van het verwachte inkomen uit zijn ondernemingsplan", "Verwachtingen zonder historie zijn doorgaans onvoldoende om verantwoord krediet te verstrekken."]]],
["Een klant betaalt partneralimentatie aan zijn ex-echtgenote. Hoe telt dit mee bij de bepaling van de maximale hypotheek?", [["De betaalde partneralimentatie verlaagt het toetsinkomen", "De TRHK brengt betaalde partneralimentatie in mindering op het toetsinkomen, omdat het een structurele verplichting is."], ["De partneralimentatie verhoogt het toetsinkomen omdat zij fiscaal aftrekbaar is", "Aftrekbaarheid maakt de alimentatie niet tot extra inkomen; het blijft een last."], ["De partneralimentatie speelt geen rol bij de leennormen", "Alimentatie drukt op de betaalcapaciteit en wordt dus meegenomen."], ["De partneralimentatie wordt bij de woningwaarde opgeteld", "Alimentatie heeft geen relatie met de woningwaarde."]]],
["Een klant heeft een studieschuld bij DUO. Wat is juist voor de hypotheekaanvraag?", [["De studieschuld telt mee als verplichting en verlaagt de hypotheek", "Een studieschuld is een financiële verplichting die de leencapaciteit verlaagt, ook al staat zij niet bij het BKR."], ["Een studieschuld telt niet mee omdat zij niet bij het BKR geregistreerd staat", "Ook zonder BKR-registratie moet de studieschuld worden meegewogen."], ["Een studieschuld moet vóór aankoop volledig zijn afgelost", "Volledige aflossing is niet verplicht; de schuld wordt wel meegewogen."], ["Een studieschuld verhoogt de maximale LTV", "Een schuld verhoogt de toegestane LTV niet."]]],
["Bij een BKR-toetsing blijkt dat een klant een doorlopend krediet heeft. Wat doet de kredietgever daarmee?", [["Hij neemt de last van het krediet mee als financiële verplichting", "Lopende kredieten drukken op de betaalcapaciteit en verlagen daardoor de maximale hypotheek."], ["Hij negeert het krediet zolang er geen achterstand bij het BKR is geregistreerd", "Ook zonder achterstand is het krediet een verplichting die meeweegt."], ["Hij verhoogt het toetsinkomen met de kredietlimiet", "Een kredietlimiet is geen inkomen."], ["Hij moet de aanvraag altijd afwijzen", "Een lopend krediet is geen automatische afwijzingsgrond."]]],
["Welk inkomensbestanddeel telt bij een werknemer in loondienst in beginsel mee in het bruto toetsinkomen?", [["Het vakantiegeld", "Het toetsinkomen is het bruto jaarinkomen inclusief vaste componenten zoals vakantietoeslag."], ["Een eenmalige bonus zonder structureel karakter", "Incidentele beloningen zijn niet duurzaam en tellen in beginsel niet mee."], ["De verwachte loonsverhoging over drie jaar", "Toekomstige verhogingen zijn onzeker en tellen niet mee als inkomen."], ["De teruggave van hypotheekrenteaftrek", "Het fiscale voordeel zit al in de financieringslastpercentages en wordt niet bij het inkomen opgeteld."]]],
["Een stel koopt een woning; alleen partner A heeft inkomen. Wat is het belangrijkste doel van een overlijdensrisicoverzekering in het advies?", [["Zorgen dat de partner na overlijden van A de lasten kan dragen", "De dekking wordt zo bepaald dat de schuld na overlijden zo ver daalt dat de lasten bij het inkomen van de nabestaande passen."], ["Zorgen dat de hypotheekrente na overlijden aftrekbaar blijft", "De renteaftrek hangt niet af van een overlijdensrisicoverzekering."], ["De NHG-kostengrens verhogen", "Een verzekering heeft geen invloed op de NHG-kostengrens."], ["Voldoen aan de fiscale aflossingseis voor de lening", "De aflossingseis heeft betrekking op de lening, niet op een verzekering."]]],
["Een werknemer in loondienst wordt langdurig ziek. Hoe verloopt zijn inkomen in hoofdlijnen?", [["Twee jaar loondoorbetaling, daarna mogelijk een lagere WIA-uitkering", "Na de loondoorbetalingsperiode kan het inkomen sterk dalen; dat moet in het hypotheekadvies worden doorgerekend."], ["Hij houdt tot zijn pensioen zijn volledige salaris via de werkgever", "De loondoorbetaling bij ziekte is beperkt tot twee jaar."], ["Hij krijgt direct een WW-uitkering van het UWV", "WW is voor werkloosheid, niet voor ziekte bij een lopend dienstverband."], ["De NHG neemt de maandlasten over vanaf de eerste ziektedag", "NHG betaalt geen maandlasten; zij kan alleen bij gedwongen verkoop een rol spelen."]]],
["Een zzp'er sluit een hypotheek af. Wat is in het advies over arbeidsongeschiktheid bijzonder aandachtspunt?", [["Hij heeft geen WIA-dekking en is aangewezen op eigen voorzieningen", "Zelfstandigen vallen niet onder de WIA; zonder verzekering of buffer kan het inkomen wegvallen."], ["Hij krijgt via de werkgever twee jaar loondoorbetaling", "Een zelfstandige heeft geen werkgever die loon doorbetaalt."], ["Hij is automatisch verzekerd via de NHG-borgtocht", "NHG is geen inkomensverzekering."], ["Zijn hypotheek wordt bij arbeidsongeschiktheid kwijtgescholden", "Arbeidsongeschiktheid leidt niet tot kwijtschelding van de hypotheek."]]],
["Waarvan hangt de duur van een WW-uitkering in hoofdlijnen af?", [["Van het arbeidsverleden van de werknemer", "Hoe langer iemand heeft gewerkt, hoe langer de WW-uitkering kan duren, tot een wettelijk maximum."], ["Van de hoogte van de hypotheek", "De hypotheek heeft geen invloed op de WW-duur."], ["Van de leeftijd van de partner", "De WW is een individuele werknemersverzekering, los van de partner."], ["Van de rentevaste periode van de lening", "De rentevaste periode speelt geen rol bij de WW."]]],
["Twee partners sluiten samen een hypotheek af en gaan na een paar jaar uit elkaar. Wat geldt tegenover de geldverstrekker?", [["Beide partners blijven hoofdelijk aansprakelijk voor de hele schuld tot de geldverstrekker één van hen ontslaat", "De geldverstrekker kan het volledige bedrag van ieder van hen vorderen; de onderlinge afspraken binden de bank niet."], ["Ieder is automatisch alleen aansprakelijk voor de helft van de schuld, naar rato van de eigendom", "Onderling kunnen zij de schuld verdelen, ook naar rato van de eigendom, maar tegenover de geldverstrekker zijn zij hoofdelijk aansprakelijk."], ["Alleen de partner die in de woning blijft, is nog aansprakelijk", "Vertrek uit de woning ontslaat iemand niet van de aansprakelijkheid."], ["De hypotheek vervalt bij een relatiebeëindiging en moet door de achterblijvende partner opnieuw worden afgesloten", "Een relatie-einde laat de bestaande kredietovereenkomst intact."]]],
["Een klant van 58 jaar sluit een hypotheek af met een looptijd tot na zijn AOW-leeftijd. Wat moet de adviseur in elk geval in kaart brengen?", [["Of de lasten na pensionering te dragen zijn met het verwachte AOW- en pensioeninkomen", "Na de AOW-leeftijd daalt het inkomen vaak; het advies moet laten zien of de woonlasten dan betaalbaar blijven."], ["Of de klant vóór zijn pensioen met de overwaarde nog een tweede woning kan kopen", "Een tweede woning is niet relevant voor de betaalbaarheid van deze hypotheek."], ["Of de rente na de AOW-leeftijd automatisch daalt", "Er is geen automatische renteverlaging bij pensionering."], ["Of de Wet Hillen de hypotheekrente na pensionering geheel of gedeeltelijk overneemt", "De Wet Hillen gaat over het eigenwoningforfait, niet over het overnemen van rente."]]],
["Hoe hoort de adviseur risico's zoals overlijden, arbeidsongeschiktheid en werkloosheid in het hypotheekadvies te behandelen?", [["De gevolgen doorrekenen, bespreken en de keuze van de klant vastleggen", "Een passend advies laat zien wat er gebeurt en welke oplossingen er zijn; de klant kiest bewust en dat wordt vastgelegd."], ["Alleen benoemen als de klant er zelf naar vraagt", "Een adviseur moet risico's uit zichzelf onderzoeken en bespreken."], ["Altijd voor elk risico een verzekering verplicht stellen", "Een verzekering is niet altijd nodig; een buffer of acceptatie kan ook passen."], ["Overlaten aan de geldverstrekker, omdat die de kredietwaardigheid toetst", "De kredietwaardigheidstoets vervangt de risicoanalyse van de adviseur niet."]]],
["Welke invloed heeft een gunstig energielabel van de woning op de leencapaciteit volgens de TRHK?", [["Afhankelijk van het label is extra leenruimte mogelijk", "De TRHK geeft extra leenruimte bij zuinigere woningen, omdat de energielasten daar lager zijn."], ["Een gunstig label verhoogt de maximale LTV naar 125%", "Het energielabel verhoogt de LTV niet tot zo'n niveau."], ["Het energielabel heeft geen invloed op de leennormen", "De TRHK houdt wel degelijk rekening met het energielabel."], ["Bij een gunstig label vervalt de toetsrente", "Het label raakt het leenbedrag, niet de toetsrentesystematiek."]]],
["Een klant wil energiebesparende voorzieningen, zoals zonnepanelen en isolatie, meefinancieren. Wat is volgens de leennormen mogelijk?", [["Onder voorwaarden een hypotheek boven 100% van de marktwaarde voor die voorzieningen", "Energiebesparende voorzieningen vormen een uitzondering op de hoofdregel van een LTV van maximaal 100%."], ["Alleen als de voorzieningen al vóór de aankoop zijn aangebracht en in de taxatie zijn meegenomen", "Ook nog aan te brengen voorzieningen kunnen worden meegefinancierd, vaak via een bouwdepot."], ["Nooit, omdat de LTV zonder uitzonderingen 100% is", "De TRHK kent juist voor energiebesparende voorzieningen een uitzondering."], ["Alleen via een persoonlijke lening buiten de hypotheek", "Meefinancieren binnen de hypotheek is juist mogelijk."]]],
["Hoe lang is een geregistreerd energielabel voor een woning geldig?", [["Tien jaar", "Een energielabel voor een woning heeft een geldigheidsduur van tien jaar."], ["Twee jaar", "Zo kort is de geldigheidsduur niet."], ["Vijf jaar", "De geldigheidsduur is langer dan vijf jaar."], ["Onbeperkt geldig", "Een energielabel heeft een beperkte geldigheidsduur."]]],
["Een klant financiert de verduurzaming via de hypotheek en het bedrag wordt in een bouwdepot gestort. Wat is de functie van dat bouwdepot?", [["Uitbetaling volgt pas op facturen voor de afgesproken maatregelen", "Het depot borgt dat het geld voor de voorzieningen wordt gebruikt die de waarde of de energiezuinigheid verbeteren."], ["Het geld wordt direct op de privérekening van de klant gestort", "Juist dat voorkomt het bouwdepot."], ["Het geld wordt belegd tot de rentevaste periode eindigt", "Een bouwdepot is geen beleggingsrekening."], ["Het geld dient als buffer voor betalingsachterstanden", "Een bouwdepot is bestemd voor de verbouwing, niet voor achterstanden."]]],
["Wat regelt de hypothekenrichtlijn (MCD) over koppelverkoop?", [["Koppelverkoop is in beginsel verboden; gebundelde verkoop (los verkrijgbaar) is toegestaan", "Bij koppelverkoop is het krediet niet los verkrijgbaar; dat is verboden. Een bundel waarbij de onderdelen ook los te krijgen zijn, mag wel."], ["Koppelverkoop is altijd toegestaan als de consument vooraf een ESIS met alle productcombinaties heeft gekregen", "Een ESIS maakt verboden koppelverkoop niet toelaatbaar."], ["Elke combinatie van een hypotheek met een ander product is verboden", "Gebundelde verkoop is wel toegestaan."], ["Koppelverkoop is alleen verboden bij hypotheken met NHG", "Het verbod volgt uit de richtlijn en geldt niet alleen bij NHG."]]],
["Waarop mag de kredietwaardigheidsbeoordeling volgens de hypothekenrichtlijn niet hoofdzakelijk worden gebaseerd?", [["Op de verwachting dat de woningwaarde zal stijgen", "De toets moet vooral kijken naar het vermogen van de consument om aan zijn verplichtingen te voldoen, niet op verwachte waardestijging."], ["Op het actuele inkomen van de consument uit loondienst of onderneming", "Het inkomen is juist een kernonderdeel van de beoordeling."], ["Op de vaste lasten en de bestaande verplichtingen van de consument", "Vaste lasten horen bij een goede beoordeling van de betaalcapaciteit."], ["Op de informatie uit het BKR-register", "BKR-informatie is een belangrijke bron en wordt juist gebruikt."]]],
["Wat is een hoofddoel van de hypothekenrichtlijn (MCD)?", [["Een hoog niveau van consumentenbescherming bij hypothecair krediet in de EU", "De MCD harmoniseert onder meer informatie, kredietwaardigheidstoets en vakbekwaamheid om consumenten te beschermen."], ["Het vaststellen van één Europese hypotheekrente voor alle lidstaten van de eurozone", "De MCD stelt geen rentes vast."], ["Het afschaffen van de renteaftrek in alle lidstaten", "Belastingregels zijn nationaal en vallen buiten de MCD."], ["Het vastleggen van één maximale LTV voor woninghypotheken in alle lidstaten", "De MCD schrijft geen LTV-maximum voor; dat is nationaal geregeld."]]],
["Mag een hypotheekadviseur een provisie ontvangen van de geldverstrekker voor de bemiddeling in een hypotheek voor een consument?", [["Nee, voor hypotheken geldt een provisieverbod", "Sinds 2013 mag een adviseur geen provisie van de aanbieder ontvangen voor hypotheken voor consumenten."], ["Ja, mits de provisie in het ESIS wordt vermeld", "Vermelding maakt de provisie niet toegestaan."], ["Ja, als de provisie lager is dan 1% van de hoofdsom", "Er geldt geen drempel; provisie is verboden."], ["Alleen als de klant schriftelijk toestemming geeft", "Toestemming van de klant heft het verbod niet op."]]],
["Een klant wil zo veel mogelijk lenen, ook al blijkt uit de inventarisatie dat de lasten zijn buffer volledig opmaken. Wat verwacht de zorgplicht van de adviseur?", [["Dat hij de risico's bespreekt, passend adviseert en alles vastlegt", "De adviseur moet het belang van de klant voorop stellen en hem wijzen op de gevolgen, ook als dat tegen zijn wens ingaat."], ["Dat hij de wens van de klant zonder commentaar uitvoert en het verschil laat tekenen", "Uitvoeren zonder kritische afweging past niet bij een adviesrelatie."], ["Dat hij de klant naar een andere adviseur verwijst", "Doorverwijzen is niet de verplichting; passend adviseren is dat wel."], ["Dat hij de AFM vooraf om toestemming vraagt", "De AFM geeft geen toestemming in individuele adviezen."]]],
["Waarom benaderen geldverstrekkers klanten met een aflossingsvrije hypotheek actief?", [["Om hen te wijzen op het risico van een onbetaalbare schuld aan het einde", "De AFM heeft aanbieders gevraagd klanten tijdig te wijzen op dit risico, passend bij hun zorgplicht."], ["Om de aflossingsvrije lening verplicht om te zetten in een annuïteitenlening", "Een verplichte omzetting is geen gevolg van deze benadering."], ["Om het overgangsrecht van de klant in te trekken", "Een geldverstrekker kan het fiscale overgangsrecht niet intrekken."], ["Om de woning opnieuw te laten taxeren voor de WOZ-waarde", "De WOZ-waarde wordt door de gemeente vastgesteld."]]],
["Een klant brengt voor de aankoop een groot bedrag eigen geld in waarvan de herkomst onduidelijk is. Wat vraagt de Wwft van de geldverstrekker?", [["De herkomst onderzoeken en zo nodig melden bij FIU-Nederland", "Het cliëntenonderzoek omvat de bron van de middelen; ongebruikelijke transacties moeten aan de FIU worden gemeld."], ["Het geld accepteren omdat het niet geleend is", "Ook eigen geld valt onder het cliëntenonderzoek."], ["De klant direct aangeven bij de politie", "Een Wwft-instelling meldt aan FIU-Nederland, niet rechtstreeks aan de politie."], ["De klant vragen een verklaring van herkomst bij de AFM of de Belastingdienst af te geven", "De AFM en de Belastingdienst geven geen verklaringen over de herkomst van geld af; het onderzoek ligt bij de Wwft-instelling zelf."]]],
["Een Wwft-instelling heeft een ongebruikelijke transactie van een klant gemeld. Mag zij de klant daarover informeren?", [["Nee, de instelling mag de klant niet vertellen dat een melding is gedaan", "De Wwft verbiedt het informeren van de klant over een melding, zodat het onderzoek niet wordt gefrustreerd."], ["Ja, de klant heeft op grond van de AVG altijd recht op inzage in de melding", "Het inzagerecht uit de AVG geldt hier niet; de geheimhoudingsplicht uit de Wwft gaat voor."], ["Ja, maar alleen schriftelijk en pas na afloop van de transactie aan de klant zelf", "Ook na afloop mag de klant niet over de melding worden ingelicht."], ["Alleen als de klant een hypotheek met NHG heeft", "NHG heeft geen enkele invloed op de geheimhoudingsplicht."]]],
["Twee partners kopen samen een woning die zij zelf gaan bewonen, ieder voor de helft. Partner A is 33 jaar, partner B is 37 jaar. De koopsom ligt onder de woningwaardegrens. Wat geldt voor de overdrachtsbelasting?", [["A is vrijgesteld voor zijn helft; B betaalt het verlaagde tarief", "De startersvrijstelling wordt per verkrijger beoordeeld; B voldoet niet aan de leeftijdseis."], ["Beiden zijn vrijgesteld omdat één van hen jonger is dan 35", "De vrijstelling geldt per persoon, niet per huishouden."], ["Beiden betalen het verlaagde tarief, omdat B te oud is", "A verliest zijn vrijstelling niet doordat B er niet aan voldoet."], ["Beiden betalen het algemene tarief omdat zij samen kopen", "Samen kopen is geen reden voor het algemene tarief; zij gaan de woning zelf bewonen."]]],
["Een starter van 28 jaar koopt een woning waarvan de koopsom iets boven de woningwaardegrens voor de startersvrijstelling ligt. Wat is het gevolg?", [["Hij heeft geen recht op de vrijstelling en betaalt over de hele koopsom het verlaagde tarief", "Boven de grens vervalt de vrijstelling volledig; zij geldt niet voor het deel tot de grens."], ["Hij betaalt alleen overdrachtsbelasting over het deel van de koopsom dat boven de woningwaardegrens ligt", "Er is geen gedeeltelijke vrijstelling; de grens werkt als een harde drempel."], ["Hij betaalt het algemene tarief over de hele koopsom", "Voor een woning die hij zelf bewoont, geldt het verlaagde tarief."], ["Hij kan de vrijstelling behouden door de woning binnen een jaar na aankoop te verbouwen", "Een latere verbouwing verandert de koopsom en de toets niet."]]],
["Hoe vaak kan iemand gebruikmaken van de startersvrijstelling in de overdrachtsbelasting?", [["Eenmaal", "De startersvrijstelling kan iedere koper maar één keer in zijn leven benutten."], ["Eenmaal per tien jaar", "Er is geen herhaling na een periode; het is eenmalig."], ["Zo vaak als hij een woning koopt onder de grens", "De vrijstelling is uitdrukkelijk bedoeld voor de eerste aankoop en eenmalig."], ["Tweemaal, eenmaal alleen en eenmaal met een partner", "Ook samen kopen geeft geen tweede kans voor dezelfde persoon."]]]
],
"inkomen":[
["Hoe lang moet een werkgever als hoofdregel het loon doorbetalen aan een zieke werknemer?", [["Maximaal 104 weken", "De loondoorbetalingsplicht bij ziekte duurt als hoofdregel twee jaar (104 weken); daarna kan een WIA-uitkering volgen."], ["Maximaal 52 weken (één jaar)", "Na 52 weken loopt de loondoorbetaling nog door; in die periode vindt de eerstejaarsevaluatie plaats."], ["Maximaal 26 weken", "Zes maanden is veel te kort; de werkgever draagt het risico twee jaar."], ["Maximaal 156 weken (drie jaar)", "Drie jaar is alleen aan de orde bij een loonsanctie of vrijwillige verlenging, niet als hoofdregel."]]],
["Hoeveel loon moet een werkgever op grond van het Burgerlijk Wetboek minimaal doorbetalen tijdens ziekte?", [["70% van het loon, met in het eerste jaar ten minste het minimumloon", "Dit is de wettelijke ondergrens; de 70% geldt tot een maximum en in het eerste ziektejaar mag de werknemer niet onder het minimumloon uitkomen."], ["100% van het loon gedurende de hele periode van twee jaar", "Volledige doorbetaling komt voor op grond van cao of arbeidsovereenkomst, maar is geen wettelijke verplichting."], ["75% van het loon in de eerste twee maanden en daarna 70%", "Deze opbouw hoort bij de WW en de loongerelateerde WGA-uitkering, niet bij loondoorbetaling bij ziekte."], ["70% van het minimumloon, ongeacht het verdiende loon", "De loondoorbetaling is gekoppeld aan het eigen loon van de werknemer, niet aan een percentage van het minimumloon."]]],
["Binnen welke termijn moet volgens de Wet verbetering poortwachter de probleemanalyse door de bedrijfsarts of arbodienst klaar zijn?", [["Binnen zes weken na de ziekmelding", "De probleemanalyse moet uiterlijk in de zesde ziekteweek worden opgesteld, zodat de re-integratie tijdig kan starten."], ["Binnen twee weken na de ziekmelding", "Zo snel hoeft het niet; de wettelijke termijn voor de probleemanalyse is zes weken."], ["Binnen acht weken na de ziekmelding", "Acht weken is de termijn voor het plan van aanpak, dat op de probleemanalyse volgt."], ["Binnen 42 weken na de ziekmelding", "In week 42 volgt de ziekmelding bij het UWV; de probleemanalyse ligt dan al lang klaar."]]],
["Wat moeten werkgever en werknemer uiterlijk in de achtste ziekteweek samen opstellen?", [["Een plan van aanpak voor de re-integratie", "Op basis van de probleemanalyse leggen werkgever en werknemer in het plan van aanpak vast welke stappen worden gezet om terug te keren naar werk."], ["Een re-integratieverslag voor het UWV", "Het re-integratieverslag hoort bij de WIA-aanvraag aan het einde van de wachttijd, niet bij week acht."], ["Een eerstejaarsevaluatie", "De eerstejaarsevaluatie vindt plaats rond het einde van het eerste ziektejaar."], ["Een vaststellingsovereenkomst", "Een vaststellingsovereenkomst regelt een beëindiging van het dienstverband en is geen re-integratie-instrument."]]],
["Wanneer moet een werkgever een langdurig zieke werknemer uiterlijk ziek melden bij het UWV?", [["In de 42e week van de ziekte", "Een werknemer die nog ziek is, moet uiterlijk in week 42 bij het UWV worden gemeld; dat is de zogenoemde 42e-weekmelding."], ["Op de eerste ziektedag", "Op de eerste ziektedag meldt de werknemer zich ziek bij de werkgever; een melding bij het UWV is dan nog niet nodig."], ["In de zesde week van de ziekte", "In week zes moet de probleemanalyse klaar zijn; de melding bij het UWV volgt later."], ["In de 104e week van de ziekte", "In week 104 eindigt de wachttijd; de WIA moet dan al ruim eerder zijn aangevraagd."]]],
["Casus: het UWV stelt bij de WIA-aanvraag van werknemer Sanne vast dat haar werkgever zich onvoldoende heeft ingespannen voor haar re-integratie. Wat is het meest waarschijnlijke gevolg?", [["De werkgever moet als loonsanctie maximaal 52 weken langer loon doorbetalen", "Bij onvoldoende re-integratie-inspanningen kan het UWV de loondoorbetalingsplicht met ten hoogste een jaar verlengen."], ["Sanne krijgt geen WIA-uitkering en verliest haar recht op een uitkering definitief", "De sanctie voor tekortschieten van de werkgever treft de werkgever; het recht van Sanne wordt alleen uitgesteld."], ["De werkgever krijgt een boete van de AFM", "De AFM houdt toezicht op de financiële markten en is niet betrokken bij re-integratie."], ["Het UWV neemt de loondoorbetaling direct over en verhaalt die later op de werkgever", "Het UWV neemt de kosten niet over; juist de werkgever moet langer doorbetalen."]]],
["Wat houdt het 'tweede spoor' bij re-integratie in?", [["Re-integratie bij een andere werkgever", "Als terugkeer bij de eigen werkgever niet lukt, moet worden gezocht naar passend werk buiten het bedrijf: het tweede spoor."], ["Re-integratie in het eigen werk of ander werk bij de eigen werkgever", "Dat is het eerste spoor; de eigen werkgever is altijd het eerste uitgangspunt."], ["Een second opinion van een andere bedrijfsarts", "Een second opinion is een recht van de werknemer, maar heet geen tweede spoor."], ["Een aanvraag voor een deskundigenoordeel bij het UWV", "Een deskundigenoordeel kan helpen bij een meningsverschil, maar is geen re-integratiespoor."]]],
["Casus: werkgever en werknemer verschillen van mening over de vraag of aangeboden werk passend is voor de zieke werknemer. Wat kan elk van beiden aanvragen?", [["Een deskundigenoordeel bij het UWV", "Het UWV kan op verzoek een onafhankelijk deskundigenoordeel geven over onder meer passende arbeid en re-integratie-inspanningen."], ["Een uitspraak van het Kifid", "Het Kifid behandelt klachten over financiële dienstverlening, niet over arbeidsrechtelijke re-integratiegeschillen."], ["Een herbeoordeling door de Belastingdienst", "De Belastingdienst heeft geen rol bij de beoordeling van passende arbeid."], ["Een bindend advies van de verzuimverzekeraar", "Een verzuimverzekeraar is partij voor de werkgever en geeft geen onafhankelijk oordeel tussen werkgever en werknemer."]]],
["Mag een werkgever een werknemer ontslaan alleen omdat die langer dan een jaar ziek is?", [["Nee, in de eerste twee ziektejaren geldt een opzegverbod bij ziekte", "Tijdens de eerste twee jaar van ziekte mag de werkgever de arbeidsovereenkomst in beginsel niet wegens ziekte opzeggen."], ["Ja, na 52 weken ziekte vervalt het opzegverbod", "Het opzegverbod is niet beperkt tot het eerste jaar; het geldt in principe twee jaar."], ["Ja, mits de werkgever een verzuimverzekering heeft afgesloten voor het loonrisico", "Een verzuimverzekering dekt het financiële risico van de werkgever en verandert niets aan het ontslagrecht."], ["Nee, een zieke werknemer kan nooit worden ontslagen, ook niet na twee jaar ziekte", "Ook bij ziekte kan ontslag onder voorwaarden mogelijk zijn, bijvoorbeeld na twee jaar of bij een dringende reden."]]],
["Wat kan het gevolg zijn als een zieke werknemer zonder deugdelijke grond weigert passende arbeid te verrichten?", [["De werkgever kan de loondoorbetaling stopzetten", "Een werknemer die zonder goede reden niet meewerkt aan zijn re-integratie, kan zijn recht op loon (tijdelijk) verliezen."], ["De werknemer krijgt direct een WIA-uitkering", "Weigeren mee te werken leidt niet tot een eerdere uitkering, maar juist tot sancties."], ["De werkgever moet het loon verhogen naar 100%", "Er is geen regel die de werkgever verplicht méér te betalen als de werknemer weigert."], ["Het UWV legt de werkgever een loonsanctie op", "Een loonsanctie treft de werkgever die tekortschiet, niet de situatie waarin de werknemer weigert."]]],
["Hoeveel wachtdagen mogen bij ziekte maximaal worden afgesproken, bijvoorbeeld in een cao?", [["Twee wachtdagen", "Wettelijk mogen maximaal twee wachtdagen worden overeengekomen waarover geen loon wordt doorbetaald."], ["Vijf wachtdagen", "Vijf wachtdagen is wettelijk niet toegestaan; het maximum ligt lager."], ["Veertien wachtdagen", "Veertien dagen is een gebruikelijk eigen risico bij verzuimverzekeringen, geen wettelijke wachttijd voor werknemers."], ["Geen enkele, wachtdagen zijn verboden", "Wachtdagen zijn niet verboden; ze mogen worden afgesproken tot het wettelijk maximum."]]],
["Voor wie is de Ziektewet (ZW) in de eerste plaats bedoeld?", [["Zieke werknemers die geen werkgever (meer) hebben die het loon doorbetaalt", "De ZW is een vangnet, bijvoorbeeld voor zieke WW-gerechtigden en flexwerkers van wie het contract tijdens ziekte afloopt."], ["Alle zieke werknemers vanaf de eerste ziektedag", "Werknemers met een werkgever krijgen loon doorbetaald; de ZW is een vangnet voor specifieke groepen."], ["Zelfstandigen zonder arbeidsongeschiktheidsverzekering", "Zelfstandigen vallen niet onder de ZW; zij moeten zich zelf particulier verzekeren."], ["Werknemers die na twee jaar ziekte minder dan 35% arbeidsongeschikt zijn", "Voor deze groep bestaat geen ZW-uitkering; zij hebben geen recht op WIA en worden geacht te werken."]]],
["Casus: Kees heeft een tijdelijk contract dat afloopt terwijl hij ziek is. Wie zorgt na afloop van het contract voor zijn inkomen bij ziekte?", [["Het UWV via de Ziektewet, tenzij zijn ex-werkgever eigenrisicodrager voor de ZW is", "Na het einde van het dienstverband valt Kees in het vangnet van de ZW; bij eigenrisicodragerschap betaalt de ex-werkgever die uitkering."], ["Zijn ex-werkgever via loondoorbetaling tot het einde van de 104 weken", "Met het einde van het contract eindigt ook de loondoorbetalingsplicht van de werkgever."], ["De gemeente via de Participatiewet", "Bijstand komt pas in beeld als er geen recht is op een werknemersverzekering of ander inkomen."], ["De SVB via de Toeslagenwet", "De Toeslagenwet wordt door het UWV uitgevoerd en vult alleen aan; zij is geen vervanging van de ZW."]]],
["Wat gebeurt er bij de eerstejaars Ziektewet-beoordeling (EZWb) van een vangnetter?", [["Het UWV toetst wat hij nog kan verdienen en of hij daardoor zijn ZW-recht verliest", "Na een jaar ziekte wordt de vangnetter getoetst aan algemeen geaccepteerde arbeid; wie voldoende kan verdienen, verliest de ZW-uitkering."], ["Het UWV beoordeelt of de ex-werkgever een loonsanctie krijgt voor te weinig re-integratie", "Een loonsanctie hoort bij de WIA-aanvraag van een werknemer met werkgever, niet bij de EZWb."], ["Het UWV kent bij een arbeidsongeschiktheid van 80% of meer automatisch een IVA-uitkering toe", "Een IVA-uitkering vraagt een WIA-beoordeling na de wachttijd; de EZWb is daar geen onderdeel van."], ["De bedrijfsarts stelt een plan van aanpak op", "Het plan van aanpak hoort bij het begin van het verzuim, niet bij de beoordeling na een jaar."]]],
["Hoe verhoudt de Ziektewet zich tot de WIA voor een vangnetter die langdurig ziek blijft?", [["De periode van ZW-uitkering telt mee voor de wachttijd van 104 weken voor de WIA", "Ook voor vangnetters geldt een wachttijd van twee jaar; de ZW-periode vult die wachttijd op."], ["De vangnetter moet na de ZW eerst nog twee jaar wachten op de WIA", "De ZW-periode is juist de wachttijd; er komt geen tweede wachttijd achteraan."], ["Een vangnetter heeft nooit recht op een WIA-uitkering", "Vangnetters kunnen na de wachttijd net als andere werknemers een WIA-uitkering krijgen."], ["De ZW loopt altijd door tot de AOW-leeftijd", "De ZW is tijdelijk en duurt maximaal twee jaar; daarna volgt eventueel de WIA."]]],
["Wat is een 'eigenrisicodrager voor de Ziektewet'?", [["Een werkgever die zelf de ZW-uitkeringen en re-integratie van zieke ex-flexwerkers betaalt", "Een ZW-eigenrisicodrager betaalt geen gedifferentieerde ZW-premie aan het UWV, maar draagt zelf het risico voor de vangnetters die van hem afkomstig zijn."], ["Een werknemer die via een eigen verzekering zelf zijn loon in de eerste twee ziektejaren financiert", "Werknemers kunnen geen eigenrisicodrager voor de ZW worden; dat is een keuze van de werkgever."], ["Een zelfstandige die geen AOV heeft gesloten", "Zo'n zelfstandige draagt feitelijk zijn eigen risico, maar heeft niets met de ZW te maken."], ["Een verzekeraar die de ZW-uitkeringen namens het UWV uitvoert voor kleine werkgevers", "Een verzekeraar kan het risico van de werkgever verzekeren, maar de werkgever blijft de eigenrisicodrager."]]],
["Hoe stelt het UWV het arbeidsongeschiktheidspercentage voor de WIA vast?", [["Door het maatmaninkomen te vergelijken met wat hij nog kan verdienen (restverdiencapaciteit)", "Het verlies aan verdiencapaciteit ten opzichte van het maatmaninkomen bepaalt het arbeidsongeschiktheidspercentage."], ["Door het aantal uren dat de werknemer nog werkt te delen door het aantal uren in zijn arbeidsovereenkomst", "De WIA kijkt naar verdiencapaciteit, niet alleen naar het aantal gewerkte uren."], ["Op basis van het oordeel van de behandelend specialist alleen", "De medische beperkingen zijn input; het percentage volgt pas uit de arbeidskundige vergelijking van inkomens."], ["Door de duur van de ziekteperiode in weken om te rekenen naar een percentage van de wachttijd", "Hoe lang iemand ziek is geweest zegt niets over het percentage arbeidsongeschiktheid."]]],
["Wat is het 'maatmaninkomen' in de WIA?", [["Het inkomen dat de werknemer verdiende voordat hij ziek werd", "Het maatmaninkomen is het uitgangspunt waartegen de resterende verdiencapaciteit wordt afgezet."], ["Het inkomen dat een gemiddelde werknemer in Nederland verdient", "Het gaat om het eigen inkomen van de werknemer, niet om een landelijk gemiddelde."], ["Het inkomen dat de werknemer na zijn ziekte nog kan verdienen", "Dat is de resterende verdiencapaciteit, de andere kant van de vergelijking."], ["Het minimumloon dat geldt voor de leeftijd van de werknemer", "Het minimumloon speelt een rol in de WGA-vervolguitkering, maar is niet het maatmaninkomen."]]],
["Casus: na twee jaar ziekte stelt het UWV vast dat Ahmed 28% arbeidsongeschikt is. Wat betekent dit voor de WIA?", [["Ahmed heeft geen recht op een WIA-uitkering", "Onder de 35% arbeidsongeschiktheid bestaat geen recht op een WIA-uitkering; Ahmed wordt geacht zijn resterende capaciteit te benutten."], ["Ahmed krijgt een WGA-uitkering naar rato van 28%", "De WGA begint pas vanaf 35% arbeidsongeschiktheid."], ["Ahmed krijgt een IVA-uitkering omdat hij langer dan twee jaar ziek is", "De IVA is alleen voor volledig en duurzaam arbeidsongeschikten (80% of meer)."], ["Ahmed krijgt de Ziektewet-uitkering zolang hij niet hersteld is", "De ZW loopt niet door na de WIA-beoordeling bij een werknemer met een werkgever."]]],
["Wie heeft recht op een WGA-uitkering?", [["Wie ten minste 35% arbeidsongeschikt is, maar niet volledig én duurzaam", "De WGA is bedoeld voor gedeeltelijk arbeidsongeschikten en voor volledig arbeidsongeschikten met kans op herstel."], ["Uitsluitend wie volledig en duurzaam arbeidsongeschikt is", "Volledig en duurzaam arbeidsongeschikten vallen onder de IVA."], ["Iedereen die na de wachttijd van 104 weken nog ziek is, ongeacht het percentage", "Er is een ondergrens van 35% arbeidsongeschiktheid."], ["Alleen werknemers die na de wachttijd nog in dienst zijn bij hun eigen werkgever", "Ook wie niet meer in dienst is, kan recht hebben op een WGA-uitkering."]]],
["Casus: Lotte is 85% arbeidsongeschikt, maar volgens het UWV is herstel op termijn goed mogelijk. Welke uitkering krijgt zij?", [["Een WGA-uitkering", "Omdat de arbeidsongeschiktheid niet duurzaam is, valt Lotte ondanks het hoge percentage onder de WGA en niet onder de IVA."], ["Een IVA-uitkering", "De IVA vereist naast 80% of meer arbeidsongeschiktheid ook dat herstel niet of nauwelijks te verwachten is."], ["Geen uitkering, omdat herstel mogelijk is", "Kans op herstel sluit een uitkering niet uit; zij bepaalt alleen welke regeling geldt."], ["Een Wajong-uitkering", "De Wajong is voor mensen die al op jonge leeftijd arbeidsongeschikt zijn; dat speelt bij Lotte niet."]]],
["Hoe hoog is de IVA-uitkering?", [["75% van het (gemaximeerde) dagloon", "De IVA bedraagt 75% van het dagloon, waarbij het dagloon is begrensd tot het maximumdagloon."], ["70% van het minimumloon", "Een percentage van het minimumloon hoort bij de WGA-vervolguitkering, niet bij de IVA."], ["100% van het laatstverdiende loon", "De IVA vult het volledige loon niet aan; bovendien geldt een maximumdagloon."], ["70% van het verschil tussen het dagloon en de restverdiencapaciteit", "Deze berekening lijkt op de loonaanvullingsuitkering in de WGA, niet op de IVA."]]],
["Waarvan hangt de duur van de loongerelateerde WGA-uitkering af?", [["Van het arbeidsverleden, op dezelfde manier als bij de WW", "De loongerelateerde fase duurt net als de WW korter of langer afhankelijk van het arbeidsverleden."], ["Van het arbeidsongeschiktheidspercentage dat het UWV vaststelt", "Het percentage bepaalt of iemand in de WGA valt, maar niet hoe lang de loongerelateerde fase duurt."], ["Van de leeftijd: de uitkering loopt door tot de AOW-leeftijd", "De loongerelateerde fase is juist tijdelijk; daarna volgt de vervolgfase."], ["Van de hoogte van het maatmaninkomen", "Het maatmaninkomen bepaalt het percentage, niet de duur van de loongerelateerde uitkering."]]],
["Casus: Mark krijgt een WGA-uitkering. Zijn loongerelateerde uitkering eindigt. Hij benut minder dan de helft van zijn resterende verdiencapaciteit. Welke uitkering krijgt hij daarna?", [["Een WGA-vervolguitkering, gebaseerd op een percentage van het minimumloon", "Wie zijn restcapaciteit onvoldoende benut, krijgt een vervolguitkering die afhangt van de arbeidsongeschiktheidsklasse en het minimumloon; dat is vaak een forse inkomensdaling."], ["Een loonaanvullingsuitkering van 70% van het verschil tussen maatmaninkomen en restverdiencapaciteit", "De loonaanvullingsuitkering is er alleen voor wie ten minste de helft van zijn restverdiencapaciteit benut."], ["Een IVA-uitkering van 75% van het dagloon", "Het eindigen van de loongerelateerde fase verandert niets aan de vraag of iemand duurzaam volledig arbeidsongeschikt is."], ["Een verlengde loongerelateerde uitkering tot de AOW-leeftijd", "De loongerelateerde fase is in duur begrensd en kan niet worden verlengd tot de AOW-leeftijd."]]],
["Welke voorwaarde geldt voor de WGA-loonaanvullingsuitkering?", [["Hij moet ten minste de helft van zijn resterende verdiencapaciteit benutten", "Wie voldoende werkt, krijgt een aanvulling die is gebaseerd op zijn eigen loon; dit stimuleert werkhervatting."], ["De werknemer moet volledig arbeidsongeschikt zijn", "Een volledig arbeidsongeschikte heeft geen restverdiencapaciteit om te benutten."], ["De werknemer moet jonger zijn dan 50 jaar", "Er geldt geen leeftijdsgrens voor de loonaanvullingsuitkering."], ["De werknemer moet minstens tien jaar bij dezelfde werkgever in dienst zijn geweest", "De duur van het dienstverband bij één werkgever is geen voorwaarde."]]],
["Wat is de belangrijkste reden dat een WGA-gerechtigde na de loongerelateerde fase een groot inkomensverlies kan lijden?", [["De vervolguitkering is bij onvoldoende benutting gebaseerd op het minimumloon, niet op het eigen loon", "Dit inkomensgat heet het WGA-hiaat en is de reden voor het bestaan van de WGA-hiaatverzekering."], ["De WGA-uitkering wordt na de loongerelateerde fase altijd stopgezet, ongeacht hoeveel iemand nog werkt", "De uitkering stopt niet, maar wordt in de vervolgfase anders berekend."], ["De werkgever moet vanaf dat moment het eerder doorbetaalde loon terugvorderen", "Een werkgever heeft geen terugvorderingsrecht op eerder betaald loon."], ["Het UWV verrekent vanaf de vervolgfase het eigen vermogen en spaargeld van de werknemer met de uitkering", "Er is geen vermogenstoets in de WGA; die geldt wel in de bijstand."]]],
["Welke drempel wordt in de WIA gehanteerd om 'volledig' arbeidsongeschikt te zijn?", [["80% of meer", "Vanaf 80% arbeidsongeschiktheid is iemand volledig arbeidsongeschikt; bij duurzaamheid volgt de IVA, anders de WGA 80-100."], ["Precies 100%", "Ook wie niet volledig 100% verdiencapaciteit verliest, kan als volledig arbeidsongeschikt gelden."], ["65% of meer", "65% is geen drempel in de WIA."], ["35% of meer", "35% is de ondergrens voor een WIA-uitkering, niet de grens voor volledige arbeidsongeschiktheid."]]],
["Casus: werknemer Ilse is 40% arbeidsongeschikt verklaard en voldoet niet aan de referte-eis. Wat betekent dit voor haar WGA-uitkering?", [["Zij slaat de loongerelateerde fase over en gaat direct naar de vervolgfase", "Wie niet aan de referte-eis voldoet, heeft geen recht op de loongerelateerde uitkering en gaat direct naar de vervolgfase."], ["Zij krijgt geen enkele WIA-uitkering", "Het niet halen van de referte-eis sluit alleen de loongerelateerde fase uit, niet de hele WGA."], ["Zij krijgt als compensatie een IVA-uitkering van 75% van het dagloon", "De IVA hangt af van volledige en duurzame arbeidsongeschiktheid, niet van de referte-eis."], ["Zij moet eerst nog een jaar Ziektewet-uitkering ontvangen voordat de WGA ingaat", "De referte-eis zegt niets over een extra periode in de Ziektewet."]]],
["Wie is in de WIA een '35-minner'?", [["Een werknemer die na de wachttijd minder dan 35% arbeidsongeschikt is", "Deze werknemer krijgt geen WIA-uitkering; de werkgever wordt geacht passend werk te bieden of de werknemer kan elders werk zoeken."], ["Een werknemer die jonger is dan 35 jaar en al een WIA-uitkering ontvangt", "De term verwijst naar het arbeidsongeschiktheidspercentage, niet naar de leeftijd."], ["Een werknemer die minder dan 35 uur per week werkt", "Het aantal contracturen staat los van deze term."], ["Een werknemer die korter dan 35 weken ziek is geweest vóór de WIA-aanvraag", "De term heeft niets met de ziekteduur te maken."]]],
["Wat geldt voor de verdiencapaciteit die het UWV vaststelt voor de WIA?", [["Het UWV gaat uit van geduide functies die hij nog kan vervullen, ook zonder baan", "De beoordeling is gebaseerd op geduide functies op de arbeidsmarkt, los van de vraag of de werknemer een baan vindt."], ["Het UWV kijkt alleen naar passende functies die bij de eigen werkgever beschikbaar zijn", "Bij de WIA-beoordeling wordt de hele arbeidsmarkt betrokken, niet alleen de eigen werkgever."], ["Het UWV gaat uit van het werk dat de werknemer zelf het liefst wil doen na zijn herstel", "Persoonlijke voorkeur speelt geen rol; het gaat om wat hij nog kan."], ["Het UWV kijkt alleen naar het eigen beroep dat de werknemer vóór zijn ziekte uitoefende", "Een beroepsarbeidsongeschiktheidscriterium hoort bij sommige particuliere AOV's, niet bij de WIA."]]],
["Voor wie is de Wajong bedoeld?", [["Wie vóór zijn 18e of tijdens een studie arbeidsongeschikt is geworden", "De Wajong is voor jonggehandicapten: wie vóór zijn 18e, of tijdens een studie vóór zijn 30e, langdurig ziek of gehandicapt raakt."], ["Werknemers die na twee jaar ziekte niet volledig herstellen van hun aandoening", "Zij vallen onder de WIA, niet onder de Wajong."], ["Zelfstandigen jonger dan 30 jaar zonder AOV", "Zelfstandig ondernemerschap geeft geen recht op de Wajong."], ["Jongeren die na het afronden van hun opleiding geen baan kunnen vinden", "Werkloosheid zonder arbeidsongeschiktheid geeft geen recht op de Wajong."]]],
["Wat geldt sinds 2015 voor nieuwe instroom in de Wajong?", [["Alleen wie duurzaam geen arbeidsvermogen heeft, kan nog Wajong krijgen", "Sinds de invoering van de Participatiewet is de Wajong beperkt tot jonggehandicapten zonder arbeidsvermogen; anderen vallen onder de gemeente."], ["Iedere jonggehandicapte krijgt een Wajong-uitkering tot de leeftijd van 27 jaar", "Er bestaat geen algemene Wajong-uitkering meer voor iedere jonggehandicapte."], ["De Wajong is in 2015 volledig afgeschaft", "De Wajong bestaat nog, maar alleen voor een beperkte groep."], ["De Wajong wordt sinds 2015 door de SVB uitgevoerd", "De Wajong wordt uitgevoerd door het UWV."]]],
["Welke instantie voert de Wajong uit?", [["Het UWV", "Het UWV beoordeelt het recht op Wajong en betaalt de uitkering."], ["De gemeente", "De gemeente is verantwoordelijk voor jonggehandicapten met arbeidsvermogen via de Participatiewet, niet voor de Wajong zelf."], ["De SVB", "De SVB voert volksverzekeringen zoals AOW en Anw uit."], ["Het Zorginstituut Nederland", "Het Zorginstituut houdt zich bezig met het basispakket van de zorgverzekering."]]],
["Wat is de referte-eis in de WW?", [["In de 36 weken vóór werkloosheid ten minste 26 weken hebben gewerkt", "Wie aan de referte-eis voldoet, heeft recht op een basis-WW-uitkering."], ["In de vijf jaar vóór werkloosheid ten minste vier jaar hebben gewerkt", "Dat lijkt op de jareneis, die bepaalt of iemand recht heeft op een langere WW."], ["Ten minste één jaar bij de laatste werkgever in dienst zijn geweest", "De referte-eis kijkt naar gewerkte weken, ongeacht bij welke werkgever."], ["Ten minste 26 weken WW-premie zelf hebben betaald", "De WW-premie wordt door de werkgever afgedragen; de referte-eis gaat over gewerkte weken."]]],
["Casus: Jeroen neemt zonder dringende reden zelf ontslag om een wereldreis te maken. Na terugkomst vraagt hij WW aan. Wat is het uitgangspunt?", [["Hij heeft geen recht op WW, want hij is verwijtbaar werkloos", "Wie zonder goede reden zelf ontslag neemt, is verwijtbaar werkloos en krijgt geen WW."], ["Hij heeft recht op WW, maar pas na een wachttijd van drie maanden", "Een wachttijd vervangt het verval van het recht niet; bij verwijtbare werkloosheid is er geen uitkering."], ["Hij heeft recht op WW, omdat hij aan de referte-eis voldoet", "Voldoen aan de referte-eis is niet voldoende als de werkloosheid verwijtbaar is."], ["Hij heeft recht op een halve WW-uitkering", "Een gedeeltelijke uitkering is niet de sanctie bij verwijtbare werkloosheid."]]],
["Hoe wordt inkomen uit werk tijdens een WW-uitkering verrekend?", [["70% van het inkomen wordt verrekend met de WW-uitkering", "Door slechts 70% te verrekenen loont het om tijdens de WW (gedeeltelijk) te werken."], ["Het verdiende inkomen wordt volledig in mindering gebracht", "Volledige verrekening zou werken ontmoedigen; de WW verrekent 70%."], ["Inkomen uit werk wordt niet verrekend", "Inkomen uit werk tijdens de WW wordt wel degelijk verrekend."], ["De WW stopt zodra er enig inkomen wordt verdiend", "De WW stopt niet direct; er wordt verrekend en pas bij voldoende inkomen eindigt de uitkering."]]],
["Waarvan hangt de duur van de WW-uitkering af?", [["Van het arbeidsverleden van de werknemer", "Hoe langer het arbeidsverleden, hoe langer de WW, tot het wettelijke maximum."], ["Van de hoogte van het laatstverdiende loon", "Het loon bepaalt de hoogte van de uitkering via het dagloon, niet de duur."], ["Van de leeftijd van de werknemer alleen", "Leeftijd is geen zelfstandige factor voor de duur; het arbeidsverleden is bepalend."], ["Van de reden van het ontslag", "De reden van ontslag bepaalt of er recht is, niet hoe lang de uitkering duurt."]]],
["Casus: Fatima verliest door een reorganisatie 12 van haar 32 contracturen. Kan zij in beginsel WW krijgen?", [["Ja, zij verliest ten minste vijf uur per week en kan voor die uren WW krijgen", "Ook gedeeltelijke werkloosheid kan recht geven op WW als het urenverlies groot genoeg is en aan de overige voorwaarden is voldaan."], ["Nee, WW is alleen mogelijk als alle contracturen tegelijk vervallen", "De WW kent ook gedeeltelijke werkloosheid."], ["Nee, zij moet eerst minstens de helft van haar contracturen per week verliezen", "Die halveringsregel geldt alleen voor werknemers die minder dan tien uur per week werkten."], ["Ja, maar alleen als zij ouder is dan 50 jaar", "Leeftijd is geen voorwaarde voor recht op WW."]]],
["Casus: Peter (45) overlijdt. Zijn vrouw Marieke (43) werkt fulltime, is niet arbeidsongeschikt en hun kinderen zijn 19 en 21 jaar. Heeft Marieke recht op een Anw-uitkering?", [["Nee, er is geen kind onder de 18 en zij is niet arbeidsongeschikt", "Zonder kind onder de 18, zonder 45% arbeidsongeschiktheid en geboren na 1950 heeft Marieke geen recht op een Anw-nabestaandenuitkering."], ["Ja, iedere nabestaande partner krijgt een Anw-uitkering tot de AOW-leeftijd", "De Anw kent strikte toegangsvoorwaarden; niet iedere partner heeft recht."], ["Ja, maar alleen tot het jongste kind de leeftijd van 21 jaar bereikt", "De leeftijdsgrens voor kinderen in de Anw ligt bij 18 jaar, en die is hier al gepasseerd."], ["Ja, omdat zij minder verdient dan Peter", "Een inkomensverschil tussen partners geeft geen recht op Anw."]]],
["Welk inkomen wordt NIET verrekend met een Anw-nabestaandenuitkering?", [["Een uitkering uit een particuliere ORV", "Uitkeringen uit een particuliere ORV worden niet gekort op de Anw; daardoor is een ORV goed te combineren met een Anw-recht."], ["Inkomen uit arbeid in loondienst of als zelfstandige", "Inkomen uit arbeid wordt (deels) verrekend met de Anw-uitkering."], ["Een WIA-uitkering na langdurige arbeidsongeschiktheid", "Uitkeringen die het inkomen uit arbeid vervangen, worden in de Anw wel verrekend."], ["Een ZW-uitkering bij ziekte als vangnetter", "Ook een ZW-uitkering vervangt loon en wordt verrekend met de Anw."]]],
["Wanneer eindigt een Anw-nabestaandenuitkering in elk geval?", [["Bij het bereiken van de AOW-leeftijd", "Vanaf de AOW-leeftijd ontvangt de nabestaande AOW en eindigt de Anw."], ["Na precies vijf jaar", "De Anw is niet in tijd begrensd tot vijf jaar; het recht hangt af van de voorwaarden."], ["Wanneer de nabestaande gaat verhuizen", "Verhuizen binnen Nederland heeft geen invloed op het recht op Anw."], ["Wanneer de nabestaande een erfenis ontvangt", "De Anw kent geen vermogenstoets; een erfenis beëindigt de uitkering niet."]]],
["Wat gebeurt er met een Anw-nabestaandenuitkering als de nabestaande gaat samenwonen of hertrouwt?", [["De uitkering stopt", "Bij een nieuw huwelijk of samenwonen met een nieuwe partner eindigt het recht op Anw."], ["De uitkering loopt ongewijzigd door", "Een nieuwe relatie met gezamenlijke huishouding beëindigt juist het recht."], ["De uitkering wordt gehalveerd", "Er is geen halvering; het recht eindigt."], ["De uitkering gaat over op de nieuwe partner", "Een Anw-uitkering is persoonlijk en gaat nooit over op een nieuwe partner."]]],
["Tot welke leeftijd heeft een wees in beginsel recht op een Anw-wezenuitkering?", [["Tot 16 jaar; bij studie of arbeidsongeschiktheid tot 21 jaar", "Na 16 jaar loopt de wezenuitkering alleen door bij bijvoorbeeld een opleiding of arbeidsongeschiktheid, tot uiterlijk 21 jaar."], ["Tot 18 jaar, ongeacht of de wees nog studeert, werkt of arbeidsongeschikt is", "18 jaar is de leeftijdsgrens voor het kind bij de nabestaandenuitkering van de partner, niet bij de wezenuitkering."], ["Tot 27 jaar als de wees een voltijdopleiding volgt", "27 jaar is geen grens in de Anw."], ["Levenslang als beide ouders zijn overleden (volle wees)", "De wezenuitkering is altijd tijdelijk."]]],
["Waarvoor dient een Anw-hiaatverzekering?", [["Het gat dekken als er geen of maar een beperkt recht op Anw is", "Een Anw-hiaatverzekering keert uit bij overlijden en vult het ontbrekende Anw-recht aan, vaak aangeboden via de pensioenregeling."], ["Om het verschil tussen WW en het laatstverdiende loon te dekken", "Dat gat heeft niets met overlijden te maken en wordt niet door een Anw-hiaatverzekering gedekt."], ["Om de AOW van de langstlevende te verhogen", "De Anw-hiaatverzekering stopt in de regel bij de AOW-leeftijd en verhoogt de AOW niet."], ["Om uitvaartkosten te betalen", "Uitvaartkosten worden gedekt door een uitvaartverzekering."]]],
["Casus: Yvonne en Bas wonen ongehuwd samen in een koopwoning. Ze hebben geen samenlevingscontract en geen testament. Bas overlijdt. Wat is het grootste risico voor Yvonne?", [["Zij erft niet van Bas, omdat zij zonder testament geen wettelijk erfgenaam is", "Ongehuwd samenwonenden erven niet automatisch van elkaar; een testament, samenlevingscontract en (kruislingse) ORV zijn daarom belangrijk."], ["Zij moet de gezamenlijke hypotheek binnen een maand na het overlijden volledig aflossen", "Een overlijden leidt niet automatisch tot een directe aflossingsplicht."], ["Zij verliest automatisch haar eigen pensioen", "Haar eigen pensioenopbouw blijft gewoon bestaan."], ["Zij moet de Anw-uitkering die Bas ontving terugbetalen", "Bas ontving geen Anw-uitkering; dat speelt hier niet."]]],
["Hoeveel AOW-opbouw mist iemand per jaar dat hij in de 50 jaar vóór zijn AOW-leeftijd niet in Nederland woonde of werkte?", [["2% per jaar", "De AOW wordt opgebouwd over 50 jaar, met 2% per verzekerd jaar; elk niet-verzekerd jaar kost 2% van de volledige AOW."], ["1% per jaar", "Bij 1% zou de opbouw 100 jaar duren; de AOW-periode is 50 jaar."], ["5% per jaar", "5% per jaar past niet bij een opbouwperiode van 50 jaar."], ["Niets, de AOW wordt altijd volledig uitgekeerd", "Wie niet verzekerd was, krijgt een gekorte AOW."]]],
["Hoe is de hoogte van de AOW voor gehuwden en samenwonenden op hoofdlijnen geregeld ten opzichte van alleenstaanden?", [["Gehuwden krijgen elk minder AOW dan een alleenstaande, omdat zij lasten delen", "Gehuwden en samenwonenden krijgen elk ongeveer 50% van het netto minimumloon, een alleenstaande ongeveer 70%."], ["Gehuwden krijgen samen evenveel als één alleenstaande", "Samen krijgen gehuwden meer dan één alleenstaande."], ["Gehuwden en alleenstaanden krijgen exact dezelfde AOW, ongeacht hun woonsituatie", "De AOW houdt rekening met de leefsituatie."], ["Alleen de oudste partner krijgt AOW voor het hele huishouden", "Iedere partner heeft een eigen recht op AOW vanaf zijn eigen AOW-leeftijd."]]],
["Casus: Hans bereikt dit jaar de AOW-leeftijd. Zijn vrouw Ellen is acht jaar jonger en heeft geen inkomen. Wat is het uitgangspunt voor hun AOW?", [["Hans krijgt een AOW voor gehuwden; voor Ellen is er geen partnertoeslag meer", "De AOW-partnertoeslag is per 2015 afgeschaft; het huishouden kan dus een inkomensgat hebben tot Ellen zelf AOW krijgt."], ["Hans krijgt een AOW voor alleenstaanden tot Ellen de AOW-leeftijd bereikt", "Gehuwden krijgen de AOW voor gehuwden, ook als de partner nog geen AOW ontvangt."], ["Ellen krijgt direct ook AOW omdat haar man AOW krijgt", "AOW is een persoonlijk recht dat ingaat op de eigen AOW-leeftijd."], ["Hans krijgt een partnertoeslag van de SVB tot Ellen AOW krijgt", "De partnertoeslag bestaat niet meer voor wie na 2014 AOW-gerechtigd werd."]]],
["Waarop is de stijging van de AOW-leeftijd gebaseerd?", [["Op de ontwikkeling van de levensverwachting", "De AOW-leeftijd is wettelijk gekoppeld aan de gemiddelde resterende levensverwachting en wordt enkele jaren vooruit vastgesteld."], ["Op de hoogte van de inflatie", "Inflatie beïnvloedt de hoogte van de AOW-bedragen, niet de AOW-leeftijd."], ["Op de dekkingsgraad van pensioenfondsen", "De dekkingsgraad gaat over pensioenfondsen, niet over de AOW."], ["Op het aantal gewerkte jaren van de persoon zelf", "De AOW-leeftijd is voor iedereen van dezelfde geboortedatum gelijk."]]],
["Welk arbeidsongeschiktheidscriterium in een AOV biedt de zelfstandige de ruimste dekking?", [["Beroepsarbeidsongeschiktheid", "Bij dit criterium is de verzekerde al arbeidsongeschikt als hij zijn eigen beroep niet meer kan uitoefenen, ook als hij ander werk nog wel kan doen."], ["Passende arbeidsongeschiktheid", "Bij passende arbeid wordt ook gekeken naar ander werk dat past bij opleiding en ervaring; dat is beperkter dan het eigen beroep."], ["Gangbare arbeidsongeschiktheid", "Bij gangbare arbeid wordt getoetst aan vrijwel alle algemeen geaccepteerde arbeid; dat is het smalste criterium."], ["Arbeidsongeschiktheid volgens de WIA-maatstaf", "De WIA-maatstaf kijkt naar de hele arbeidsmarkt en is daardoor juist beperkt voor de verzekerde."]]],
["Casus: tandarts Floor kan door een handblessure haar beroep niet meer uitoefenen, maar zou wel als docent tandheelkunde kunnen werken. Bij welke AOV-dekking krijgt zij het meest waarschijnlijk een uitkering?", [["Bij een dekking op basis van beroepsarbeidsongeschiktheid", "Floor kan haar eigen beroep niet meer uitoefenen; bij een beroepsdekking is dat voldoende voor een uitkering."], ["Bij een dekking op basis van passende arbeid", "Werk als docent tandheelkunde past bij haar opleiding en ervaring, waardoor een passende-arbeiddekking mogelijk niet of minder uitkeert."], ["Bij een dekking op basis van gangbare arbeid", "Bij gangbare arbeid wordt ook naar ander algemeen werk gekeken; dat dekt haar situatie het minst."], ["Bij elke dekking in gelijke mate, omdat het criterium niet uitmaakt", "Het arbeidsongeschiktheidscriterium bepaalt juist aan welk werk Floor wordt getoetst en dus of en hoeveel er wordt uitgekeerd."]]],
["Wat is het effect van een langere wachttijd (eigenrisicoperiode) in een AOV?", [["Lagere premie, maar de verzekerde moet de eerste periode zelf overbruggen", "Een langere wachttijd verkleint het risico voor de verzekeraar; de zelfstandige moet wel voldoende buffer hebben."], ["De premie wordt hoger, omdat de verzekeraar over een langere periode moet uitkeren", "Bij een langere wachttijd begint de uitkering later; de premie daalt juist."], ["De uitkering wordt hoger als compensatie voor het wachten", "De hoogte van de uitkering hangt af van het verzekerde bedrag, niet van de wachttijd."], ["Er verandert niets aan premie of dekking", "De wachttijd is een belangrijke premiebepalende factor."]]],
["Casus: Dirk is zelfstandig loodgieter met een spaarbuffer van zes maanden vaste lasten. Hij wil zo min mogelijk premie betalen voor zijn AOV. Welke keuze ligt het meest voor de hand?", [["Een langere wachttijd kiezen die past bij zijn buffer", "Met zijn buffer kan Dirk de eerste maanden zelf overbruggen; een langere wachttijd verlaagt de premie aanzienlijk."], ["Een zo kort mogelijke wachttijd kiezen", "Een korte wachttijd geeft de hoogste premie, terwijl Dirk zijn buffer dan niet benut."], ["Het verzekerd bedrag hoger zetten dan zijn inkomen", "Oververzekeren verhoogt de premie en wordt door verzekeraars beperkt."], ["De eindleeftijd van de AOV zo hoog mogelijk kiezen", "Een hogere eindleeftijd verlengt de dekking, maar verhoogt juist de premie."]]],
["Waarom accepteren verzekeraars bij een AOV doorgaans geen verzekerd bedrag dat gelijk is aan of hoger is dan het volledige inkomen?", [["Om oververzekering te voorkomen en de prikkel tot werkhervatting te behouden", "Als een uitkering even hoog of hoger is dan het inkomen, verdwijnt de financiële prikkel om weer aan het werk te gaan."], ["Omdat de Wft een maximum van 50% van het inkomen voorschrijft", "De Wft schrijft geen maximumpercentage voor het verzekerd bedrag voor."], ["Omdat de Belastingdienst een hogere uitkering niet toestaat", "Fiscaal is er geen verbod; het maximum is een acceptatiebeleid van verzekeraars."], ["Omdat de premie anders niet aftrekbaar is", "De aftrekbaarheid van de premie hangt niet af van de verhouding tussen verzekerd bedrag en inkomen."]]],
["Wat is het verschil tussen een AOV als sommenverzekering en als schadeverzekering?", [["Sommen: een vooraf afgesproken bedrag; schade: vergoeding van het werkelijke inkomensverlies", "Bij een schadeverzekering moet de verzekerde het inkomensverlies aantonen; bij een sommenverzekering hangt de uitkering af van het verzekerde bedrag en het AO-percentage."], ["Een sommenverzekering keert alleen uit bij overlijden", "Uitkeren bij overlijden is kenmerkend voor een ORV, niet voor het verschil tussen sommen- en schadeverzekeringen."], ["Bij een schadeverzekering is de premie altijd fiscaal aftrekbaar en bij een sommenverzekering nooit", "De fiscale behandeling hangt niet af van dit onderscheid."], ["Een schadeverzekering heeft nooit een wachttijd", "Ook een AOV op schadebasis kent een wachttijd."]]],
["Wat houdt een gezondheidsclausule (uitsluiting) in een AOV in?", [["Arbeidsongeschiktheid door een vooraf bekende aandoening is niet gedekt", "Bij een bestaand gezondheidsrisico kan de verzekeraar de dekking accepteren onder uitsluiting van die aandoening."], ["De verzekerde moet jaarlijks een medische keuring bij de verzekeraar ondergaan", "Een jaarlijkse keuring is geen standaardonderdeel van een AOV of uitsluiting."], ["De verzekeraar mag de polis op elk moment opzeggen", "Een uitsluiting gaat over de dekking, niet over een opzeggingsrecht."], ["De premie wordt altijd verdubbeld", "Een premieopslag is een ander instrument dan een uitsluiting en is niet vast verdubbeld."]]],
["Casus: een AOV dekt arbeidsongeschiktheid vanaf 25%. Zelfstandige Jan is volgens de verzekeraar 20% arbeidsongeschikt. Wat is het gevolg?", [["Jan krijgt geen uitkering, want hij blijft onder de polisdrempel", "De uitkering begint pas als het in de polis afgesproken minimum-AO-percentage wordt gehaald."], ["Jan krijgt 20% van het verzekerd bedrag, naar rato van zijn arbeidsongeschiktheid", "Onder de polisdrempel wordt niet uitgekeerd, ook niet naar rato."], ["Jan krijgt 25% van het verzekerd bedrag, het minimum volgens de polis", "Een uitkering naar de drempel zelf bestaat niet; hij is minder arbeidsongeschikt dan de drempel."], ["Jan krijgt een uitkering uit de WIA", "Als zelfstandige is Jan in de regel niet verzekerd voor de WIA."]]],
["Wat is een broodfonds?", [["Een groep zelfstandigen die elkaar bij ziekte tijdelijk steunt met schenkingen", "Een broodfonds is geen verzekering; deelnemers storten maandelijks en schenken een zieke deelnemer een tijdelijk inkomen."], ["Een verplichte publieke AOV voor zelfstandigen, uitgevoerd door het UWV", "Een broodfonds is vrijwillig en wordt door de deelnemers zelf georganiseerd."], ["Een AOV van een verzekeraar met een korte uitkeringsduur van maximaal twee jaar", "Een broodfonds is geen verzekeringsproduct van een verzekeraar."], ["Een spaarrekening bij de bank voor ondernemers", "Een broodfonds werkt als collectief van schenkingen, niet als individuele spaarrekening."]]],
["Casus: Ruud is directeur-grootaandeelhouder (dga) van zijn eigen bv en is niet verzekerd voor de werknemersverzekeringen. Wat volgt hieruit voor zijn inkomensadvies?", [["Hij valt buiten ZW en WIA en moet zijn arbeidsongeschiktheidsrisico zelf regelen", "Een dga die niet verzekerd is voor de werknemersverzekeringen, valt buiten ZW, WIA en WW; een AOV ligt dan voor de hand."], ["De bv betaalt hem verplicht twee jaar loon door en daarna volgt een WIA-uitkering van het UWV", "Zonder werknemersverzekeringen is er geen WIA na twee jaar."], ["Hij krijgt bij arbeidsongeschiktheid een Wajong-uitkering", "De Wajong is voor jonggehandicapten en niet bedoeld voor dga's."], ["Hij is automatisch verzekerd via de AOW", "De AOW is een ouderdomsvoorziening en dekt geen arbeidsongeschiktheid."]]],
["Wat is op hoofdlijnen de bedoeling van de voorgenomen basisverzekering arbeidsongeschiktheid voor zelfstandigen?", [["Een verplichte publieke basisdekking rond minimumloonniveau, met ruimte om particulier aan te vullen", "Het kabinet werkt aan een verplichte basisdekking voor zelfstandigen; voor een inkomen boven dat niveau of een kortere wachttijd blijft een particuliere AOV nodig. Controleer de actuele stand van het wetsvoorstel."], ["Een verplichte particuliere AOV op beroepsbasis voor alle zelfstandigen, uit te voeren door verzekeraars", "De basisverzekering is een publieke regeling en geen verplichte particuliere beroepsdekking."], ["Een vrijwillige spaarregeling via de Belastingdienst", "Het gaat om een verzekering tegen langdurige arbeidsongeschiktheid, niet om een spaarregeling."], ["Een uitbreiding van de Wajong naar alle zelfstandigen zonder eigen AOV", "De Wajong blijft voor jonggehandicapten; de basisverzekering is een aparte regeling."]]],
["Casus: zzp'er Noor vraagt of zij haar AOV kan opzeggen omdat 'er toch een verplichte verzekering komt'. Wat is een zorgvuldig advies?", [["Niet opzeggen: de regeling is er nog niet en biedt straks alleen een basisniveau na lange wachttijd", "Zolang de regeling niet in werking is, is Noor niet verzekerd; ook daarna is aanvulling vaak nodig voor inkomen boven het basisniveau en de eerste periode."], ["Opzeggen, omdat de basisverzekering met terugwerkende kracht dekking geeft vanaf de aankondiging", "Er is geen aanwijzing dat de regeling met terugwerkende kracht dekking biedt."], ["Opzeggen, omdat de basisverzekering het volledige inkomen vervangt", "De voorgenomen uitkering is juist een basisniveau en vervangt een hoger inkomen niet volledig."], ["Opzeggen en het geld sparen, omdat deelname aan een broodfonds wettelijk verplicht wordt voor zzp'ers", "Een broodfonds wordt niet wettelijk verplicht."]]],
["Wat dekt een WIA-excedentverzekering?", [["Het inkomensverlies over het deel van het loon boven het maximumdagloon", "De WIA verzekert alleen loon tot het maximumdagloon; de excedentverzekering vult het verlies over het meerdere aan."], ["Het inkomensverlies tijdens de eerste twee ziektejaren", "In de eerste twee jaar betaalt de werkgever loon door; dat gat dekt de excedentverzekering niet."], ["Het inkomensverlies bij werkloosheid boven de WW", "Werkloosheid valt buiten de WIA-excedentverzekering."], ["De uitvaartkosten bij overlijden na arbeidsongeschiktheid", "Uitvaartkosten worden gedekt door een uitvaartverzekering."]]],
["Casus: Marloes verdient ruim boven het maximumdagloon en haar werkgever biedt een collectieve WGA-hiaatverzekering, maar geen WIA-excedentverzekering. Welk risico blijft voor haar bestaan?", [["Haar loon boven het maximumdagloon is bij arbeidsongeschiktheid onverzekerd", "De WGA-hiaatverzekering vult het gat tot het niveau van het (gemaximeerde) WIA-loon aan; voor het loon daarboven is een excedentdekking nodig."], ["Zij is niet verzekerd tijdens de eerste twee ziektejaren", "In de eerste twee jaar geldt de loondoorbetaling door de werkgever."], ["Zij krijgt geen WGA-uitkering, omdat haar loon boven het maximumdagloon ligt", "Een hoog inkomen sluit de WGA niet uit; alleen het dagloon is gemaximeerd."], ["Haar WGA-hiaatverzekering vervalt bij een hoog inkomen", "Een hoog inkomen is geen vervalgrond van de WGA-hiaatverzekering."]]],
["Wanneer komt een WGA-hiaatverzekering in de regel tot uitkering?", [["Als de werknemer in de WGA-vervolgfase een uitkering op minimumloonniveau krijgt", "De WGA-hiaatverzekering vult de vaak lage vervolguitkering aan; dat is het WGA-hiaat."], ["Vanaf de eerste ziektedag", "In de eerste twee jaar is er loondoorbetaling en is er nog geen WGA."], ["Alleen bij een IVA-uitkering", "Bij de IVA is er geen WGA-vervolgfase, en dus geen WGA-hiaat."], ["Alleen als de werknemer na de wachttijd minder dan 35% arbeidsongeschikt is verklaard", "Onder de 35% is er geen WGA-uitkering; daarvoor bestaan aparte 'WIA 35-min'-dekkingen."]]],
["Hoe wordt een uitkering uit een collectieve WIA-excedentverzekering die via de werkgever loopt fiscaal in de regel behandeld?", [["Als belast inkomen in box 1", "Uitkeringen die het inkomen vervangen, worden belast als inkomen; bij een werkgeversregeling vaak als loon."], ["Als belastingvrije schadevergoeding", "Een inkomensvervangende uitkering is geen onbelaste schadevergoeding."], ["Als vermogen in box 3", "Box 3 is niet van toepassing op periodieke inkomensvervangende uitkeringen."], ["Als inkomen uit aanmerkelijk belang in box 2", "Box 2 gaat over inkomsten uit een aanmerkelijk belang, zoals dividend."]]],
["Wat dekt een verzuimverzekering?", [["Het loondoorbetalingsrisico van de werkgever bij ziekte van werknemers", "Een verzuimverzekering vergoedt de werkgever (een deel van) het doorbetaalde loon tijdens de eerste twee ziektejaren."], ["De WIA-uitkering van de werknemer zodra de wachttijd van twee jaar is verstreken", "Na twee jaar is er geen verzuim meer maar WIA; daarvoor bestaan andere verzekeringen."], ["Het inkomensverlies van een zelfstandige bij ziekte", "Een zelfstandige verzekert zich met een AOV, niet met een verzuimverzekering."], ["De kosten van de werknemer voor medische behandeling", "Medische kosten vallen onder de zorgverzekering."]]],
["Casus: een kleine werkgever met vijf werknemers twijfelt of hij een verzuimverzekering nodig heeft. Welk argument weegt het zwaarst?", [["Eén langdurig zieke werknemer kost hem tot twee jaar loon, plus vaak een vervanger", "Voor een kleine werkgever kan één langdurig zieke werknemer een grote financiële last zijn; een verzuimverzekering spreidt dat risico."], ["Een verzuimverzekering is voor iedere werkgever wettelijk verplicht", "Een verzuimverzekering is niet verplicht; de werkgever kan het risico ook zelf dragen."], ["Zonder verzuimverzekering hoeft hij het loon niet door te betalen", "De loondoorbetalingsplicht geldt los van de vraag of de werkgever verzekerd is."], ["Een verzuimverzekering neemt de verplichtingen uit de Wet verbetering poortwachter over", "De re-integratieplichten blijven gelden, ook als de werkgever verzekerd is."]]],
["Wat houdt een stop-loss-verzuimverzekering in?", [["De werkgever draagt het verzuim zelf tot een maximumbedrag; de verzekeraar betaalt het meerdere", "Stop-loss beschermt de werkgever tegen uitschieters, terwijl hij het 'normale' verzuim zelf betaalt."], ["De verzekeraar vergoedt alle verzuimkosten vanaf de eerste dag", "Volledige vergoeding vanaf dag één is geen stop-loss, maar een uitgebreide dekking zonder eigen risico."], ["De verzekering stopt automatisch zodra een werknemer langer dan een jaar ziek is gebleven", "Stop-loss verwijst naar het begrenzen van het verlies, niet naar het stoppen van de dekking."], ["De werknemer betaalt de premie via zijn loon en de werkgever ontvangt de uitkeringen bij verzuim", "De premie van een verzuimverzekering is voor rekening van de werkgever."]]],
["Wat houdt eigenrisicodragerschap voor de WGA in?", [["De werkgever betaalt zelf maximaal tien jaar de WGA-uitkeringen en regelt de re-integratie", "De werkgever betaalt dan geen gedifferentieerde WGA-premie aan het UWV, maar draagt zelf het risico; dat wordt vaak verzekerd."], ["De werknemer betaalt zelf zijn WGA-uitkering", "Het eigenrisicodragerschap is een keuze van de werkgever en legt geen kosten bij de werknemer neer."], ["De werkgever draagt zelf het risico van de IVA-uitkeringen van zijn (ex-)werknemers", "Eigenrisicodragerschap gaat over de WGA; de IVA blijft bij het UWV."], ["De werkgever hoeft tijdens de eerste twee ziektejaren geen loon meer door te betalen aan zieke werknemers", "De loondoorbetalingsplicht in de eerste twee jaar blijft volledig bestaan."]]],
["Wat heeft een werkgever nodig om eigenrisicodrager voor de WGA te worden?", [["Een garantieverklaring van een verzekeraar of bank", "Met de garantieverklaring is gewaarborgd dat de uitkeringen doorlopen, ook als de werkgever niet meer kan betalen."], ["Een vergunning van de AFM", "De AFM verleent geen vergunningen voor eigenrisicodragerschap."], ["Schriftelijke toestemming van iedere individuele werknemer", "Individuele toestemming van werknemers is niet vereist."], ["Een minimumaantal van 100 werknemers", "Ook kleinere werkgevers kunnen eigenrisicodrager worden."]]],
["Wat dekt een woonlastenverzekering?", [["Een tijdelijke maandelijkse uitkering voor de woonlasten bij AO en/of werkloosheid", "Een woonlastenverzekering helpt de hypotheeklasten tijdelijk te betalen; de dekkingsomvang en duur verschillen per polis."], ["De volledige aflossing van de hypotheek bij werkloosheid", "Een woonlastenverzekering keert maandbedragen uit en lost de hypotheek niet af."], ["Schade aan de woning door brand of storm", "Dat is een opstalverzekering."], ["Het inkomensverlies bij arbeidsongeschiktheid, levenslang en tot het volledige bruto inkomen", "De uitkering is beperkt in duur en hoogte en dekt niet levenslang het inkomen."]]],
["Hoe wordt een woonlastenverzekering in de regel fiscaal behandeld?", [["De premie is niet aftrekbaar en de uitkering is onbelast", "Omdat de woonlastenverzekering geen inkomensvoorziening in fiscale zin is, is de premie niet aftrekbaar en de uitkering niet belast."], ["De premie is aftrekbaar en de uitkering belast in box 1", "Die behandeling geldt voor een AOV, niet voor een woonlastenverzekering."], ["De premie is aftrekbaar als hypotheekrente", "Een verzekeringspremie is geen rente op een eigenwoningschuld."], ["De uitkering valt in box 3", "Een woonlastenuitkering wordt niet als vermogen in box 3 belast."]]],
["Casus: Tom en Lisa vragen of een woonlastenverzekering een AOV kan vervangen. Tom is zelfstandige. Wat is het juiste uitgangspunt?", [["Nee, die dekt alleen de woonlasten en tijdelijk; een AOV beschermt het inkomen langdurig", "Voor een zelfstandige zonder werknemersverzekeringen is een woonlastenverzekering hooguit een aanvulling, geen vervanging."], ["Ja, een woonlastenverzekering dekt hetzelfde inkomensrisico als een AOV", "De dekking verschilt sterk in omvang en duur."], ["Ja, omdat de woonlastenverzekering net als een AOV tot de AOW-leeftijd uitkeert", "Woonlastenverzekeringen keren in de regel beperkt in de tijd uit."], ["Nee, omdat een woonlastenverzekering alleen voor werknemers in loondienst kan worden gesloten", "Ook zelfstandigen kunnen een woonlastenverzekering sluiten, al dan niet met werkloosheidsdekking."]]],
["Welke ORV past qua verloop van het verzekerd kapitaal het best bij een annuïteitenhypotheek?", [["Een annuïtair dalende ORV", "Het verzekerd kapitaal daalt in hetzelfde tempo als de schuld van een annuïteitenhypotheek: eerst langzaam, later sneller."], ["Een gelijkblijvende ORV", "Een gelijkblijvend kapitaal past beter bij een aflossingsvrije hypotheek."], ["Een lineair dalende ORV", "Lineair dalend past bij een lineaire hypotheek, waarbij de schuld elk jaar met hetzelfde bedrag daalt."], ["Een stijgende ORV", "Een stijgend kapitaal sluit niet aan bij een dalende schuld."]]],
["Casus: Sander en Ilona hebben een aflossingsvrije hypotheek van € 250.000,00 en willen bij overlijden van één van beiden de schuld kunnen aflossen. Welke ORV ligt het meest voor de hand?", [["Een gelijkblijvende ORV", "Bij een aflossingsvrije hypotheek blijft de schuld gelijk; een gelijkblijvend verzekerd kapitaal sluit daarop aan."], ["Een annuïtair dalende ORV", "Bij een annuïtair dalende dekking daalt het kapitaal, terwijl de aflossingsvrije schuld gelijk blijft."], ["Een lineair dalende ORV", "Ook bij lineair dalend kapitaal ontstaat een groeiend tekort ten opzichte van de gelijkblijvende schuld."], ["Een uitvaartverzekering", "Een uitvaartverzekering dekt de uitvaartkosten, niet een hypotheekschuld."]]],
["Wat is een 'kruislingse' ORV?", [["De ene partner is verzekeringnemer en begunstigde op het leven van de andere partner", "Doordat de begunstigde zelf de premie betaalt, valt de uitkering niet onder de fictie van de Successiewet."], ["Een ORV die twee hypotheekdelen tegelijk dekt", "Kruislings gaat over de rolverdeling tussen partners, niet over hypotheekdelen."], ["Een ORV die zowel bij overlijden als bij arbeidsongeschiktheid van een partner uitkeert", "Dekking bij arbeidsongeschiktheid is iets anders dan een kruislingse constructie."], ["Een ORV die na overlijden overgaat op de kinderen", "Een kruislingse ORV is geen erfrechtelijke regeling voor kinderen."]]],
["Casus: Bram sluit een ORV op zijn eigen leven, betaalt zelf de premie en wijst zijn partner aan als begunstigde. Bram overlijdt. Wat geldt voor de uitkering aan de partner?", [["De uitkering valt in beginsel onder de erfbelasting", "Volgens de Successiewet wordt een uitkering uit een verzekering waarvoor de overledene de premie betaalde, aangemerkt als verkrijging krachtens erfrecht."], ["De uitkering is altijd vrij van erfbelasting omdat zij buiten de nalatenschap valt", "Ook als de uitkering niet in de nalatenschap valt, kan de Successiewet haar als fictieve erfrechtelijke verkrijging belasten."], ["De uitkering wordt belast in box 1 als inkomen", "Een ORV-uitkering is geen inkomen in box 1."], ["De uitkering moet worden verrekend met de Anw", "Een particuliere ORV-uitkering wordt niet met de Anw verrekend."]]],
["Hoe wordt een overlijdensrisicoverzekering zonder waardeopbouw tijdens de looptijd fiscaal behandeld?", [["De premie is niet aftrekbaar en de polis heeft in box 3 geen of nauwelijks waarde", "Een zuivere risicoverzekering bouwt geen afkoopwaarde op; de premie is een niet-aftrekbare uitgave."], ["De premie is aftrekbaar in box 1 als uitgave voor inkomensvoorziening", "Die aftrek geldt voor bijvoorbeeld AOV- en lijfrentepremies, niet voor een ORV."], ["De polis valt in box 1 als eigenwoningschuld", "Een ORV is geen schuld en valt niet in de eigenwoningregeling."], ["Over het verzekerd kapitaal wordt jaarlijks box 3-heffing berekend", "Het verzekerd kapitaal is geen bezitting zolang er niets is uitgekeerd."]]],
["Wordt een uitkering uit een ORV bij overlijden belast met inkomstenbelasting?", [["Nee, de uitkering is geen inkomen; wel kan erfbelasting aan de orde zijn", "Een ORV-uitkering is niet belast in box 1; afhankelijk van wie de premie betaalde kan de Successiewet van toepassing zijn."], ["Ja, de uitkering wordt belast in box 1 tegen het hoogste tarief", "De uitkering is geen periodiek inkomen en wordt niet in box 1 belast."], ["Ja, de uitkering wordt belast als inkomen uit aanmerkelijk belang", "Box 2 heeft niets te maken met een ORV-uitkering."], ["Ja, de uitkering wordt belast als loon uit dienstbetrekking", "Er is geen dienstbetrekking tussen begunstigde en verzekeraar."]]],
["Waarom is een rookverklaring relevant bij het sluiten van een ORV?", [["Rokers hebben een hoger sterfterisico en betalen daarom meestal meer premie", "Verzekeraars hanteren aparte tarieven voor rokers en niet-rokers; een onjuiste verklaring kan gevolgen hebben voor de uitkering."], ["Rokers kunnen wettelijk geen ORV sluiten", "Rokers kunnen een ORV sluiten, maar tegen een hogere premie."], ["De rookverklaring bepaalt wie de begunstigde is", "De begunstiging wordt door de verzekeringnemer aangewezen, los van rookgedrag."], ["Met een rookverklaring wordt de uitkering voor de begunstigde vrijgesteld van erfbelasting", "Rookgedrag heeft geen fiscale gevolgen voor de uitkering."]]],
["Casus: Ellen en Rob zijn compagnons in een vof. Zij willen dat bij overlijden van één van hen de ander het aandeel kan overnemen zonder in financiële problemen te komen. Welke oplossing past?", [["Een compagnonsverzekering: een ORV waarmee de overblijver het aandeel kan overnemen", "Met een compagnonsverzekering ontvangt de overblijvende compagnon een bedrag waarmee hij de erfgenamen kan uitkopen."], ["Een woonlastenverzekering voor beide compagnons, met de vof als begunstigde", "Een woonlastenverzekering dekt de woonlasten bij AO of werkloosheid, niet de overname van een bedrijfsaandeel."], ["Een verzuimverzekering op naam van de vof die de inkomsten van de overleden vennoot vervangt", "Een verzuimverzekering dekt loondoorbetaling bij ziekte van werknemers."], ["Een Anw-hiaatverzekering voor de vof", "Een Anw-hiaatverzekering is voor nabestaanden, niet voor de overname van een onderneming."]]],
["Wat is de rol van de geldverstrekker als een ORV aan hem is verpand?", [["Bij overlijden heeft hij recht op de uitkering tot het bedrag van de openstaande schuld", "Door de verpanding is de uitkering in de eerste plaats bestemd voor (gedeeltelijke) aflossing van de hypotheek."], ["De geldverstrekker betaalt de premie van de ORV", "De premie wordt door de verzekeringnemer betaald, niet door de geldverstrekker."], ["De geldverstrekker wordt verzekerde in de polis", "De verzekerde is degene op wiens leven de polis is gesloten."], ["De geldverstrekker mag de polis op elk moment zonder toestemming van de verzekeringnemer afkopen", "Een risicoverzekering heeft in de regel geen afkoopwaarde, en verpanding geeft geen vrij afkooprecht."]]],
["Wat is het verschil tussen een uitvaartnaturaverzekering en een uitvaartkapitaalverzekering?", [["Natura levert diensten en goederen voor de uitvaart; kapitaal keert een geldbedrag uit", "Bij de naturavariant regelt de verzekeraar de uitvaart; bij de kapitaalvariant ontvangen de nabestaanden geld."], ["Een naturaverzekering keert altijd meer uit dan een kapitaalverzekering", "De hoogte hangt af van de verzekerde dienstverlening of het verzekerde bedrag, niet van het type."], ["Een kapitaalverzekering is alleen voor kinderen", "Een kapitaalverzekering kan voor iedereen worden gesloten."], ["Een naturaverzekering dekt naast de uitvaart ook het inkomensverlies van de nabestaanden", "Een uitvaartverzekering dekt alleen de uitvaart."]]],
["Hoe wordt een uitvaartkapitaalverzekering in box 3 behandeld?", [["Er geldt een vrijstelling tot een maximumbedrag", "Rechten uit een uitvaartkapitaalverzekering zijn tot een (jaarlijks geïndexeerd) maximumbedrag vrijgesteld in box 3."], ["De volledige waarde is altijd belast in box 3", "Er bestaat een specifieke vrijstelling voor uitvaartverzekeringen."], ["De premie is aftrekbaar in box 1", "Premies voor een uitvaartverzekering zijn niet aftrekbaar."], ["De verzekering valt in box 2", "Box 2 gaat over aanmerkelijk belang en heeft niets met een uitvaartverzekering te maken."]]],
["Casus: een 70-jarige klant heeft een oude uitvaartnaturapolis uit 1985 en vraagt of die nog toereikend is. Waar moet de adviseur in elk geval op letten?", [["Of het dienstenpakket nog past bij de huidige wensen en uitvaartkosten", "Oude natura- of kapitaalpolissen kunnen achterblijven bij de huidige kosten, waardoor nabestaanden moeten bijbetalen."], ["Of de polis kan worden omgezet in een AOV met dezelfde premie en looptijd", "Op 70-jarige leeftijd en voor een uitvaartbehoefte is een AOV niet relevant."], ["Of de klant de premie alsnog kan aftrekken", "Premies voor een uitvaartverzekering zijn niet aftrekbaar."], ["Of de klant na het overlijden van zijn partner recht heeft op een Anw-uitkering", "De Anw stopt bij de AOW-leeftijd en heeft niets met de uitvaart te maken."]]],
["Hoe wordt de premie voor een particuliere AOV van een zelfstandige fiscaal behandeld?", [["Als aftrekbare uitgave voor inkomensvoorziening in box 1", "De premie voor een AOV is aftrekbaar in box 1; de uitkering is dan ook belast."], ["Als niet-aftrekbare consumptieve uitgave", "De AOV-premie is juist aftrekbaar."], ["Als kostenpost die alleen in box 2 aftrekbaar is", "Een zelfstandige met een eenmanszaak heeft geen box 2-inkomen uit zijn onderneming."], ["Als bezitting in box 3", "Een AOV heeft geen vermogenswaarde in box 3."]]],
["Hoe wordt een uitkering uit een particuliere AOV fiscaal behandeld?", [["Als belast inkomen in box 1", "Omdat de premie aftrekbaar is, wordt de uitkering als periodieke uitkering belast in box 1."], ["Als onbelaste schadevergoeding", "Een AOV-uitkering vervangt inkomen en is daarom belast."], ["Als vermogen in box 3", "Een periodieke inkomensvervangende uitkering valt niet in box 3."], ["Als belaste schenking", "Een verzekeringsuitkering is geen schenking."]]],
["Casus: zelfstandige Bart verdient gemiddeld € 60.000,00 winst per jaar. Hij wil het verzekerd bedrag van zijn AOV baseren op zijn netto besteedbaar inkomen. Waarom is dat onverstandig?", [["Omdat de uitkering belast is, moet hij het verzekerd bedrag bruto bepalen", "De AOV-uitkering wordt belast in box 1; wie op netto basis verzekert, houdt na belasting te weinig over."], ["Omdat de premie dan niet meer aftrekbaar is", "De aftrekbaarheid hangt niet af van de hoogte van het verzekerde bedrag."], ["Omdat verzekeraars alleen verzekerde bedragen accepteren die boven de gemiddelde winst liggen", "Verzekeraars beperken het verzekerd bedrag juist tot een deel van de winst."], ["Omdat een verzekerd bedrag op netto basis altijd tot oververzekering en dus premieverspilling leidt", "Een netto basis leidt eerder tot onderverzekering."]]],
["Welke combinatie van fiscale behandeling hoort bij een AOV, een ORV en een woonlastenverzekering?", [["AOV: aftrek en belaste uitkering; ORV en woonlasten: geen aftrek, uitkering niet in box 1", "Alleen de AOV is in box 1 een inkomensvoorziening; de ORV en de woonlastenverzekering kennen geen premieaftrek en geen box 1-heffing over de uitkering."], ["Alle drie: premie aftrekbaar in box 1 en uitkering belast als periodieke uitkering", "De ORV en de woonlastenverzekering kennen geen premieaftrek."], ["Alle drie: premie niet aftrekbaar en uitkering onbelast, omdat het risicoverzekeringen zijn", "Voor de AOV geldt juist premieaftrek en een belaste uitkering."], ["AOV en ORV: premie aftrekbaar en uitkering belast; woonlastenverzekering: geen van beide", "De ORV-premie is niet aftrekbaar."]]],
["Welke risico's horen in elk geval aan bod te komen in een inkomensanalyse bij een hypotheekadvies?", [["Arbeidsongeschiktheid, werkloosheid, overlijden en pensionering", "Een volledige inkomensanalyse laat zien wat de financiële gevolgen van deze gebeurtenissen zijn voor de betaalbaarheid van de woonlasten."], ["Alleen overlijden van de hoofdkostwinner", "Een analyse die zich alleen op overlijden richt, is niet volledig."], ["Alleen de rentestand bij het einde van de rentevaste periode", "Renterisico is relevant, maar is geen inkomensrisico zoals AO of werkloosheid."], ["Alleen de waardeontwikkeling van de woning", "De woningwaarde is relevant voor de financiering, maar niet voor de inkomensanalyse."]]],
["Casus: werknemer Linda heeft een vast contract en vraagt advies over een AOV omdat zij bang is voor inkomensverlies bij ziekte. Wat doet de adviseur eerst?", [["Nagaan welke voorzieningen zij al heeft, zoals loondoorbetaling, WIA en WGA-hiaatdekking", "Pas als de bestaande voorzieningen bekend zijn, kan de adviseur bepalen of er een resterend inkomensrisico is dat aanvullende dekking rechtvaardigt."], ["Direct een AOV met de kortste wachttijd adviseren, zodat zij vanaf dag één gedekt is", "Zonder inventarisatie van bestaande dekkingen kan het advies leiden tot dubbele of onnodige verzekering."], ["Haar adviseren haar vaste contract op te zeggen", "Dit is geen verantwoord advies en lost het inkomensrisico niet op."], ["Een woonlastenverzekering adviseren in plaats van een uitgebreide analyse van haar inkomen", "Ook een woonlastenverzekering adviseren zonder analyse is in strijd met de zorgvuldigheid."]]],
["Wat verplicht de Europese richtlijn verzekeringsdistributie (IDD) de distributeur vóór het sluiten van een verzekering?", [["Op basis van klantinformatie diens wensen en behoeften vaststellen", "De IDD vereist dat elk aangeboden verzekeringsproduct aansluit bij de wensen en behoeften van de klant."], ["Altijd een medische keuring laten uitvoeren", "Of een keuring nodig is, hangt af van het product en de acceptatiecriteria, niet van de IDD."], ["Altijd het goedkoopste product op de markt adviseren, ongeacht de dekking", "De IDD schrijft geen goedkoopste product voor; het gaat om passendheid."], ["De verzekering vooraf laten goedkeuren door de AFM", "De AFM keurt individuele verzekeringen niet vooraf goed."]]],
["Welke informatie moet een verzekeringsdistributeur onder de IDD in elk geval aan de klant geven?", [["De aard van de beloning die hij voor zijn dienstverlening ontvangt", "De IDD verlangt dat de klant weet of de distributeur bijvoorbeeld een fee of provisie ontvangt."], ["De winstcijfers van de verzekeraar over de afgelopen tien jaar", "Winstcijfers van de verzekeraar zijn geen verplichte klantinformatie onder de IDD."], ["De persoonlijke inkomsten van de adviseur", "Het gaat om de aard van de beloning voor de dienstverlening, niet om het privé-inkomen."], ["De namen van alle andere klanten met hetzelfde product", "Dat zou in strijd zijn met de privacy van die klanten."]]],
["Casus: een adviseur adviseert een zelfstandige een AOV met beroepsdekking en de kortste wachttijd, terwijl de premie een groot deel van het besteedbaar inkomen opslokt. De klant kan dit niet blijven betalen. Wat is het belangrijkste probleem?", [["Het advies is niet passend, omdat het de financiële positie van de klant negeert", "De zorgplicht vereist dat een advies ook betaalbaar is; alternatieven zoals een langere wachttijd of een lager verzekerd bedrag hadden moeten worden afgewogen."], ["Een beroepsdekking mag volgens de Wft nooit aan zelfstandigen worden geadviseerd", "Een beroepsdekking kan juist passend zijn; het probleem is de betaalbaarheid."], ["De adviseur had een woonlastenverzekering moeten adviseren", "Dat lost het probleem van de onbetaalbare inkomensdekking niet op."], ["Er is geen probleem, zolang de klant het adviesrapport en de offerte heeft ondertekend", "Een handtekening ontslaat de adviseur niet van zijn zorgplicht."]]],
["Hoe moet een adviseur omgaan met de gezondheidsverklaring van een klant bij een AOV- of ORV-aanvraag?", [["De klant vult hem zelf in; hij gaat rechtstreeks naar de medisch adviseur", "Gezondheidsgegevens zijn bijzondere persoonsgegevens; de adviseur hoort geen kennis te nemen van de medische details."], ["De adviseur vult de verklaring namens de klant in om fouten en vertraging te voorkomen", "Daarmee neemt de adviseur kennis van gevoelige gegevens en loopt hij het risico op onjuiste opgaven."], ["De adviseur bewaart een kopie in het klantdossier", "Medische gegevens horen niet in het dossier van het advieskantoor."], ["De verklaring wordt via de acceptant van de verzekeraar openbaar gedeeld", "Gezondheidsgegevens worden alleen door de medische dienst van de verzekeraar beoordeeld."]]],
["Wat zijn gezondheidsgegevens volgens de AVG?", [["Bijzondere persoonsgegevens, met een verwerkingsverbod tenzij een uitzondering geldt", "Voor gezondheidsgegevens gelden strengere regels dan voor gewone persoonsgegevens."], ["Gewone persoonsgegevens, zoals naam en adres, die vrij mogen worden verwerkt", "Gezondheidsgegevens zijn juist een bijzondere categorie."], ["Openbare gegevens die de verzekeraar vrij mag delen met andere financiële instellingen", "Gezondheidsgegevens zijn juist zeer gevoelig en niet openbaar."], ["Gegevens die alleen onder de Wwft vallen en na vijf jaar moeten worden vernietigd", "De Wwft gaat over witwassen; de bescherming van gezondheidsgegevens valt onder de AVG."]]],
["Welk recht heeft een keurling op grond van de Wet op de medische keuringen bij een keuring voor een verzekering?", [["Het recht om de uitslag eerst zelf te horen en doorgifte aan de verzekeraar te blokkeren", "Met dit recht houdt de keurling zelf de regie over de uitslag; de verzekeraar kan de aanvraag dan wel weigeren."], ["Het recht om de premie zelf vast te stellen", "De premie wordt door de verzekeraar bepaald."], ["Het recht om de keuring door zijn eigen huisarts als keurend arts te laten uitvoeren, op kosten van de verzekeraar", "Een behandelend arts mag in de regel niet als keurend arts optreden, en de keurling bepaalt de kosten van de keuring niet."], ["Het recht op een gegarandeerde acceptatie tegen standaardpremie na de keuring", "Een keuring garandeert geen acceptatie."]]],
["Wat is de functie van de 'vragengrens' bij verzekeringskeuringen?", [["Onder die grens mag de verzekeraar niet vragen naar erfelijkheidsonderzoek en de uitslag", "De vragengrens beschermt mensen met een (mogelijk) erfelijk risico die een verzekering tot een bepaald bedrag willen sluiten."], ["Boven de vragengrens mag de verzekeraar helemaal geen gezondheidsvragen meer stellen aan de aanvrager", "Het is juist andersom: boven de grens zijn meer vragen toegestaan."], ["De vragengrens bepaalt het maximum verzekerd bedrag in een AOV", "De vragengrens beperkt welke vragen mogen worden gesteld, niet het maximum verzekerd bedrag."], ["De vragengrens geldt alleen voor de Wwft-identificatie", "De vragengrens hoort bij medische keuringen, niet bij de Wwft."]]],
["Casus: een bv wil via adviseur Karin een ORV sluiten op het leven van de dga. Karin is Wwft-plichtig als bemiddelaar in levensverzekeringen. Wat hoort bij haar cliëntenonderzoek?", [["De identiteit van de bv en haar uiteindelijk belanghebbende(n) vaststellen en verifiëren", "Bij een rechtspersoon als cliënt moet de Wwft-instelling ook de UBO identificeren en redelijke maatregelen nemen om diens identiteit te verifiëren."], ["Alleen het opvragen van het KvK-nummer van de bv", "Een KvK-nummer is onvoldoende; ook de UBO moet in kaart worden gebracht."], ["Een medische keuring van alle aandeelhouders", "Een medische keuring heeft niets met het Wwft-cliëntenonderzoek te maken."], ["Geen cliëntenonderzoek, omdat een bv geen consument is en de Wwft alleen particulieren beschermt", "De Wwft geldt ook voor zakelijke cliënten."]]],
["Casus: een klant weigert bij het sluiten van een ORV mee te werken aan het Wwft-cliëntenonderzoek. Wat moet de adviseur doen?", [["De relatie niet aangaan, de transactie niet uitvoeren en een FIU-melding overwegen", "Als het cliëntenonderzoek niet kan worden afgerond, mag de Wwft-instelling de dienst niet verlenen; de situatie kan een ongebruikelijke transactie opleveren."], ["De ORV toch afsluiten, omdat een ORV geen beleggingsproduct is en dus buiten de Wwft valt", "Ook bij een ORV moet het cliëntenonderzoek zijn afgerond."], ["De klant een korting geven zodat hij wel meewerkt", "Een korting is geen oplossing en verandert niets aan de Wwft-plicht."], ["De verzekeraar vragen het cliëntenonderzoek over te slaan bij een klein verzekerd bedrag", "Het cliëntenonderzoek is een wettelijke verplichting die niet kan worden overgeslagen."]]]
],
"pensioen":[
["Uit welke drie pijlers bestaat het Nederlandse pensioenstelsel?", [["AOW, werkgeverspensioen en individuele aanvullingen", "De eerste pijler is de AOW, de tweede het pensioen via de werkgever en de derde de individuele voorzieningen zoals lijfrente."], ["AOW, Anw en werkgeverspensioen", "De Anw is een nabestaandenvoorziening binnen de sociale zekerheid en geen aparte pensioenpijler."], ["Werkgeverspensioen, lijfrente en vermogen in de eigen woning", "De eigen woning kan financieel helpen na pensionering, maar is geen pensioenpijler."], ["AOW, bijstand en individuele aanvullingen", "Bijstand is een vangnet via de Participatiewet en hoort niet bij de pensioenpijlers."]]],
["Tot welke pijler behoort een lijfrenteverzekering die een zelfstandige zonder personeel zelf afsluit?", [["De derde pijler", "Individuele, op eigen initiatief getroffen voorzieningen zoals lijfrente en banksparen vormen de derde pijler."], ["De eerste pijler", "De eerste pijler is de AOW, een volksverzekering die niet door eigen keuze wordt opgebouwd."], ["De tweede pijler", "De tweede pijler is het pensioen dat via de werkgever of een verplichte beroepsregeling wordt opgebouwd."], ["De nulde pijler", "Het begrip 'nulde pijler' wordt soms informeel gebruikt, maar een individuele lijfrente valt in de derde pijler."]]],
["Hoe wordt de AOW in hoofdzaak gefinancierd?", [["Via een omslagstelsel: werkenden betalen voor de huidige AOW'ers, aangevuld met een rijksbijdrage", "De AOW-premie van nu financiert de uitkeringen van nu; omdat de premie niet toereikend is, vult het Rijk aan uit belastinggeld."], ["Via kapitaaldekking: iedere verzekerde spaart vanaf zijn 17e een eigen AOW-vermogen op bij de SVB", "Kapitaaldekking hoort bij de tweede en derde pijler; voor de AOW wordt geen individueel vermogen opgebouwd."], ["Via premies die werkgevers en werknemers afdragen aan een bedrijfstakpensioenfonds, dat de AOW uitkeert", "Bedrijfstakpensioenfondsen voeren tweedepijlerpensioen uit, niet de AOW."], ["Volledig uit de opbrengst van het pensioenvermogen van de SVB", "De SVB voert de AOW uit, maar beheert geen pensioenvermogen waaruit de AOW wordt betaald."]]],
["Wat is een kenmerkend verschil tussen de tweede en de derde pijler?", [["De tweede pijler loopt via werkgever of beroepsgroep, de derde berust op individuele keuze", "Werkgeverspensioen is gekoppeld aan het dienstverband; derdepijlerproducten sluit iemand zelf af."], ["De tweede pijler is altijd vrijwillig, de derde pijler is wettelijk verplicht", "Het is eerder andersom: deelname aan een werkgeversregeling is vaak verplicht, de derde pijler is vrijwillig."], ["De tweede pijler wordt uitgevoerd door de SVB, de derde pijler door het UWV", "De SVB voert de AOW uit en het UWV de werknemersverzekeringen; pensioenuitvoerders voeren de tweede pijler uit."], ["Over de tweede pijler wordt nooit belasting geheven, over de derde pijler altijd bij uitkering in box 1", "Voor beide pijlers geldt in de regel de omkeerregel: inleg aftrekbaar of vrijgesteld, uitkering belast."]]],
["Bas (45) werkt in loondienst en bouwt pensioen op bij het pensioenfonds van zijn werkgever. Hij wil weten hoe zijn totale oudedagsinkomen is opgebouwd. Welke bronnen tellen daarbij mee?", [["AOW, het werkgeverspensioen en eventuele eigen voorzieningen zoals lijfrente", "Voor een volledig beeld van het oudedagsinkomen bekijk je alle drie de pijlers samen."], ["Alleen het werkgeverspensioen, omdat de AOW pas op de AOW-leeftijd zelf wordt vastgesteld", "Ook als de AOW-leeftijd nog kan veranderen, hoort de AOW in het totaalbeeld thuis."], ["Alleen de AOW, omdat het werkgeverspensioen nog kan wijzigen", "Het werkgeverspensioen is vaak de grootste aanvulling en mag niet ontbreken in de analyse."], ["Alleen de eigen voorzieningen, omdat de rest wettelijk vastligt", "AOW en werkgeverspensioen liggen niet volledig vast en vormen juist de basis van het oudedagsinkomen."]]],
["Hoeveel AOW bouwt iemand op per jaar dat hij in Nederland woont of werkt in de opbouwperiode?", [["2% van de volledige AOW", "De opbouwperiode is 50 jaar en elk verzekerd jaar levert 2% op, samen 100%."], ["2,5% van de volledige AOW", "Bij 2,5% zou al na 40 jaar een volledige AOW bereikt zijn; de opbouw is 2% per jaar."], ["1,75% van de volledige AOW", "1,75% is een opbouwpercentage dat in werkgeversregelingen voorkwam, niet bij de AOW."], ["Een vast bedrag afhankelijk van het inkomen", "De AOW-opbouw is inkomensonafhankelijk en wordt uitgedrukt in een percentage per verzekerd jaar."]]],
["Over welke periode bouwt iemand AOW op?", [["De 50 jaar direct voorafgaand aan de eigen AOW-leeftijd", "De opbouwperiode schuift mee met de AOW-leeftijd en begint 50 jaar voor die leeftijd."], ["Vanaf de 15e verjaardag tot de AOW-leeftijd", "Een vaste startleeftijd van 15 jaar geldt niet meer sinds de AOW-leeftijd met de levensverwachting is gaan meebewegen."], ["Vanaf de eerste werkdag tot de AOW-leeftijd", "AOW-opbouw is gebaseerd op wonen of werken in Nederland, niet op de eerste werkdag."], ["De 40 jaar direct voorafgaand aan de eigen AOW-leeftijd, gerekend per kalenderjaar", "De periode is 50 jaar; 40 jaar zou slechts 80% opleveren."]]],
["Fatima kwam op haar 30e naar Nederland en woont hier sindsdien. Ga uit van een AOW-leeftijd van 67 jaar. Hoeveel procent van de volledige AOW bouwt zij op, als zij tot haar AOW-leeftijd in Nederland blijft wonen?", [["74%", "De opbouwperiode loopt van 17 tot 67 jaar; zij mist 13 jaar, dat is 13 x 2% = 26% korting."], ["80%", "80% hoort bij 40 verzekerde jaren; Fatima heeft 37 verzekerde jaren."], ["70%", "70% hoort bij 35 verzekerde jaren; Fatima heeft er 37."], ["100%", "Een volledige AOW vereist 50 verzekerde jaren; zij mist de jaren tussen 17 en 30."]]],
["Hoe is de AOW-leeftijd gekoppeld aan de levensverwachting?", [["De AOW-leeftijd stijgt met twee derde van de stijging van de levensverwachting en wordt vijf jaar vooruit vastgesteld", "Sinds de wet van 2019 telt een jaar langere levensverwachting voor acht maanden mee, en de leeftijd wordt vijf jaar van tevoren bekendgemaakt."], ["De AOW-leeftijd stijgt een-op-een mee met de stijging van de levensverwachting en wordt jaarlijks per direct aangepast door de SVB", "Een een-op-eenkoppeling gold eerder; nu is het twee derde en geldt een aankondigingstermijn van vijf jaar."], ["De AOW-leeftijd ligt wettelijk vast op 67 jaar en wordt niet meer aangepast", "Na 2024 kan de AOW-leeftijd via de koppeling met de levensverwachting verder stijgen."], ["De AOW-leeftijd wordt per cao afgesproken tussen werkgevers en vakbonden", "De AOW-leeftijd is wettelijk geregeld; cao-partijen gaan alleen over de pensioenregeling van de werkgever."]]],
["Waar is de hoogte van de AOW-uitkering aan gekoppeld?", [["Aan het netto minimumloon", "De AOW volgt het netto minimumloon; voor een alleenstaande en voor samenwonenden gelden verschillende percentages daarvan."], ["Aan het laatstverdiende loon van de AOW'er", "De AOW is inkomensonafhankelijk; het eigen loon speelt geen rol."], ["Aan de dekkingsgraad van de pensioenfondsen", "De dekkingsgraad is van belang voor tweedepijlerpensioenen, niet voor de AOW."], ["Aan het gemiddelde loon over de hele loopbaan", "Een middelloonsystematiek komt voor in werkgeversregelingen, niet bij de AOW."]]],
["Twee gehuwde partners hebben beiden de AOW-leeftijd bereikt en een volledige opbouw. Hoe ontvangen zij AOW?", [["Ieder ontvangt een eigen AOW-uitkering voor samenwonenden", "Elke partner heeft een eigen recht; de AOW voor gehuwden en samenwonenden is per persoon lager dan voor een alleenstaande."], ["Zij ontvangen samen één AOW-uitkering voor een alleenstaande", "Partners hebben ieder een eigen AOW-recht; er is geen gezamenlijke alleenstaandenuitkering."], ["Alleen de oudste partner ontvangt AOW, met een partnertoeslag", "Iedere partner ontvangt zelf AOW vanaf de eigen AOW-leeftijd; de partnertoeslag is voor nieuwe gevallen afgeschaft."], ["Ieder ontvangt een volledige alleenstaanden-AOW", "Voor gehuwden en samenwonenden geldt een lager bedrag per persoon dan voor een alleenstaande."]]],
["Speelt het vermogen of het overige inkomen van een AOW-gerechtigde een rol bij de hoogte van de AOW?", [["Nee, de AOW is een volksverzekering zonder inkomens- of vermogenstoets", "De hoogte hangt af van het aantal verzekerde jaren en de leefsituatie, niet van inkomen of vermogen."], ["Ja, bij een vermogen boven de vermogensgrens van de bijstand wordt de AOW naar rato gekort", "Een vermogenstoets bestaat bij de bijstand, niet bij de AOW."], ["Ja, een werkgeverspensioen wordt met de AOW verrekend", "De AOW wordt niet verrekend met een werkgeverspensioen; wel houdt de werkgeversregeling vaak rekening met de AOW via de franchise."], ["Alleen het inkomen van de partner wordt meegeteld", "Inkomen van de partner beïnvloedt de AOW niet; alleen de leefsituatie (alleenstaand of samenwonend) telt."]]],
["Wat wordt bedoeld met het Anw-hiaat?", [["Het inkomensgat bij overlijden doordat de Anw niet of beperkt uitkeert en het partnerpensioen dat niet opvangt", "Door de strenge voorwaarden en de inkomenstoets van de Anw kan de nabestaande inkomen tekortkomen; dat gat heet het Anw-hiaat."], ["Het verschil tussen de AOW voor alleenstaanden en voor samenwonenden", "Dat verschil heeft niets met de Anw te maken; het gaat om de AOW-leefsituatie."], ["De periode tussen het einde van de WW-uitkering en de ingangsdatum van de AOW, waarin alleen bijstand mogelijk is", "Dat is een werkloosheidsgat; het Anw-hiaat gaat over overlijden van een partner."], ["Het tekort aan AOW-opbouw door jaren in het buitenland", "Dat is een AOW-gat door ontbrekende verzekerde jaren, geen Anw-hiaat."]]],
["Hoe kan het Anw-hiaat worden afgedekt?", [["Met een Anw-hiaatverzekering of -pensioen, vaak via de pensioenuitvoerder, of een overlijdensrisicoverzekering", "Deze voorzieningen keren uit bij overlijden van de partner en vullen zo het ontbrekende inkomen aan."], ["Met een aanvraag voor vrijwillige AOW-verzekering bij de SVB, die bij overlijden een Anw-aanvulling uitkeert", "Vrijwillige AOW-verzekering vult AOW-gaten aan, niet het inkomensverlies bij overlijden."], ["Met een hoog-laagconstructie in het ouderdomspensioen, waardoor de partner al vóór de pensioendatum een hogere uitkering krijgt", "Een hoog-laagconstructie regelt de hoogte van het eigen ouderdomspensioen en dekt het overlijdensrisico niet."], ["Met een WW-uitkering voor de nabestaande", "Overlijden van een partner geeft geen recht op WW; de WW gaat over werkloosheid."]]],
["Sanne (38) is ongehuwd samenwonend met Tim, heeft geen kinderen, werkt fulltime en is niet arbeidsongeschikt. Tim overlijdt. Heeft Sanne recht op een Anw-nabestaandenuitkering?", [["Nee: zij heeft geen kind onder 18, is niet ten minste 45% arbeidsongeschikt en is niet vóór 1950 geboren", "Een gezamenlijke huishouding kan meetellen, maar de Anw kent daarnaast deze aanvullende voorwaarden."], ["Ja, omdat ieder die een gezamenlijke huishouding voerde met de overledene recht heeft op een Anw-uitkering", "Een gezamenlijke huishouding is nodig maar niet voldoende; ook een van de aanvullende voorwaarden moet vervuld zijn."], ["Nee, omdat ongehuwd samenwonenden nooit onder de Anw vallen", "Ongehuwd samenwonenden met een gezamenlijke huishouding kunnen wel onder de Anw vallen."], ["Ja, maar alleen gedurende het eerste jaar na het overlijden, als overbruggingsuitkering van de SVB", "De Anw kent geen algemene eerstejaarsuitkering voor iedere nabestaande."]]],
["Wanneer eindigt een Anw-nabestaandenuitkering in elk geval?", [["Bij het bereiken van de AOW-leeftijd", "Vanaf de AOW-leeftijd heeft de nabestaande recht op AOW en stopt de Anw-uitkering."], ["Na precies vijf jaar uitkering", "De Anw kent geen vaste maximale duur van vijf jaar."], ["Zodra de nabestaande 50 jaar wordt", "Een leeftijd van 50 jaar is geen eindmoment van de Anw."], ["Bij de eerste salarisverhoging van de nabestaande", "Inkomen kan de uitkering verlagen via de inkomenstoets, maar een salarisverhoging beëindigt het recht niet automatisch."]]],
["Wat is het verschil tussen partnerpensioen op opbouwbasis en op risicobasis?", [["Bij opbouwbasis blijft de aanspraak na uitdiensttreding bestaan; bij risicobasis is er alleen dekking tijdens de deelneming (plus eventuele uitloop)", "Risicobasis werkt als een overlijdensrisicoverzekering: er wordt niets opgebouwd dat na einde deelneming overblijft."], ["Bij risicobasis wordt een hoger kapitaal opgebouwd dan bij opbouwbasis, dat bij uitdiensttreding via waardeoverdracht naar de nieuwe uitvoerder gaat", "Bij risicobasis wordt geen kapitaal opgebouwd; de premie betaalt alleen de dekking."], ["Bij opbouwbasis is de dekking pas na tien jaar deelneming geldig; bij risicobasis direct vanaf de eerste werkdag", "Bij opbouwbasis groeit de aanspraak per deelnemingsjaar, er is geen wachttijd van tien jaar."], ["Er is geen verschil; het zijn twee namen voor hetzelfde", "Het verschil is wezenlijk, vooral bij baanwisseling: op risicobasis kan de dekking vervallen."]]],
["Pieter heeft partnerpensioen op risicobasis bij zijn werkgever. Hij neemt ontslag en gaat als zzp'er verder. Waarop moet de adviseur hem wijzen?", [["Dat de partnerpensioendekking na afloop vervalt en hij moet bekijken of hij zijn overlijdensrisico wil verzekeren", "Op risicobasis eindigt de dekking met de deelneming (na een eventuele uitloop); als zzp'er moet hij het nabestaandenrisico zelf regelen."], ["Dat zijn partner levenslang het volledige partnerpensioen behoudt, ook als hij na zijn ontslag geen premie meer betaalt", "Bij risicobasis blijft geen aanspraak bestaan na einde deelneming."], ["Dat het partnerpensioen automatisch overgaat naar de Anw, die zijn partner bij overlijden een aanvullende uitkering geeft", "De Anw is een aparte volksverzekering met eigen voorwaarden en neemt het partnerpensioen niet over."], ["Dat hij het partnerpensioen bij uitdiensttreding kan laten afkopen en het bedrag als zzp'er in een lijfrente kan storten", "Bij risicobasis is er geen opgebouwde waarde die afgekocht kan worden."]]],
["Wat houdt uitruil van partnerpensioen naar ouderdomspensioen in?", [["De deelnemer ruilt (een deel van) het partnerpensioen in voor een hoger ouderdomspensioen, met schriftelijke toestemming van de partner", "Omdat de partner zijn aanspraak verliest, vereist de Pensioenwet schriftelijke instemming van die partner."], ["De partner ruilt zijn eigen ouderdomspensioen in voor een hoger partnerpensioen bij overlijden van de deelnemer", "Uitruil gaat over de rechten binnen de regeling van de deelnemer, niet over het eigen pensioen van de partner."], ["De deelnemer ruilt partnerpensioen in voor een hoger ouderdomspensioen zonder dat de partner betrokken hoeft te worden, mits hij dit vóór de pensioendatum meldt", "Juist omdat de partner rechten verliest, is zijn schriftelijke toestemming vereist."], ["De werkgever beslist eenzijdig om het partnerpensioen om te zetten", "Uitruil is een keuzerecht van de deelnemer, met instemming van de partner, geen werkgeversbesluit."]]],
["Wat is het doel van een wezenpensioen?", [["Een uitkering voor kinderen van een overleden deelnemer tot een in de regeling bepaalde leeftijd", "Het wezenpensioen ondersteunt kinderen financieel na overlijden van de ouder die deelnemer was."], ["Een levenslange uitkering voor de kinderen van een deelnemer, ingaand op de pensioendatum van de deelnemer", "Het wezenpensioen is tijdelijk en eindigt op de leeftijd die de regeling bepaalt."], ["Een aanvulling op de kinderbijslag zolang de deelnemer leeft", "Het wezenpensioen keert pas uit na overlijden van de deelnemer."], ["Een uitkering aan de ex-partner van de deelnemer na scheiding", "Rechten van een ex-partner lopen via verevening en het bijzonder partnerpensioen, niet via het wezenpensioen."]]],
["Wie geldt als partner voor het partnerpensioen van een ongehuwd samenwonende deelnemer?", [["Dat bepaalt het pensioenreglement; vaak is een samenlevingscontract of aanmelding bij de uitvoerder vereist", "Gehuwden en geregistreerd partners zijn doorgaans automatisch partner; voor samenwoners stelt de regeling eigen voorwaarden."], ["Iedereen die ten minste zes maanden op hetzelfde adres in de BRP staat ingeschreven, ongeacht het reglement", "Alleen inschrijving op hetzelfde adres is meestal niet voldoende; de regeling bepaalt de voorwaarden."], ["Ongehuwd samenwonenden kunnen nooit partnerpensioen krijgen", "Veel regelingen kennen wel partnerpensioen voor samenwoners, mits aan de voorwaarden is voldaan."], ["Alleen een partner met wie de deelnemer kinderen heeft, mits het ouderschap juridisch is erkend", "Kinderen zijn geen algemene voorwaarde voor het partnerbegrip in pensioenregelingen."]]],
["Op welk pensioen ziet de standaardverevening van de Wet verevening pensioenrechten bij scheiding?", [["Het ouderdomspensioen opgebouwd tijdens het huwelijk of geregistreerd partnerschap", "Alleen de opbouw tijdens de huwelijksperiode wordt verevend; opbouw daarvoor of daarna niet."], ["Al het ouderdomspensioen dat de deelnemer ooit heeft opgebouwd, ook vóór het huwelijk", "Opbouw van voor het huwelijk en na de scheiding valt buiten de verevening."], ["De AOW van beide ex-partners", "De AOW is een persoonlijk recht en wordt niet verevend."], ["Het partnerpensioen dat tijdens het huwelijk is opgebouwd", "Het opgebouwde partnerpensioen wordt niet verevend; daarvoor krijgt de ex-partner het bijzonder partnerpensioen."]]],
["Wat is het bijzonder partnerpensioen?", [["Het tot de scheiding opgebouwde partnerpensioen dat na de scheiding bestemd blijft voor de ex-partner", "Bij scheiding behoudt de ex-partner een recht op het tot dan toe opgebouwde partnerpensioen."], ["Een extra partnerpensioen dat de uitvoerder na de scheiding toekent aan een nieuwe partner van de deelnemer", "Een nieuwe partner krijgt hooguit partnerpensioen over latere opbouw; het bijzonder partnerpensioen is voor de ex."], ["Een tijdelijk partnerpensioen tot de AOW-leeftijd van de partner", "Het bijzonder partnerpensioen is niet per definitie tijdelijk en is niet gekoppeld aan de AOW-leeftijd."], ["Het deel van het ouderdomspensioen dat de ex-partner via verevening krijgt", "Het verevende ouderdomspensioen en het bijzonder partnerpensioen zijn twee verschillende rechten."]]],
["Wat is het verschil tussen verevening en conversie bij scheiding?", [["Bij conversie krijgt de ex-partner een zelfstandig pensioenrecht; bij verevening blijft de uitbetaling afhankelijk van het leven van de deelnemer", "Bij conversie worden de rechten definitief gesplitst; bij verevening stopt de betaling aan de ex in beginsel als de deelnemer overlijdt."], ["Conversie is de wettelijke standaard bij scheiding; verevening moet apart worden afgesproken in huwelijkse voorwaarden of een echtscheidingsconvenant", "Het is andersom: verevening is de standaard, voor conversie moeten beide ex-partners en de uitvoerder meewerken."], ["Bij verevening wordt het pensioen direct afgekocht en uitgekeerd; bij conversie wordt het pas op de pensioendatum gesplitst", "Verevening leidt tot een periodieke uitkering vanaf de pensioendatum, niet tot afkoop."], ["Er is geen verschil; beide termen staan voor gelijke verdeling", "Beide gaan over verdeling, maar het verschil in zelfstandigheid van het recht is wezenlijk."]]],
["Mark en Lotte scheiden en melden de scheiding na drie jaar alsnog bij de pensioenuitvoerder. Wat is daarvan het gevolg?", [["De uitvoerder hoeft Lotte niet meer rechtstreeks uit te betalen; zij moet haar deel dan van Mark zelf zien te krijgen", "Na de termijn van twee jaar houdt de ex-partner het recht op verevening, maar vervalt de garantie van rechtstreekse betaling."], ["Lotte verliest elk recht op verevening, omdat de wettelijke meldtermijn van twee jaar is verstreken", "Het recht op verevening blijft bestaan; alleen de rechtstreekse uitbetaling via de uitvoerder is niet meer gegarandeerd."], ["De uitvoerder verevent alsnog automatisch en rechtstreeks, omdat voor het melden van een scheiding geen wettelijke termijn geldt", "De wet kent wel een termijn van twee jaar voor de melding."], ["Mark moet een boete betalen aan de uitvoerder", "De Wvps kent geen boete voor een late melding."]]],
["Esther en Ruud zijn ongehuwd samenwonend zonder geregistreerd partnerschap en gaan uit elkaar. Geldt de Wvps voor hun pensioenopbouw?", [["Nee, de Wvps geldt alleen bij huwelijk of geregistreerd partnerschap; verdeling kan via eigen afspraken", "Voor ongehuwd samenwonenden is geen wettelijke verevening geregeld."], ["Ja, de Wvps geldt voor iedereen die een gezamenlijke huishouding voerde en op hetzelfde adres stond ingeschreven", "Een gezamenlijke huishouding is voor de Wvps niet voldoende."], ["Ja, maar alleen als zij samen kinderen hebben", "Het hebben van kinderen maakt de Wvps niet van toepassing op samenwoners."], ["Ja, mits zij meer dan vijf jaar samenwoonden", "De duur van het samenwonen is voor de Wvps niet bepalend."]]],
["Kunnen echtgenoten afwijken van de standaardverevening van de Wvps?", [["Ja, via huwelijkse voorwaarden of een echtscheidingsconvenant kunnen zij anders verdelen of verevening uitsluiten", "De Wvps is de standaard, maar partijen kunnen schriftelijk iets anders overeenkomen."], ["Nee, de gelijke verdeling is dwingend recht; alleen de rechter kan bij de echtscheidingsuitspraak daarvan afwijken", "Afwijken is mogelijk via huwelijkse voorwaarden of een convenant."], ["Alleen met toestemming van De Nederlandsche Bank", "DNB houdt toezicht op uitvoerders en beslist niet over afspraken tussen ex-partners."], ["Alleen als de pensioenuitvoerder daartoe zelf besluit", "De afspraak ligt bij de echtgenoten zelf; de uitvoerder voert hun keuze uit."]]],
["Tussen welke partijen wordt de pensioenovereenkomst gesloten?", [["Tussen de werkgever en de werknemer", "De pensioenovereenkomst is de afspraak over pensioen als onderdeel van de arbeidsvoorwaarden."], ["Tussen de werkgever en de pensioenuitvoerder", "Dat is de uitvoeringsovereenkomst, niet de pensioenovereenkomst."], ["Tussen de werknemer en de pensioenuitvoerder", "De relatie tussen uitvoerder en werknemer is vastgelegd in het pensioenreglement."], ["Tussen de werknemer en De Nederlandsche Bank", "DNB is toezichthouder en geen partij bij een pensioenovereenkomst."]]],
["Hoe heet de overeenkomst tussen de werkgever en de pensioenuitvoerder over de uitvoering van de pensioenregeling?", [["De uitvoeringsovereenkomst", "Daarin leggen werkgever en uitvoerder onder meer vast hoe de premie wordt betaald en welke informatie wordt uitgewisseld."], ["Het pensioenreglement", "Het pensioenreglement beschrijft de rechten en plichten tussen uitvoerder en deelnemer."], ["De pensioenovereenkomst", "De pensioenovereenkomst sluit de werkgever met de werknemer."], ["Het uitvoeringsreglement", "Een uitvoeringsreglement wordt gebruikt bij verplichte deelneming in een bedrijfstakpensioenfonds, maar de algemene term is uitvoeringsovereenkomst."]]],
["Wat houdt de onderbrengingsplicht van de Pensioenwet in?", [["De werkgever moet de pensioenovereenkomst onderbrengen bij een pensioenfonds, pensioenverzekeraar of PPI", "Zo staat het pensioenvermogen los van het risico van de onderneming."], ["De werkgever moet iedere werknemer een pensioenregeling aanbieden", "De Pensioenwet verplicht niet tot het aanbieden van pensioen; een verplichting kan wel voortvloeien uit een cao of verplichtstelling."], ["De werknemer moet zijn pensioen zelf bij een verzekeraar onderbrengen", "De plicht rust op de werkgever, niet op de werknemer."], ["De werkgever moet het pensioenvermogen op een geblokkeerde bankrekening van de onderneming zetten, gescheiden van het werkkapitaal", "Pensioenvermogen binnen de eigen onderneming houden is juist niet toegestaan voor werknemers."]]],
["Is een werkgever wettelijk verplicht om zijn werknemers een pensioenregeling aan te bieden?", [["Nee, tenzij een verplichtstelling van een bedrijfstakpensioenfonds of een cao hem daartoe verplicht", "De Pensioenwet regelt wat geldt als er een pensioenregeling is, maar kent geen algemene plicht om er een aan te bieden."], ["Ja, iedere werkgever met personeel moet pensioen aanbieden", "Een algemene pensioenplicht voor werkgevers bestaat in Nederland niet."], ["Ja, maar alleen voor werknemers met een vast contract", "Ook voor vaste werknemers bestaat geen algemene wettelijke plicht."], ["Nee, en een werkgever kan ook niet via een verplichtstelling van een bedrijfstakpensioenfonds worden verplicht", "Via een verplichtstelling kan deelneming in een bedrijfstakpensioenfonds wel verplicht zijn."]]],
["Welke omschrijving past bij een uitkeringsovereenkomst?", [["De werkgever zegt een bepaalde pensioenuitkering toe, bijvoorbeeld op basis van middelloon", "Bij een uitkeringsovereenkomst staat de hoogte van de uitkering centraal en is de benodigde premie variabel."], ["De werkgever zegt een vaste premie toe en de uitkering hangt af van het rendement", "Dat is een premieovereenkomst."], ["De werkgever zegt een vast kapitaal op de pensioendatum toe waarmee een uitkering wordt aangekocht", "Dat is een kapitaalovereenkomst."], ["De werknemer bepaalt zelf jaarlijks hoeveel premie de werkgever betaalt", "Zo werkt geen van de wettelijke pensioenovereenkomsten."]]],
["Wat kenmerkt een kapitaalovereenkomst?", [["Er wordt een vast kapitaal op de pensioendatum toegezegd, waarmee een uitkering wordt aangekocht", "Het kapitaal ligt vast; de hoogte van de uitkering hangt af van de inkooptarieven op dat moment."], ["Er wordt een vaste levenslange uitkering toegezegd", "Een toegezegde uitkering hoort bij de uitkeringsovereenkomst."], ["Er wordt alleen een vaste premie toegezegd zonder enige garantie", "Dat is kenmerkend voor de premieovereenkomst."], ["Er wordt een vast kapitaal toegezegd dat op de pensioendatum vrij opneembaar als bedrag ineens wordt uitgekeerd", "Het kapitaal moet worden omgezet in een pensioenuitkering en is niet vrij opneembaar."]]],
["Bij welke pensioenovereenkomst ligt het beleggingsrisico in beginsel bij de deelnemer?", [["Bij de premieovereenkomst", "De werkgever betaalt een afgesproken premie; de uiteindelijke uitkering hangt af van het beleggingsresultaat."], ["Bij de uitkeringsovereenkomst", "Daar is een uitkering toegezegd en ligt het risico vooral bij de uitvoerder en het collectief."], ["Bij de kapitaalovereenkomst", "Het kapitaal ligt vast; het beleggingsrisico tijdens de opbouw ligt niet bij de deelnemer."], ["Bij geen enkele overeenkomst; dat risico ligt altijd bij de werkgever", "Bij een premieovereenkomst draagt de werkgever het beleggingsrisico juist niet."]]],
["Wat is waardeoverdracht?", [["Het meenemen van de waarde van opgebouwde pensioenaanspraken naar de uitvoerder van de nieuwe werkgever", "De gewezen deelnemer kan zo zijn pensioen bundelen bij de uitvoerder van de nieuwe werkgever."], ["Het overdragen van pensioen aan de ex-partner na scheiding", "Verdeling bij scheiding verloopt via verevening of conversie, niet via waardeoverdracht."], ["Het uitkeren van de waarde van het pensioen als bedrag ineens bij uitdiensttreding, waarover loonheffing wordt ingehouden", "Dat is afkoop; bij waardeoverdracht blijft het geld bestemd voor pensioen."], ["Het omzetten van pensioen in een lijfrente bij een bank", "Waardeoverdracht gaat naar de pensioenuitvoerder van de nieuwe werkgever, niet naar een bancaire lijfrente."]]],
["Wanneer is individuele waardeoverdracht tijdelijk niet toegestaan?", [["Als de dekkingsgraad van de overdragende of de ontvangende pensioenuitvoerder onder de 100% ligt", "Zo wordt voorkomen dat een tekort wordt meegenomen of dat achterblijvers worden benadeeld."], ["Als de werknemer korter dan tien jaar bij de oude werkgever heeft gewerkt en dus nog geen onvoorwaardelijke aanspraak heeft", "Er geldt geen minimale diensttijd van tien jaar voor waardeoverdracht."], ["Als de nieuwe werkgever in een andere bedrijfstak actief is", "Een andere bedrijfstak is geen grond om waardeoverdracht te weigeren."], ["Als de werknemer ouder is dan 55 jaar", "Er geldt geen leeftijdsgrens van 55 jaar voor waardeoverdracht."]]],
["Wat is het doel van de regels voor automatische waardeoverdracht van kleine pensioenen?", [["Voorkomen dat deelnemers veel kleine, versnipperde pensioenen bij verschillende uitvoerders houden", "Kleine pensioenen worden zo samengevoegd bij de uitvoerder van de nieuwe werkgever, zodat ze niet verloren gaan of worden afgekocht."], ["Kleine pensioenen bij uitdiensttreding direct contant uitbetalen, zodat de deelnemer er zelf over kan beschikken", "De regeling is juist bedoeld om kleine pensioenen voor de oude dag te behouden."], ["Kleine pensioenen overbrengen naar de AOW", "Tweedepijlerpensioen kan niet naar de AOW worden overgebracht."], ["Kleine pensioenen laten omzetten in een lijfrente op naam van de werkgever", "Een pensioen wordt niet omgezet in een lijfrente op naam van de werkgever."]]],
["Aan welke eisen moet pensioeninformatie volgens de Pensioenwet in ieder geval voldoen?", [["Correct, duidelijk en evenwichtig", "De informatie moet ook begrijpelijk en tijdig zijn, zodat de deelnemer er een beslissing op kan baseren."], ["Volledig, juridisch en uitputtend", "Uitputtende juridische informatie gaat juist ten koste van de begrijpelijkheid."], ["Uitsluitend schriftelijk en op papier", "Pensioeninformatie mag ook elektronisch worden verstrekt."], ["Vooraf goedgekeurd door de AFM", "De AFM houdt toezicht op pensioencommunicatie, maar keurt informatie niet vooraf goed."]]],
["Wat is het Uniform Pensioenoverzicht (UPO) voor een actieve deelnemer?", [["Een periodiek overzicht van de uitvoerder met opgebouwde en te bereiken pensioenaanspraken in vaste opzet", "Doordat alle uitvoerders dezelfde opzet volgen, zijn overzichten onderling vergelijkbaar."], ["Een overzicht dat de adviseur verplicht moet opstellen bij elk pensioenadvies en jaarlijks aan de klant moet sturen", "Het UPO komt van de pensioenuitvoerder, niet van de adviseur."], ["Een jaarlijks overzicht van de SVB met alleen de AOW", "De SVB informeert over de AOW; het UPO gaat over het pensioen bij de uitvoerder."], ["Een contract waarin de werknemer zijn keuzes vastlegt", "Het UPO is een informatieoverzicht, geen contract."]]],
["Kees heeft bij uitdiensttreding een premievrije aanspraak achtergelaten bij zijn oude pensioenfonds. Hoe heet Kees ten opzichte van dat fonds?", [["Gewezen deelnemer", "Een gewezen deelnemer bouwt geen pensioen meer op maar heeft nog wel opgebouwde aanspraken."], ["Pensioengerechtigde", "Een pensioengerechtigde ontvangt al een pensioenuitkering; Kees bouwt alleen niet meer op."], ["Aspirant-deelnemer", "Een aspirant-deelnemer moet nog gaan deelnemen in de regeling."], ["Actieve deelnemer", "Een actieve deelnemer bouwt nog pensioen op bij het fonds; Kees is uit dienst."]]],
["Welke twee typen premieregelingen kent de Wet toekomst pensioenen?", [["De solidaire premieregeling en de flexibele premieregeling", "In het nieuwe stelsel worden pensioenen opgebouwd in een van deze twee regelingen."], ["De middelloonregeling en de eindloonregeling", "Dit zijn varianten van de uitkeringsovereenkomst die in het nieuwe stelsel verdwijnen."], ["De kapitaalregeling en de beschikbare-premieregeling nieuwe stijl", "Deze termen horen bij het oude stelsel en zijn niet de twee nieuwe Wtp-contracten."], ["De collectieve regeling en de bancaire regeling", "Een 'bancaire regeling' bestaat niet als contractvorm onder de Wtp."]]],
["Wat is een kenmerk van de solidaire premieregeling?", [["Er wordt collectief belegd, met een solidariteitsreserve om schokken te dempen en risico's te delen", "Het rendement wordt via vaste regels aan leeftijdsgroepen toegedeeld; de solidariteitsreserve zorgt voor extra risicodeling."], ["Iedere deelnemer kiest zelf zijn beleggingsmix en draagt het volledige risico, zonder collectieve reserve", "Dat past meer bij de flexibele premieregeling."], ["De uitkering is gegarandeerd door de werkgever", "In de solidaire premieregeling is geen uitkering gegarandeerd; er is een pensioenambitie."], ["Er wordt niet belegd; het pensioen groeit alleen met de premies", "Ook in de solidaire premieregeling wordt belegd."]]],
["Wat is een kenmerk van de flexibele premieregeling?", [["De deelnemer heeft een eigen pensioenvermogen dat volgens een lifecycle wordt belegd, met keuzemogelijkheden", "Het risico wordt afgestemd op de leeftijd en het risicoprofiel van de deelnemer."], ["Alle deelnemers delen één collectief vermogen zonder persoonlijke toedeling, met een solidariteitsreserve voor schokken", "In beide Wtp-regelingen heeft de deelnemer een persoonlijk pensioenvermogen."], ["De werkgever kiest elk jaar opnieuw de hoogte van de uitkering", "De uitkering hangt af van het opgebouwde vermogen, niet van een jaarlijkse werkgeverskeuze."], ["De deelnemer mag het vermogen op elk moment vrij opnemen", "Pensioenvermogen blijft bestemd voor pensioen en is niet vrij opneembaar."]]],
["Wat betekent het afschaffen van de doorsneesystematiek onder de Wtp?", [["Iedere deelnemer krijgt een leeftijdsonafhankelijke premie, waardoor jongeren relatief meer opbouwen dan voorheen", "Voorheen gold een gelijk opbouwpercentage tegen een gelijke premie; nu levert de premie per leeftijd een eigen opbouw op."], ["De premie wordt hoger naarmate de deelnemer ouder wordt, waardoor oudere werknemers juist meer pensioen opbouwen", "Een stijgende premie (staffel) was juist kenmerkend voor oude premieregelingen; de Wtp gaat uit van een vlakke premie."], ["Iedere deelnemer bouwt jaarlijks hetzelfde percentage pensioen op over zijn pensioengrondslag, ongeacht zijn leeftijd", "Dat was juist de doorsneesystematiek die verdwijnt."], ["De AOW wordt voortaan door pensioenfondsen uitgekeerd", "De AOW blijft een volksverzekering via de SVB."]]],
["Waarom moeten sociale partners bij de transitie naar het nieuwe stelsel aandacht besteden aan compensatie?", [["Omdat vooral middelbare en oudere werknemers nadeel kunnen hebben van de overgang naar een vlakke premie", "Zij hebben in hun jonge jaren relatief weinig opgebouwd en bouwen bij een vlakke premie later minder op dan onder de doorsneesystematiek."], ["Omdat jongeren door de Wtp een lagere AOW krijgen", "De Wtp verandert de AOW niet."], ["Omdat werkgevers na de transitie geen premie meer hoeven te betalen en werknemers de volledige premie zelf dragen", "Werkgevers blijven premie betalen in het nieuwe stelsel."], ["Omdat gepensioneerden hun hele uitkering moeten terugbetalen", "Gepensioneerden hoeven niets terug te betalen."]]],
["Wat wordt bij de transitie bedoeld met invaren?", [["Het omzetten van bestaande, opgebouwde pensioenaanspraken en -rechten naar de nieuwe premieregeling", "Na invaren worden ook oude rechten in het nieuwe contract voortgezet als persoonlijk pensioenvermogen of uitkering."], ["Het overstappen van een werknemer naar een andere werkgever, waarbij zijn pensioen naar de nieuwe uitvoerder gaat", "Dat leidt hooguit tot waardeoverdracht, niet tot invaren."], ["Het afkopen van alle pensioenen bij de overstap", "Invaren betekent juist dat de rechten blijven bestaan in het nieuwe contract."], ["Het aanmelden van nieuwe werknemers bij een pensioenfonds", "Dat is aanmelding van deelnemers, geen invaren."]]],
["Wat is de uiterste datum waarop pensioenregelingen moeten zijn overgegaan naar het nieuwe stelsel van de Wtp?", [["1 januari 2028", "De transitieperiode van de Wtp loopt tot uiterlijk 1 januari 2028."], ["1 januari 2027", "Dat was de oorspronkelijke einddatum; deze is verschoven naar 1 januari 2028."], ["1 juli 2023", "Op 1 juli 2023 is de Wtp in werking getreden; dat is het begin, niet het einde van de transitie."], ["31 december 2029", "De transitieperiode loopt niet tot eind 2029."]]],
["Op welke datum is de Wet toekomst pensioenen in werking getreden?", [["1 juli 2023", "Vanaf die datum liep de transitieperiode naar het nieuwe stelsel."], ["1 januari 2022", "In 2022 lag het wetsvoorstel nog bij het parlement."], ["1 januari 2025", "Op die datum stapten sommige fondsen over, maar de wet gold al eerder."], ["1 januari 2028", "Dat is de uiterste transitiedatum, niet de datum van inwerkingtreding."]]],
["Heeft een individuele deelnemer onder de Wtp een bezwaarrecht tegen het invaren van zijn pensioen?", [["Nee, er is geen individueel bezwaarrecht; belangen worden geborgd via een evenwichtige afweging door het bestuur en de fondsorganen", "Het bestuur moet evenwichtig afwegen en verantwoorden; de verantwoordings- of belanghebbendenorganen hebben een versterkte rol."], ["Ja, iedere deelnemer kan binnen zes maanden na het transitiebesluit van het fonds individueel schriftelijk bezwaar maken tegen invaren", "Een individueel bezwaarrecht is bewust niet in de wet opgenomen."], ["Ja, maar alleen deelnemers ouder dan 60 jaar", "Er bestaat geen leeftijdsgebonden individueel bezwaarrecht."], ["Nee, maar de deelnemer kan wel eisen dat zijn opgebouwde pensioen vóór de transitiedatum wordt afgekocht of overgedragen", "Afkoop als alternatief voor invaren is niet mogelijk."]]],
["Hoe is het partnerpensioen vóór de pensioendatum onder de Wtp in beginsel geregeld?", [["Op risicobasis, met een maximale hoogte die is gekoppeld aan het salaris", "Daardoor hangt de dekking niet meer af van het aantal dienstjaren; de wet stelt een maximum van 50% van het salaris."], ["Op opbouwbasis, afhankelijk van het aantal dienstjaren bij de huidige werkgever", "De Wtp kiest voor risicobasis zodat de hoogte niet van de diensttijd afhangt."], ["Het partnerpensioen is onder de Wtp afgeschaft", "Het partnerpensioen blijft bestaan, maar op risicobasis."], ["Als een vast bedrag dat voor iedere deelnemer gelijk is", "De hoogte is gerelateerd aan het salaris, niet een vast bedrag."]]],
["Welk gevolg heeft het nabestaandenpensioen op risicobasis voor werknemers die van baan wisselen of werkloos worden?", [["Na einde dienstverband loopt de dekking nog kort door (uitloop) en vervalt daarna; zij moeten hun dekking opnieuw bekijken", "Bij risicobasis bestaat de dekking alleen tijdens de deelneming plus de wettelijke uitloop."], ["De dekking blijft levenslang bestaan bij de oude werkgever, ook als de werknemer daarna geen premie meer betaalt", "Bij risicobasis is er geen blijvende aanspraak na afloop."], ["De dekking gaat automatisch over naar de AOW", "Er bestaat geen overgang van partnerpensioen naar de AOW."], ["De werknemer krijgt bij einde dienstverband het opgebouwde partnerpensioen als bedrag ineens uitbetaald, belast in box 1", "Op risicobasis wordt niets opgebouwd dat kan worden uitbetaald."]]],
["Wat betekent de keuze voor een variabele pensioenuitkering in het nieuwe stelsel?", [["De uitkering kan meebewegen met beleggingsresultaten en ontwikkelingen in de levensverwachting", "Een variabele uitkering kan stijgen en dalen; schokken kunnen wel over enkele jaren worden gespreid."], ["De uitkering is gegarandeerd en stijgt jaarlijks met de inflatie", "Een variabele uitkering is juist niet gegarandeerd."], ["De deelnemer kiest zelf per maand het bedrag dat hij opneemt", "Ook een variabele uitkering is een periodieke pensioenuitkering volgens vaste regels, geen vrije opname."], ["De uitkering stopt zodra het persoonlijke pensioenvermogen op is, ongeacht de leeftijd van de gepensioneerde", "Een pensioenuitkering is in beginsel levenslang."]]],
["Geldt na het einde van de transitie nog een uitkeringsovereenkomst als vorm voor nieuwe pensioenopbouw?", [["Nee, nieuwe opbouw vindt dan plaats in een premieovereenkomst nieuwe stijl", "De Wtp maakt een einde aan nieuwe opbouw in uitkeringsovereenkomsten."], ["Ja, werkgevers mogen vrij kiezen tussen een uitkeringsovereenkomst en een premieovereenkomst", "Na de transitie is nieuwe opbouw in een uitkeringsovereenkomst niet meer toegestaan."], ["Ja, maar alleen voor werknemers ouder dan 50 jaar", "Er bestaat geen leeftijdsuitzondering voor nieuwe opbouw in een uitkeringsovereenkomst."], ["Ja, als de werkgever zelf garant staat voor de uitkering", "Een garantie van de werkgever maakt nieuwe opbouw in een uitkeringsovereenkomst niet mogelijk."]]],
["Ahmed heeft een premieregeling met een leeftijdsafhankelijke premiestaffel. Zijn werkgever stapt over naar een regeling onder de Wtp. Wat kan voor hem gelden?", [["Sociale partners kunnen kiezen voor eerbiedigende werking, zodat zijn staffel onder voorwaarden mag doorlopen", "Nieuwe werknemers krijgen dan een vlakke premie; bestaande deelnemers kunnen hun staffel houden."], ["Zijn staffel moet op 1 januari 2028 in alle gevallen met terugwerkende kracht worden teruggedraaid naar een vlakke premie", "Eerdere opbouw wordt niet teruggedraaid; voor bestaande deelnemers kan de staffel zelfs doorlopen."], ["Hij moet zelf het verschil in premie bijbetalen", "Een deelnemer hoeft geen premieverschil bij te betalen vanwege de overgang."], ["Hij verliest het al opgebouwde pensioenvermogen", "Opgebouwd pensioenvermogen blijft van de deelnemer."]]],
["Hoe worden te verwachten pensioenuitkeringen in het nieuwe stelsel aan deelnemers getoond?", [["In verschillende scenario's, zoals een verwacht, een optimistisch en een pessimistisch scenario", "Zo ziet de deelnemer dat het pensioen niet vastligt en kan meebewegen met de economie."], ["Als één gegarandeerd bedrag dat bij de start van de uitkering wordt vastgezet en niet meer kan wijzigen", "In het nieuwe stelsel is de uitkering niet gegarandeerd."], ["Uitsluitend als totaalbedrag van alle betaalde premies", "Alleen ingelegde premie zegt weinig over de te verwachten uitkering."], ["Alleen als percentage van het laatstverdiende loon", "Een vervangingsratio kan helpen, maar de wettelijke communicatie werkt met scenario's."]]],
["Welke informatie moeten deelnemers rond de transitie in ieder geval krijgen van hun pensioenuitvoerder?", [["Persoonlijke informatie over hun pensioen vóór en na de overstap, zodat het effect zichtbaar is", "Deelnemers moeten kunnen zien wat de overstap voor hun eigen pensioen betekent."], ["Een aanbod om het pensioen af te kopen in plaats van over te stappen", "De transitie biedt geen afkoopmogelijkheid als alternatief."], ["Een verzoek om zelf een nieuwe pensioenuitvoerder te kiezen", "De keuze van de uitvoerder ligt bij werkgever en sociale partners, niet bij de deelnemer."], ["Uitsluitend algemene informatie over de wet en de transitie, zonder persoonlijke gegevens over de eigen aanspraken", "Algemene informatie is niet genoeg; juist persoonlijke informatie is belangrijk."]]],
["Een klant zegt na een brief over de Wtp: 'Mijn pensioen is nu een potje geld, dus ik kan het straks vrij opnemen.' Wat is de juiste reactie van de adviseur?", [["Het vermogen blijft bestemd voor een pensioenuitkering; vrije opname kan niet, wel mogelijk tot 10% ineens op de pensioendatum", "Het vermogen wordt gebruikt voor een levenslange uitkering; de keuze voor een bedrag ineens is beperkt."], ["Dat klopt, vanaf de pensioendatum kan hij het hele vermogen vrij opnemen, mits hij over het opgenomen bedrag box 1-belasting betaalt", "Vrije opname van het hele pensioenvermogen is niet toegestaan."], ["Dat klopt, het vermogen kan al vóór de pensioendatum worden opgevraagd, bijvoorbeeld voor aflossing van de hypotheek", "Het pensioenvermogen is niet vóór de pensioendatum opvraagbaar."], ["Het pensioenvermogen gaat bij de overstap naar de AOW", "Tweedepijlerpensioen en AOW blijven gescheiden."]]],
["Wat is het Witteveenkader?", [["Het fiscale kader in de Wet op de loonbelasting dat de maximale fiscaal gefaciliteerde pensioenopbouw of -premie bepaalt", "Binnen dit kader geldt de omkeerregel; daarboven is de opbouw niet fiscaal gefaciliteerd."], ["Het financieel toetsingskader van DNB voor de financiële positie van pensioenfondsen, met eisen aan buffers en dekkingsgraad", "Het financieel toetsingskader van DNB gaat over buffers, niet over fiscale grenzen."], ["De regels voor pensioenverdeling bij scheiding", "Pensioenverdeling bij scheiding staat in de Wvps."], ["De regels voor de AOW-opbouw van migranten", "De AOW-opbouw is geregeld in de Algemene Ouderdomswet."]]],
["Wat houdt de omkeerregel in bij pensioen?", [["Premies en aanspraken zijn tijdens de opbouw onbelast of aftrekbaar; de uitkeringen zijn belast", "De belastingheffing wordt uitgesteld tot het moment van uitkeren."], ["Premies zijn belast en de uitkeringen zijn onbelast", "Die systematiek geldt bij nettopensioen en netto-lijfrente, niet bij de omkeerregel."], ["Zowel premies als uitkeringen zijn onbelast", "Volledige vrijstelling bestaat niet; de uitkering wordt belast."], ["De werkgever betaalt de belasting over de uitkering in plaats van de werknemer, als eindheffing via de loonaangifte", "De gepensioneerde betaalt zelf belasting over de pensioenuitkering."]]],
["Wat gebeurt er fiscaal als een pensioenregeling de grenzen van het Witteveenkader overschrijdt?", [["De regeling wordt bovenmatig en verliest haar fiscale status, waardoor de aanspraak als loon belast kan worden", "Een bovenmatige regeling is onzuiver; dat leidt tot belastingheffing bij de werknemer."], ["Alleen het bovenmatige deel wordt pas belast bij uitkering, zonder gevolgen voor de rest van de pensioenregeling", "Het gevolg is ingrijpender: de regeling verliest haar status als pensioenregeling."], ["De werkgever moet de pensioenuitvoerder een boete betalen", "Er is geen boete aan de uitvoerder; het gevolg is fiscaal."], ["Er gebeurt niets; het Witteveenkader is een richtlijn zonder gevolgen", "Overschrijding van het fiscale kader heeft wel degelijk fiscale gevolgen."]]],
["Wat is de franchise in een pensioenregeling?", [["Het deel van het salaris waarover geen pensioen wordt opgebouwd, omdat daar de AOW al in voorziet", "Pensioengevend salaris minus franchise is de pensioengrondslag."], ["Het maximale pensioengevende salaris waarboven geen fiscaal gefaciliteerde opbouw meer mogelijk is", "Dat is de aftoppingsgrens (het maximum pensioengevend loon), niet de franchise."], ["Het eigen risico dat de deelnemer betaalt bij arbeidsongeschiktheid", "De franchise heeft niets met arbeidsongeschiktheid te maken."], ["Het deel van de premie dat de werknemer zelf betaalt", "Dat is de werknemersbijdrage."]]],
["Wat verandert de Wtp aan de systematiek van het Witteveenkader?", [["De fiscale grens wordt uitgedrukt als een maximale premie in plaats van een maximaal opbouwpercentage", "Bij premieregelingen nieuwe stijl past een premiegrens beter dan een opbouwgrens."], ["Het fiscale kader vervalt volledig; elke premie is aftrekbaar", "Er blijft een fiscaal maximum gelden."], ["De omkeerregel wordt vervangen door belastingheffing in box 3", "De omkeerregel blijft bestaan; pensioen valt niet in box 3."], ["Pensioenopbouw wordt alleen nog fiscaal gefaciliteerd over het salaris tot de franchise, daarboven via nettopensioen", "De franchise is juist het deel waarover geen pensioen wordt opgebouwd."]]],
["Tot wanneer mag een ouderdomspensioen fiscaal gezien uiterlijk ingaan?", [["Uiterlijk vijf jaar na de AOW-leeftijd", "Uitstel van het pensioen is fiscaal toegestaan tot vijf jaar na de AOW-leeftijd."], ["Uiterlijk op de AOW-leeftijd, uitstel is niet toegestaan", "Uitstel na de AOW-leeftijd is wel mogelijk, tot een maximum."], ["Uiterlijk tien jaar na de AOW-leeftijd", "Tien jaar is langer dan fiscaal is toegestaan."], ["Er geldt geen uiterste ingangsdatum", "Er geldt wel een fiscale uiterste ingangsdatum."]]],
["Welk deel van de waarde van het ouderdomspensioen kan een deelnemer op de pensioeningangsdatum maximaal als bedrag ineens laten uitbetalen?", [["10%", "De deelnemer mag maximaal 10% van de waarde van zijn ouderdomspensioen op de ingangsdatum ineens opnemen."], ["25%", "25% is meer dan de wet toestaat; het maximum is 10%."], ["7,5%", "Het maximum ligt hoger, namelijk op 10%."], ["50%", "Zo'n groot deel ineens opnemen is niet toegestaan; het maximum is 10%."]]],
["Joke overweegt op haar pensioendatum een bedrag ineens op te nemen. Waarop moet de adviseur haar in elk geval wijzen?", [["Het bedrag ineens is belast in box 1, kan gevolgen hebben voor toeslagen en verlaagt haar periodieke pensioen blijvend", "Door het hogere inkomen in het jaar van opname kunnen belasting en inkomensafhankelijke regelingen ongunstig uitpakken."], ["Het bedrag ineens is onbelast omdat over de premie al belasting is betaald, en het telt ook niet mee voor toeslagen", "Door de omkeerregel is over de premie juist geen belasting betaald; de uitkering is belast."], ["Haar periodieke pensioen blijft even hoog; het bedrag ineens komt daar bovenop en wordt tegen een bijzonder tarief in box 3 belast", "Het bedrag ineens gaat ten koste van de latere periodieke uitkering."], ["Het bedrag ineens kan zij op elk gewenst moment na de pensioendatum opvragen, uiterlijk tot haar 75e verjaardag", "De keuze moet op de pensioeningangsdatum worden gemaakt, niet op een willekeurig later moment."]]],
["Wanneer is de premie voor een lijfrente in box 1 aftrekbaar?", [["Als er een pensioentekort is, binnen de jaarruimte of reserveringsruimte", "Lijfrentepremie is alleen aftrekbaar voor zover de belastingplichtige een pensioentekort heeft."], ["Altijd volledig, ongeacht het pensioen dat al via de werkgever wordt opgebouwd", "De aftrek is beperkt tot de jaarruimte en reserveringsruimte."], ["Alleen als de lijfrente bij een pensioenfonds wordt afgesloten", "Lijfrente kan bij een verzekeraar of bank lopen; een pensioenfonds is niet vereist."], ["Alleen als de premie door de werkgever wordt betaald", "Lijfrente is juist een individuele voorziening die de klant zelf betaalt."]]],
["Wat is de reserveringsruimte bij lijfrente?", [["Niet benutte jaarruimte uit eerdere jaren, die binnen wettelijke grenzen alsnog benut kan worden", "Wie in eerdere jaren zijn jaarruimte niet benutte, kan dat beperkt inhalen."], ["De ruimte om lijfrente op te nemen vóór de pensioendatum", "Reserveringsruimte gaat over aftrek van premie, niet over vervroegde opname."], ["Het bedrag dat een bank reserveert voor administratiekosten", "Dat is geen fiscaal begrip."], ["Het deel van de lijfrente dat bij overlijden vóór de einddatum naar de erfgenamen gaat, vrij van belasting", "Dat heeft niets met de reserveringsruimte te maken."]]],
["Hoe wordt een fiscaal gefaciliteerde lijfrente tijdens de opbouwfase in box 3 behandeld?", [["Het lijfrentetegoed is vrijgesteld in box 3", "Omdat de uitkeringen later in box 1 worden belast, valt de waarde tijdens de opbouw niet in box 3."], ["Het tegoed wordt jaarlijks belast als vermogen in box 3", "De fiscaal gefaciliteerde lijfrente is in box 3 vrijgesteld."], ["Het tegoed wordt belast in box 2", "Box 2 gaat over een aanmerkelijk belang, niet over lijfrente."], ["Het tegoed wordt belast als het boven de lijfrentegrens uitkomt", "Er geldt geen aparte box 3-heffing boven een lijfrentegrens."]]],
["Wat is een fiscaal gevolg als een fiscaal gefaciliteerde lijfrente in één keer wordt afgekocht?", [["De afkoopsom is belast in box 1 en er kan revisierente verschuldigd zijn", "Omdat de premie eerder aftrekbaar was, wordt de afkoop belast en kan revisierente over de waarde worden geheven."], ["De afkoopsom is onbelast omdat het eigen spaargeld betreft dat al in box 3 werd belast", "De premie is eerder afgetrokken; de afkoopsom is daarom belast."], ["De afkoopsom valt in box 3 tegen het forfaitaire rendement", "Afkoop van een gefaciliteerde lijfrente wordt in box 1 belast."], ["Afkopen van een lijfrente is wettelijk nooit toegestaan", "Afkopen kan, maar heeft fiscale gevolgen."]]],
["Wat is het nettopensioen?", [["Een vrijwillige regeling via de pensioenuitvoerder voor opbouw boven de aftoppingsgrens, betaald uit nettoloon", "Inleg is niet aftrekbaar; de uitkering is onbelast en het vermogen is vrijgesteld in box 3."], ["De AOW na aftrek van loonheffing", "Dat is de netto AOW, niet het nettopensioen."], ["Het werkgeverspensioen na aftrek van de werknemersbijdrage en de loonheffing over de pensioenpremie", "Het nettopensioen is een aparte regeling boven de aftoppingsgrens."], ["Een pensioen waarover de werkgever de belasting betaalt, zodat de werknemer een netto-uitkering ontvangt zonder heffing", "Bij het nettopensioen betaalt de werknemer de inleg uit zijn nettoloon."]]],
["Ilse verdient ruim boven de aftoppingsgrens voor fiscaal gefaciliteerde pensioenopbouw. Haar werkgever biedt een nettopensioenregeling aan. Wat is daarvan een kenmerk?", [["De inleg is niet aftrekbaar en de uitkering is onbelast", "Het nettopensioen werkt tegenovergesteld aan de omkeerregel; de waarde is tijdens de opbouw vrijgesteld in box 3."], ["De inleg is aftrekbaar en de uitkering is belast in box 1", "Dat is de omkeerregel van het gewone pensioen; bij nettopensioen is het andersom."], ["De werkgever is verplicht de volledige premie te betalen", "Het nettopensioen wordt uit het nettoloon van de werknemer betaald; deelname is vrijwillig."], ["Het opgebouwde vermogen telt mee in box 3", "Het vermogen in een nettopensioenregeling is vrijgesteld in box 3."]]],
["Waar kan een particulier een fiscaal gefaciliteerde lijfrente in de opbouwfase onderbrengen?", [["Bij een verzekeraar, of bij een bank of beleggingsinstelling via een lijfrenterekening of -beleggingsrecht", "Sinds de introductie van banksparen kan lijfrente ook bancair worden opgebouwd."], ["Uitsluitend bij een bedrijfstakpensioenfonds", "Een bedrijfstakpensioenfonds voert tweedepijlerpensioen uit, geen individuele lijfrentes."], ["Uitsluitend bij de SVB", "De SVB voert volksverzekeringen uit en biedt geen lijfrentes aan."], ["Op een gewone spaarrekening op eigen naam zonder blokkering, mits de klant het tegoed niet vóór zijn AOW-leeftijd opneemt", "Voor fiscale facilitering moet het tegoed geblokkeerd zijn en aan voorwaarden voldoen."]]],
["Sinds wanneer kan een dga geen nieuw pensioen meer opbouwen in eigen beheer?", [["Sinds 1 april 2017", "Met de Wet uitfasering pensioen in eigen beheer is verdere opbouw per 1 april 2017 beëindigd."], ["Sinds 1 januari 2015", "Op die datum is de fiscale pensioenopbouw beperkt, maar pensioen in eigen beheer bestond nog."], ["Sinds 1 januari 2020", "Op die datum was de opbouw al jaren beëindigd."], ["Sinds 1 juli 2023", "Dat is de ingangsdatum van de Wtp, niet de datum van de uitfasering van pensioen in eigen beheer."]]],
["Welke keuzemogelijkheden had een dga bij de uitfasering van pensioen in eigen beheer?", [["Premievrij laten staan, afkopen met fiscale korting of omzetten in een oudedagsverplichting", "Afkopen met korting was alleen tijdelijk mogelijk; premievrij laten staan en de oudedagsverplichting bleven als opties over."], ["Het pensioen overdragen aan de SVB als aanvulling op de AOW, of het als dividend uitkeren uit de bv", "Pensioen in eigen beheer kan niet naar de SVB worden overgedragen."], ["Doorgaan met opbouw in eigen beheer tot de pensioendatum", "Verdere opbouw is juist beëindigd."], ["Het pensioen omzetten in een nettopensioen in eigen beheer", "Ook een nettopensioen kan niet in eigen beheer worden opgebouwd."]]],
["Wat is een oudedagsverplichting (ODV)?", [["Een verplichting van de bv om de dga vanaf een bepaalde leeftijd periodiek uit te keren, ontstaan uit pensioen in eigen beheer", "Bij de ODV vervalt het partnerpensioen; de waarde blijft in de bv."], ["Een verplichte lijfrente die elke dga bij een verzekeraar moet afsluiten over het loon boven de aftoppingsgrens", "De ODV is een verplichting van de eigen bv, geen verzekering."], ["De wettelijke verplichting van iedere werkgever met personeel om werknemers vanaf de AOW-leeftijd een aanvullend pensioen te bieden", "Een algemene werkgeversverplichting tot pensioen bestaat niet."], ["Een AOW-aanvulling voor ondernemers", "De ODV staat los van de AOW."]]],
["Een dga wil zijn pensioen in eigen beheer omzetten in een oudedagsverplichting. Wat is daarvoor nodig als hij gehuwd is?", [["Schriftelijke toestemming van zijn partner, omdat die de aanspraak op partnerpensioen verliest", "Omzetting tast de rechten van de partner aan; daarom moet de partner instemmen."], ["Voorafgaande toestemming van de Belastingdienst, aan te vragen door de bv via een fiscaal vooroverleg", "Een voorafgaande toestemming van de Belastingdienst is geen voorwaarde."], ["Een besluit van de AFM", "De AFM is niet betrokken bij omzetting van pensioen in eigen beheer."], ["Niets, de dga beslist zelfstandig zonder betrokkenheid van zijn partner", "De partner moet juist instemmen omdat hij rechten verliest."]]],
["Waarom kon een dga met een aanmerkelijk belang vroeger pensioen in eigen beheer opbouwen, terwijl dat voor gewone werknemers niet mocht?", [["Omdat de onderbrengingsplicht van de Pensioenwet niet geldt voor de directeur-grootaandeelhouder", "De Pensioenwet beschermt werknemers; voor de dga gold de verplichting om extern onder te brengen niet."], ["Omdat de dga geen AOW ontvangt", "De dga heeft gewoon recht op AOW; dat was niet de reden."], ["Omdat de AFM daarvoor een vergunning afgaf", "Voor pensioen in eigen beheer was geen AFM-vergunning nodig."], ["Omdat de bv daarvoor premie afdroeg aan een bedrijfstakpensioenfonds, dat het pensioen weer aan de bv uitleende", "Bij pensioen in eigen beheer bleef het pensioen juist binnen de eigen bv."]]],
["Hoe kan een dga na de uitfasering van pensioen in eigen beheer nog fiscaal gefaciliteerd voor zijn oude dag sparen?", [["Via een pensioenregeling bij een externe uitvoerder, zoals een verzekeraar, of via lijfrente binnen de jaarruimte", "Opbouw in eigen beheer is niet meer mogelijk, maar externe onderbrenging en lijfrente wel."], ["Door in een tweede, nieuw opgerichte eigen bv opnieuw pensioen in eigen beheer op te bouwen, los van de werkmaatschappij", "Ook in een andere eigen bv kan geen pensioen in eigen beheer meer worden opgebouwd."], ["Door de AOW-leeftijd fiscaal te laten vervroegen", "De AOW-leeftijd is wettelijk bepaald en kan niet fiscaal worden vervroegd."], ["Door privévermogen fiscaal vrijgesteld in box 2 te parkeren", "Een dergelijke vrijstelling bestaat niet."]]],
["Welke rol speelt het loon van de dga bij een externe pensioenregeling?", [["De pensioengrondslag is gebaseerd op het werkelijk genoten loon uit de bv, binnen de fiscale grenzen", "Het pensioen moet passen bij het loon dat de dga werkelijk ontvangt; dividend telt niet mee."], ["Dividenduitkeringen tellen volledig mee als pensioengevend loon, omdat de dga ook aandeelhouder van de bv is", "Dividend is geen loon en is niet pensioengevend."], ["De dga mag een willekeurige pensioengrondslag kiezen", "De grondslag moet aansluiten bij het werkelijke loon en de fiscale regels."], ["Het loon speelt geen rol omdat de dga geen werknemer is", "Fiscaal is de dga werknemer van zijn bv en speelt zijn loon wel een rol."]]],
["Een dga heeft zijn pensioen in eigen beheer premievrij laten staan. Wat betekent dat?", [["De opgebouwde aanspraken blijven in de bv staan, maar er komt geen nieuwe opbouw meer bij", "De bv blijft de verplichting houden het opgebouwde pensioen uit te keren."], ["Het pensioen is daarmee automatisch overgedragen aan een verzekeraar, die de verdere uitvoering overneemt", "Premievrij laten staan betekent juist dat het in de bv blijft."], ["Het pensioen is afgekocht en belast", "Afkoop is een andere keuze dan premievrij laten staan."], ["De bv mag de pensioenverplichting vrij laten vallen", "De bv blijft de verplichting houden tegenover de dga en zijn partner."]]],
["Welke beperking geldt voor een premiepensioeninstelling (PPI)?", [["Een PPI mag alleen premieovereenkomsten uitvoeren en geen biometrische risico's zoals overlijden zelf dragen", "Overlijdens- en arbeidsongeschiktheidsrisico's moet een PPI herverzekeren of bij een verzekeraar onderbrengen."], ["Een PPI mag alleen uitkeringsovereenkomsten uitvoeren en moet daarvoor een solvabiliteitsbuffer aanhouden", "Een PPI is juist bedoeld voor premieovereenkomsten."], ["Een PPI mag alleen pensioenregelingen uitvoeren voor overheidswerkgevers en instellingen in de semipublieke sector", "Een PPI kan door werkgevers in alle sectoren worden gebruikt."], ["Een PPI mag geen beleggingen doen met de premies", "Het beleggen van premies is juist de kern van een PPI."]]],
["Wat is een bedrijfstakpensioenfonds?", [["Een pensioenfonds voor een hele bedrijfstak, waarin de minister deelneming verplicht kan stellen", "Na een verplichtstelling moeten werkgevers in die bedrijfstak aansluiten, tenzij vrijstelling geldt."], ["Een pensioenfonds voor één onderneming of concern", "Dat is een ondernemingspensioenfonds."], ["Een fonds voor beoefenaren van een vrij beroep, zoals medisch specialisten, notarissen en apothekers", "Dat is een beroepspensioenfonds."], ["Een fonds dat door een verzekeraar wordt uitgevoerd onder een verzekeringsvergunning van DNB", "Een bedrijfstakpensioenfonds is een zelfstandige stichting, geen verzekeraar."]]],
["Wat is een kenmerk van een algemeen pensioenfonds (APF)?", [["Het kan regelingen van meerdere werkgevers uitvoeren in financieel gescheiden collectiviteitkringen", "Elke kring heeft een eigen vermogen, zodat tekorten niet worden doorgeschoven naar andere kringen."], ["Het voert uitsluitend de AOW uit", "De AOW wordt uitgevoerd door de SVB."], ["Het is een verzekeraar die ook bankdiensten aanbiedt", "Een APF is een pensioenfonds, geen verzekeraar of bank."], ["Het mag alleen werkgevers met minder dan 50 werknemers bedienen die niet onder een verplichtstelling vallen", "Voor een APF geldt geen grens op basis van het aantal werknemers."]]],
["Welke toezichthouders zijn betrokken bij pensioenuitvoerders?", [["DNB houdt prudentieel toezicht en de AFM gedragstoezicht, waaronder op pensioencommunicatie", "DNB bewaakt de financiële soliditeit, de AFM onder meer de informatieverstrekking aan deelnemers."], ["Alleen de AFM, omdat pensioen een financieel product is en zij ook de financiële soliditeit bewaakt", "De financiële soliditeit valt onder DNB."], ["Alleen DNB, omdat pensioenfondsen geen klanten hebben", "Ook de AFM houdt toezicht, bijvoorbeeld op de pensioencommunicatie."], ["De SVB en het UWV samen", "SVB en UWV zijn uitvoeringsorganisaties, geen toezichthouders op pensioenuitvoerders."]]],
["Een werkgever zonder verplichtstelling wil een premieregeling inclusief partnerpensioen op risicobasis onderbrengen. Welke uitvoerders kan hij kiezen?", [["Een pensioenverzekeraar, een PPI (met herverzekering van het overlijdensrisico) of een daarvoor openstaand fonds, zoals een APF", "Bij een PPI moet het risico op overlijden worden ondergebracht bij een verzekeraar."], ["Alleen een PPI, omdat verzekeraars geen premieregelingen uitvoeren en pensioenfondsen alleen verplichtgestelde regelingen mogen uitvoeren", "Verzekeraars voeren wel premieregelingen uit."], ["Alleen een bank met een lijfrentevergunning, die het overlijdensrisico bij een herverzekeraar onderbrengt", "Een bank is geen pensioenuitvoerder in de zin van de Pensioenwet."], ["Zijn eigen onderneming in eigen beheer", "Voor werknemers geldt de onderbrengingsplicht; eigen beheer is niet toegestaan."]]],
["Welke informatie moet een adviseur in elk geval verzamelen voor een goed pensioenadvies aan een particulier?", [["Financiële positie, kennis en ervaring, doelen en risicobereidheid, inclusief bestaande AOW- en pensioenaanspraken", "Pas met dat volledige klantbeeld kan het advies passend zijn."], ["Alleen het bruto jaarinkomen en de gewenste pensioenleeftijd, omdat de rest uit mijnpensioenoverzicht.nl blijkt", "Het inkomen is één onderdeel van het klantprofiel, niet het geheel."], ["Alleen de gewenste pensioenleeftijd", "De pensioenleeftijd is een wens, geen volledig klantprofiel."], ["Uitsluitend het UPO van de laatste werkgever en het bruto jaarinkomen, omdat de AOW voor iedereen gelijk is", "Eén UPO geeft geen volledig beeld; ook AOW, andere pensioenen en de persoonlijke situatie tellen mee."]]],
["Wat houdt de zorgplicht van een pensioenuitvoerder bij een premieregeling met beleggingskeuzes in?", [["De uitvoerder moet de deelnemer bij keuzes begeleiden en rekening houden met zijn risicoprofiel", "De deelnemer draagt beleggingsrisico; daarom moet de uitvoerder helpen bij passende keuzes."], ["De uitvoerder garandeert een minimale uitkering op de pensioendatum, ten minste gelijk aan de som van de ingelegde premies", "Een zorgplicht is geen garantie op een bepaalde uitkering."], ["De uitvoerder hoeft niets te doen, de deelnemer is zelf verantwoordelijk", "De wet legt juist een zorgplicht bij de uitvoerder."], ["De uitvoerder moet het pensioenvermogen van de deelnemer bij een bank stallen, zodat er geen beleggingsrisico meer is", "Dat is geen invulling van de zorgplicht."]]],
["Thomas staat op het punt met pensioen te gaan en heeft een premieregeling. Hij vraagt of hij zijn pensioenuitkering ook bij een andere uitvoerder mag aankopen. Wat is juist?", [["Ja, hij heeft in beginsel shoprecht en kan met het kapitaal elders een uitkering aankopen", "Bij een premieovereenkomst mag de deelnemer op de pensioendatum vergelijken en elders aankopen."], ["Nee, de uitkering moet altijd bij de eigen uitvoerder worden aangekocht, tegen het tarief uit het reglement", "De Pensioenwet kent juist een shoprecht."], ["Ja, maar alleen bij een bank als bancaire lijfrente vrij opneembaar", "Het kapitaal blijft bestemd voor een pensioenuitkering; vrije opname is niet toegestaan."], ["Nee, shoppen kan alleen bij een uitkeringsovereenkomst", "Het shoprecht hoort juist bij premieregelingen met een kapitaal op de pensioendatum."]]],
["Een werkgever vraagt een adviseur een nieuwe collectieve pensioenregeling te selecteren. Wat hoort bij zorgvuldig advies?", [["Wensen en situatie van werkgever en werknemers inventariseren, uitvoerders en kosten vergelijken en de keuze vastleggen", "Zo kan de werkgever een onderbouwde keuze maken die past bij zijn doelen en budget."], ["Direct de uitvoerder met de laagste premie kiezen, omdat dekking en service bij alle uitvoerders wettelijk gelijk zijn geregeld", "Premie alleen is onvoldoende; ook dekking, kosten en kwaliteit van de uitvoering tellen mee."], ["Alleen de werknemers laten stemmen over de uitvoerder en de uitslag van de stemming vastleggen in de cao", "De werkgever kiest; draagvlak bij werknemers en een eventueel instemmingsrecht van de OR zijn wel relevant."], ["De keuze overlaten aan de toezichthouder", "De toezichthouder adviseert werkgevers niet over de keuze van een uitvoerder."]]],
["Een klant vraagt bij pensionering advies over hoog-laag, uitruil en een bedrag ineens. Wat is de juiste aanpak van de adviseur?", [["De keuzes in samenhang bekijken met de financiële situatie, partner, toeslagen en fiscaliteit, en de gevolgen uitleggen", "Deze keuzes beïnvloeden elkaar en zijn vaak onomkeerbaar."], ["Altijd adviseren het maximale bedrag ineens op te nemen, omdat de klant dan zelf over zijn pensioenvermogen kan beschikken", "Een bedrag ineens is niet in elke situatie verstandig."], ["Alleen de keuze met het hoogste bruto bedrag adviseren, omdat die per saldo ook netto altijd het meest oplevert", "Ook netto-effecten, de partner en toeslagen tellen mee."], ["De keuzes overlaten aan de pensioenuitvoerder", "De klant beslist; de adviseur ondersteunt die keuze met advies."]]],
["Wat is Pensioen 1-2-3?", [["Gelaagde pensioeninformatie: laag 1 de kern, laag 2 verdieping en laag 3 alle details en documenten", "Zo kan de deelnemer zelf bepalen hoe diep hij in de informatie duikt."], ["Een stappenplan voor het aanvragen van AOW", "De AOW-aanvraag loopt via de SVB en heeft niets met Pensioen 1-2-3 te maken."], ["Drie verplichte keuzes die een deelnemer jaarlijks moet maken: pensioenleeftijd, beleggingsprofiel en partnerdekking", "Pensioen 1-2-3 is een informatieopzet, geen keuzemoment."], ["Een classificatie van pensioenfondsen naar risico", "Het is geen risicoclassificatie van uitvoerders."]]],
["Wat kan een gebruiker vinden op mijnpensioenoverzicht.nl?", [["Een overzicht van de AOW en het via werkgevers opgebouwde pensioen bij de verschillende uitvoerders", "Door in te loggen met DigiD ziet de gebruiker zijn eerste- en tweedepijleraanspraken samen."], ["Een volledig overzicht van alle bankrekeningen en spaargelden", "Gewone banktegoeden staan niet op mijnpensioenoverzicht.nl."], ["Een gegarandeerde berekening van het netto besteedbaar inkomen na pensionering, inclusief toeslagen en belasting", "Het overzicht geeft bruto aanspraken en indicaties, geen garantie op netto inkomen."], ["Een vergelijking van pensioenuitvoerders met rangschikking", "De site vergelijkt geen uitvoerders."]]],
["Een klant print zijn overzicht van mijnpensioenoverzicht.nl voor een pensioenadvies. Wat moet de adviseur daarnaast in het algemeen nog uitvragen?", [["Eigen derdepijlervoorzieningen, zoals lijfrentes en banksparen, en de situatie van de partner", "Die gegevens staan in de regel niet op het overzicht, maar zijn nodig voor een volledig advies."], ["Niets, het overzicht bevat alle relevante pensioeninformatie", "Derdepijlerproducten en de partnersituatie ontbreken doorgaans."], ["Alleen de AOW-gegevens, omdat die niet op het overzicht staan", "De AOW staat juist wel op het overzicht."], ["Alleen de pensioenen uit het buitenland, omdat de derde pijler en partnergegevens er al wel op staan", "Lijfrentes en partnergegevens staan juist niet op het overzicht; ook buitenlandse pensioenen ontbreken er in de regel."]]],
["Wat is een belangrijk doel van de Wet pensioencommunicatie?", [["Deelnemers beter laten begrijpen wat hun pensioen inhoudt, met informatie die aansluit bij hun behoefte", "Met gelaagde informatie en digitale mogelijkheden moet pensioen begrijpelijker worden."], ["Het verplicht maken van pensioenadvies voor iedere werknemer voordat hij een keuze in zijn pensioenregeling maakt", "De wet verplicht niet tot het inwinnen van advies."], ["Het afschaffen van het Uniform Pensioenoverzicht", "Het UPO bestaat nog steeds."], ["Het overdragen van alle pensioencommunicatie aan de AFM", "De uitvoerder blijft verantwoordelijk voor de communicatie; de AFM houdt toezicht."]]],
["Wat moet een verzekeringsdistributeur onder de IDD vóór het sluiten van een verzekering in ieder geval vaststellen?", [["De wensen en behoeften van de klant, zodat het aangeboden product daarbij past", "Deze verplichting geldt ook als er geen advies wordt gegeven."], ["Het BKR-registratienummer van de klant", "Een BKR-toets hoort bij krediet en niet bij de IDD-verplichting."], ["Het pensioenvermogen van de klant bij de werkgever, zoals vermeld op het meest recente UPO", "Dat kan relevant zijn, maar is niet de algemene IDD-verplichting."], ["Of de klant al eerder een verzekering heeft opgezegd", "De IDD vraagt de wensen en behoeften, niet de opzeggingsgeschiedenis."]]],
["Wat houdt het productontwikkelingsproces (POG) onder de IDD in?", [["Verzekeraars stellen per product een doelgroep vast en toetsen het; distributeurs houden daar rekening mee", "Zo moet worden voorkomen dat producten worden verkocht aan klanten voor wie ze niet bedoeld zijn."], ["Distributeurs moeten zelf nieuwe verzekeringsproducten ontwikkelen", "Distributeurs ontwikkelen meestal niet zelf; zij moeten wel rekening houden met de doelgroep."], ["Elke nieuwe verzekering moet vooraf door de AFM worden goedgekeurd, inclusief de premie en de polisvoorwaarden", "Er is geen voorafgaande productgoedkeuring door de AFM."], ["Verzekeraars mogen alleen nog producten via een adviseur verkopen", "De IDD verbiedt directe verkoop niet."]]],
["Wat vereist de IDD van een verzekeringsdistributeur met betrekking tot zijn beloning?", [["Dat hij de klant informeert over de aard van zijn beloning in verband met de verzekering", "De klant moet weten of de distributeur bijvoorbeeld een vergoeding van de klant of een andere beloning ontvangt."], ["Dat hij nooit een beloning van een verzekeraar ontvangt bij geen enkel product", "De IDD bevat geen algemeen beloningsverbod; nationale provisieverboden staan los daarvan."], ["Dat hij zijn beloning vooraf laat goedkeuren door DNB en jaarlijks in het AFM-register publiceert", "DNB keurt beloningen van distributeurs niet goed."], ["Dat hij zijn beloning pas na tien jaar mag ontvangen", "De IDD kent geen dergelijke termijn."]]],
["Wat moet een instelling onder de Wwft doen met een ongebruikelijke transactie?", [["Onverwijld melden bij de FIU-Nederland", "De melding moet onverwijld worden gedaan zodra het ongebruikelijke karakter bekend is."], ["Melden bij de AFM binnen dertig dagen", "Ongebruikelijke transacties worden gemeld bij de FIU-Nederland, niet bij de AFM."], ["De klant direct vertellen dat er een melding wordt gedaan", "Het is juist verboden de klant over de melding te informeren."], ["Alleen melden als het bedrag boven een vaste grens ligt", "Ook subjectieve indicatoren kunnen tot een meldplicht leiden, ongeacht het bedrag."]]],
["Hoe lang moet een Wwft-instelling de gegevens van het cliëntenonderzoek ten minste bewaren?", [["Vijf jaar na het einde van de zakelijke relatie of de transactie", "Zo kunnen opsporingsdiensten later nog gegevens opvragen."], ["Eén jaar na het einde van de zakelijke relatie", "De termijn is langer, namelijk vijf jaar."], ["Tot de klant de AOW-leeftijd bereikt", "De bewaartermijn hangt niet af van de leeftijd van de klant."], ["Twintig jaar na de eerste transactie, ongeacht wanneer de relatie eindigt", "De Wwft noemt vijf jaar na het einde van de relatie of transactie."]]],
["Een klant die een politiek prominente functie bekleedt, wil een omvangrijke lijfrente-inleg doen. Wat vraagt de Wwft van de instelling?", [["Verscherpt cliëntenonderzoek, onder meer naar de herkomst van het vermogen", "Bij een politiek prominent persoon geldt een hoger risico op bijvoorbeeld corruptie."], ["Niets bijzonders, het gewone cliëntenonderzoek volstaat altijd", "Bij een PEP is verscherpt cliëntenonderzoek verplicht."], ["De zakelijke relatie direct weigeren", "Een PEP mag klant zijn, maar onder verscherpte maatregelen."], ["Een melding bij de FIU-Nederland, ongeacht de omvang of aard van de transactie", "Een PEP-status is op zich geen reden voor een melding."]]]
],
"zorgverzekering":[
["Sinds wanneer is de Zorgverzekeringswet (Zvw) van kracht?", [["1 januari 2006", "Op 1 januari 2006 verving de Zvw de tweedeling tussen ziekenfonds en particuliere ziektekostenverzekering."], ["1 januari 2008", "In 2008 werd het verplicht eigen risico ingevoerd; de Zvw zelf bestond toen al twee jaar."], ["1 januari 2015, gelijk met de Wlz", "Op 1 januari 2015 traden de Wlz en de Wmo 2015 in werking, niet de Zvw."], ["1 januari 2007", "Op 1 januari 2007 trad de Wft in werking; de Zvw gold toen al een jaar."]]],
["Welk stelsel verving de Zorgverzekeringswet in 2006?", [["De tweedeling tussen ziekenfonds en particuliere ziektekostenverzekering", "Vóór 2006 was een deel van de bevolking ziekenfondsverzekerd en verzekerde de rest zich particulier; de Zvw maakte daar één basisverzekering voor iedereen van."], ["De Algemene Wet Bijzondere Ziektekosten voor langdurige zorg", "De AWBZ werd in 2015 opgevolgd door onder meer de Wlz, niet door de Zvw."], ["Het stelsel van gemeentelijke zorgvoorzieningen uit de Wvg", "De Wet voorzieningen gehandicapten ging op in de Wmo, niet in de Zvw."], ["Een publieke volksverzekering voor curatieve zorg die werd uitgevoerd door de SVB", "Ziektekosten werden niet via een SVB-volksverzekering geregeld; het ging om ziekenfondsen en particuliere verzekeraars."]]],
["Welke typering past het best bij het stelsel van de Zorgverzekeringswet?", [["Private verzekeraars voeren een verplichte verzekering uit binnen publieke randvoorwaarden", "De zorgverzekering is een privaatrechtelijke overeenkomst, maar de wet bepaalt onder meer verzekeringsplicht, acceptatieplicht, pakket en premieregels."], ["De overheid voert de verzekering uit en zorgverzekeraars doen alleen de administratie", "Zorgverzekeraars dragen zelf het verzekeringsrisico en sluiten zelf contracten met zorgaanbieders."], ["Gemeenten bepalen per inwoner welke zorgverzekering passend is", "Gemeenten voeren de Wmo en Jeugdwet uit; iedere verzekerde kiest zelf zijn zorgverzekeraar."], ["Een vrijwillige verzekering waarvan de inhoud per verzekeraar vrij is", "De verzekering is verplicht en de inhoud van het basispakket is wettelijk vastgelegd."]]],
["Wie is in Nederland verplicht een zorgverzekering af te sluiten?", [["Iedereen die op grond van de Wet langdurige zorg verzekerd is", "De verzekeringsplicht is gekoppeld aan de Wlz-verzekering: ingezetenen en niet-ingezetenen die hier in loondienst werken en loonbelasting betalen."], ["Alleen personen met de Nederlandse nationaliteit", "Nationaliteit is niet bepalend; ook een buitenlander die hier woont is verzekeringsplichtig."], ["Alleen ingezetenen met een inkomen boven de vroegere ziekenfondsgrens", "Een inkomensgrens gold vroeger voor het ziekenfonds; onder de Zvw speelt inkomen geen rol bij de verzekeringsplicht."], ["Alleen ingezetenen van 18 jaar en ouder", "Ook kinderen zijn verzekeringsplichtig; zij moeten worden aangemeld, maar betalen geen premie."]]],
["Pieter komt vanuit het buitenland in Nederland wonen en wordt daardoor verzekeringsplichtig. Wat geldt als hij zich binnen vier maanden aanmeldt bij een zorgverzekeraar?", [["De verzekering gaat met terugwerkende kracht in vanaf het begin van de verzekeringsplicht", "Wie zich binnen vier maanden aanmeldt, is verzekerd vanaf de dag waarop de verzekeringsplicht ontstond; daarover is dan ook premie verschuldigd."], ["De verzekering gaat pas in op de eerste dag van het volgende kalenderjaar", "De Zvw kent geen wachttijd tot het nieuwe jaar; de verzekering kan het hele jaar door ingaan."], ["De verzekering gaat in op de dag van aanmelding; over de periode daarvoor bestaat geen dekking", "Binnen de termijn van vier maanden werkt de verzekering juist terug tot het begin van de verzekeringsplicht."], ["De verzekeraar mag hem eerst medisch keuren voordat de dekking ingaat", "Voor de basisverzekering geldt een acceptatieplicht; een medische keuring is niet toegestaan."]]],
["Een verzekeringsplichtige meldt zich pas zes maanden na het ontstaan van zijn verzekeringsplicht aan voor een zorgverzekering. Wat is het gevolg?", [["De verzekering werkt niet terug en gaat pas vanaf de aanmelding in", "Na de termijn van vier maanden vervalt de terugwerkende kracht; zorgkosten uit de onverzekerde periode zijn voor eigen rekening."], ["De verzekeraar mag de aanvraag weigeren omdat de termijn is verstreken", "De acceptatieplicht blijft gelden; ook een late aanvrager moet worden geaccepteerd."], ["De verzekering gaat toch in vanaf het ontstaan van de verzekeringsplicht", "Terugwerkende kracht geldt alleen bij aanmelding binnen vier maanden."], ["Hij moet eerst een jaar wachten voordat de basisverzekering kan ingaan", "Er is geen wachttermijn; de verzekering gaat direct vanaf de aanmelding in."]]],
["Lisa en Daan krijgen op 5 maart een zoon. Wat moeten zij doen om ervoor te zorgen dat hun kind vanaf de geboorte verzekerd is?", [["Het kind binnen vier maanden na de geboorte aanmelden bij een zorgverzekeraar", "Bij aanmelding binnen vier maanden gaat de verzekering met terugwerkende kracht in op de geboortedatum."], ["Niets, een kind is automatisch verzekerd via de polis van de moeder", "Een kind moet zelf worden aangemeld; het is premievrij, maar niet automatisch verzekerd."], ["Het kind vóór 1 januari van het volgende jaar aanmelden", "Die termijn is te ruim; na vier maanden vervalt de terugwerkende kracht."], ["Een aanvullende verzekering voor het kind afsluiten bij de verzekeraar van een ouder", "De basisverzekering moet worden geregeld; een aanvullende verzekering is vrijwillig en vervangt de basisverzekering niet."]]],
["Welke groep is uitgezonderd van de verzekeringsplicht van de Zorgverzekeringswet?", [["Militairen in werkelijke dienst", "Militairen in werkelijke dienst krijgen hun zorg via Defensie en zijn daarom niet verzekeringsplichtig."], ["Zelfstandigen zonder personeel", "Een zzp'er die hier woont is gewoon verzekeringsplichtig."], ["Studenten die in Nederland wonen", "Ook studenten die hier wonen zijn Wlz-verzekerd en dus verzekeringsplichtig."], ["Ambtenaren in dienst van het Rijk", "Ambtenaren vallen sinds 2006 gewoon onder de Zvw."]]],
["Hoe kan iemand met gemoedsbezwaren tegen verzekeren buiten de verzekeringsplicht van de Zvw vallen?", [["Door een ontheffing op grond van gemoedsbezwaren, af te geven door de SVB", "Gemoedsbezwaarden kunnen bij de Sociale Verzekeringsbank een verklaring van gemoedsbezwaren aanvragen; zij zijn dan niet verzekeringsplichtig."], ["Door een verklaring van de huisarts dat hij weinig zorg gebruikt", "Zorggebruik speelt geen rol bij de verzekeringsplicht."], ["Door een schriftelijke opzegging bij zijn zorgverzekeraar", "Opzeggen zonder nieuwe verzekering is niet mogelijk zolang de verzekeringsplicht bestaat."], ["Door ontheffing aan te vragen bij de Nederlandse Zorgautoriteit", "De NZa is toezichthouder en verleent geen ontheffingen van de verzekeringsplicht."]]],
["Wat houdt de acceptatieplicht voor de basisverzekering in?", [["De verzekeraar moet iedere verzekeringsplichtige binnen zijn werkgebied accepteren", "Een zorgverzekeraar mag een aanvraag voor de basisverzekering niet weigeren, ongeacht leeftijd of gezondheid."], ["De verzekeraar mag alleen weigeren bij een ernstige chronische aandoening", "Ook chronisch zieken moeten worden geaccepteerd; daarvoor is de acceptatieplicht juist bedoeld."], ["De verzekerde moet elk aanbod van zijn huidige verzekeraar accepteren", "De acceptatieplicht rust op de verzekeraar, niet op de verzekerde; die mag jaarlijks overstappen."], ["De verzekeraar moet ook de aanvullende verzekering altijd accepteren", "Voor aanvullende verzekeringen geldt geen acceptatieplicht."]]],
["Mevrouw Bakker (62) heeft diabetes en reuma. Zij wil per 1 januari naar een andere zorgverzekeraar voor haar basisverzekering. Wat mag de nieuwe verzekeraar doen?", [["Haar accepteren tegen dezelfde premie als iedere andere verzekerde met die polis", "Acceptatieplicht en het verbod op premiedifferentiatie betekenen dat zij gewoon wordt geaccepteerd tegen de reguliere premie."], ["Haar accepteren met een opslag op de premie vanwege haar aandoeningen", "Een opslag naar gezondheid is in de basisverzekering verboden."], ["Haar weigeren omdat zij een verhoogd risico op zorgkosten heeft", "Weigeren op gezondheid is in strijd met de acceptatieplicht."], ["Haar accepteren nadat zij een gezondheidsverklaring heeft ingevuld", "Voor de basisverzekering mogen geen medische vragen worden gesteld."]]],
["Wat betekent het verbod op premiedifferentiatie in de basisverzekering?", [["Iedereen met dezelfde polis betaalt dezelfde premie, ongeacht leeftijd of gezondheid", "De premie mag niet verschillen naar persoonskenmerken zoals leeftijd, geslacht of gezondheid."], ["Alle zorgverzekeraars moeten exact dezelfde premie vragen", "Verzekeraars stellen hun premie zelf vast; die verschilt per verzekeraar en per polis."], ["De premie mag alleen verschillen naar leeftijdsklasse", "Leeftijdsafhankelijke premies zijn in de basisverzekering juist niet toegestaan."], ["De premie mag niet hoger zijn dan de inkomensafhankelijke bijdrage die de werkgever vergoedt", "Er bestaat geen wettelijke koppeling tussen de nominale premie en de inkomensafhankelijke bijdrage."]]],
["Welke premiekorting op de basisverzekering is toegestaan?", [["Korting in ruil voor een vrijwillig eigen risico", "De Zvw staat een premiekorting toe als de verzekerde kiest voor een vrijwillig eigen risico."], ["Korting voor niet-rokers en sporters met een fitnessabonnement", "Korting op basis van leefstijl of gezondheid is in strijd met het verbod op premiedifferentiatie."], ["Korting voor jongeren tot 27 jaar", "Leeftijdskorting is in de basisverzekering niet toegestaan; in een aanvullende verzekering mag dat wel."], ["Korting voor verzekerden die een jaar lang geen zorg gebruiken", "Een no-claimkorting op de basisverzekering bestaat niet meer; die is in 2008 vervangen door het verplicht eigen risico."]]],
["Een zorgverzekeraar biedt een naturapolis en een restitutiepolis aan. Mag de premie van die twee polissen verschillen?", [["Ja, de premie mag per polis verschillen, maar binnen één polis betaalt iedereen hetzelfde", "Het verbod op premiedifferentiatie geldt per product; verschillende polisvormen mogen een eigen premie hebben."], ["Nee, een verzekeraar mag maar één premie voor de basisverzekering hanteren", "Een verzekeraar mag meerdere basispolissen aanbieden met elk een eigen premie."], ["Ja, maar alleen als de restitutiepolis minder zorg dekt", "Het pakket is bij alle polisvormen gelijk; het verschil zit in vrije artsenkeuze en vergoeding."], ["Nee, de NZa stelt de premie voor elke polisvorm vast", "De NZa stelt geen premies vast; verzekeraars bepalen hun premie zelf."]]],
["Wat is het doel van de risicoverevening tussen zorgverzekeraars?", [["Verzekeraars compenseren voor verschillen in het risicoprofiel van hun verzekerden", "Omdat verzekeraars iedereen moeten accepteren tegen dezelfde premie, worden zij gecompenseerd voor verzekerden met hogere verwachte kosten."], ["Ervoor zorgen dat alle verzekeraars dezelfde winst maken", "Risicoverevening corrigeert voor risicoverschillen, niet voor verschillen in efficiëntie of winst."], ["De premie per verzekerde laten afhangen van zijn gezondheid en zijn zorggebruik in het vorige jaar", "Dat zou juist premiedifferentiatie zijn, wat verboden is."], ["Wanbetalers verdelen over alle zorgverzekeraars", "Voor wanbetalers bestaat een aparte wanbetalersregeling; dat is iets anders dan risicoverevening."]]],
["Wie bepaalt de inhoud van het basispakket van de zorgverzekering?", [["De overheid, op advies van het Zorginstituut Nederland", "De minister legt het pakket vast in regelgeving; het Zorginstituut adviseert over wat erin hoort."], ["Iedere zorgverzekeraar voor zijn eigen verzekerden", "Het basispakket is wettelijk vastgelegd en bij alle verzekeraars gelijk."], ["De Nederlandse Zorgautoriteit", "De NZa gaat over tarieven, prestaties en toezicht, niet over de inhoud van het pakket."], ["Zorgverzekeraars Nederland als brancheorganisatie", "ZN behartigt belangen van verzekeraars, maar stelt het pakket niet vast."]]],
["Waarin kunnen basisverzekeringen van verschillende zorgverzekeraars van elkaar verschillen?", [["In polisvorm, gecontracteerde zorgaanbieders, premie en service", "De inhoud van het pakket is gelijk; verschillen zitten in de keuzevrijheid van zorgaanbieders, de vergoeding van niet-gecontracteerde zorg, premie en dienstverlening."], ["In de soorten zorg die onder het basispakket vallen", "Welke zorg verzekerd is, ligt wettelijk vast en is bij alle verzekeraars hetzelfde."], ["In de hoogte van het verplicht eigen risico", "Het verplicht eigen risico is wettelijk vastgesteld en voor iedereen gelijk."], ["In de leeftijdsgrens voor premievrije verzekering van kinderen", "Kinderen tot 18 jaar zijn bij elke verzekeraar premievrij; dat ligt in de wet vast."]]],
["Welke zorg valt onder het basispakket van de Zorgverzekeringswet?", [["Wijkverpleging", "Verpleging en verzorging thuis door de wijkverpleegkundige valt sinds 2015 onder de Zvw."], ["Huishoudelijke hulp", "Huishoudelijke ondersteuning is een maatwerkvoorziening van de gemeente onder de Wmo."], ["Een periodieke tandartscontrole voor een volwassene", "Reguliere mondzorg voor volwassenen zit niet in het basispakket, maar kan aanvullend worden verzekerd."], ["Repatriëring na een ongeval in het buitenland", "Terugvervoer naar Nederland valt niet onder de basisverzekering; daarvoor is een reis- of aanvullende verzekering nodig."]]],
["Joost (35) verzwikt zijn enkel bij het hardlopen en gaat zes keer naar de fysiotherapeut. Hij heeft geen chronische aandoening. Hoe worden deze kosten vergoed?", [["Niet uit de basisverzekering, wel eventueel uit een aanvullende verzekering", "Fysiotherapie voor volwassenen zit alleen in beperkte gevallen, zoals bij bepaalde chronische aandoeningen, in het basispakket."], ["Volledig uit de basisverzekering, na verwijzing door de huisarts", "Een verwijzing maakt reguliere fysiotherapie voor een volwassene niet tot basiszorg."], ["Uit de basisverzekering, buiten het eigen risico om", "Fysiotherapie voor deze klacht is geen basiszorg en dus ook geen uitzondering op het eigen risico."], ["Via de Wmo, omdat het om herstel van mobiliteit gaat", "De Wmo vergoedt geen fysiotherapie; die valt onder de Zvw of een aanvullende verzekering."]]],
["Aan welke criteria toetst het Zorginstituut of zorg in het basispakket hoort?", [["Effectiviteit, kosteneffectiviteit, noodzakelijkheid en uitvoerbaarheid", "Dit zijn de vier pakketcriteria die het Zorginstituut hanteert bij zijn advies over het basispakket."], ["Populariteit, beschikbaarheid, prijs en wachttijd", "Populariteit en wachttijd zijn geen pakketcriteria."], ["Leeftijd, inkomen, gezondheid en woonplaats van de patiënt", "Dit zijn persoonskenmerken; het pakket is voor iedereen gelijk."], ["Winstgevendheid, marktaandeel, solvabiliteit en kosten van de zorgverzekeraar", "Dit zijn bedrijfseconomische maatstaven van verzekeraars, geen pakketcriteria."]]],
["Wat is de algemene voorwaarde waaraan zorg moet voldoen om uit de basisverzekering te worden vergoed?", [["De zorg moet voldoen aan de stand van de wetenschap en praktijk", "Zorg is alleen verzekerd als die bewezen effectief is; experimentele zorg valt in de regel buiten het pakket."], ["De zorg moet zijn voorgeschreven door een medisch specialist", "Veel basiszorg, zoals huisartsenzorg, vraagt geen voorschrift van een specialist."], ["De zorg moet in Nederland worden verleend", "Ook zorg in het buitenland kan onder voorwaarden worden vergoed."], ["De zorg moet goedkoper zijn dan een vergelijkbare behandeling", "Kosteneffectiviteit speelt bij pakketbeslissingen, maar is geen voorwaarde die per declaratie wordt getoetst."]]],
["Wat betekent het preferentiebeleid van een zorgverzekeraar voor geneesmiddelen?", [["Per werkzame stof wordt alleen het aangewezen middel vergoed, behalve bij medische noodzaak", "Bij medische noodzaak die de voorschrijver aangeeft, moet de verzekeraar toch het andere middel vergoeden."], ["De verzekerde mag elk merkgeneesmiddel kiezen zonder bijbetaling, mits de huisarts het voorschrijft", "Preferentiebeleid beperkt juist de keuze tot het aangewezen middel."], ["De apotheker bepaalt welk geneesmiddel in het pakket komt", "Het pakket wordt door de overheid vastgesteld; de verzekeraar wijst binnen dat pakket het preferente middel aan."], ["Geneesmiddelen vallen alleen onder de aanvullende verzekering, niet onder de basisverzekering", "Geregistreerde geneesmiddelen die zijn aangewezen, vallen onder het basispakket."]]],
["Wat is het verschil tussen een eigen bijdrage en het eigen risico?", [["Een eigen bijdrage hoort bij een specifieke zorgsoort; het eigen risico geldt voor zorgkosten per jaar", "Een eigen bijdrage, zoals bij kraamzorg of sommige hulpmiddelen, betaalt men ook als het eigen risico al vol is."], ["Een eigen bijdrage geldt alleen bij aanvullende verzekeringen, het eigen risico alleen bij de basisverzekering", "Ook binnen de basisverzekering bestaan eigen bijdragen, bijvoorbeeld bij geneesmiddelen boven de vergoedingslimiet."], ["Er is geen verschil; beide begrippen worden in de polisvoorwaarden door elkaar gebruikt", "Het zijn verschillende regelingen met elk een eigen werking."], ["Het eigen risico geldt alleen voor kinderen onder de 18", "Het verplicht eigen risico geldt juist niet voor kinderen onder de 18."]]],
["Voor wie geldt het verplicht eigen risico van de zorgverzekering?", [["Voor verzekerden van 18 jaar en ouder", "Kinderen tot 18 jaar hebben geen eigen risico; vanaf 18 jaar geldt het verplicht eigen risico."], ["Voor alle verzekerden, inclusief kinderen", "Voor kinderen onder de 18 geldt geen eigen risico."], ["Alleen voor verzekerden met een restitutiepolis", "Het verplicht eigen risico geldt bij elke polisvorm."], ["Alleen voor verzekerden met een inkomen boven een wettelijke grens", "Het eigen risico is niet inkomensafhankelijk."]]],
["Welke zorg valt NIET onder het verplicht eigen risico?", [["Huisartsenzorg", "Huisartsenzorg is wettelijk uitgezonderd van het eigen risico, zodat de drempel naar de huisarts laag blijft."], ["Een behandeling door een medisch specialist in het ziekenhuis", "Medisch-specialistische zorg valt onder het eigen risico."], ["Een behandeling in de gespecialiseerde ggz", "Ggz-behandelingen in de basisverzekering vallen onder het eigen risico."], ["Ambulancevervoer naar het ziekenhuis", "Ziekenvervoer valt onder het eigen risico."]]],
["Welke kosten tellen WEL mee voor het verplicht eigen risico?", [["Geneesmiddelen die de huisarts voorschrijft", "Het consult bij de huisarts is uitgezonderd, maar de voorgeschreven geneesmiddelen vallen wel onder het eigen risico."], ["Een consult bij de huisarts", "Huisartsenzorg is uitgezonderd van het eigen risico."], ["Verloskundige zorg en kraamzorg na een thuisbevalling", "Verloskunde en kraamzorg zijn uitgezonderd; voor kraamzorg geldt wel een eigen bijdrage."], ["Wijkverpleging bij iemand thuis", "Wijkverpleging valt buiten het eigen risico."]]],
["Welke zorg is uitgezonderd van het verplicht eigen risico?", [["Ketenzorg, zoals de zorg voor patiënten met diabetes", "Ketenzorg voor onder meer diabetes, COPD en hart- en vaatziekten valt buiten het eigen risico."], ["Een opname in een ziekenhuis", "Ziekenhuiszorg valt onder het eigen risico."], ["Een behandeling door een kaakchirurg", "Kaakchirurgie valt onder het eigen risico."], ["Laboratoriumonderzoek in het ziekenhuis op verzoek van een specialist", "Dit hoort bij medisch-specialistische zorg en valt onder het eigen risico."]]],
["Emma wordt op 14 juni 18 jaar. Hoe werkt het verplicht eigen risico voor haar in dat kalenderjaar?", [["Het eigen risico geldt naar rato vanaf 1 juli", "Het eigen risico gaat in vanaf de eerste dag van de maand na de 18e verjaardag en wordt voor dat jaar evenredig berekend."], ["Het volledige eigen risico geldt voor het hele jaar", "Over de maanden vóór haar 18e verjaardag geldt geen eigen risico."], ["Het eigen risico geldt pas vanaf 1 januari van het volgende jaar", "Het eigen risico gaat al in het jaar van de 18e verjaardag in, naar rato."], ["Het eigen risico geldt vanaf 14 juni, haar verjaardag zelf", "Het eigen risico en de premie gaan in per de eerste dag van de maand na de verjaardag."]]],
["Wat is een vrijwillig eigen risico?", [["Een extra eigen risico bovenop het verplichte, in ruil voor een lagere premie", "De verzekerde kiest er zelf voor en krijgt daarvoor premiekorting; het geldt voor dezelfde zorg als het verplicht eigen risico."], ["Een eigen risico dat alleen geldt voor de aanvullende verzekering", "Het vrijwillig eigen risico hoort bij de basisverzekering."], ["Een eigen risico dat in de plaats komt van het verplicht eigen risico, tegen een lagere premie", "Het vrijwillig eigen risico komt erbovenop en vervangt het verplichte deel niet."], ["Een eigen risico dat ook voor huisartsenzorg geldt", "Het vrijwillig eigen risico kent dezelfde uitzonderingen als het verplichte, dus huisartsenzorg blijft erbuiten."]]],
["Hoe hoog kan het vrijwillig eigen risico in de basisverzekering zijn?", [["In stappen van € 100 tot maximaal € 500 bovenop het verplicht eigen risico", "De Zvw laat een vrijwillig eigen risico toe van € 100, € 200, € 300, € 400 of € 500."], ["Elk bedrag dat verzekerde en verzekeraar samen afspreken", "De wet bepaalt de mogelijke treden; vrij onderhandelen is niet toegestaan."], ["Maximaal het bedrag van één jaarpremie", "Het maximum is geen jaarpremie, maar een vast bedrag van € 500."], ["In stappen van € 250 tot maximaal € 1.000 bovenop het verplicht eigen risico", "Zulke treden kent de Zvw niet; het maximum ligt op € 500."]]],
["De heer Smit heeft een chronische longziekte en maakt elk jaar hoge ziekenhuiskosten. Hij overweegt een vrijwillig eigen risico om premie te besparen. Wat is het juiste advies?", [["Afraden, omdat hij het extra eigen risico vrijwel zeker volledig zal betalen", "Bij voorspelbaar hoge zorgkosten is de extra eigen betaling meestal groter dan de premiekorting."], ["Aanraden, omdat chronisch zieken een hogere premiekorting krijgen", "De korting is voor iedereen met hetzelfde vrijwillig eigen risico gelijk; gezondheid speelt geen rol."], ["Aanraden, omdat chronische zorg buiten het eigen risico valt", "Ziekenhuiszorg valt gewoon onder het eigen risico; alleen bijvoorbeeld ketenzorg is uitgezonderd."], ["Afraden, omdat chronisch zieken wettelijk geen vrijwillig eigen risico mogen kiezen", "Iedere verzekerde van 18 jaar of ouder mag kiezen; het is alleen ongunstig bij hoge kosten."]]],
["Een behandeltraject in het ziekenhuis start op 10 december en loopt door tot in maart van het volgende jaar. Ten laste van het eigen risico van welk jaar komen de kosten?", [["Van het jaar waarin het traject is gestart", "Bij medisch-specialistische zorg telt de startdatum van het zorgtraject voor het eigen risico."], ["Van het jaar waarin het traject eindigt", "De einddatum is bepalend voor de declaratie, maar niet voor het jaar van het eigen risico."], ["Naar rato verdeeld over beide jaren", "De kosten worden niet over de jaren gesplitst."], ["Van het jaar waarin de verzekeraar de nota betaalt", "Het betaalmoment is niet bepalend voor het eigen risico."]]],
["Wat kenmerkt een naturapolis?", [["De verzekerde heeft recht op zorg van door de verzekeraar gecontracteerde aanbieders", "Bij natura levert de verzekeraar de zorg via gecontracteerde aanbieders; niet-gecontracteerde zorg wordt vaak lager vergoed."], ["De verzekerde kiest vrij een zorgaanbieder en krijgt de kosten altijd volledig vergoed", "Dat past bij een restitutiepolis, en ook dan geldt een maximum op marktconform niveau."], ["De verzekerde betaalt alle zorg zelf en declareert achteraf", "Bij natura declareert de gecontracteerde aanbieder doorgaans rechtstreeks bij de verzekeraar."], ["De polis dekt minder zorgsoorten dan een restitutiepolis", "Het pakket is bij elke polisvorm gelijk; het verschil zit in de keuzevrijheid."]]],
["Wat kenmerkt een restitutiepolis?", [["De verzekerde heeft recht op vergoeding van zorgkosten bij een zorgaanbieder naar keuze", "Bij restitutie kiest de verzekerde vrij en vergoedt de verzekeraar tot een marktconform of wettelijk tarief."], ["De verzekerde mag alleen naar zorgaanbieders waarmee de verzekeraar een contract heeft gesloten", "Dat is een kenmerk van natura- en budgetpolissen."], ["De verzekerde betaalt geen eigen risico", "Ook bij restitutie geldt het verplicht eigen risico."], ["De verzekerde krijgt naast de basiszorg ook tandartszorg en fysiotherapie vergoed", "De polisvorm verandert niets aan de inhoud van het pakket."]]],
["Hoeveel moet een zorgverzekeraar bij een naturapolis minimaal vergoeden voor zorg bij een niet-gecontracteerde zorgaanbieder?", [["Zoveel dat de vergoeding geen feitelijke hinderpaal vormt voor die keuze", "Volgens de Zvw (art. 13) en de rechtspraak mag de verzekeraar korten, maar niet zo sterk dat de vrije keuze feitelijk onmogelijk wordt."], ["Altijd het volledige bedrag van de nota", "Volledige vergoeding van niet-gecontracteerde zorg is bij natura niet verplicht."], ["Niets, omdat de verzekerde bij een naturapolis alleen recht heeft op gecontracteerde zorg", "Een vergoeding van nul zou een hinderpaal vormen en is daarom niet toegestaan."], ["Hetzelfde bedrag als bij een restitutiepolis", "Een restitutiepolis vergoedt doorgaans meer; bij natura mag de vergoeding lager zijn."]]],
["Wat is een combinatiepolis?", [["Een polis met natura voor sommige zorgsoorten en restitutie voor andere", "Een combinatiepolis mengt beide vormen, bijvoorbeeld vrije keuze bij ziekenhuiszorg en natura bij andere zorg."], ["Een basisverzekering en een aanvullende verzekering in één pakket bij één verzekeraar", "Dat is een combinatie van verzekeringen, geen polisvorm van de basisverzekering."], ["Een polis die partners samen afsluiten", "Of partners op één polis staan, zegt niets over de polisvorm."], ["Een polis die zowel de Zvw als de Wlz dekt", "De Wlz is een volksverzekering en wordt niet via een zorgpolis gedekt."]]],
["Wat kenmerkt een budgetpolis?", [["Een naturapolis met weinig gecontracteerde zorgaanbieders en een lagere premie", "Wie naar een niet-gecontracteerde aanbieder gaat, krijgt bij een budgetpolis vaak een lagere vergoeding."], ["Een polis met een kleiner basispakket, waardoor de premie lager is", "Ook een budgetpolis dekt het volledige wettelijke basispakket."], ["Een polis zonder verplicht eigen risico", "Het verplicht eigen risico geldt bij elke polis."], ["Een polis die alleen beschikbaar is voor minima via de gemeente, met een lagere premie", "Een budgetpolis staat open voor iedereen; voor minima bestaan daarnaast gemeentelijke collectiviteiten."]]],
["Mevrouw Visser wil zich laten behandelen door een specialist in een kliniek waarmee haar verzekeraar geen contract heeft. Zij wil zo min mogelijk zelf bijbetalen. Welke polisvorm past daar het best bij?", [["Een restitutiepolis", "Een restitutiepolis vergoedt zorg bij een aanbieder naar keuze tot een marktconform tarief, ook zonder contract."], ["Een budgetpolis", "Een budgetpolis heeft een beperkt aantal contracten en vergoedt niet-gecontracteerde zorg vaak lager."], ["Een naturapolis", "Bij natura krijgt zij voor niet-gecontracteerde zorg in de regel een lagere vergoeding."], ["Een polis met een vrijwillig eigen risico", "Een vrijwillig eigen risico verlaagt de premie, maar verhoogt juist de eigen betaling."]]],
["Meneer Jansen heeft een restitutiepolis. De niet-gecontracteerde kliniek waar hij zich laat behandelen, rekent een tarief dat ruim boven het in Nederland gangbare tarief ligt. Wat geldt?", [["De verzekeraar vergoedt tot het marktconforme tarief; het meerdere betaalt hij zelf", "Ook bij restitutie vergoedt de verzekeraar niet meer dan een redelijk, in Nederland gangbaar of wettelijk vastgesteld tarief."], ["De verzekeraar moet het volledige gedeclareerde bedrag vergoeden", "Restitutie betekent vrije keuze, niet onbeperkte vergoeding van elk tarief."], ["De verzekeraar vergoedt niets, omdat bij niet-gecontracteerde zorg geen recht op vergoeding bestaat", "Bij restitutie is een contract met de kliniek niet nodig voor vergoeding."], ["De meerkosten gaan ten laste van zijn verplicht eigen risico", "Het eigen risico geldt voor verzekerde kosten; kosten boven het vergoedbare tarief zijn helemaal niet verzekerd."]]],
["Wanneer kan een verzekerde in de regel overstappen naar een andere basisverzekering?", [["Eén keer per jaar, per 1 januari", "De basisverzekering kan jaarlijks per 1 januari worden opgezegd; tussentijds kan dat alleen in bijzondere situaties."], ["Op elk moment, met een opzegtermijn van één maand", "Vrij tussentijds opzeggen is bij de basisverzekering niet mogelijk."], ["Alleen als de premie met meer dan tien procent stijgt", "Een premiestijging geeft geen apart opzegmoment midden in het jaar; overstappen kan gewoon per 1 januari."], ["Eén keer per drie jaar, na afloop van de contractduur", "De Zvw kent geen meerjarige contracten voor de basisverzekering."]]],
["Karin wil per 1 januari overstappen naar een andere zorgverzekeraar. Welke termijnen gelden?", [["Opzeggen uiterlijk 31 december; de nieuwe polis kan tot en met 31 januari worden gesloten, met ingang van 1 januari", "Zo houdt de verzekerde in januari nog even de tijd om een nieuwe polis te kiezen, zonder onverzekerd te zijn."], ["Opzeggen uiterlijk 1 november; de nieuwe verzekering moet vóór 1 december zijn gesloten en gaat dan per 1 januari in", "Zulke vroege termijnen gelden niet; opzeggen kan tot het einde van het jaar."], ["Opzeggen uiterlijk 31 januari; de nieuwe verzekering gaat dan per 1 maart in", "Te laat: opzeggen moet vóór 1 januari en de nieuwe verzekering werkt terug tot 1 januari."], ["Opzeggen uiterlijk 30 november; de nieuwe verzekering gaat in op de dag van sluiten, zonder terugwerkende kracht", "De wet geeft tot en met 31 december om op te zeggen, met terugwerkende kracht voor de nieuwe polis."]]],
["Wat houdt de opzegservice bij het overstappen van zorgverzekeraar in?", [["De nieuwe zorgverzekeraar zegt de oude verzekering namens de verzekerde op", "Met de opzegservice hoeft de verzekerde niet zelf op te zeggen; dat voorkomt dat hij dubbel of niet verzekerd is."], ["De oude verzekeraar zoekt een nieuwe verzekeraar voor de verzekerde", "De oude verzekeraar bemiddelt niet naar een concurrent."], ["Het CAK regelt de overstap voor alle verzekerden", "Het CAK speelt geen rol bij gewone overstappen."], ["De adviseur is verplicht de opzegging aangetekend te versturen", "Er is geen aangetekende opzegging nodig; de nieuwe verzekeraar regelt het."]]],
["Een verzekerde heeft een premieachterstand bij zijn huidige zorgverzekeraar en wil per 1 januari overstappen. Wat mag de huidige verzekeraar doen?", [["De opzegging weigeren zolang de achterstand niet is betaald", "Een verzekeraar mag de opzegging weigeren bij een premieachterstand; zo kan een wanbetaler niet steeds overstappen en schulden achterlaten."], ["De basisverzekering per direct beëindigen", "De verzekeraar mag de verzekerde niet onverzekerd laten; daarvoor bestaat de wanbetalersregeling."], ["De nieuwe verzekeraar verplichten de schuld over te nemen", "De nieuwe verzekeraar neemt geen premieschuld over."], ["De achterstand verrekenen met zijn zorgtoeslag", "Een zorgverzekeraar kan de zorgtoeslag niet zelf verrekenen."]]],
["In welke situatie eindigt de basisverzekering midden in het jaar?", [["Als de verzekerde emigreert en daardoor niet meer verzekeringsplichtig is", "Bij het einde van de verzekeringsplicht kan de basisverzekering tussentijds eindigen."], ["Als de verzekerde binnen Nederland verhuist", "Een verhuizing binnen Nederland laat de verzekeringsplicht bestaan."], ["Als het verplicht eigen risico volledig is verbruikt", "Het verbruiken van het eigen risico heeft geen gevolg voor de looptijd."], ["Als de verzekerde ontevreden is over de klantenservice en dat schriftelijk meldt", "Ontevredenheid is geen grond om tussentijds op te zeggen; overstappen kan per 1 januari."]]],
["Welke regel geldt voor aanvullende zorgverzekeringen?", [["Er geldt geen acceptatieplicht; de verzekeraar mag een aanvraag weigeren", "De acceptatieplicht van de Zvw geldt alleen voor de basisverzekering."], ["Er geldt dezelfde acceptatieplicht als voor de basisverzekering", "Aanvullende verzekeringen vallen niet onder de acceptatieplicht."], ["De premie moet voor iedereen gelijk zijn", "Het verbod op premiedifferentiatie geldt alleen voor de basisverzekering."], ["De dekking wordt jaarlijks vastgesteld door het Zorginstituut", "De inhoud van aanvullende verzekeringen bepaalt de verzekeraar zelf."]]],
["Mag een zorgverzekeraar bij een aanvraag voor een aanvullende verzekering medische vragen stellen?", [["Ja, dat mag; zij mag de aanvraag op grond daarvan weigeren of beperken", "Bij aanvullende verzekeringen mag de verzekeraar het risico beoordelen, bijvoorbeeld met een gezondheidsverklaring."], ["Nee, medische vragen zijn bij alle zorgverzekeringen verboden", "Het verbod op medische selectie geldt alleen voor de basisverzekering."], ["Alleen als de aanvrager ouder is dan 65 jaar", "Er is geen wettelijke leeftijdsgrens voor het stellen van medische vragen."], ["Alleen met toestemming van de NZa", "Voor een gezondheidsverklaring is geen toestemming van de NZa nodig."]]],
["Wat is een wachttijd bij een aanvullende verzekering?", [["Een periode na ingang van de verzekering waarin bepaalde zorg nog niet wordt vergoed", "Wachttijden komen vooral voor bij uitgebreide tandartsdekkingen en orthodontie."], ["De wettelijke termijn waarbinnen de verzekeraar een declaratie moet betalen", "Een betaaltermijn is iets anders dan een wachttijd in de dekking."], ["De maximale wachttijd voor behandeling bij een gecontracteerde aanbieder", "Dat zijn de zogenoemde Treeknormen, die horen bij de zorgplicht in de basisverzekering."], ["De periode waarbinnen de verzekerde moet opzeggen", "Een opzegtermijn heeft niets te maken met een wachttijd voor vergoeding."]]],
["Mag een zorgverzekeraar de premie van een aanvullende verzekering laten afhangen van de leeftijd van de verzekerde?", [["Ja, voor aanvullende verzekeringen mag de premie naar leeftijd verschillen", "Het verbod op premiedifferentiatie geldt alleen voor de basisverzekering."], ["Nee, de premie moet voor alle leeftijden gelijk zijn", "Die regel geldt voor de basisverzekering, niet voor de aanvullende verzekering."], ["Alleen voor verzekerden jonger dan 18 jaar", "Er bestaat geen wettelijke beperking tot kinderen."], ["Alleen als de NZa het premieverschil per leeftijdsgroep vooraf heeft goedgekeurd", "De NZa keurt premies van aanvullende verzekeringen niet goed."]]],
["Kan een verzekerde zijn basisverzekering bij de ene en zijn aanvullende verzekering bij een andere verzekeraar onderbrengen?", [["Ja, maar niet iedere verzekeraar biedt een aanvullende verzekering los aan", "De wet verbiedt het niet, maar verzekeraars mogen eisen dat de basisverzekering ook bij hen loopt."], ["Nee, de wet verplicht beide verzekeringen bij dezelfde verzekeraar", "Er is geen wettelijke verplichting om beide bij één verzekeraar te hebben."], ["Ja, en de verzekeraar van de aanvullende verzekering moet hem dan altijd accepteren", "Voor aanvullende verzekeringen geldt geen acceptatieplicht."], ["Nee, een aanvullende verzekering is alleen mogelijk binnen een collectiviteit", "Aanvullende verzekeringen zijn ook individueel af te sluiten."]]],
["De heer De Vries (58) heeft een uitgebreide aanvullende verzekering en wil overstappen naar een andere verzekeraar voor zijn basisverzekering. Bij zijn huidige verzekeraar kan de aanvullende verzekering alleen samen met de basisverzekering. Wat is een zorgvuldig advies?", [["Pas opzeggen als vaststaat dat een nieuwe verzekeraar hem voor vergelijkbare aanvullende dekking accepteert", "Zonder acceptatieplicht voor aanvullende verzekeringen loopt hij het risico zijn aanvullende dekking kwijt te raken."], ["Direct opzeggen, want de nieuwe verzekeraar moet hem op grond van de acceptatieplicht ook aanvullend accepteren", "Een acceptatieplicht geldt alleen voor de basisverzekering."], ["Opzeggen en de aanvullende dekking via de zorgtoeslag laten vergoeden", "Zorgtoeslag is een tegemoetkoming in de premie, geen vervanging van een aanvullende verzekering."], ["Niet overstappen, want boven de 55 jaar is overstappen van aanvullende verzekering wettelijk beperkt", "Voor de basisverzekering geldt geen leeftijdsgrens bij overstappen."]]],
["Welke mondzorg valt voor een volwassene onder de basisverzekering?", [["Kaakchirurgie en een volledige uitneembare gebitsprothese", "Voor volwassenen dekt de basisverzekering onder meer kaakchirurgie en de volledige prothese, waarbij een eigen bijdrage kan gelden."], ["De halfjaarlijkse controle en het gebitsreinigen bij de tandarts", "Reguliere controles voor volwassenen vallen niet onder de basisverzekering."], ["Het vullen van gaatjes", "Gewone tandheelkundige behandelingen voor volwassenen zijn niet basisverzekerd."], ["Een kroon of brug na tandverlies", "Kronen en bruggen vallen voor volwassenen in de regel niet onder de basisverzekering."]]],
["Hoe is mondzorg voor kinderen tot 18 jaar in de basisverzekering geregeld?", [["Reguliere mondzorg, zoals controles en vullingen, valt in de basisverzekering", "Voor kinderen tot 18 jaar dekt de basisverzekering de gewone tandartszorg."], ["Mondzorg voor kinderen loopt via de Jeugdwet van de gemeente", "De Jeugdwet gaat over jeugdhulp, niet over tandartszorg."], ["Mondzorg voor kinderen valt alleen onder een aanvullende verzekering", "Gewone tandartszorg voor kinderen zit juist in het basispakket."], ["Alleen spoedeisende tandartszorg valt in de basisverzekering", "Ook controles en preventieve zorg zijn voor kinderen basisverzekerd."]]],
["De ouders van Sem (11) willen weten hoe een beugel bij de orthodontist wordt vergoed. Er is geen sprake van een zeer ernstige ontwikkelingsstoornis. Wat is juist?", [["In dit geval valt orthodontie niet onder de basisverzekering; wel aanvullend te verzekeren", "Orthodontie zit alleen bij zeer ernstige afwijkingen in het basispakket; anders is een aanvullende verzekering nodig."], ["Orthodontie valt voor kinderen tot 18 jaar altijd onder de basisverzekering, zonder eigen risico", "De basisverzekering dekt orthodontie alleen in uitzonderlijke situaties."], ["Orthodontie wordt vergoed via de gemeente op grond van de Wmo", "De Wmo vergoedt geen mondzorg."], ["Orthodontie valt onder de basisverzekering, maar met eigen risico", "Kinderen hebben geen eigen risico en orthodontie is hier geen basiszorg."]]],
["Anouk (42) laat haar verstandskiezen operatief verwijderen door een kaakchirurg in het ziekenhuis. Hoe worden de kosten vergoed?", [["Uit de basisverzekering, waarbij het verplicht eigen risico geldt", "Kaakchirurgie is basisverzekerde zorg en valt onder het eigen risico."], ["Uit de basisverzekering, zonder eigen risico", "Kaakchirurgie is niet uitgezonderd van het eigen risico."], ["Alleen uit een aanvullende tandartsverzekering", "Kaakchirurgie zit in het basispakket."], ["Niet, omdat mondzorg voor volwassenen nooit wordt vergoed", "Bepaalde mondzorg voor volwassenen, zoals kaakchirurgie, valt wel onder de basisverzekering."]]],
["Wat geldt voor de inhoud van een basisverzekering die via een collectiviteit wordt afgesloten?", [["Het basispakket is gelijk aan dat van een individuele basisverzekering", "Een collectiviteit kan andere voorwaarden of aanvullende afspraken hebben, maar het wettelijke basispakket blijft hetzelfde."], ["Het collectief mag zorgsoorten uit het basispakket schrappen", "Het basispakket ligt wettelijk vast en kan niet worden beperkt."], ["Het verplicht eigen risico vervalt voor deelnemers aan een collectiviteit", "Het verplicht eigen risico geldt ook binnen een collectiviteit."], ["Leden van het collectief worden medisch gekeurd", "Voor de basisverzekering is medische selectie altijd verboden."]]],
["Wat is een gemeentelijke collectieve zorgverzekering (gemeentepolis)?", [["Een collectiviteit die gemeenten aanbieden aan inwoners met een laag inkomen", "Gemeenten bieden minima zo een zorgverzekering met een passende aanvullende dekking, soms met een bijdrage van de gemeente."], ["Een verplichte verzekering voor alle inwoners van een gemeente", "Deelname is vrijwillig en gericht op inwoners met een laag inkomen."], ["Een verzekering die de Wmo-voorzieningen vervangt", "De Wmo blijft een gemeentelijke voorziening naast de zorgverzekering."], ["Een polis waarbij de gemeente de basisverzekering zelf uitvoert en de premie int", "De verzekering wordt uitgevoerd door een zorgverzekeraar; de gemeente sluit het collectieve contract."]]],
["Ahmed neemt via zijn werkgever deel aan een collectieve zorgverzekering. Hij gaat bij een andere werkgever werken. Wat gebeurt er met zijn basisverzekering?", [["De basisverzekering loopt door; alleen de collectieve voordelen kunnen vervallen", "Het einde van het dienstverband beëindigt de verzekering niet; de verzekeraar zet de polis in de regel individueel voort."], ["De basisverzekering eindigt op de laatste werkdag", "Hij blijft verzekeringsplichtig en verzekerd; de polis eindigt niet door het einde van het dienstverband."], ["Zijn oude werkgever moet de premie blijven betalen tot 1 januari van het volgende jaar", "De werkgever is niet verplicht premie door te betalen."], ["Hij moet opnieuw worden geaccepteerd na een medische keuring", "Medische selectie voor de basisverzekering is verboden."]]],
["Uit welke twee hoofdbronnen wordt de basisverzekering gefinancierd?", [["De nominale premie en de inkomensafhankelijke bijdrage Zvw", "Verzekerden van 18 jaar en ouder betalen premie aan hun verzekeraar; daarnaast is over het inkomen een inkomensafhankelijke bijdrage verschuldigd."], ["De zorgtoeslag en de eigen bijdrage Wlz", "Zorgtoeslag is een tegemoetkoming voor verzekerden en de Wlz is een aparte volksverzekering."], ["De premie volksverzekeringen en de premie werknemersverzekeringen via de loonheffing", "Dat zijn premies voor onder meer AOW, Wlz en WW, niet voor de Zvw."], ["De gemeentelijke belastingen en de rijksbijdrage Wmo", "De Wmo wordt via gemeenten gefinancierd en staat los van de zorgverzekering."]]],
["Wie betaalt de inkomensafhankelijke bijdrage Zvw over het loon van een werknemer?", [["De werkgever, via de werkgeversheffing Zvw", "Sinds 2013 betaalt de werkgever over het loon van de werknemer de werkgeversheffing; de werknemer betaalt die bijdrage niet zelf."], ["De werknemer, via een aanslag van de zorgverzekeraar", "Zorgverzekeraars innen alleen de nominale premie, niet de inkomensafhankelijke bijdrage."], ["De werknemer, waarna de werkgever een belaste vergoeding geeft", "Dat oude vergoedingssysteem is in 2013 vervangen door de werkgeversheffing."], ["Het UWV, op basis van de polisadministratie", "Het UWV betaalt geen bijdrage over het loon van werknemers in dienst bij een werkgever."]]],
["Sophie is zelfstandig ondernemer. Hoe betaalt zij de inkomensafhankelijke bijdrage Zvw over haar winst?", [["Zelf, tegen het lagere tarief, via een aanslag van de Belastingdienst", "Ondernemers en anderen zonder werkgever betalen de bijdrage zelf tegen een lager tarief, na een aanslag op basis van hun inkomen."], ["Via haar zorgverzekeraar, bovenop de nominale premie, als vast percentage van de winst", "De verzekeraar int de inkomensafhankelijke bijdrage niet."], ["Niet, ondernemers zijn vrijgesteld van de bijdrage", "Ook over winst uit onderneming is de bijdrage verschuldigd."], ["Via de werkgeversheffing tegen het hoge tarief", "De werkgeversheffing geldt voor loon, niet voor winst van een zelfstandige."]]],
["Wat geldt voor de inkomensafhankelijke bijdrage Zvw bij een hoog inkomen?", [["De bijdrage wordt geheven tot een maximumbijdrage-inkomen, niet daarboven", "Er geldt een maximum bijdrage-inkomen, zodat de bijdrage niet onbeperkt stijgt met het inkomen."], ["Het percentage stijgt progressief met het inkomen, net als in de schijven van box 1", "Er gelden vaste percentages, geen progressieve schijven."], ["Boven een bepaald inkomen vervalt de verzekeringsplicht", "De verzekeringsplicht staat los van het inkomen."], ["Bij een hoog inkomen betaalt men geen nominale premie meer", "Iedereen van 18 jaar en ouder betaalt de nominale premie aan zijn verzekeraar."]]],
["Hoe wordt de zorg voor kinderen onder de 18 in de basisverzekering gefinancierd, nu zij geen premie betalen?", [["Via een rijksbijdrage aan het Zorgverzekeringsfonds", "Het Rijk betaalt een bijdrage aan het Zorgverzekeringsfonds voor de premievrije verzekering van kinderen."], ["Via een verhoogde premie voor de ouders die hen meeverzekeren", "Ouders betalen geen extra premie voor hun kinderen."], ["Via de kinderbijslag van de SVB", "Kinderbijslag is een volksverzekering en wordt niet gebruikt om zorgpremie te betalen."], ["Via de zorgtoeslag van de ouders", "Zorgtoeslag is een tegemoetkoming in de eigen premie van volwassenen."]]],
["Aan welke voorwaarden moet iemand onder meer voldoen om recht te hebben op zorgtoeslag?", [["Meerderjarig zijn, een Nederlandse zorgverzekering hebben en onder de inkomens- en vermogensgrens blijven", "Zorgtoeslag is een inkomensafhankelijke tegemoetkoming voor volwassen verzekerden; ook rechtmatig verblijf is een voorwaarde."], ["Een aanvullende verzekering hebben en minder verdienen dan een modaal inkomen, ongeacht het eigen vermogen", "Een aanvullende verzekering is geen voorwaarde; het gaat om de basisverzekering."], ["Een naturapolis hebben bij een gecontracteerde zorgverzekeraar", "De polisvorm speelt geen rol voor het recht op zorgtoeslag."], ["Minstens één kind hebben en huur betalen", "Dat zijn geen voorwaarden voor zorgtoeslag; die gelden deels voor andere toeslagen."]]],
["Jesse kiest voor een duurdere restitutiepolis. Heeft dat invloed op de hoogte van zijn zorgtoeslag?", [["Nee, de zorgtoeslag gaat uit van een standaardpremie, niet van zijn eigen premie", "De toeslag gaat uit van een wettelijke standaardpremie, zodat de polis- of premiekeuze geen invloed heeft."], ["Ja, hoe hoger de premie, hoe hoger de zorgtoeslag, tot een wettelijk maximum per jaar", "Dan zou een dure polis automatisch meer toeslag geven; zo werkt de regeling niet."], ["Ja, bij een restitutiepolis vervalt het recht op zorgtoeslag", "De polisvorm is niet van belang voor het recht op zorgtoeslag."], ["Nee, maar zijn verzekeraar moet het premieverschil met de naturapolis compenseren", "Er bestaat geen compensatieplicht voor de verzekeraar."]]],
["Welk inkomen telt voor de zorgtoeslag als toetsingsinkomen?", [["In de regel het verzamelinkomen, samen met dat van een eventuele toeslagpartner", "De AWIR gebruikt het verzamelinkomen van de aanvrager en zijn toeslagpartner."], ["Het netto maandloon van de aanvrager", "De AWIR rekent met het fiscale jaarinkomen, niet met het netto maandloon."], ["Alleen het inkomen van de aanvrager, nooit dat van een fiscale partner of toeslagpartner", "Het inkomen van een toeslagpartner telt mee."], ["Het inkomen van het jaar waarin de aanvraag wordt ingediend", "Het gaat om het inkomen van het jaar waarover de toeslag wordt toegekend, niet om het aanvraagjaar."]]],
["Fatima ontvangt zorgtoeslag als voorschot op basis van een geschat jaarinkomen. Achteraf blijkt haar inkomen hoger. Wat gebeurt er?", [["Bij de definitieve berekening wordt het te veel ontvangen voorschot teruggevorderd", "Onder de AWIR is een voorschot voorlopig; na vaststelling van het inkomen volgt de definitieve berekening en eventueel terugvordering."], ["Niets, een eenmaal uitbetaald voorschot is definitief", "Een voorschot is per definitie voorlopig."], ["Haar zorgverzekeraar verrekent het verschil met haar premie", "De zorgverzekeraar is niet betrokken bij de vaststelling of terugvordering van zorgtoeslag."], ["Zij krijgt een boete en verliest het recht op zorgtoeslag voor vijf jaar", "Een hoger inkomen leidt tot terugvordering, niet tot een automatische boete of uitsluiting."]]],
["Tot wanneer kan iemand zorgtoeslag aanvragen over een bepaald kalenderjaar?", [["Tot en met 1 september van het jaar daarna", "De AWIR staat aanvragen achteraf toe tot 1 september van het volgende jaar."], ["Uiterlijk 1 januari van het betreffende jaar", "Aanvragen kan ook gedurende en na afloop van het jaar."], ["Tot vijf jaar na afloop van het jaar", "Zo lang is de aanvraagtermijn niet."], ["Alleen binnen vier maanden na het afsluiten van de zorgverzekering", "De termijn van vier maanden hoort bij de verzekeringsplicht, niet bij de zorgtoeslag."]]],
["Welke instantie kent de zorgtoeslag toe?", [["Dienst Toeslagen", "Dienst Toeslagen voert de toeslagen uit, waaronder de zorgtoeslag."], ["De zorgverzekeraar", "De verzekeraar int de premie, maar kent geen zorgtoeslag toe."], ["Het CAK", "Het CAK int onder meer eigen bijdragen Wlz en Wmo en voert de wanbetalersregeling uit."], ["De Sociale Verzekeringsbank", "De SVB voert volksverzekeringen uit, zoals AOW en kinderbijslag."]]],
["Voor wie is de Wet langdurige zorg (Wlz) bedoeld?", [["Voor wie blijvend permanent toezicht of 24 uur per dag zorg in de nabijheid nodig heeft", "De Wlz is gericht op zware, langdurige zorg, bijvoorbeeld bij ernstige dementie of een zware beperking."], ["Voor iedereen die tijdelijk hulp in het huishouden of begeleiding bij dagbesteding nodig heeft", "Huishoudelijke hulp valt onder de Wmo van de gemeente."], ["Voor mensen die kortdurend herstellen na een ziekenhuisopname", "Kortdurende zorg na een opname valt doorgaans onder de Zvw."], ["Voor jongeren tot 18 jaar met psychische problemen", "Jeugdhulp, waaronder jeugd-ggz, valt onder de Jeugdwet."]]],
["Welke instantie stelt vast of iemand toegang heeft tot zorg uit de Wlz?", [["Het Centrum indicatiestelling zorg (CIZ)", "Het CIZ beoordeelt of iemand aan de toegangscriteria van de Wlz voldoet en geeft een indicatiebesluit af."], ["De zorgverzekeraar van de cliënt", "De zorgverzekeraar voert de Zvw uit, niet de toegang tot de Wlz."], ["De gemeente via een keukentafelgesprek", "Een keukentafelgesprek hoort bij de Wmo."], ["De huisarts met een verwijzing", "Een verwijzing van de huisarts geeft geen toegang tot de Wlz."]]],
["Mevrouw Peters (81) komt thuis na een heupoperatie. Zij heeft hulp nodig bij het wassen en aankleden en bij het schoonhouden van haar huis. Hoe is dat geregeld?", [["Wassen en aankleden via de Zvw (wijkverpleging), schoonmaken via de Wmo", "Persoonlijke verzorging door de wijkverpleging is Zvw-zorg; huishoudelijke hulp is een Wmo-voorziening van de gemeente."], ["Beide vallen onder de Wlz", "Voor de Wlz is een blijvende behoefte aan permanent toezicht nodig; dat is hier niet aan de orde."], ["Beide vallen onder de Wmo van de gemeente, via één maatwerkvoorziening thuis", "Persoonlijke verzorging door de wijkverpleging valt sinds 2015 onder de Zvw."], ["Beide vallen onder de aanvullende verzekering, onderdeel thuiszorg", "Wijkverpleging is basisverzekerde zorg en huishoudelijke hulp een gemeentelijke voorziening."]]],
["Welke organisatie int de eigen bijdrage voor zorg uit de Wlz en voor maatwerkvoorzieningen uit de Wmo?", [["Het CAK", "Het CAK berekent en int de eigen bijdragen voor zowel de Wlz als de Wmo."], ["De zorgverzekeraar", "De zorgverzekeraar int de premie en het eigen risico van de Zvw, niet de eigen bijdrage Wlz of Wmo."], ["Dienst Toeslagen", "Dienst Toeslagen keert toeslagen uit en int geen eigen bijdragen."], ["Het Zorginstituut Nederland", "Het Zorginstituut adviseert over het pakket en beheert fondsen, maar int geen eigen bijdragen."]]],
["Wim heeft voor het dagelijks gebruik thuis een rolstoel nodig. Hij woont zelfstandig en heeft geen Wlz-indicatie. Waar kan hij in de regel terecht?", [["Bij de gemeente, op grond van de Wmo", "Rolstoelen voor dagelijks gebruik worden voor zelfstandig wonenden via de Wmo verstrekt."], ["Bij zijn zorgverzekeraar, op grond van de basisverzekering", "Een rolstoel voor dagelijks gebruik valt in deze situatie niet onder de Zvw."], ["Bij het CIZ, dat de rolstoel verstrekt", "Het CIZ indiceert voor de Wlz, maar verstrekt geen hulpmiddelen."], ["Bij het UWV, als voorziening voor arbeidsongeschikten", "Het UWV verstrekt alleen voorzieningen in verband met werk."]]],
["Onder welke wet valt geestelijke gezondheidszorg voor jongeren tot 18 jaar?", [["De Jeugdwet, uitgevoerd door de gemeente", "Sinds 2015 is de gemeente verantwoordelijk voor jeugdhulp, inclusief jeugd-ggz."], ["De Zorgverzekeringswet, uitgevoerd door de zorgverzekeraar", "Ggz voor volwassenen valt onder de Zvw; voor jongeren tot 18 jaar geldt de Jeugdwet."], ["De Wet langdurige zorg, uitgevoerd door het zorgkantoor", "De Wlz is voor blijvende zware zorg, niet voor reguliere jeugd-ggz."], ["De Wmo 2015, uitgevoerd door de gemeente", "De Wmo gaat over maatschappelijke ondersteuning; jeugdhulp aan minderjarigen valt onder de Jeugdwet."]]],
["Waarvoor dient de Europese gezondheidskaart (EHIC)?", [["Voor medisch noodzakelijke zorg bij tijdelijk verblijf in een ander EU/EER-land of Zwitserland", "Met de EHIC krijgt de verzekerde zorg volgens de regels en tarieven van het publieke stelsel van het verblijfsland."], ["Voor geplande behandelingen in elk land ter wereld", "De EHIC geldt alleen in de EU, de EER en Zwitserland en is bedoeld voor onvoorziene, medisch noodzakelijke zorg."], ["Voor repatriëring naar Nederland na een ongeval", "Terugvervoer valt niet onder de EHIC en ook niet onder de basisverzekering."], ["Als vervanging van een reisverzekering, inclusief dekking voor bagage, annulering en repatriëring", "De EHIC dekt alleen zorgkosten, geen bagage of annulering."]]],
["Familie Mulder krijgt tijdens een vakantie buiten Europa spoedeisende zorg in een privékliniek. Hoe vergoedt de basisverzekering dat?", [["Tot maximaal het tarief dat voor die zorg in Nederland gebruikelijk is", "De basisverzekering dekt zorg in het buitenland in de regel tot het Nederlandse tarief; een duurder buitenlands tarief komt voor eigen rekening of voor een aanvullende verzekering."], ["Volledig, ongeacht de hoogte van de buitenlandse nota", "Volledige vergoeding van dure buitenlandse tarieven is niet gegarandeerd vanuit de basisverzekering."], ["Niet, omdat de basisverzekering buiten Europa nooit dekking geeft", "Ook buiten Europa vergoedt de basisverzekering zorg, maar tot het Nederlandse tariefniveau."], ["Alleen als zij vooraf een EHIC hebben laten registreren", "De EHIC werkt alleen binnen de EU, EER en Zwitserland en is geen voorwaarde voor vergoeding elders."]]],
["Tom woont in Nederland en gaat fulltime in loondienst werken bij een werkgever in België. Hij werkt alleen in België. Wat geldt voor zijn zorgverzekering?", [["Hij valt in beginsel onder het Belgische stelsel en is niet meer Zvw-verzekeringsplichtig", "Volgens de Europese coördinatieregels geldt het werklandbeginsel; met een S1-formulier kan hij ook in Nederland zorg krijgen."], ["Hij blijft verzekeringsplichtig in Nederland omdat hij hier woont", "Bij werken in een ander EU-land is in beginsel de sociale zekerheid van het werkland van toepassing."], ["Hij moet zowel in België als in Nederland een volledige basisverzekering afsluiten en betalen", "De Europese regels voorkomen juist dubbele verzekering; slechts één land is bevoegd."], ["Hij kan vrij kiezen in welk land hij verzekerd wil zijn", "De toepasselijke wetgeving volgt uit de coördinatieregels; een vrije keuze bestaat niet."]]],
["Een Nederlandse werknemer wordt door zijn werkgever voor achttien maanden gedetacheerd naar Duitsland. Hij heeft een A1-verklaring. Wat betekent dat voor zijn zorgverzekering?", [["Hij blijft verzekerd voor de Nederlandse sociale zekerheid en dus voor de Zvw", "Met een A1-verklaring bij detachering blijft de Nederlandse wetgeving van toepassing, inclusief de verzekeringsplicht."], ["Hij moet zijn Nederlandse zorgverzekering opzeggen en een Duitse afsluiten", "Bij detachering met A1-verklaring blijft hij juist in Nederland verzekerd."], ["Hij is in die periode in geen enkel land verzekerd", "Hij blijft via de Nederlandse regels verzekerd."], ["Hij is alleen voor spoedeisende zorg verzekerd", "Zijn basisverzekering blijft volledig doorlopen."]]],
["Mevrouw De Groot (70) verhuist naar Spanje. Zij ontvangt alleen AOW en een Nederlands pensioen en is daardoor niet meer Wlz-verzekerd. Hoe regelt zij haar zorg?", [["Zij registreert zich via het CAK als verdragsgerechtigde en betaalt een verdragsbijdrage", "Verdragsgerechtigden ontvangen zorg in het woonland voor rekening van Nederland; het CAK regelt de registratie en de bijdrage."], ["Zij houdt haar gewone Nederlandse basisverzekering aan", "Zonder Wlz-verzekering is zij niet meer verzekeringsplichtig voor de Zvw."], ["Zij is automatisch verzekerd via de Spaanse sociale zekerheid, zonder een bijdrage te betalen", "Omdat zij alleen een Nederlandse uitkering heeft, is Nederland verantwoordelijk voor haar zorgkosten."], ["Zij moet zich aanmelden bij Dienst Toeslagen", "Dienst Toeslagen voert toeslagen uit, geen registratie van verdragsgerechtigden."]]],
["Wanneer meldt een zorgverzekeraar een verzekeringnemer aan bij het CAK in het kader van de wanbetalersregeling?", [["Bij een premieachterstand van zes maandpremies", "Na zes maanden achterstand volgt aanmelding bij het CAK, dat dan een bestuursrechtelijke premie gaat heffen."], ["Bij de eerste niet-betaalde maandpremie", "Eerst volgen herinneringen en een aanbod voor een betalingsregeling."], ["Pas na drie jaar premieachterstand", "Zo lang wordt niet gewacht; de regeling start bij zes maandpremies achterstand."], ["Alleen als de verzekerde ook zijn eigen risico niet betaalt", "Het gaat om achterstand in de premie, niet om het eigen risico."]]],
["Wat houdt de bestuursrechtelijke premie in de wanbetalersregeling in?", [["Een premie die het CAK heft, zo mogelijk door inhouding op loon of uitkering", "De wanbetaler betaalt in plaats van premie aan de verzekeraar een hogere bestuursrechtelijke premie, vaak via een bronheffing."], ["Een boete van de NZa voor de zorgverzekeraar", "De bestuursrechtelijke premie wordt opgelegd aan de verzekerde, niet aan de verzekeraar."], ["Een korting op de premie om de achterstand sneller af te lossen", "Het gaat juist om een hogere premie, als prikkel om de schuld af te lossen."], ["Een premie voor een aanvullende verzekering die het CAK aanbiedt", "Het CAK biedt geen aanvullende verzekeringen aan."]]],
["Wat geldt voor een zorgverzekeraar als een verzekeringnemer een premieachterstand van twee maandpremies heeft?", [["De verzekeraar moet een betalingsregeling aanbieden", "De Zvw verplicht de verzekeraar bij twee maandpremies achterstand een betalingsregeling aan te bieden, om verdere schulden te voorkomen."], ["De verzekeraar moet de basisverzekering beëindigen", "Beëindigen is niet de bedoeling; de wanbetalersregeling houdt de verzekerde juist verzekerd."], ["De verzekeraar moet de verzekerde direct aanmelden bij het CAK", "Aanmelding bij het CAK volgt pas bij zes maandpremies achterstand."], ["De verzekeraar mag geen zorg meer vergoeden", "De verzekerde houdt recht op zorg uit de basisverzekering."]]],
["Uit gegevensvergelijking blijkt dat Mark verzekeringsplichtig is, maar geen zorgverzekering heeft. Hij reageert niet op brieven. Wat kan uiteindelijk volgen?", [["Na boetes kan het CAK hem ambtshalve verzekeren bij een zorgverzekeraar", "Het CAK spoort onverzekerden op, legt bij uitblijven van reactie boetes op en kan iemand uiteindelijk ambtshalve verzekeren."], ["Hij verliest zijn recht op een zorgverzekering voor vijf jaar", "Uitsluiting is niet mogelijk; hij blijft verzekeringsplichtig."], ["Zijn werkgever wordt verplicht een verzekering voor hem te sluiten", "De verzekeringsplicht rust op Mark zelf, niet op zijn werkgever."], ["De gemeente sluit automatisch een gemeentepolis voor hem af", "Een gemeentepolis is een vrijwillige collectiviteit, geen sanctie voor onverzekerden."]]],
["Welke taak heeft het Zorginstituut Nederland?", [["Adviseren over het basispakket en het beheren van het Zorgverzekeringsfonds", "Het Zorginstituut adviseert de minister over de pakketinhoud, beheert de fondsen en voert de risicoverevening uit."], ["Het vaststellen van de premie van iedere zorgverzekeraar", "Verzekeraars stellen hun premie zelf vast."], ["Het houden van prudentieel toezicht op zorgverzekeraars", "Prudentieel toezicht op zorgverzekeraars ligt bij De Nederlandsche Bank."], ["Het beslechten van geschillen tussen verzekerden en verzekeraars", "Geschillen gaan naar de SKGZ of de rechter."]]],
["Welke rol heeft de Nederlandse Zorgautoriteit (NZa) ten aanzien van zorgverzekeraars?", [["Toezicht op de rechtmatige uitvoering van de Zvw, zoals de zorgplicht", "De NZa ziet erop toe dat verzekeraars de Zvw goed uitvoeren en stelt regels voor tarieven en prestaties in de zorg."], ["Het vaststellen van de inhoud van het basispakket na advies van zorgverzekeraars", "Het pakket wordt door de overheid vastgesteld op advies van het Zorginstituut."], ["Het indiceren van zorg uit de Wet langdurige zorg", "Indicatiestelling voor de Wlz is een taak van het CIZ."], ["Het innen van de inkomensafhankelijke bijdrage Zvw", "Die bijdrage wordt door de Belastingdienst geïnd."]]],
["Welke toezichthouder houdt prudentieel toezicht op zorgverzekeraars?", [["De Nederlandsche Bank", "DNB ziet als prudentieel toezichthouder toe op de financiële soliditeit van verzekeraars, ook van zorgverzekeraars."], ["De Inspectie Gezondheidszorg en Jeugd", "De IGJ houdt toezicht op de kwaliteit en veiligheid van zorg, niet op de solvabiliteit van verzekeraars."], ["De Autoriteit Consument & Markt", "De ACM houdt toezicht op mededinging, niet op de financiële soliditeit van verzekeraars."], ["Het Zorginstituut Nederland", "Het Zorginstituut is geen toezichthouder op de soliditeit van verzekeraars."]]],
["Een verzekerde is het niet eens met de afwijzing van een declaratie door zijn zorgverzekeraar. Wat is de juiste volgorde van stappen?", [["Eerst klagen bij de zorgverzekeraar, daarna eventueel naar de SKGZ", "De SKGZ behandelt een klacht pas als de verzekeraar eerst de kans heeft gehad die zelf op te lossen."], ["Direct naar het Kifid", "Geschillen over zorgverzekeringen horen bij de SKGZ, niet bij het Kifid."], ["Eerst een klacht bij de NZa, daarna een procedure bij de kantonrechter", "De NZa behandelt geen individuele geschillen tussen verzekerde en verzekeraar."], ["Eerst naar het Zorginstituut, daarna naar de zorgverzekeraar zelf", "Het Zorginstituut behandelt geen individuele klachten van verzekerden."]]],
["Over welke verzekeringen kan de Stichting Klachten en Geschillen Zorgverzekeringen (SKGZ) oordelen?", [["Over zowel de basisverzekering als aanvullende zorgverzekeringen", "De SKGZ is de geschilleninstantie voor zorgverzekeringen, zowel basis als aanvullend."], ["Alleen over de basisverzekering", "Ook klachten over aanvullende zorgverzekeringen kan de SKGZ behandelen."], ["Alleen over aanvullende verzekeringen", "Juist ook geschillen over de basisverzekering horen bij de SKGZ."], ["Over alle schadeverzekeringen, zoals reis- en inboedelverzekeringen", "Voor andere schadeverzekeringen is het Kifid de klachteninstantie."]]],
["Een geschil bij de SKGZ gaat over de vraag of een behandeling onder het basispakket valt. Welke rol heeft het Zorginstituut daarbij?", [["De SKGZ vraagt het Zorginstituut om advies over de uitleg van het pakket", "Bij geschillen over de inhoud van de basisverzekering wint de geschillencommissie advies in bij het Zorginstituut."], ["Het Zorginstituut neemt het geschil over en doet zelf uitspraak", "Het Zorginstituut adviseert alleen; de uitspraak is aan de SKGZ."], ["Het Zorginstituut vertegenwoordigt de zorgverzekeraar", "Het Zorginstituut is onafhankelijk en geen partij in het geschil."], ["Het Zorginstituut speelt geen rol bij geschillen over het pakket", "Juist bij geschillen over de pakketinhoud is zijn advies van belang."]]],
["Wat houdt de zorgplicht van een zorgverzekeraar op grond van de Zvw in?", [["Zorgen dat verzekerden de zorg krijgen waarop zij recht hebben, of de kosten daarvan vergoeden", "Bij natura betekent dit voldoende gecontracteerde zorg binnen redelijke tijd en afstand, met wachtlijstbemiddeling als dat nodig is."], ["De verzekeraar moet iedere verzekerde jaarlijks persoonlijk adviseren over zijn gezondheid en leefstijl", "Gezondheidsadvies is geen onderdeel van de zorgplicht van de verzekeraar."], ["De verzekeraar moet alle zorgaanbieders in Nederland contracteren tegen dezelfde tarieven", "De verzekeraar mag selectief contracteren, zolang er voldoende zorg beschikbaar is."], ["De verzekeraar moet de premie jaarlijks gelijk houden", "De zorgplicht gaat over de levering van zorg, niet over de hoogte van de premie."]]],
["Een klant vraagt zijn adviseur om de goedkoopste basisverzekering. Hij wordt binnenkort behandeld in een ziekenhuis waarmee hij een goede band heeft. Wat hoort de adviseur in elk geval te doen?", [["Nagaan of dat ziekenhuis gecontracteerd is en uitleggen wat de polis anders vergoedt", "Bij een natura- of budgetpolis kan niet-gecontracteerde zorg lager worden vergoed; dat is voor deze klant wezenlijke informatie."], ["Alleen de premie vergelijken, omdat het basispakket overal gelijk is", "Het pakket is gelijk, maar de vergoeding van niet-gecontracteerde zorg verschilt per polis."], ["Adviseren een vrijwillig eigen risico te nemen om nog meer te besparen", "Bij een geplande behandeling met kosten is een hoger eigen risico juist ongunstig."], ["Doorverwijzen naar de NZa voor een overzicht van gecontracteerde ziekenhuizen per verzekeraar", "De adviseur moet de klant zelf goed informeren over de gevolgen van zijn keuze."]]],
["Welke vakbekwaamheidseis geldt onder de Wft voor een adviseur die adviseert over zorgverzekeringen?", [["Hij moet het Wft-diploma Zorgverzekeringen hebben en zijn kennis via PE actueel houden", "Voor advies over zorgverzekeringen is het specifieke Wft-diploma Zorgverzekeringen nodig; via permanente educatie blijft de adviseur vakbekwaam."], ["Geen, omdat de basisverzekering als wettelijke verzekering geen financieel product in de zin van de Wft is", "Een zorgverzekering is een schadeverzekering en dus een financieel product onder de Wft."], ["Alleen een medische opleiding op minimaal hbo-niveau", "De Wft vraagt een Wft-diploma, geen medische opleiding."], ["Alleen het Wft-diploma Hypothecair Krediet", "Dat diploma gaat over hypotheken, niet over zorgverzekeringen."]]],
["Wat houdt de algemene zorgplicht van art. 4:24a Wft in voor een adviseur in zorgverzekeringen?", [["Hij moet zorgvuldig rekening houden met de rechtmatige belangen van de klant", "Deze open norm geldt naast de specifieke regels, bijvoorbeeld bij het afwegen van polisvorm en eigen risico."], ["Hij moet ervoor zorgen dat de klant voldoende en tijdig zorg krijgt van zijn verzekeraar", "Dat is de zorgplicht van de zorgverzekeraar op grond van de Zvw."], ["Hij moet altijd de goedkoopste polis adviseren", "Het belang van de klant is niet altijd de laagste premie, bijvoorbeeld bij behoefte aan vrije artsenkeuze."], ["Hij moet de klant elk jaar laten overstappen", "Overstappen is alleen zinvol als dat in het belang van de klant is."]]],
["Hoe worden gezondheidsgegevens onder de AVG aangemerkt?", [["Als bijzondere persoonsgegevens; verwerking is verboden tenzij een wettelijke uitzondering geldt", "Voor gezondheidsgegevens gelden strengere regels; verwerking mag alleen als een uitzondering van toepassing is."], ["Als gewone persoonsgegevens, net als naam en adres, die met toestemming vrij mogen worden verwerkt", "Gezondheidsgegevens vallen in een strengere categorie dan gewone persoonsgegevens."], ["Als openbare gegevens die vrij mogen worden gedeeld", "Gezondheidsgegevens zijn juist bijzonder gevoelig en niet vrij deelbaar."], ["Als gegevens die alleen een arts mag inzien en een zorgverzekeraar nooit mag verwerken", "Verzekeraars mogen onder voorwaarden gezondheidsgegevens verwerken, bijvoorbeeld via een medisch adviseur."]]],
["Een klant vult voor een aanvullende verzekering een gezondheidsverklaring in en wil die aan zijn adviseur meegeven. Wat is de zorgvuldige werkwijze?", [["Rechtstreeks of in gesloten envelop laten sturen naar de medisch adviseur van de verzekeraar", "Zo blijven de gezondheidsgegevens beperkt tot wie ze nodig heeft voor de risicobeoordeling."], ["De verklaring kopiëren en in het klantdossier bewaren", "Onnodig bewaren van gezondheidsgegevens is in strijd met dataminimalisatie."], ["De verklaring zelf beoordelen en alleen de uitkomst doorgeven", "De adviseur is geen medisch adviseur en hoort de gegevens niet te beoordelen."], ["De verklaring per gewone e-mail doorsturen naar de acceptatieafdeling, zodat de aanvraag sneller loopt", "Onbeveiligd versturen naar een algemene afdeling past niet bij de beveiligingseisen voor bijzondere gegevens."]]],
["Binnen welke termijn moet een datalek met risico voor betrokkenen in de regel worden gemeld bij de Autoriteit Persoonsgegevens?", [["Binnen 72 uur na ontdekking", "De AVG verplicht een melding binnen 72 uur nadat de organisatie het lek heeft ontdekt, tenzij het lek waarschijnlijk geen risico oplevert."], ["Binnen vier weken na ontdekking", "Die termijn is te lang; de AVG vraagt melding binnen 72 uur."], ["Alleen bij het jaarlijkse verantwoordingsverslag", "Een datalek moet direct worden gemeld, niet pas achteraf in een jaarverslag."], ["Binnen 24 uur bij de AFM", "Datalekken worden gemeld bij de Autoriteit Persoonsgegevens, niet bij de AFM."]]],
["Welk AVG-beginsel houdt in dat een adviseur niet meer persoonsgegevens verwerkt dan nodig is voor zijn advies?", [["Dataminimalisatie", "Dataminimalisatie betekent dat alleen gegevens worden verwerkt die noodzakelijk zijn voor het doel."], ["Dataportabiliteit", "Dataportabiliteit is het recht van de betrokkene om zijn gegevens mee te nemen."], ["Recht op vergetelheid", "Dat is het recht van de betrokkene op verwijdering van gegevens."], ["Privacy by design", "Privacy by design gaat over het inbouwen van privacy in systemen en processen, niet specifiek over de omvang van de verwerking."]]],
["Sinds wanneer zijn de regels van de Insurance Distribution Directive (IDD) in Nederland van toepassing?", [["1 oktober 2018", "De IDD verving de richtlijn verzekeringsbemiddeling (IMD) en is sinds 1 oktober 2018 van toepassing."], ["1 januari 2013, samen met het provisieverbod", "Op 1 januari 2013 ging het provisieverbod in voor complexe producten; dat staat los van de IDD."], ["25 mei 2018", "Op 25 mei 2018 werd de AVG van toepassing, niet de IDD."], ["1 januari 2006", "Op 1 januari 2006 trad de Zvw in werking."]]],
["Wat moet een verzekeringsdistributeur onder de IDD vaststellen voordat een verzekering wordt gesloten, ook als hij niet adviseert?", [["De wensen en behoeften van de klant", "De IDD verplicht distributeurs de wensen en behoeften vast te stellen en alleen een verzekering aan te bieden die daarbij past."], ["De volledige vermogenspositie van alle familieleden", "Een dergelijk uitgebreid onderzoek vraagt de IDD niet."], ["Of de klant de premie ook over tien jaar kan betalen", "Dat is geen specifieke IDD-eis voor schadeverzekeringen."], ["Of de klant eerder een klacht heeft ingediend bij de SKGZ", "Eerdere klachten zijn geen onderdeel van de wensen- en behoeftentoets."]]],
["Op wie is de IDD van toepassing?", [["Op alle verzekeringsdistributeurs: verzekeraars die direct verkopen én tussenpersonen", "De IDD geldt voor de hele distributieketen, dus ook voor verzekeraars die zonder tussenpersoon verkopen."], ["Alleen op onafhankelijke tussenpersonen die namens meerdere verzekeraars adviseren en bemiddelen", "Ook verzekeraars die zelf verkopen vallen onder de IDD."], ["Alleen op verzekeraars, niet op adviseurs en bemiddelaars die zelf geen risico dragen", "Juist tussenpersonen zijn een belangrijke doelgroep van de IDD."], ["Alleen op aanbieders van levensverzekeringen", "De IDD geldt voor schade- en levensverzekeringen."]]]
]
};
